e-item { border-radius:12px; border:1px solid #dbeafe; background:#eff6ff; padding:10px; }\n        .worklog-result-actions { display:flex; flex-wrap:wrap; gap:8px; }\n        .worklog-result-action-btn { border:none; border-radius:999px; padding:6px 12px; cursor:pointer; font-size:12px; font-weight:800; color:#fff; background:#2563eb; }\n        .worklog-result-action-btn.secondary { background:#7c3aed; }\n        .worklog-result-action-btn.ghost { background:#0f766e; }\n        .worklog-tool-trace-list { display:flex; flex-direction:column; gap:8px; }\n        .worklog-tool-trace-item { border-radius:12px; border:1px solid #e2e8f0; background:#f8fafc; padding:8px 10px; }\n        .worklog-stream-groups { display:flex; flex-direction:column; gap:10px; }\n        .worklog-stream-tab-bar { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:10px; }\n        .worklog-stream-tab-btn { border:none; border-radius:999px; padding:5px 10px; cursor:pointer; background:#e2e8f0; color:#334155; font-size:11px; font-weight:800; }\n        .worklog-stream-tab-btn.active { background:#2563eb; color:#fff; }\n        .worklog-stream-group { border-radius:14px; border:1px solid #dbeafe; background:linear-gradient(135deg, #ffffff, #f8fafc); overflow:hidden; position:relative; }\n        .worklog-stream-group.hidden-stream-tab { display:none; }\n        .worklog-stream-step.entering { animation: streamStepEnter 0.45s ease-out; } /* worklog-stream-step.entering */\n        .worklog-step-trace-line { position:absolute; left:18px; top:44px; bottom:14px; width:3px; border-radius:999px; background:linear-gradient(180deg, rgba(148,163,184,0.18), rgba(59,130,246,0.36), rgba(148,163,184,0.18)); }\n        .worklog-stream-group.current-group .worklog-step-trace-line { background:linear-gradient(180deg, rgba(96,165,250,0.32), rgba(37,99,235,0.9), rgba(96,165,250,0.32)); animation: currentStepTracePulse 1.5s ease-in-out infinite; }\n        .worklog-stream-group-header { display:flex; justify-content:space-between; align-items:center; gap:8px; padding:10px 12px; border-bottom:1px solid #dbeafe; background:linear-gradient(135deg, #eff6ff, #f8fafc); }\n        .worklog-stream-step-list { display:flex; flex-direction:column; gap:8px; padding:12px 12px 12px 34px; }\n        .worklog-stream-step { border-radius:12px; border:1px solid #e2e8f0; background:#f8fafc; padding:8px 10px; position:relative; }\n        .worklog-stream-step::before { content:''; position:absolute; left:-24px; top:14px; width:10px; height:10px; border-radius:999px; background:#cbd5e1; box-shadow:0 0 0 4px rgba(226,232,240,0.9); }\n        .worklog-stream-step.current-step { border-color:#60a5fa; background:linear-gradient(135deg, #eff6ff, #dbeafe); box-shadow:0 0 0 2px rgba(96,165,250,0.18), 0 14px 32px rgba(37,99,235,0.12); animation: currentStepTracePulse 1.5s ease-in-out infinite; } /* worklog-stream-step current-step */\n        .worklog-stream-step.current-step::before { background:#2563eb; box-shadow:0 0 0 6px rgba(191,219,254,0.95); }\n        @keyframes currentStepTracePulse {\n            0% { box-shadow:0 0 0 2px rgba(96,165,250,0.14), 0 8px 22px rgba(37,99,235,0.10); }\n            50% { box-shadow:0 0 0 3px rgba(59,130,246,0.26), 0 18px 38px rgba(37,99,235,0.18); }\n            100% { box-shadow:0 0 0 2px rgba(96,165,250,0.14), 0 8px 22px rgba(37,99,235,0.10); }\n        }\n        @keyframes streamStepEnter {\n            0% { opacity:0; transform:translateY(8px) scale(0.985); }\n            100% { opacity:1; transform:translateY(0) scale(1); }\n        }\n        .result-artifact-panel, .result-diff-preview { border-radius:14px; border:1px solid #dbeafe; background:linear-gradient(135deg, #ffffff, #f8fafc); padding:12px; }\n        .result-artifact-panel { border-color:#bfdbfe; background:linear-gradient(135deg, #eff6ff, #eef6ff); }\n        .result-panel-title { font-size:12px; font-weight:800; color:#1e3a8a; margin-bottom:8px; }\n        .result-artifact-list { display:flex; flex-direction:column; gap:10px; }\n        .result-diff-preview pre { margin:0; padding:12px; border-radius:12px; background:#0f172a; color:#e2e8f0; overflow:auto; font-size:12px; }\n        .result-diff-preview code { font-family:Consolas, monospace; white-space:pre; }\n        @media (max-width: 980px) {\n            .worklog-process-layout { grid-template-columns:1fr; }\n        }\n        .worklog-process-panel { display:flex; flex-direction:column; gap:12px; }\n        .worklog-timeline { display:flex; flex-direction:column; gap:8px; }\n\n        .worklog-timeline-item { border-radius:12px; padding:10px 12px; border:1px solid #dbeafe; background:linear-gradient(135deg, #ffffff, #f8fafc); }\n        .worklog-timeline-item.stdout { border-color:#93c5fd; background:linear-gradient(135deg, #eff6ff, #dbeafe); }\n        .worklog-timeline-item.chat { border-color:#cbd5e1; background:linear-gradient(135deg, #f8fafc, #f1f5f9); }\n        .worklog-timeline-item.heartbeat { border-color:#fde68a; background:linear-gradient(135deg, #fffbeb, #fef3c7); }\n        .worklog-timeline-item.watchdog, .worklog-timeline-item.failed, .worklog-timeline-item.error { border-color:#fca5a5; background:linear-gradient(135deg, #fff1f2, #fee2e2); }\n        .worklog-timeline-item.latest { box-shadow:0 0 0 2px rgba(37,99,235,0.18), 0 10px 28px rgba(37,99,235,0.12); }\n        .worklog-timeline-meta { font-size:11px; color:#64748b; margin-bottom:4px; display:flex; gap:8px; flex-wrap:wrap; }\n        .worklog-stage-list { display:flex; flex-direction:column; gap:10px; position:relative; padding-left:18px; }\n        .worklog-stage-list::before { content:''; position:absolute; left:8px; top:6px; bottom:6px; width:2px; background:linear-gradient(180deg, rgba(148,163,184,0.15), rgba(59,130,246,0.28), rgba(148,163,184,0.15)); }\n        .worklog-stage-node { position:relative; }\n        .worklog-stage-node::before { content:''; position:absolute; left:-14px; top:18px; width:10px; height:10px; 