dge { background:#dbeafe; color:#1d4ed8; }\n        .artifact-kind-badge { background:#dcfce7; color:#166534; }\n        .artifact-status-badge.pending { background:#e2e8f0; color:#475569; }\n        .artifact-status-badge.exists { background:#dcfce7; color:#166534; }\n        .artifact-status-badge.missing { background:#fee2e2; color:#b91c1c; }\n        .artifact-status-badge.online { background:#dbeafe; color:#1d4ed8; }\n        .artifact-status-badge.offline { background:#fde68a; color:#92400e; }\n        .worklog-artifact-actions { display:flex; flex-wrap:wrap; gap:8px; margin-top:8px; }\n        .worklog-artifact-title-row { display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:8px; }\n        .artifact-title-button { border:none; background:transparent; padding:0; cursor:pointer; color:#1d4ed8; font-size:12px; font-weight:700; text-align:left; }\n        .artifact-title-button:hover { text-decoration:underline; }\n        .worklog-artifact-quick-btn { border:none; border-radius:999px; padding:4px 10px; cursor:pointer; background:#0f766e; color:#fff; font-size:11px; font-weight:700; }\n        .worklog-artifact-quick-btn.folder { background:#7c3aed; }\n        .worklog-artifact-btn[disabled], .worklog-artifact-quick-btn[disabled] { opacity:0.45; cursor:not-allowed; }\n        .worklog-artifact-btn { border:none; border-radius:999px; padding:5px 10px; cursor:pointer; font-size:11px; font-weight:700; color:#fff; }\n        .worklog-artifact-btn.open { background:#2563eb; }\n        .worklog-artifact-btn.reveal { background:#7c3aed; }\n        .worklog-artifact-btn.preview { background:#059669; }\n        .worklog-step-panel { border-radius:12px; background:#0f172a; color:#e2e8f0; overflow:hidden; }\n        .worklog-step-details { margin:0; }\n        .worklog-step-details summary { list-style:none; cursor:pointer; padding:12px; display:flex; justify-content:space-between; align-items:center; gap:8px; font-size:12px; font-weight:700; color:#bfd