{ background:#fef3c7; color:#92400e; }\n.agent-runtime-pill.health-offline { background:#e5e7eb; color:#4b5563; }\n.agent-runtime-pill.budget-warning { background:#fef3c7; color:#92400e; }\n.agent-runtime-pill.budget-hard-stop { background:#fee2e2; color:#b91c1c; }\n.agent-runtime-pill.adapter-hermes { background:linear-gradient(135deg,#ede9fe,#ddd6fe); color:#5b21b6; }\n.agent-runtime-pill.adapter-localnode { background:linear-gradient(135deg,#dbeafe,#bfdbfe); color:#1d4ed8; }\n.agent-detail-modal { position: fixed; inset: 0; background: rgba(15, 23, 42, 0.45); z-index: 10020; display: none; align-items: center; justify-content: center; padding: 24px; }\n.agent-detail-dialog { width: min(980px, 92vw); max-height: 85vh; overflow: auto; background: #fff; border-radius: 18px; padding: 20px; box-shadow: 0 20px 60px rgba(15, 23, 42, 0.25); }\n.agent-detail-header { display: flex; justify-content: space-between; gap: 12px; align-items: center; margin-bottom: 16px; }\n.agent-detail-section { margin-top: 16px; padding-top: 16px; border-top: 1px solid #e2e8f0; }\n.agent-step { padding: 10px; border: 1px solid #e2e8f0; border-radius: 10px; background: #f8fafc; margin-bottom: 8px; }\n.agent-process-preview { margin-top: 10px; padding: 10px; border-radius: 10px; background: #0f172a; color: #e2e8f0; font-size: 12px; }\n.agent-process-preview-title { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:8px; font-weight:700; color:#bfdbfe; }\n.agent-process-log { display:flex; flex-direction:column; gap:6px; max-height: 180px; overflow:auto; }\n.agent-process-log-item { padding:6px 8px; border-radius:8px; background: rgba(148, 163, 184, 0.12); border:1px solid rgba(148,163,184,0.2); white-space:pre-wrap; word-break:break-word; }\n.agent-process-log-item.watchdog { border-color:#fca5a5; background: rgba(127, 29, 29, 0.32); color:#fecaca; }\n.agent-process-log-item.stdout { border-color:#334155; }\n.agent-process-log-meta { font-size:11px; color:#94a3b8; margin-bottom:4px; }\n.agent-artifact-link { display: block; margin-bottom: 6px; word-break: break-all; }\n.app-dialog-overlay { position: fixed; inset: 0; background: rgba(15, 23, 42, 0.42); z-index: 10080; display: none; align-items: center; justify-content: center; padding: 24px; backdrop-filter: blur(5px); }\n.app-dialog-card { width: min(460px, 92vw); background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%); border-radius: 22px; box-shadow: 0 24px 60px rgba(15, 23, 42, 0.22); border: 1px solid rgba(148, 163, 184, 0.25); overflow: hidden; }\n.app-dialog-head { display: flex; gap: 14px; align-items: flex-start; padding: 22px 22px 16px; }\n.app-dialog-icon { width: 42px; height: 42px; border-radius: 14px; display: inline-flex; align-items: center; justify-content: center; font-size: 20px; flex-shrink: 0; }\n.app-dialog-icon.info { background: #e0f2fe; color: #0284c7; }\n.app-dialog-icon.success { background: #dcfce7; color: #15803d; }\n.app-dialog-icon.warning { background: #fef3c7; color: #b45309; }\n.app-dialog-icon.error { background: #fee2e2; color: #b91c1c; }\n.app-dialog-title { margin: 0; font-size: 20px; font-weight: 800; color: #0f172a; }\n.app-dialog-message { margin: 8px 0 0; font-size: 14px; line-height: 1.7; color: #475569; white-space: pre-wrap; }\n.app-dialog-foot { display: flex; justify-content: flex-end; gap: 10px; padding: 0 22px 22px; }\n.app-dialog-btn { border: none; border-radius: 999px; padding: 11px 18px; font-size: 14px; font-weight: 700; cursor: pointer; transition: transform .15s ease, box-shadow .15s ease; }\n.app-dialog-btn:hover { transform: translateY(-1px); }\n.app-dialog-btn.primary { background: linear-gradient(135deg, #2563eb, #0ea5e9); color: #fff; box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22); }\n.app-dialog-btn.warning { background: linear-gradient(135deg, #f59e0b, #f97316); color: #fff; box-shadow: 0 12px 24px rgba(245, 158, 11, 0.22); }\n.app-dialog-btn.error { background: linear-gradient(135deg, #ef4444, #dc2626); color: #fff; box-shadow: 0 12px 24px rgba(239, 68, 68, 0.22); }\n.app-dialog-btn.neutral { background: #e2e8f0; color: #334155; }\n@media (max-width: 900px) { .agent-runtime-panel.expanded { height: min(70vh, 620px); max-height: 70vh; } .agent-runtime-grid { grid-template-columns: 1fr; } }\n\n    </style>\n\n</head>\n\n<body class=\"niuma-office-theme-v2\" style=\"margin:0; padding:0; width:100vw; height:100vh; background-color:#ab9980; \">\n    <div class=\"header-container\">\n        <div class=\"header-left\" style=\"justify-content: flex-start; padding-bottom: 5px;\">\n            <div style=\"display: flex; flex-direction: column; align-items: flex-start; cursor: pointer; margin-bottom: 12px; transition: transform 0.2s;\" onclick=\"openLicenseModal()\" title=\"点击修改公司名称并尝试申请执照\" onmouseover=\"this.style.transform='translateX(5px)'\" onmouseout=\"this.style.transform='none'\">\n                <h1 style=\"margin: 0; display: flex; align-items: center; gap: 10px; font-size: 2.2rem;\">\n                    \ud83c\udfe2 <span id=\"companyNameDisplay\" style=\"background: linear-gradient(120deg, var(--pipi-cyan), var(--pipi-magenta));\">牛马Claw</span>\n                </h1>\n                <span id=\"licenseTag\" style=\"margin-top: 6px; font-size: 0.75rem; padding: 4px 8px; border-radius: 6px; background: #e74c3c; color: white; font-weight: bold; letter-spacing: 1px; box-shadow: 0 4px 10px rgba(0,0,0,0.1);\">未获取营业执照</span>\n            </div>\n            <p>欢迎回来，这是您的团队。点击工位可以单独派单。</p>\n            <div id=\"deskAlertSummaryBar\" onclick=\"jumpToDeskAlerts()\" style=\"display:none; margin: 6px 0 12px; padding:10px 12px; border-radius:10px; background:#fef2f2; color:#b91c1c; font-size:13px; font-weight:bold; border:1px solid #fecaca; cursor:pointer;\">当前没有异常告警</div>\n            <div id=\"controlPlaneOverviewStrip\" style=\"display:grid; grid-template-columns:repeat(auto-fit, minmax(120px, 1fr)); gap:10px; margin: 0 0 14px;\">\n                <div style=\"padding:10px 12px; border-radius:12px; background:rgba(255,255,255,0.82); border:1px solid rgba(148,163,184,0.28);\"><div style=\"font-size:11px; color:#64748b;\">员工数</div><div style=\"font-size:18px; font-weight:800; color:#0f172a;\">0</div></div>\n                <div style=\"padding:10px 12px; border-radius:12px; background:rgba(255,255,255,0.82); border:1px solid rgba(148,163,184,0.28);\"><div style=\"font-size:11px; color:#64748b;\">活跃任务</div><div style=\"font-size:18px; font-weight:800; color:#0f172a;\">0</div></div>\n                <div style=\"padding:10px 12px; border-radius:12px; background:rgba(255,255,255,0.82); border:1px solid rgba(148,163,184,0.28);\"><div style=\"font-size:11px; color:#64748b;\">阻塞任务</div><div style=\"font-size:18px; font-weight:800; color:#0f172a;\">0</div></div>\n                <div style=\"padding:10px 12px; border-radius:12px; background:rgba(255,255,255,0.82); border:1px solid rgba(148,163,184,0.28);\"><div style=\"font-size:11px; color:#64748b;\">异常告警</div><div style=\"font-size:18px; font-weight:800; color:#0f172a;\">0</div></div>\n                <div style=\"padding:10px 12px; border-radius:12px; background:rgba(255,255,255,0.82); border:1px solid rgba(148,163,184,0.28);\"><div style=\"font-size:11px; color:#64748b;\">预算紧张员工</div><div style=\"font-size:18px; font-weight:800; color:#0f172a;\">0</div></div>\n                <div style=\"padding:10px 12px; border-radius:12px; background:rgba(255,255,255,0.82); border:1px solid rgba(148,163,184,0.28);\"><div style=\"font-size:11px; color:#64748b;\">周期任务数</div><div style=\"font-size:18px; font-weight:800; color:#0f172a;\">0</div></div>\n            </div>\n\n            <div class=\"btn-group-wrapper\">\n                <div class=\"btn-row\">\n                    <button onclick=\"openCreateCompanyModal()\" class=\"top-btn btn-create\">\ud83d\ude80 一键开设公司</button>\n                    <button onclick=\"openCeoModal()\" class=\"top-btn btn-deploy\">\ud83e\udde0 部署战略项目</button>\n                    <button onclick=\"openBoardModal()\" class=\"top-btn btn-board\">\ud83d\udcca 项目看板</button>\n                    <button onclick=\"openRoutineModal()\" class=\"top-btn btn-board\">⏰ 周期任务 <span id=\"deskAlertBadge\" style=\"display:none; margin-left:6px; padding:2px 8px; border-radius:999px; background:#dc2626; color:#fff; font-size:11px; font-weight:800;\">0</span></button>\n                    <button onclick=\"openSopModal()\" class=\"top-btn btn-sop\">\ud83d\udcd0 公司制度/SOP</button>\n                </div>\n                <div class=\"btn-row\">\n                    <button onclick=\"openBossMarket()\" class=\"top-btn btn-boss\">\ud83d\udcbc BOSS 直聘</button>\n                    <button onclick=\"clearAllMemory()\" class=\"top-btn btn-clear\">\ud83e\uddf9 一键清空记忆</button>\n                    <button onclick=\"bankruptcy()\" class=\"top-btn btn-bankrupt\">\ud83d\udd25 一键破产</button>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"guide-right\" style=\"background: rgba(255,255,255,0.85);\">\n            <div id=\"onboardingGuide\" style=\"color: #333; font-size: 0.95rem; line-height: 1.5;\">\n                <h3 style=\"margin-top:0; color:#2c3e50;\">\ud83c\udfe2 公司简介与工作指南</h3>\n                <p style=\"color:#666;\">HR 还未配置公司简介。点击左侧「一键开设公司」生成团队与指南。</p>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"desk-grid\" id=\"mainDeskGrid\"></div>\n\n    <div id=\"recruitModal\"\n        style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:9999; align-items:center; justify-content:center; backdrop-filter:blur(3px);\">\n        <div style=\"background:#fff; padding:25px; border-radius:15px; width:300px; display:flex; flex-direction:column; gap:12px; box-shadow:0 10px 30px rgba(0,0,0,0.2);\">\n            <h3 style=\"margin:0 0 5px 0; text-align:center; color:#333;\">\ud83e\uddd1 招募新员工</h3>\n            <input type=\"text\" id=\"recruitName\" placeholder=\"员工姓名\"\n                style=\"padding:10px; border:1px solid #ddd; border-radius:8px; outline:none; font-weight:bold;\">\n            <input type=\"text\" id=\"recruitRole\" placeholder=\"岗位名称\"\n                style=\"padding:10px; border:1px solid #ddd; border-radius:8px; outline:none;\">\n            <textarea id=\"recruitResume\" placeholder=\"简历摘要\"\n                style=\"padding:10px; border:1px solid #ddd; border-radius:8px; outline:none; font-size:12px; height:60px; resize:none; font-family:inherit;\"></textarea>\n            <input type=\"text\" id=\"recruitDesc\" placeholder=\"工作说明\"\n                style=\"padding:10px; border:1px solid #ddd; border-radius:8px; outline:none; font-size:12px;\">\n            <input type=\"text\" id=\"recruitUrl\" placeholder=\"节点 URL，例如 http://127.0.0.1:5050\"\n                style=\"padding:10px; border:1px solid #ddd; border-radius:8px; outline:none; font-size:12px;\" onblur=\"fetchNodeModels()\">\n            <details style=\"margin-top: 4px; font-size: 13px; color: #666; cursor: pointer;\">\n                <summary style=\"outline: none; font-weight: bold;\">模型与节点配置</summary>\n                <div style=\"margin-top: 8px;\">\n                    <label style=\"display:block; margin-bottom: 4px; font-size:11px;\">选择这个员工默认使用的模型</label>\n                    <select id=\"recruitModelIndex\" style=\"width:100%; padding:8px; border:1px solid #ddd; border-radius:8px; outline:none;\">\n                        <option value=\"0\">默认模型 (0)</option>\n                    </select>\n                    <div id=\"modelFetchStatus\" style=\"font-size:11px; color:#999; margin-top:4px;\">输入节点 URL 后会自动拉取可用模型。</div>\n                </div>\n            </details>\n\n            <div style=\"display:flex; gap:10px; margin-top:10px;\">\n                <button onclick=\"confirmRecruit()\" style=\"flex:1; padding:10px; background:#333; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">确认入职</button>\n                <button onclick=\"closeModal('recruitModal')\" style=\"flex:1; padding:10px; background:#eee; color:#666; border:none; border-radius:8px; cursor:pointer;\">取消</button>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"createCompanyModal\"\n        style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:10000; align-items:center; justify-content:center; backdrop-filter:blur(3px);\">\n        <div style=\"background:#fff; padding:25px; border-radius:15px; width:340px; display:flex; flex-direction:column; gap:12px; box-shadow:0 10px 30px rgba(0,0,0,0.2);\">\n            <h3 style=\"margin:0 0 5px 0; text-align:center; color:#333;\">\ud83c\udfe2 一键开设公司</h3>\n            <textarea id=\"companyDesc\" placeholder=\"请输入公司愿景或业务描述...\"\n                style=\"padding:10px; border:1px solid #ddd; border-radius:8px; outline:none; height:80px; resize:none; font-family:inherit;\"></textarea>\n            <input type=\"text\" id=\"masterNodeUrl\" placeholder=\"主节点地址，例如 http://127.0.0.1:5050\"\n                style=\"padding:10px; border:1px solid #ddd; border-radius:8px; outline:none; font-size:13px; font-family:monospace;\">\n            <div style=\"display:flex; gap:10px; margin-top:10px;\">\n                <button id=\"btnConfirmCreate\" onclick=\"confirmCreateCompany()\"\n                    style=\"flex:1; padding:10px; background:#2980b9; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">开始创建</button>\n                <button onclick=\"closeModal('createCompanyModal')\"\n                    style=\"flex:1; padding:10px; background:#eee; color:#666; border:none; border-radius:8px; cursor:pointer;\">取消</button>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"reportModal\" onclick=\"if(event.target===this) closeModal('reportModal')\">\n        <div class=\"report-content\">\n            <div class=\"report-header\">\n                <h3 id=\"reportTitle\" style=\"margin:0; color:#333;\">\ud83d\udcd8 工作报告</h3>\n                <button onclick=\"closeModal('reportModal')\" style=\"border:none; background:none; font-size:20px; cursor:pointer; color:#666;\">✕</button>\n            </div>\n            <div class=\"report-body\" id=\"reportMarkdown\"></div>\n            <div id=\"agentRuntimePanel\" style=\"display:none;\"></div>\n        </div>\n    </div>\n\n    <div id=\"deskAlertActionModal\" onclick=\"if(event.target===this) closeModal('deskAlertActionModal')\" style=\"display:none; position:fixed; inset:0; background:rgba(15,23,42,0.45); z-index:10070; align-items:center; justify-content:center; backdrop-filter:blur(4px);\">\n        <div style=\"background:#fff; width:min(420px, 92vw); border-radius:18px; padding:20px; box-shadow:0 18px 45px rgba(15,23,42,0.25); display:flex; flex-direction:column; gap:12px;\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center; gap:10px;\">\n                <h3 id=\"deskAlertActionTitle\" style=\"margin:0; color:#0f172a;\">工位异常快捷处理</h3>\n                <button onclick=\"closeModal('deskAlertActionModal')\" style=\"border:none; background:none; font-size:20px; cursor:pointer; color:#94a3b8;\">✕</button>\n            </div>\n            <div id=\"deskAlertActionMessage\" style=\"font-size:13px; color:#475569; line-height:1.7;\">正在整理该工位的异常信息...</div>\n            <div id=\"deskAlertSummaryCard\" style=\"display:flex; flex-direction:column; gap:8px; background:#f8fafc; border:1px solid #e2e8f0; border-radius:12px; padding:12px;\">\n                <div style=\"display:flex; justify-content:space-between; align-items:center; gap:8px;\">\n                    <strong style=\"font-size:13px; color:#0f172a;\">单员工异常合并摘要</strong>\n                    <span style=\"font-size:11px; color:#475569;\">优先级指引</span>\n                </div>\n                <div id=\"deskAlertSummaryHeadline\" style=\"font-size:12px; color:#334155; line-height:1.6;\">当前异常类型：none / 当前优先级：normal</div>\n                <div id=\"deskAlertSummaryMeta\" style=\"font-size:12px; color:#64748b; line-height:1.7;\">建议动作：打开异常面板继续确认。</div>\n            </div>\n            <div id=\"deskAlertActionMeta\" style=\"font-size:12px; color:#64748b; line-height:1.6; background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px; padding:10px;\">最近失败摘要：暂无 / critical 告警：否</div>\n            <div id=\"deskAlertActionTimeline\" style=\"display:flex; flex-direction:column; gap:8px; background:#fff; border:1px solid #e2e8f0; border-radius:12px; padding:12px;\">\n                <div style=\"display:flex; justify-content:space-between; align-items:center; gap:8px;\">\n                    <strong style=\"font-size:13px; color:#0f172a;\">最近 3 次执行</strong>\n                    <span style=\"font-size:11px; color:#64748b;\">执行时间线卡</span>\n                </div>\n                <div id=\"deskAlertActionTimelineSummary\" style=\"font-size:12px; color:#475569; line-height:1.6;\">最近成功：暂无 / 最近失败：暂无</div>\n                <div id=\"deskAlertActionTimelineList\" style=\"display:flex; flex-direction:column; gap:8px;\"></div>\n            </div>\n            <div id=\"deskAlertHeartbeatCard\" style=\"display:flex; flex-direction:column; gap:8px; background:#fffef7; border:1px solid #f5e7a1; border-radius:12px; padding:12px;\">\n                <div style=\"display:flex; justify-content:space-between; align-items:center; gap:8px;\">\n                    <strong style=\"font-size:13px; color:#0f172a;\">heartbeat 健康卡</strong>\n                    <span style=\"font-size:11px; color:#92400e;\">心跳专属详情</span>\n                </div>\n                <div id=\"deskAlertHeartbeatSummary\" style=\"font-size:12px; color:#475569; line-height:1.6;\">最近心跳：暂无 / 心跳来源：暂无 / 心跳状态：unknown</div>\n                <div id=\"deskAlertHeartbeatMeta\" style=\"font-size:12px; color:#64748b; line-height:1.7;\">heartbeat 异常说明：当前没有 heartbeat 异常。</div>\n            </div>\n            <div id=\"deskAlertActionButtons\" style=\"display:grid; grid-template-columns:1fr 1fr; gap:10px;\">\n                <button id=\"deskAlertRecoverBtn\" onclick=\"performDeskRecoverAction()\" style=\"padding:10px 14px; background:#2563eb; color:#fff; border:none; border-radius:10px; cursor:pointer; font-weight:bold;\">恢复任务</button>\n                <button id=\"deskAlertAckBtn\" onclick=\"performDeskAckAction()\" style=\"padding:10px 14px; background:#64748b; color:#fff; border:none; border-radius:10px; cursor:pointer; font-weight:bold;\">确认告警</button>\n                <button id=\"deskAlertViewLogBtn\" onclick=\"performDeskViewLogAction()\" style=\"padding:10px 14px; background:#10b981; color:#fff; border:none; border-radius:10px; cursor:pointer; font-weight:bold;\">查看日志</button>\n                <button id=\"deskAlertPanelBtn\" onclick=\"jumpToDeskAlerts()\" style=\"padding:10px 14px; background:#f59e0b; color:#fff; border:none; border-radius:10px; cursor:pointer; font-weight:bold;\">打开异常面板</button>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"deskTaskFocusModal\" class=\"desk-task-focus-modal\" onclick=\"if(event.target===this) closeModal('deskTaskFocusModal')\" style=\"display:none; position:fixed; inset:0; background:rgba(15,23,42,0.45); z-index:10080; align-items:center; justify-content:center; backdrop-filter:blur(4px);\">\n        <div style=\"background:#fff; width:min(460px, 92vw); border-radius:18px; padding:20px; box-shadow:0 18px 45px rgba(15,23,42,0.25); display:flex; flex-direction:column; gap:12px;\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center; gap:10px;\">\n                <h3 id=\"deskTaskFocusTitle\" style=\"margin:0; color:#0f172a;\">工位任务快捷面板</h3>\n                <button onclick=\"closeModal('deskTaskFocusModal')\" style=\"border:none; background:none; font-size:20px; cursor:pointer; color:#94a3b8;\">✕</button>\n            </div>\n            <div id=\"deskTaskFocusBody\" style=\"display:flex; flex-direction:column; gap:10px; color:#334155;\">\n                <div class=\"agent-inline-note\">正在整理最重要任务...</div>\n            </div>\n            <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:10px;\">\n                <button id=\"deskTaskFocusPrimaryBtn\" class=\"desk-task-focus-primary\" onclick=\"performDeskTaskPrimaryAction()\" style=\"padding:10px 14px; background:#2563eb; color:#fff; border:none; border-radius:10px; cursor:pointer; font-weight:bold;\">直接处理</button>\n                <button id=\"deskTaskFocusSecondaryBtn\" class=\"desk-task-focus-secondary\" onclick=\"performDeskTaskSecondaryAction()\" style=\"padding:10px 14px; background:#64748b; color:#fff; border:none; border-radius:10px; cursor:pointer; font-weight:bold;\">打开关联运行</button>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"agentRunModal\" class=\"agent-detail-modal\" onclick=\"if(event.target===this) document.getElementById('agentRunModal').style.display='none'\">\n        <div class=\"agent-detail-dialog\">\n            <div class=\"agent-detail-header\">\n                <h3 id=\"agentRunModalTitle\" style=\"margin:0; color:#0f172a;\">智能体运行详情</h3>\n                <button class=\"agent-run-btn ghost\" onclick=\"document.getElementById('agentRunModal').style.display='none'\">关闭</button>\n            </div>\n            <div id=\"agentRunModalBody\" style=\"color:#334155;\"></div>\n        </div>\n    </div>\n\n    <div id=\"taskModal\"\n        onclick=\"if(event.target===this) closeModal('taskModal')\"\n        style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:9999; align-items:center; justify-content:center; backdrop-filter:blur(3px);\">\n        <div style=\"background:#fff; padding:25px; border-radius:15px; width:340px; display:flex; flex-direction:column; gap:12px; box-shadow:0 10px 30px rgba(0,0,0,0.2);\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center; gap:12px;\">\n                <h3 id=\"taskModalTitle\" style=\"margin:0; text-align:center; color:#333; flex:1;\">下发工作任务</h3>\n                <button onclick=\"closeModal('taskModal')\" style=\"border:none; background:none; font-size:20px; cursor:pointer; color:#94a3b8; line-height:1;\">✕</button>\n            </div>\n            <textarea id=\"taskInput\" placeholder=\"请输入具体的需求指令...\"\n                style=\"padding:10px; border:1px solid #ddd; border-radius:8px; height:90px; resize:none; outline:none; font-family:inherit;\"></textarea>\n\n            <div id=\"taskModalSnapshotAuditCard\" class=\"task-modal-snapshot-audit\" style=\"display:none; flex-direction:column; gap:6px; background:#eff6ff; border:1px solid #bfdbfe; border-radius:10px; padding:10px;\">\n                <div id=\"taskModalSnapshotAuditSummary\" style=\"font-size:12px; font-weight:700; color:#1d4ed8;\">当前 snapshot decision：无</div>\n                <div id=\"taskModalSnapshotAuditMeta\" style=\"font-size:12px; color:#334155; line-height:1.5;\">当前没有沿用 control-plane decision。</div>\n                <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:6px; font-size:11px; color:#475569;\">\n                    <div id=\"taskModalSnapshotAuditSource\">来源：未设置</div>\n                    <div id=\"taskModalSnapshotAuditTask\">任务：未设置</div>\n                    <div id=\"taskModalSnapshotAuditEmployee\">员工：未设置</div>\n                    <div id=\"taskModalSnapshotAuditContract\">contract：未设置</div>\n                </div>\n                <div id=\"taskModalSnapshotAuditActions\" style=\"display:grid; grid-template-columns:1fr 1fr; gap:6px; margin-top:4px;\">\n                    <button id=\"taskModalSnapshotAuditUseCurrentBtn\" type=\"button\" onclick=\"renderTaskModalSnapshotAuditState()\" style=\"padding:7px 8px; border:none; border-radius:8px; background:#dbeafe; color:#1d4ed8; font-size:12px; cursor:pointer; font-weight:700;\">沿用当前决策</button>\n                    <button id=\"taskModalSnapshotAuditReviewBtn\" type=\"button\" onclick=\"mutateTaskModalSnapshotAuditDecision('review-first')\" style=\"padding:7px 8px; border:none; border-radius:8px; background:#fef3c7; color:#92400e; font-size:12px; cursor:pointer; font-weight:700;\">改为复核优先</button>\n                    <button id=\"taskModalSnapshotAuditDirectBtn\" type=\"button\" onclick=\"mutateTaskModalSnapshotAuditDecision('act-compatible')\" style=\"padding:7px 8px; border:none; border-radius:8px; background:#dcfce7; color:#166534; font-size:12px; cursor:pointer; font-weight:700;\">改为直接执行</button>\n                    <button id=\"taskModalSnapshotAuditClearBtn\" type=\"button\" onclick=\"mutateTaskModalSnapshotAuditDecision('clear')\" style=\"padding:7px 8px; border:none; border-radius:8px; background:#fee2e2; color:#b91c1c; font-size:12px; cursor:pointer; font-weight:700;\">清空决策</button>\n                </div>\n            </div>\n\n            <div style=\"display:flex; flex-direction:column; gap:8px; background:#f8fafc; border:1px dashed #cbd5e1; border-radius:10px; padding:10px;\">\n                <div style=\"font-size:12px; color:#475569; line-height:1.5;\">支持上传参考图片、文档、表格、PDF、PPT 等附件，员工会结合附件继续完成任务。</div>\n                <input id=\"taskAttachmentInput\" type=\"file\" multiple accept=\"image/*,.txt,.md,.json,.csv,.tsv,.html,.htm,.doc,.docx,.pdf,.ppt,.pptx,.xls,.xlsx\" onchange=\"handleTaskAttachmentsChanged(this)\" style=\"font-size:12px;\">\n                <div id=\"taskAttachmentList\" style=\"display:none; font-size:12px; color:#334155; background:#fff; border:1px solid #e2e8f0; border-radius:8px; padding:8px; max-height:110px; overflow:auto;\"></div>\n            </div>\n\n            <div style=\"display:flex; gap:10px; margin-top:12px;\">\n                <button id=\"taskModalConfirmBtn\" onclick=\"confirmTaskV2()\" style=\"flex:2; padding:12px; background:linear-gradient(135deg, #4a90e2, #357abd); color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold; font-size:15px; box-shadow: 0 4px 10px rgba(74,144,226,0.3);\">\ud83d\ude80 开始干活</button>\n                <button onclick=\"cancelEmployeeTask()\" style=\"flex:1; padding:12px; background:linear-gradient(135deg, #e74c3c, #c0392b); color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold; font-size:14px; box-shadow: 0 4px 10px rgba(231,76,60,0.3);\">\ud83d\uded1 中止任务</button>\n            </div>\n\n            <div style=\"display:grid; grid-template-columns: 1fr 1fr; gap:8px; margin-top:12px;\">\n                <button onclick=\"editEmployee()\" style=\"padding:10px; background:#f8f9fa; color:#2c3e50; border:1px solid #dee2e6; border-radius:8px; cursor:pointer; font-weight:bold;\">\ud83d\udcd8 修改信息</button>\n                <button onclick=\"clearEmployeeMemory()\" style=\"padding:10px; background:#fff3cd; color:#856404; border:1px solid #ffeeba; border-radius:8px; cursor:pointer; font-weight:bold;\">\ud83e\uddf9 清空记忆</button>\n                <button onclick=\"uploadToBoss()\" style=\"padding:10px; background:#f3e5f5; color:#8e44ad; border:1px solid #e1bee7; border-radius:8px; cursor:pointer; font-weight:bold;\">\ud83d\udce4 上传 BOSS</button>\n                <button onclick=\"fireEmployee()\" style=\"padding:10px; background:#fcf0f0; color:#c0392b; border:1px solid #f5c6cb; border-radius:8px; cursor:pointer; font-weight:bold;\">\ud83d\udd25 开除员工</button>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"bossModal\" style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:10050; align-items:center; justify-content:center; backdrop-filter:blur(3px);\">\n        <div style=\"background:#f8fafc; padding:25px; border-radius:15px; width:min(1100px, 90vw); max-height:85vh; display:flex; flex-direction:column; gap:12px; box-shadow:0 10px 30px rgba(0,0,0,0.2);\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n                <h3 style=\"margin:0; color:#059669; display: flex; align-items: center; gap: 8px;\">\ud83d\udcbc 人才市场</h3>\n                <button onclick=\"closeModal('bossModal')\" style=\"background:none; border:none; font-size:1.4em; cursor:pointer; color:#94a3b8;\">✕</button>\n            </div>\n            <input type=\"text\" id=\"bossSearchInput\" placeholder=\"\ud83d\udd0e 搜索姓名、岗位、技能...\" oninput=\"filterBossMarket()\" style=\"margin-bottom:12px; padding:10px; border:1px solid #cbd5e1; border-radius:8px; outline:none; font-size:14px; width:100%; box-sizing:border-box;\">\n            <div id=\"bossTalentList\" class=\"talent-list\"></div>\n        </div>\n    </div>\n\n    <div id=\"sopModal\" style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:10050; align-items:center; justify-content:center; backdrop-filter:blur(3px);\">\n        <div style=\"background:#fff; padding:25px; border-radius:15px; width:540px; display:flex; flex-direction:column; gap:12px; box-shadow:0 10px 30px rgba(0,0,0,0.2);\">\n            <h3 style=\"margin:0 0 5px 0; text-align:center; color:#333;\">\ud83d\udcd0 公司制度与工作流（SOP）</h3>\n            <p style=\"font-size:12px; color:#666; margin:0;\">这里的规则会同步给所有员工，后续执行任务时自动生效。</p>\n            <textarea id=\"sopInput\" placeholder=\"请输入公司制度、协作规则、审批流程等内容...\" style=\"padding:12px; border:1px solid #ddd; border-radius:8px; outline:none; height:180px; resize:none; font-family:inherit; font-size:13px; line-height:1.5;\"></textarea>\n            <div style=\"display:flex; gap:10px; margin-top:10px;\">\n                <button onclick=\"saveSopConfig()\" style=\"flex:1; padding:10px; background:#2c3e50; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">保存制度</button>\n                <button onclick=\"closeModal('sopModal')\" style=\"flex:1; padding:10px; background:#eee; color:#666; border:none; border-radius:8px; cursor:pointer;\">取消</button>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"routineModal\" onclick=\"if(event.target===this) closeModal('routineModal')\" style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:10050; align-items:center; justify-content:center; backdrop-filter:blur(5px);\">\n        <div style=\"background:#f8fafc; padding:25px; border-radius:15px; width:min(1180px, 92vw); max-height:88vh; display:flex; flex-direction:column; gap:16px; box-shadow:0 10px 30px rgba(0,0,0,0.2); overflow:hidden;\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center; border-bottom: 1px solid #e2e8f0; padding-bottom: 15px;\">\n                <div>\n                    <h3 style=\"margin:0; color:#1e293b; display:flex; align-items:center; gap:8px;\">⏰ 周期任务管理台</h3>\n                    <p style=\"margin:6px 0 0; font-size:12px; color:#64748b;\">集中管理巡检、日报、提醒与自动唤醒任务，保持 niuma 团队持续运转。</p>\n                </div>\n                <div style=\"display:flex; gap:10px;\">\n                    <button onclick=\"resetRoutineForm()\" style=\"padding:8px 14px; background:#2563eb; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">➕ 新增周期任务</button>\n                    <button onclick=\"closeModal('routineModal')\" style=\"background:none; border:none; font-size:1.4em; cursor:pointer; color:#94a3b8;\">✕</button>\n                </div>\n            </div>\n            <div style=\"display:grid; grid-template-columns:minmax(360px, 1.1fr) minmax(320px, 0.9fr); gap:16px; min-height:0; flex:1;\">\n                <div style=\"background:#fff; border:1px solid #e2e8f0; border-radius:14px; display:flex; flex-direction:column; min-height:0; overflow:hidden;\">\n                    <div style=\"display:flex; justify-content:space-between; align-items:center; padding:14px 16px; border-bottom:1px solid #e2e8f0;\">\n                        <div>\n                            <div style=\"font-weight:bold; color:#0f172a;\">任务列表</div>\n                            <div style=\"font-size:12px; color:#64748b;\">支持立即执行、编辑、删除任务，并查看上次/下次运行时间。</div>\n                        </div>\n                        <div id=\"routineSummaryBadge\" style=\"font-size:12px; color:#475569; background:#f8fafc; border:1px solid #e2e8f0; border-radius:999px; padding:6px 10px;\">正在读取...</div>\n                    </div>\n                    <div style=\"padding:16px; overflow:auto; display:flex; flex-direction:column; gap:12px; min-height:0;\">\n                        <div id=\"routineList\" style=\"display:flex; flex-direction:column; gap:12px;\"></div>\n                        <div style=\"display:grid; grid-template-columns:1fr 1fr 1fr; gap:12px;\">\n                            <div style=\"border:1px solid #e2e8f0; border-radius:12px; background:#f8fafc; padding:12px; min-height:180px;\">\n                                <div style=\"font-weight:bold; color:#0f172a; margin-bottom:8px;\">执行历史</div>\n                                <div id=\"routineHistoryList\" style=\"display:flex; flex-direction:column; gap:8px;\"></div>\n                            </div>\n                            <div style=\"border:1px solid #e2e8f0; border-radius:12px; background:#f8fafc; padding:12px; min-height:180px;\">\n                                <div style=\"font-weight:bold; color:#0f172a; margin-bottom:8px;\">心跳状态</div>\n                                <div id=\"routineHeartbeatSummary\" style=\"display:flex; flex-direction:column; gap:8px;\"></div>\n                            </div>\n                            <div style=\"border:1px solid #e2e8f0; border-radius:12px; background:#f8fafc; padding:12px; min-height:180px;\">\n                                <div style=\"font-weight:bold; color:#0f172a; margin-bottom:8px;\">异常告警</div>\n                                <div id=\"routineAlertsList\" style=\"display:flex; flex-direction:column; gap:8px;\"></div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div style=\"background:#fff; border:1px solid #e2e8f0; border-radius:14px; padding:18px; overflow:auto;\">\n                    <div style=\"display:flex; justify-content:space-between; align-items:center; gap:12px; margin-bottom:12px;\">\n                        <div>\n                            <div id=\"routineEditorTitle\" style=\"font-weight:bold; color:#0f172a;\">新增周期任务</div>\n                            <div style=\"font-size:12px; color:#64748b;\">可以配置员工、频率、提示词与下次运行时间。</div>\n                        </div>\n                        <div id=\"routineEditingHint\" style=\"font-size:12px; color:#2563eb; background:#eff6ff; border:1px solid #bfdbfe; border-radius:999px; padding:4px 10px;\">新建模式</div>\n                    </div>\n                    <input type=\"hidden\" id=\"routineIdInput\">\n                    <div style=\"display:flex; flex-direction:column; gap:12px;\">\n                        <label style=\"display:flex; flex-direction:column; gap:6px; font-size:13px; color:#334155;\">\n                            <span>任务名称</span>\n                            <input id=\"routineNameInput\" type=\"text\" placeholder=\"例如：每日项目巡检\" style=\"padding:10px 12px; border:1px solid #cbd5e1; border-radius:8px; outline:none; font-size:14px;\">\n                        </label>\n                        <label style=\"display:flex; flex-direction:column; gap:6px; font-size:13px; color:#334155;\">\n                            <span>负责员工</span>\n                            <select id=\"routineEmployeeInput\" style=\"padding:10px 12px; border:1px solid #cbd5e1; border-radius:8px; outline:none; font-size:14px; background:#fff;\"></select>\n                        </label>\n                        <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:10px;\">\n                            <label style=\"display:flex; flex-direction:column; gap:6px; font-size:13px; color:#334155;\">\n                                <span>触发间隔（分钟）</span>\n                                <input id=\"routineIntervalInput\" type=\"number\" min=\"1\" step=\"1\" placeholder=\"1440\" style=\"padding:10px 12px; border:1px solid #cbd5e1; border-radius:8px; outline:none; font-size:14px;\">\n                            </label>\n                            <label style=\"display:flex; flex-direction:column; gap:6px; font-size:13px; color:#334155;\">\n                                <span>下次运行时间</span>\n                                <input id=\"routineNextRunInput\" type=\"text\" placeholder=\"2026-04-16 09:00:00\" style=\"padding:10px 12px; border:1px solid #cbd5e1; border-radius:8px; outline:none; font-size:14px;\">\n                            </label>\n                        </div>\n                        <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:10px;\">\n                            <label style=\"display:flex; flex-direction:column; gap:6px; font-size:13px; color:#334155;\">\n                                <span>最大重试次数</span>\n                                <input id=\"routineMaxRetriesInput\" type=\"number\" min=\"0\" step=\"1\" placeholder=\"2\" style=\"padding:10px 12px; border:1px solid #cbd5e1; border-radius:8px; outline:none; font-size:14px;\">\n                            </label>\n                            <label style=\"display:flex; flex-direction:column; gap:6px; font-size:13px; color:#334155;\">\n                                <span>失败退避（分钟）</span>\n                                <input id=\"routineBackoffInput\" type=\"number\" min=\"1\" step=\"1\" placeholder=\"10\" style=\"padding:10px 12px; border:1px solid #cbd5e1; border-radius:8px; outline:none; font-size:14px;\">\n                            </label>\n                        </div>\n                        <label style=\"display:flex; align-items:center; gap:8px; font-size:13px; color:#334155; background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px; padding:10px 12px;\">\n                            <input id=\"routineEnabledInput\" type=\"checkbox\" checked>\n                            <span>启用中</span>\n                        </label>\n                        <label style=\"display:flex; flex-direction:column; gap:6px; font-size:13px; color:#334155;\">\n                            <span>执行提示词</span>\n                            <textarea id=\"routinePromptInput\" placeholder=\"请输入执行内容，例如：请检查项目看板、异常任务与最近运行记录，输出中文巡检报告。\" style=\"padding:12px; border:1px solid #cbd5e1; border-radius:8px; outline:none; min-height:180px; resize:vertical; font-family:inherit; font-size:13px; line-height:1.6;\"></textarea>\n                        </label>\n                        <div style=\"font-size:12px; color:#64748b; line-height:1.6; background:#f8fafc; border:1px dashed #cbd5e1; border-radius:10px; padding:10px 12px;\">\n                            建议写明确输出格式，例如“列出阻塞任务 / 新风险 / 建议动作”。如果留空下次运行时间，系统会按当前时间 + 间隔自动计算。\n                        </div>\n                        <div style=\"display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px;\">\n                            <button onclick=\"saveRoutineConfig()\" style=\"padding:10px 14px; background:#16a34a; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">\ud83d\udcbe 保存任务</button>\n                            <button onclick=\"runRoutineNow(document.getElementById('routineIdInput').value)\" style=\"padding:10px 14px; background:#f59e0b; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">⚡ 立即执行</button>\n                            <button onclick=\"deleteRoutineJob(document.getElementById('routineIdInput').value)\" style=\"padding:10px 14px; background:#ef4444; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">\ud83d\uddd1 删除任务</button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"boardModal\" style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:10050; align-items:center; justify-content:center; backdrop-filter:blur(5px);\">\n        <div style=\"background:#f8fafc; padding:25px; border-radius:15px; height:85vh; width:85vw; display:flex; flex-direction:column; box-shadow:0 10px 30px rgba(0,0,0,0.2);\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center; border-bottom: 1px solid #e2e8f0; padding-bottom: 15px;\">\n                <h3 style=\"margin:0; color:#1e293b; display: flex; align-items: center; gap: 8px;\">\ud83d\udcca 项目看板: <span id=\"boardProjectName\" style=\"color:#3b82f6;\">正在同步进度...</span></h3>\n                <div style=\"display:flex; gap: 10px;\">\n                    <button onclick=\"deleteProject()\" style=\"padding:6px 12px; background:#e74c3c; color:white; border:none; border-radius:6px; cursor:pointer; font-weight:bold;\">\ud83d\uddd1 清空</button>\n                    <button onclick=\"closeModal('boardModal')\" style=\"background:none; border:none; font-size:1.4em; cursor:pointer; color:#94a3b8;\">✕</button>\n                </div>\n            </div>\n            <div id=\"boardProjectList\" class=\"project-list-container\"></div>\n        </div>\n    </div>\n\n    <div id=\"ceoModal\" style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:10000; align-items:center; justify-content:center; backdrop-filter:blur(3px);\">\n        <div style=\"background:#fff; padding:25px; border-radius:15px; width:450px; display:flex; flex-direction:column; gap:12px; box-shadow:0 10px 30px rgba(0,0,0,0.2);\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n                <h3 style=\"margin:0; color:#2c3e50; font-size: 1.2rem;\">\ud83e\udde0 CEO 战略部署中心</h3>\n                <button onclick=\"closeModal('ceoModal')\" style=\"border:none; background:none; font-size:20px; cursor:pointer; color:#666;\">✕</button>\n            </div>\n            <p style=\"font-size:12px; color:#666; margin:0;\">请输入全局战略或新项目需求，提交后将交给 PM（ceo）拆解并同步到项目看板。</p>\n            <textarea id=\"ceoTaskInput\" placeholder=\"请输入战略目标、项目方向或执行需求...\" style=\"padding:12px; border:1px solid #ddd; border-radius:8px; outline:none; height:120px; resize:none; font-family:inherit; font-size:14px; background: #f8fafc;\"></textarea>\n            <div style=\"display:flex; gap:10px; margin-top:10px;\">\n                <button onclick=\"dispatchCeoTask()\" style=\"flex:1; padding:12px; background:linear-gradient(135deg, #16a085, #27ae60); color:#fff; border:none; border-radius:8px; font-weight:bold; cursor:pointer; box-shadow:0 4px 10px rgba(39,174,96,0.3); transition: transform 0.2s;\">\ud83d\ude80 一键发布战略并更新看板</button>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"strategyEditModal\" style=\"display:none; position:fixed; inset:0; background:rgba(0,0,0,0.6); z-index:10050; align-items:center; justify-content:center; backdrop-filter:blur(3px);\">\n        <div style=\"background:#f8fafc; padding:25px; border-radius:15px; width:550px; max-height: 80vh; display:flex; flex-direction:column; gap:15px; box-shadow:0 10px 30px rgba(0,0,0,0.2);\">\n            <div style=\"display:flex; justify-content:space-between; align-items:center; border-bottom: 1px solid #e2e8f0; padding-bottom: 10px;\">\n                <h3 style=\"margin:0; color:#2c3e50; font-size: 1.2rem;\">\ud83d\udee0 战略二次编排</h3>\n                <button onclick=\"closeModal('strategyEditModal')\" style=\"border:none; background:none; font-size:20px; cursor:pointer; color:#666;\">✕</button>\n            </div>\n            <div style=\"display: flex; align-items: center; gap: 10px;\">\n                <strong style=\"color: #475569; width: 80px;\">项目名称:</strong>\n                <input type=\"text\" id=\"editProjectName\" style=\"flex:1; padding:10px; border:1px solid #cbd5e1; border-radius:8px; outline:none; font-weight:bold; color:#1e293b;\">\n            </div>\n            <div style=\"flex:1; overflow-y:auto; padding-right: 5px; background: #fff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 10px;\" id=\"editTaskListContainer\"></div>\n            <div style=\"display:flex; gap:10px; margin-top:5px;\">\n                <button onclick=\"addStrategyTask()\" style=\"padding:10px 15px; background:#f1f5f9; color:#475569; border:1px solid #cbd5e1; border-radius:8px; font-weight:bold; cursor:pointer; transition: 0.2s;\">➕ 新增一项任务</button>\n                <div style=\"flex: 1;\"></div>\n                <button onclick=\"confirmAndDispatchStrategy()\" style=\"padding:10px 20px; background:linear-gradient(135deg, #16a085, #27ae60); color:#fff; border:none; border-radius:8px; font-weight:bold; cursor:pointer; box-shadow:0 4px 10px rgba(39,174,96,0.3);\">\ud83d\ude80 确认发布并执行</button>\n            </div>\n        </div>\n    </div>\n\n    <div id=\"loadingOverlay\" class=\"hr-loading-container\">\n        <div class=\"hr-spinner\"></div>\n        <div class=\"hr-loading-text\">HR 正在处理中...</div>\n        <div class=\"hr-loading-subtext\">这可能需要一点时间来同步公司配置、岗位信息和节点状态。<br>请稍等，系统会自动完成后续步骤。</div>\n    </div>\n\n    <div id=\"appDialogModal\" class=\"app-dialog-overlay\" onclick=\"if(event.target===this) closeModal('appDialogModal')\">\n        <div class=\"app-dialog-card\">\n            <div class=\"app-dialog-head\">\n                <div id=\"appDialogIcon\" class=\"app-dialog-icon info\">ℹ\ufe0f</div>\n                <div style=\"flex:1;\">\n                    <h3 id=\"appDialogTitle\" class=\"app-dialog-title\">系统提示</h3>\n                    <div id=\"appDialogMessage\" class=\"app-dialog-message\"></div>\n                </div>\n            </div>\n            <div class=\"app-dialog-foot\">\n                <button id=\"appDialogConfirm\" class=\"app-dialog-btn primary\" onclick=\"closeModal('appDialogModal')\">我知道了</button>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        let currentTargetDesk = null;\n        let currentTargetName = '';\n        let currentDeskTaskFocusContext = null;\n        const deskReports = {};\n        let routineManagerCache = [];\n        let routineHistoryCache = [];\n        let heartbeatCache = {};\n        let currentDeskAlertContext = null;\n        \n        function closeModal(id) {\n            const modal = document.getElementById(id);\n            modal.style.display = 'none';\n            if (id === 'reportModal') {\n                delete modal.dataset.employee;\n                delete modal.dataset.agentPanelCollapsed;\n                delete modal.dataset.followLatest;\n                delete modal.dataset.pinnedStageKeys;\n                delete modal.dataset.openStageKeys;\n                delete modal.dataset.worklogCardFilter;\n                delete modal.dataset.worklogStreamTab;\n                resetAgentRuntimePanel(true);\n            }\n        }\n\n        function showAppDialog(options) {\n            const modal = document.getElementById('appDialogModal');\n            const title = document.getElementById('appDialogTitle');\n            const message = document.getElementById('appDialogMessage');\n            const icon = document.getElementById('appDialogIcon');\n            const confirmBtn = document.getElementById('appDialogConfirm');\n            if (!modal || !title || !message || !icon || !confirmBtn) {\n                alert(typeof options === 'string' ? options : (options?.message || '系统提示'));\n                return;\n            }\n\n            const config = typeof options === 'string' ? { message: options } : (options || {});\n            const tone = String(config.tone || 'info').toLowerCase();\n            const toneMap = {\n                info: { icon: 'ℹ\ufe0f', button: 'primary' },\n                success: { icon: '✅', button: 'primary' },\n                warning: { icon: '⚠\ufe0f', button: 'warning' },\n                error: { icon: '❌', button: 'error' }\n            };\n            const currentTone = toneMap[tone] || toneMap.info;\n\n            title.textContent = config.title || '系统提示';\n            message.textContent = config.message || '';\n            icon.className = `app-dialog-icon ${tone}`;\n            icon.textContent = config.icon || currentTone.icon;\n            confirmBtn.className = `app-dialog-btn ${config.buttonTone || currentTone.button}`;\n            confirmBtn.textContent = config.confirmText || '我知道了';\n            modal.style.display = 'flex';\n        }\n\n        const DEFAULT_AGENT_BASE = 'http://127.0.0.1:5050';\n\n        function getAgentBaseForUser(user) {\n            try {\n                return normalizeAgentBaseUrl(window.teamConfig?.PeerNodes?.[user]?.Url || DEFAULT_AGENT_BASE);\n            } catch (_) {\n                return normalizeAgentBaseUrl(DEFAULT_AGENT_BASE);\n            }\n        }\n\n        async function fetchAgentJsonSafe(url, options) {\n            const res = await fetch(url, options);\n            if (!res.ok) {\n                throw new Error((await res.text()) || ('HTTP ' + res.status));\n            }\n            return await res.json();\n        }\n\n        function getRunIdFromObject(run) {\n            return run?.runId || run?.RunId || '';\n        }\n\n        function getPendingApproval(run) {\n            return run?.pendingApproval || run?.PendingApproval || null;\n        }\n\n        function getPendingApprovalId(run) {\n            const pending = getPendingApproval(run);\n            return String(pending?.approvalId || pending?.ApprovalId || '').trim();\n        }\n\n        function getBoardTaskLinkedRunId(task) {\n            const result = String(task?.result || task?.Result || '');\n            const marker = result.match(/agent-run:([a-z0-9_-]+)/i) || result.match(/Run ID[:：]\\s*`?([^\\s`]+)/i);\n            return marker ? String(marker[1] || '').trim() : '';\n        }\n\n        function runMatchesBoardTask(run, taskId, taskTitle, linkedRunId) {\n            const normalizedTaskId = String(taskId || '').trim();\n            const normalizedTitle = String(taskTitle || '').trim();\n            const normalizedLinkedRunId = String(linkedRunId || '').trim();\n            const runTaskId = String(run?.taskId || run?.TaskId || run?.boardTaskId || run?.BoardTaskId || '').trim();\n            const runId = getRunIdFromObject(run);\n            const runText = String(run?.taskText || run?.TaskText || '').trim();\n            if (normalizedTaskId && runTaskId && runTaskId === normalizedTaskId) return true;\n            if (normalizedLinkedRunId && runId && runId === normalizedLinkedRunId) return true;\n            return !!(normalizedTitle && runText.includes(normalizedTitle));\n        }\n\n        function findBoardTaskById(taskId) {\n            const normalizedTaskId = String(taskId || '').trim();\n            if (!normalizedTaskId) return null;\n            const projects = Array.isArray(window.latestBoardProjects) ? window.latestBoardProjects : [];\n            for (const project of projects) {\n                const tasks = Array.isArray(project?.tasks || project?.Tasks) ? (project.tasks || project.Tasks) : [];\n                const task = tasks.find(item => String(item?.id || item?.Id || '').trim() === normalizedTaskId);\n                if (task) return task;\n            }\n            return null;\n        }\n\n        async function findPendingApprovalRunForTask(task, employeeName) {\n            if (!employeeName) return null;\n            const runs = await fetchAgentJsonSafe('/api/agent/runs?user=' + encodeURIComponent(employeeName)).catch(() => []);\n            window.agentRunCacheByEmployee = window.agentRunCacheByEmployee || {};\n            window.agentRunCacheByEmployee[employeeName] = Array.isArray(runs) ? runs : [];\n            const taskId = String(task?.id || task?.Id || '').trim();\n            const taskTitle = String(task?.title || task?.Title || '').trim();\n            const linkedRunId = getBoardTaskLinkedRunId(task);\n            const list = Array.isArray(runs) ? runs : [];\n            const matched = list.find(run => getPendingApprovalId(run) && runMatchesBoardTask(run, taskId, taskTitle, linkedRunId));\n            if (matched) return matched;\n            if (!taskId && !taskTitle && !linkedRunId) return list.find(run => getPendingApprovalId(run)) || null;\n            return null;\n        }\n\n        function getStatusClass(status) {\n            return String(status || '').toLowerCase().replace(/[^a-z_]+/g, '') || 'unknown';\n        }\n\n        function getRunSteps(run) {\n            return Array.isArray(run?.steps) ? run.steps : (Array.isArray(run?.Steps) ? run.Steps : []);\n        }\n\n        function getStepText(step) {\n            return String(step?.ToolResult || step?.toolResult || step?.RawModelOutput || step?.rawModelOutput || step?.Error || step?.error || '').trim();\n        }\n\n        function getStepKindLabel(step) {\n            const kind = String(step?.Kind || step?.kind || '').toLowerCase();\n            if (kind === 'stdout') return '实时输出';\n            if (kind === 'watchdog') return '超时监控';\n            if (kind === 'heartbeat') return '处理中';\n            if (kind === 'chat') return '任务状态';\n            return kind || 'step';\n        }\n\n        function toChineseBubbleText(text, kind, fallbackText) {\n            const raw = String(text || '').trim();\n            const fallback = String(fallbackText || '').trim();\n            const hasChinese = /[\\u4e00-\\u9fff]/.test(raw);\n            const shortText = hasChinese ? raw.slice(0, 30) : '';\n            if (kind === 'watchdog') {\n                return shortText ? `异常：${shortText}` : '异常：任务执行超时或失败';\n            }\n            if (kind === 'stdout') {\n                return shortText ? `进展：${shortText}` : '进展：正在处理任务';\n            }\n            if (kind === 'heartbeat') {\n                return '进展：仍在处理中';\n            }\n            if (kind === 'chat') {\n                return shortText ? `状态：${shortText}` : (fallback || '状态：正在处理任务');\n            }\n            if (fallback) {\n                return /[\\u4e00-\\u9fff]/.test(fallback) ? fallback : '状态：处理中';\n            }\n            return '状态：处理中';\n        }\n\n        function getBubbleProcessText(run, fallbackText) {\n            const steps = getRunSteps(run);\n            for (let i = steps.length - 1; i >= 0; i--) {\n                const step = steps[i];\n                const kind = String(step?.Kind || step?.kind || '').toLowerCase();\n                const text = getStepText(step);\n                if (!text) continue;\n                if (kind === 'watchdog') return toChineseBubbleText(text, 'watchdog', fallbackText);\n                if (kind === 'stdout') return toChineseBubbleText(text, 'stdout', fallbackText);\n                if (kind === 'heartbeat') return toChineseBubbleText(text, 'heartbeat', fallbackText);\n                if (kind === 'chat') return toChineseBubbleText(text, 'chat', fallbackText);\n            }\n            return toChineseBubbleText('', '', fallbackText);\n        }\n\n        function normalizeAgentBaseUrl(rawUrl) {\n            return String(rawUrl || DEFAULT_AGENT_BASE || '').replace('127.0.0.1', 'localhost');\n        }\n\n        async function fetchAgentJsonWithFallback(base, path) {\n            const primaryBase = normalizeAgentBaseUrl(base);\n            try {\n                return await fetchAgentJsonSafe(primaryBase + path);\n            } catch (err) {\n                const fallbackBase = String(base || DEFAULT_AGENT_BASE || '');\n                if (!fallbackBase || fallbackBase === primaryBase) {\n                    throw err;\n                }\n                return await fetchAgentJsonSafe(fallbackBase + path);\n            }\n        }\n\n        function renderAgentStepPreview(run, maxItems = 4) {\n            const steps = getRunSteps(run)\n                .filter(step => ['stdout', 'watchdog', 'chat'].includes(String(step?.Kind || step?.kind || '').toLowerCase()))\n                .slice(-maxItems);\n            if (!steps.length) {\n                return '<div class=\"agent-inline-note\">暂无过程日志</div>';\n            }\n            const html = steps.map(step => {\n                const kind = String(step?.Kind || step?.kind || '').toLowerCase() || 'step';\n                return `\n                    <div class=\"agent-process-log-item ${escapeHtml(kind)}\">\n                        <div class=\"agent-process-log-meta\">${escapeHtml(getStepKindLabel(step))} / ${escapeHtml(step?.Timestamp || step?.timestamp || '')}</div>\n                        <div>${escapeHtml(getStepText(step))}</div>\n                    </div>`;\n            }).join('');\n            return `<div class=\"agent-process-preview\"><div class=\"agent-process-preview-title\"><span>实时过程日志</span><span>${steps.length} 条</span></div><div class=\"agent-process-log\">${html}</div></div>`;\n        }\n\n        function resetAgentRuntimePanel(hidden) {\n            const panel = document.getElementById('agentRuntimePanel');\n            if (!panel) return;\n            panel.innerHTML = '';\n            panel.style.display = hidden ? 'none' : 'block';\n            panel.className = hidden ? '' : 'agent-runtime-panel collapsed';\n        }\n\n        function isAgentPanelCollapsed() {\n            const reportModal = document.getElementById('reportModal');\n            return reportModal?.dataset?.agentPanelCollapsed !== 'false';\n        }\n\n        function setAgentPanelCollapsed(collapsed) {\n            const reportModal = document.getElementById('reportModal');\n            if (reportModal) {\n                reportModal.dataset.agentPanelCollapsed = collapsed ? 'true' : 'false';\n            }\n            const panel = document.getElementById('agentRuntimePanel');\n            if (!panel) return;\n            panel.classList.toggle('collapsed', collapsed);\n            panel.classList.toggle('expanded', !collapsed);\n            const toggle = panel.querySelector('.agent-runtime-toggle');\n            if (toggle) {\n                toggle.textContent = collapsed ? '展开智能体面板' : '收起智能体面板';\n            }\n        }\n\n        function toggleAgentRuntimePanel() {\n            setAgentPanelCollapsed(!isAgentPanelCollapsed());\n        }\n\n        function wrapAgentPanelContent(innerHtml) {\n            const collapsed = isAgentPanelCollapsed();\n            const buttonText = collapsed ? '展开智能体面板' : '收起智能体面板';\n            return `\n                <div class=\"agent-runtime-header\">\n                    <h4>智能体面板</h4>\n                    <button class=\"agent-runtime-toggle\" onclick=\"toggleAgentRuntimePanel()\">${buttonText}</button>\n                </div>\n                <div class=\"agent-runtime-body\">${innerHtml}</div>`;\n        }\n\n        function renderApprovalButtons(run, empName) {\n            const pending = getPendingApproval(run);\n            if (!pending) return '';\n            const approvalId = pending.approvalId || pending.ApprovalId || '';\n            if (!approvalId) return '';\n            const runId = getRunIdFromObject(run);\n            return `\n                <div class=\"agent-run-actions\">\n                    <button class=\"agent-run-btn warn\" onclick=\"approveAgentRun('${empName}','${runId}','${approvalId}')\">批准操作</button>\n                    <button class=\"agent-run-btn danger\" onclick=\"rejectAgentRun('${empName}','${runId}','${approvalId}')\">拒绝操作</button>\n                </div>`;\n        }\n\n        async function approveAgentRun(empName, runId, approvalId) {\n            await fetchAgentJsonSafe('/api/agent/approve?user=' + encodeURIComponent(empName), {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify({ runId, approvalId })\n            });\n            alert('已批准，智能体会继续执行。');\n        }\n\n        async function rejectAgentRun(empName, runId, approvalId) {\n            const reason = prompt('请输入拒绝原因：', '不允许执行该高风险系统操作。') || 'Rejected by operator.';\n            await fetchAgentJsonSafe('/api/agent/reject?user=' + encodeURIComponent(empName), {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify({ runId, approvalId, reason })\n            });\n            alert('已拒绝该操作。');\n        }\n\n        async function approveBoardTaskAgentApproval(taskId, employeeName, trigger) {\n            const button = trigger && trigger.tagName ? trigger : null;\n            const task = findBoardTaskById(taskId);\n            if (!task || !employeeName) {\n                alert('没有定位到审批，请先刷新项目看板后再试。');\n                return;\n            }\n            if (!confirm('批准该员工节点继续执行当前等待审批的系统操作？')) return;\n            const originalText = button ? button.textContent : '';\n            try {\n                if (button) {\n                    button.disabled = true;\n                    button.textContent = '批准中...';\n                }\n                const run = await findPendingApprovalRunForTask(task, employeeName);\n                const runId = getRunIdFromObject(run);\n                const approvalId = getPendingApprovalId(run);\n                if (!runId || !approvalId) throw new Error('没有找到该任务的待审批运行。');\n                await fetchAgentJsonSafe('/api/agent/approve?user=' + encodeURIComponent(employeeName), {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/json' },\n                    body: JSON.stringify({ runId, approvalId })\n                });\n                alert('已批准，员工节点会继续执行。');\n                await refreshGovernanceSurfacesAfterTaskAction(employeeName);\n            } catch (err) {\n                alert(err?.message || String(err));\n            } finally {\n                if (button && button.isConnected) {\n                    button.disabled = false;\n                    button.textContent = originalText || '批准继续';\n                }\n            }\n        }\n\n        async function rejectBoardTaskAgentApproval(taskId, employeeName, trigger) {\n            const button = trigger && trigger.tagName ? trigger : null;\n            const task = findBoardTaskById(taskId);\n            if (!task || !employeeName) {\n                alert('没有定位到审批，请先刷新项目看板后再试。');\n                return;\n            }\n            const reason = prompt('请输入拒绝原因：', '不允许执行该系统操作，请改用更安全的交付方式。') || '';\n            if (!reason.trim()) return;\n            const originalText = button ? button.textContent : '';\n            try {\n                if (button) {\n                    button.disabled = true;\n                    button.textContent = '拒绝中...';\n                }\n                const run = await findPendingApprovalRunForTask(task, employeeName);\n                const runId = getRunIdFromObject(run);\n                const approvalId = getPendingApprovalId(run);\n                if (!runId || !approvalId) throw new Error('没有找到该任务的待审批运行。');\n                await fetchAgentJsonSafe('/api/agent/reject?user=' + encodeURIComponent(employeeName), {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/json' },\n                    body: JSON.stringify({ runId, approvalId, reason: reason.trim() })\n                });\n                alert('已拒绝该系统操作。');\n                await refreshGovernanceSurfacesAfterTaskAction(employeeName);\n            } catch (err) {\n                alert(err?.message || String(err));\n            } finally {\n                if (button && button.isConnected) {\n                    button.disabled = false;\n                    button.textContent = originalText || '拒绝执行';\n                }\n            }\n        }\n\n        function getAdapterTypeDisplayLabel(adapterType) {\n            const normalized = String(adapterType || '').trim().toLowerCase();\n            if (normalized === 'hermes') return 'Hermes 员工节点';\n            if (normalized === 'localnode') return '标准员工节点';\n            if (!normalized) return '未识别节点';\n            return normalized;\n        }\n\n        function getHealthToneMeta(healthStatus) {\n            const normalized = String(healthStatus || '').trim().toLowerCase();\n            if (normalized === 'healthy') return { label: '健康', pillClass: 'health-healthy' };\n            if (normalized === 'running') return { label: '运行中', pillClass: 'health-running' };\n            if (normalized === 'error' || normalized === 'failed' || normalized === 'timeout') return { label: '异常', pillClass: 'health-error' };\n            if (normalized === 'warning') return { label: '预警', pillClass: 'health-warning' };\n            if (normalized === 'offline') return { label: '离线', pillClass: 'health-offline' };\n            return { label: normalized || '未知', pillClass: 'health-offline' };\n        }\n\n        function renderAgentCapabilitySection(profile) {\n            const capabilityBadges = (profile.capabilities || []).map(item => `<span class=\"agent-runtime-pill\">${escapeHtml(item)}</span>`).join('') || '<span class=\"agent-inline-note\">暂无能力标签</span>';\n            const supportItems = profile.supports || {};\n            const supportMap = [\n                supportItems.approvals ? '支持审批' : '不支持审批',\n                supportItems.attachments ? '支持附件' : '不支持附件',\n                supportItems.runs ? '支持运行详情' : '不支持运行详情',\n                supportItems.vision ? '支持视觉' : ''\n            ].filter(Boolean).map(label => `<span class=\"agent-runtime-pill completed\">${escapeHtml(label)}</span>`).join('') || '<span class=\"agent-inline-note\">暂无支持项</span>';\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>能力标签</h5>\n                    <div>${capabilityBadges}</div>\n                </div>\n                <div class=\"agent-runtime-section-card\">\n                    <h5>支持项</h5>\n                    <div>${supportMap}</div>\n                </div>`;\n        }\n\n        function renderAgentBudgetSection(budgetMonthly, budgetUsed, budgetStatusText, budgetLevel, latestRunCost, latestRunCurrency, latestRunModel, latestRunProvider, latestInputTokens, latestOutputTokens) {\n            const budgetPillClass = budgetLevel === 'hard-stop' ? 'budget-hard-stop' : budgetLevel === 'warning' ? 'budget-warning' : 'completed';\n            const budgetSettingText = budgetMonthly > 0 ? String(budgetMonthly) : '未设置';\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>预算状态</h5>\n                    <div style=\"margin-bottom:6px;\"><span class=\"agent-runtime-pill ${budgetPillClass}\">${escapeHtml(budgetStatusText)}</span></div>\n                    <div class=\"agent-runtime-stat\"><strong>本月预算</strong>：${escapeHtml(budgetSettingText)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>当前已用</strong>：${escapeHtml(budgetUsed.toFixed(2))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最近运行成本</strong>：${escapeHtml(latestRunCost.toFixed(2))} ${escapeHtml(latestRunCurrency)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最近模型</strong>：${escapeHtml(latestRunProvider || 'unknown')} / ${escapeHtml(latestRunModel || 'unknown')}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最近 Token</strong>：输入 ${escapeHtml(String(latestInputTokens))} / 输出 ${escapeHtml(String(latestOutputTokens))}</div>\n                </div>`;\n        }\n\n        function renderAgentHealthSection(healthInfo, heartbeatStatus, heartbeatMessage, lastHeartbeat) {\n            const tone = getHealthToneMeta(healthInfo.status || heartbeatStatus);\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>健康状态</h5>\n                    <div style=\"margin-bottom:6px;\"><span class=\"agent-runtime-pill ${tone.pillClass}\">${escapeHtml(tone.label)}</span></div>\n                    <div class=\"agent-runtime-stat\"><strong>最近心跳</strong>：${escapeHtml(lastHeartbeat)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>状态来源</strong>：${escapeHtml(healthInfo.source || 'worker')}</div>\n                    <div class=\"agent-runtime-stat\"><strong>说明</strong>：${escapeHtml(heartbeatMessage || '暂无说明')}</div>\n                </div>`;\n        }\n\n        function renderAgentIdentitySummary(profile, empName) {\n            const adapterTypeLabel = String(profile.adapterType || '').trim();\n            const adapterLabel = getAdapterTypeDisplayLabel(adapterTypeLabel);\n            const adapterClass = adapterTypeLabel ? `adapter-${adapterTypeLabel}` : '';\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>节点类型</h5>\n                    <div style=\"margin-bottom:6px;\"><span class=\"agent-runtime-pill ${adapterClass}\">${escapeHtml(adapterLabel)}</span></div>\n                    <div class=\"agent-runtime-stat\"><strong>员工</strong>：${escapeHtml(empName)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>工作区</strong>：${escapeHtml(profile.workspace || '')}</div>\n                </div>`;\n        }\n\n        function buildEmployeeTaskPostureSummary(empName) {\n            const projects = window.latestBoardProjects || [];\n            const assignedTasks = [];\n            projects.forEach(project => {\n                const tasks = Array.isArray(project?.tasks || project?.Tasks) ? (project.tasks || project.Tasks) : [];\n                tasks.forEach(task => {\n                    if (String(task?.assignee || task?.Assignee || '').trim() === String(empName || '').trim()) {\n                        assignedTasks.push({ project, task });\n                    }\n                });\n            });\n            const inReviewTasks = assignedTasks.filter(item => String(item.task?.status || item.task?.Status || '').trim().toLowerCase() === 'in_review');\n            const blockedTasks = assignedTasks.filter(item => String(item.task?.status || item.task?.Status || '').trim().toLowerCase() === 'blocked');\n            const topPriorityTask = assignedTasks[0] || null;\n            const latestRunTask = assignedTasks.find(item => findLatestRunForTask(item.task, empName)) || null;\n            const recommendedTask = assignedTasks.map(item => ({ ...item, recommendation: buildTaskGovernanceRecommendation(item.task, empName) }))\n                .sort((a, b) => {\n                    const score = { '先升级给上级': 5, '先恢复执行': 4, '先通知审核责任人': 3, '先提交审核': 2, '先补充评论 / 上下文': 1 };\n                    return (score[b.recommendation?.action] || 0) - (score[a.recommendation?.action] || 0);\n                })[0] || null;\n            return {\n                assignedTasks,\n                inReviewCount: inReviewTasks.length,\n                blockedCount: blockedTasks.length,\n                topPriorityTask,\n                latestRunTask,\n                recommendedTask\n            };\n        }\n\n        function renderAgentTaskPostureSection(empName) {\n            const summary = buildEmployeeTaskPostureSummary(empName);\n            const currentTaskCount = summary.assignedTasks.length;\n            const topPriorityTask = summary.topPriorityTask ? String(summary.topPriorityTask.task?.title || summary.topPriorityTask.task?.Title || '未命名任务') : '暂无';\n            const latestRunTask = summary.latestRunTask ? String(summary.latestRunTask.task?.title || summary.latestRunTask.task?.Title || '未命名任务') : '暂无';\n            const recommendedAction = summary.recommendedTask?.recommendation?.action || '暂无';\n            const recommendedTaskTitle = summary.recommendedTask ? String(summary.recommendedTask.task?.title || summary.recommendedTask.task?.Title || '未命名任务') : '暂无';\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>任务态势</h5>\n                    <div class=\"agent-runtime-stat\"><strong>当前负责任务</strong>：${escapeHtml(String(currentTaskCount))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>待审核任务数</strong>：${escapeHtml(String(summary.inReviewCount))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>阻塞任务数</strong>：${escapeHtml(String(summary.blockedCount))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最高优先级任务</strong>：${escapeHtml(topPriorityTask)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最近运行对应任务</strong>：${escapeHtml(latestRunTask)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>当前最需要处理</strong>：${escapeHtml(recommendedTaskTitle)} / ${escapeHtml(recommendedAction)}</div>\n                </div>`;\n        }\n\n        async function renderAgentPanelForEmployee(empName) {\n            const panel = document.getElementById('agentRuntimePanel');\n            if (!panel || !empName) return;\n\n            panel.style.display = 'block';\n            panel.className = isAgentPanelCollapsed() ? 'agent-runtime-panel collapsed' : 'agent-runtime-panel expanded';\n            panel.innerHTML = wrapAgentPanelContent('<div class=\"agent-inline-note\">正在加载员工档案、记忆和运行记录...</div>');\n\n            try {\n                const [profile, runs, heartbeats, routineHistory, routines] = await Promise.all([\n                    fetchAgentJsonSafe('/api/agent/profile?user=' + encodeURIComponent(empName)),\n                    fetchAgentJsonSafe('/api/agent/runs?user=' + encodeURIComponent(empName)),\n                    fetch('/api/heartbeat').then(r => r.ok ? r.json() : {}),\n                    fetch('/api/routines/history').then(r => r.ok ? r.json() : []),\n                    fetch('/api/routines').then(r => r.ok ? r.json() : [])\n                ]);\n\n                window.agentRunCacheByEmployee = window.agentRunCacheByEmployee || {};\n                window.agentRunCacheByEmployee[empName] = Array.isArray(runs) ? runs : [];\n                const latestRunForPanel = Array.isArray(runs) && runs.length ? runs[0] : null;\n                if (String(latestRunForPanel?.status || latestRunForPanel?.Status || '').toLowerCase() === 'running') {\n                    setAgentPanelCollapsed(false);\n                    panel.className = 'agent-runtime-panel expanded';\n                }\n\n                const memoryCards = (profile.recentMemory || []).map(item => `\n                    <div class=\"agent-runtime-card\">\n                        <strong>${escapeHtml(item.date)}</strong>\n                        <div style=\"white-space:pre-wrap; font-size:12px;\">${escapeHtml(item.content)}</div>\n                    </div>`).join('') || '<div class=\"agent-inline-note\">暂无近期记忆</div>';\n\n                const adapterTypeLabel = String(profile.adapterType || '').trim();\n                const configNode = window.teamConfig?.PeerNodes?.[empName] || {};\n                const orgSummary = [`汇报对象：${profile.reportsTo || configNode.ReportsTo || configNode.reportsTo || '无'}`, `直属下级：${(Object.entries(window.teamConfig?.PeerNodes || {}).filter(([childName, childInfo]) => (childInfo.ReportsTo || childInfo.reportsTo) === empName).map(([childName]) => childName).join('、') || '无')}`, `组织关系：${buildEmployeeChainOfCommand(empName).join(' -> ') || '无'}`].join(' / ');\n                const budgetMonthly = Number(configNode.BudgetMonthly || configNode.budgetMonthly || profile.budgetMonthly || 0);\n                const budgetUsed = (runs || []).reduce((sum, run) => sum + Number(run.estimatedCost || run.EstimatedCost || 0), Number(configNode.BudgetUsed || configNode.budgetUsed || profile.budgetUsed || 0));\n                const budgetSoftRatio = Number(configNode.BudgetSoftLimitRatio || configNode.budgetSoftLimitRatio || 0.8);\n                const budgetHardRatio = Number(configNode.BudgetHardLimitRatio || configNode.budgetHardLimitRatio || 1.0);\n                const budgetLevel = budgetMonthly > 0 && budgetUsed >= budgetMonthly * budgetHardRatio ? 'hard-stop' : budgetMonthly > 0 && budgetUsed >= budgetMonthly * budgetSoftRatio ? 'warning' : 'normal';\n                const budgetStatusText = budgetLevel === 'hard-stop' ? '预算已耗尽' : budgetLevel === 'warning' ? '预算紧张' : '预算正常';\n                const latestRunCost = Number((runs || [])[0]?.estimatedCost || (runs || [])[0]?.EstimatedCost || 0);\n                const latestRunCurrency = String((runs || [])[0]?.costCurrency || (runs || [])[0]?.CostCurrency || 'USD');\n                const latestRunModel = String((runs || [])[0]?.model || (runs || [])[0]?.Model || '');\n                const latestRunProvider = String((runs || [])[0]?.provider || (runs || [])[0]?.Provider || '');\n                const latestInputTokens = Number((runs || [])[0]?.inputTokens || (runs || [])[0]?.InputTokens || 0);\n                const latestOutputTokens = Number((runs || [])[0]?.outputTokens || (runs || [])[0]?.OutputTokens || 0);\n                const healthInfo = profile.health || {};\n                const employeeHeartbeat = heartbeats?.[empName] || {};\n                const lastHeartbeat = healthInfo.lastSeenAt || employeeHeartbeat.last_seen_at || employeeHeartbeat.LastSeenAt || '暂无';\n                const heartbeatStatus = healthInfo.status || employeeHeartbeat.last_status || employeeHeartbeat.LastStatus || 'unknown';\n                const heartbeatMessage = healthInfo.message || employeeHeartbeat.last_message || employeeHeartbeat.LastMessage || '暂无心跳说明';\n                const employeeRoutines = (Array.isArray(routines) ? routines : []).filter(item => String(item.employee || item.Employee || '') === String(empName));\n                const employeeRoutineRuns = (Array.isArray(routineHistory) ? routineHistory : []).filter(item => String(item.employee || item.Employee || '') === String(empName)).slice(0, 3);\n                const latestRoutineRun = employeeRoutineRuns[0] || null;\n                const routineSummaryText = employeeRoutines.length\n                    ? `周期任务：${employeeRoutines.map(item => item.name || item.Name || '未命名任务').join('、')}`\n                    : '周期任务：暂无例行任务记录';\n                const failureSummaryText = employeeRoutines.length\n                    ? `连续失败：${employeeRoutines.map(item => `${item.name || item.Name || '未命名任务'} ${item.consecutive_failures ?? item.ConsecutiveFailures ?? 0} 次`).join(' / ')}`\n                    : '连续失败：0';\n                const alertSummaryText = employeeRoutines.length\n                    ? `告警级别：${employeeRoutines.map(item => `${item.name || item.Name || '未命名任务'} ${item.alert_level || item.AlertLevel || 'normal'}`).join(' / ')}`\n                    : '告警级别：normal';\n                const latestRoutineSummary = latestRoutineRun\n                    ? `最近例行执行：${latestRoutineRun.routine_name || latestRoutineRun.RoutineName || '未命名任务'} / ${latestRoutineRun.status || latestRoutineRun.Status || 'unknown'} / ${latestRoutineRun.started_at || latestRoutineRun.StartedAt || '未知时间'}`\n                    : '最近例行执行：暂无';\n                const alertHandleHint = (employeeRoutines.some(item => ['warning', 'critical'].includes(String(item.alert_level || item.AlertLevel || '').toLowerCase())) || ['warning', 'critical'].includes(String(employeeHeartbeat.alert_level || employeeHeartbeat.AlertLevel || '').toLowerCase()))\n                    ? '点击处理异常：可直接从工位气泡进入快捷菜单。'\n                    : '点击处理异常：当前无异常';\n                const identitySummary = renderAgentIdentitySummary(profile, empName);\n                const capabilitySection = renderAgentCapabilitySection(profile);\n                const budgetSummary = renderAgentBudgetSection(budgetMonthly, budgetUsed, budgetStatusText, budgetLevel, latestRunCost, latestRunCurrency, latestRunModel, latestRunProvider, latestInputTokens, latestOutputTokens);\n                const healthSummary = renderAgentHealthSection(healthInfo, heartbeatStatus, heartbeatMessage, lastHeartbeat);\n\n                const runCards = (runs || []).slice(0, 6).map(run => {\n                    const previewHtml = renderAgentStepPreview(run, 3);\n                    const runCost = Number(run.estimatedCost || run.EstimatedCost || 0);\n                    const runCurrency = String(run.costCurrency || run.CostCurrency || 'USD');\n                    const runModel = String(run.model || run.Model || '');\n                    const runProvider = String(run.provider || run.Provider || '');\n                    return `\n                    <div class=\"agent-run-item\">\n                        <div class=\"agent-run-item-title\">${escapeHtml(run.taskText)}</div>\n                        <div class=\"agent-run-item-meta\">\n                            <span class=\"agent-runtime-pill ${getStatusClass(run.status)}\">${escapeHtml(run.status)}</span>\n                            <span>${escapeHtml(run.updatedAt || '')}</span>\n                        </div>\n                        <div style=\"white-space:pre-wrap; font-size:12px; color:#475569;\">${escapeHtml(run.finalContent || run.lastError || '')}</div>\n                        <div class=\"agent-inline-note\" style=\"margin-top:6px;\">成本：${escapeHtml(runCost.toFixed(2))} ${escapeHtml(runCurrency)}</div>\n                        <div class=\"agent-inline-note\" style=\"margin-top:4px;\">模型：${escapeHtml(runProvider || 'unknown')} / ${escapeHtml(runModel || 'unknown')}</div>\n                        ${previewHtml}\n                        <div class=\"agent-run-actions\" style=\"margin-top:8px;\">\n                            <button class=\"agent-run-btn primary\" onclick=\"openAgentRun('${empName}','${getRunIdFromObject(run)}')\">查看运行详情</button>\n                        </div>\n                        ${renderApprovalButtons(run, empName)}\n                    </div>`;\n                }).join('') || '<div class=\"agent-inline-note\">暂无运行记录</div>';\n\n                const toolBadges = (profile.tools || []).map(tool => `\n                    <span class=\"agent-runtime-pill ${tool.requiresApproval ? 'waiting_approval' : 'completed'}\">${escapeHtml(tool.label || tool.name)}</span>\n                `).join('');\n\n                panel.innerHTML = wrapAgentPanelContent(`\n                    <div class=\"agent-runtime-grid\">\n                        <div class=\"agent-runtime-card\">\n                            <strong>员工档案</strong>\n                            <div class=\"agent-inline-note\" style=\"margin-bottom:8px;\">${escapeHtml(orgSummary)}</div>\n                            <div class=\"agent-runtime-section-grid\">${identitySummary}${healthSummary}${budgetSummary}${renderAgentTaskPostureSection(empName)}${capabilitySection}</div>\n                            <div style=\"white-space:pre-wrap; font-size:12px; margin-top:10px;\">${escapeHtml(profile.identity || '')}</div>\n                            <div style=\"margin-top:10px; display:flex; flex-wrap:wrap;\">${toolBadges}</div>\n                        </div>\n                        <div>\n                            <div class=\"agent-runtime-card\" style=\"margin-bottom:12px;\">\n                                <strong>最近记忆</strong>\n                                ${memoryCards}\n                            </div>\n                            <div class=\"agent-runtime-card\">\n                                <strong>最近运行</strong>\n                                <div class=\"agent-run-list\">${runCards}</div>\n                            </div>\n                        </div>\n                    </div>`);\n                setAgentPanelCollapsed(isAgentPanelCollapsed());\n            } catch (err) {\n                panel.innerHTML = wrapAgentPanelContent(`<div class=\"agent-inline-note\" style=\"color:#b91c1c;\">加载失败：${escapeHtml(err?.message || String(err))}</div>`);\n                setAgentPanelCollapsed(isAgentPanelCollapsed());\n            }\n        }\n\n        function renderAgentRunControlSummary(run, empName) {\n            const provider = String(run.Provider || run.provider || 'unknown');\n            const model = String(run.Model || run.model || 'unknown');\n            const inputTokens = Number(run.InputTokens || run.inputTokens || 0);\n            const outputTokens = Number(run.OutputTokens || run.outputTokens || 0);\n            const estimatedCost = Number(run.EstimatedCost || run.estimatedCost || 0);\n            const costCurrency = String(run.CostCurrency || run.costCurrency || 'USD');\n            const adapterType = String(run.AdapterType || run.adapterType || window.teamConfig?.PeerNodes?.[empName]?.AdapterType || '').toLowerCase();\n            const adapterLabel = getAdapterTypeDisplayLabel(adapterType);\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>运行控制卡</h5>\n                    <div class=\"agent-runtime-stat\"><strong>供应方 / 模型</strong>：${escapeHtml(provider)} / ${escapeHtml(model)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>Token 使用</strong>：输入 ${escapeHtml(String(inputTokens))} / 输出 ${escapeHtml(String(outputTokens))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>成本估算</strong>：${escapeHtml(estimatedCost.toFixed(2))} ${escapeHtml(costCurrency)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>节点类型</strong>：${escapeHtml(adapterLabel)}</div>\n                </div>`;\n        }\n\n        function renderAgentRunRiskSummary(run, empName) {\n            const pendingApproval = run.PendingApproval || run.pendingApproval;\n            const hasApproval = !!pendingApproval;\n            const riskText = hasApproval ? '需人工审批 / 高风险动作' : '当前未检测到高风险动作';\n            const healthSource = run.Health || run.health || {};\n            const healthTone = getHealthToneMeta(healthSource.status || (String(run.Status || run.status || '').toLowerCase() === 'running' ? 'running' : 'healthy'));\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>风险动作</h5>\n                    <div style=\"margin-bottom:6px;\"><span class=\"agent-runtime-pill ${healthTone.pillClass}\">${escapeHtml(healthTone.label)}</span></div>\n                    <div class=\"agent-runtime-stat\"><strong>健康摘要</strong>：${escapeHtml(healthSource.message || healthTone.label)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>审批状态</strong>：${escapeHtml(hasApproval ? '需人工审批' : '无需审批')}</div>\n                    <div class=\"agent-runtime-stat\"><strong>高风险动作</strong>：${escapeHtml(riskText)}</div>\n                </div>`;\n        }\n\n        function renderAgentRunArtifactSummary(run) {\n            const artifacts = run.Artifacts || run.artifacts || [];\n            const latestArtifact = artifacts[0] || null;\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>产物摘要</h5>\n                    <div class=\"agent-runtime-stat\"><strong>产物数量</strong>：${escapeHtml(String(artifacts.length))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最近产物</strong>：${escapeHtml(latestArtifact ? (latestArtifact.Label || latestArtifact.label || latestArtifact.Url || latestArtifact.url || '未命名产物') : '暂无产物')}</div>\n                </div>`;\n        }\n\n        function renderAgentRunStepSummary(run) {\n            const steps = run.Steps || run.steps || [];\n            const latestStep = steps.length ? steps[steps.length - 1] : null;\n            const latestTool = steps.slice().reverse().find(step => String(step.Tool || step.tool || '').trim()) || null;\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>步骤摘要</h5>\n                    <div class=\"agent-runtime-stat\"><strong>步骤数量</strong>：${escapeHtml(String(steps.length))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最近工具</strong>：${escapeHtml(latestTool ? (latestTool.Tool || latestTool.tool || '未知工具') : '暂无')}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最后一步</strong>：${escapeHtml(latestStep ? (latestStep.Status || latestStep.status || latestStep.Kind || latestStep.kind || '未知') : '暂无')}</div>\n                </div>`;\n        }\n\n        function renderAgentRunMetaSection(run, empName) {\n            return `<div class=\"agent-runtime-section-grid\">${renderAgentRunControlSummary(run, empName)}${renderAgentRunRiskSummary(run, empName)}${renderAgentRunArtifactSummary(run)}${renderAgentRunStepSummary(run)}${renderAgentRunTaskContextSection(run, empName)}</div>`;\n        }\n\n        function normalizeRunTaskBindingText(text) {\n            return String(text || '')\n                .toLowerCase()\n                .replace(/[\\r\\n\\t]+/g, ' ')\n                .replace(/[\"'“”‘’`]/g, ' ')\n                .replace(/[()（）\\[\\]【】{}<>]/g, ' ')\n                .replace(/[,:：;；|/\\\\-]+/g, ' ')\n                .replace(/\\s+/g, ' ')\n                .trim();\n        }\n\n        function buildRunTaskBindingCandidates(run, tasks, empName) {\n            const normalizedTaskId = String(run?.taskId || run?.TaskId || run?.boardTaskId || run?.BoardTaskId || '').trim().toLowerCase();\n            const normalizedRunTaskText = normalizeRunTaskBindingText(run?.taskText || run?.TaskText || '');\n            const normalizedEmployeeName = String(empName || '').trim().toLowerCase();\n            return (Array.isArray(tasks) ? tasks : []).map(task => {\n                const candidateTaskId = String(task?.id || task?.Id || '').trim().toLowerCase();\n                const candidateTitle = String(task?.title || task?.Title || '').trim();\n                const normalizedCandidateTitle = normalizeRunTaskBindingText(candidateTitle);\n                const candidateAssignee = String(task?.assignee || task?.Assignee || '').trim().toLowerCase();\n                let score = 0;\n                let matchMode = '';\n                if (normalizedTaskId && candidateTaskId === normalizedTaskId) {\n                    score = 100;\n                    matchMode = 'task-id';\n                } else if (normalizedEmployeeName && candidateAssignee === normalizedEmployeeName && normalizedCandidateTitle && normalizedRunTaskText) {\n                    if (normalizedRunTaskText === normalizedCandidateTitle) {\n                        score = 80;\n                        matchMode = 'title-exact';\n                    } else if (normalizedRunTaskText.startsWith(`${normalizedCandidateTitle} `) || normalizedRunTaskText.endsWith(` ${normalizedCandidateTitle}`)) {\n                        score = 60;\n                        matchMode = 'title-edge';\n                    } else if (normalizedRunTaskText.includes(` ${normalizedCandidateTitle} `)) {\n                        score = 40;\n                        matchMode = 'title-contained';\n                    }\n                }\n                return { task, score, matchMode, normalizedTitle: normalizedCandidateTitle };\n            }).filter(item => item.score > 0);\n        }\n\n        function selectRunTaskBindingCandidate(candidates) {\n            const sorted = (Array.isArray(candidates) ? candidates : [])\n                .slice()\n                .sort((left, right) => right.score - left.score || right.normalizedTitle.length - left.normalizedTitle.length);\n            if (!sorted.length) return null;\n            const best = sorted[0];\n            if (best.matchMode === 'task-id') return best;\n            if (best.matchMode === 'title-contained' && sorted.length > 1) return null;\n            const competing = sorted.filter(item => item !== best && item.score === best.score);\n            if (competing.length) return null;\n            return best;\n        }\n\n        function findBoardTaskByRun(run, empName) {\n            const projects = window.latestBoardProjects || [];\n            const allCandidates = projects.flatMap(project => {\n                const tasks = Array.isArray(project?.tasks || project?.Tasks) ? (project.tasks || project.Tasks) : [];\n                return buildRunTaskBindingCandidates(run, tasks, empName).map(candidate => ({ ...candidate, project }));\n            });\n            const selectedCandidate = selectRunTaskBindingCandidate(allCandidates);\n            return selectedCandidate ? { project: selectedCandidate.project, task: selectedCandidate.task } : null;\n        }\n\n        function jumpToBoardTask(taskId, empName) {\n            const normalizedTaskId = String(taskId || '').trim();\n            if (!normalizedTaskId) return;\n            const taskRow = document.querySelector(`.task-row[data-task-id=\"${CSS.escape(normalizedTaskId)}\"]`);\n            if (!taskRow) {\n                showAppDialog({ tone: 'warning', title: '没有定位到任务', message: `当前看板中没有找到任务 ${normalizedTaskId}，请先刷新项目看板。` });\n                return;\n            }\n            const taskList = taskRow.closest('.task-list');\n            if (taskList) taskList.style.display = 'block';\n            const projectHeader = taskList?.previousElementSibling;\n            if (projectHeader?.classList?.contains('project-header')) {\n                projectHeader.classList.add('expanded');\n                const icon = projectHeader.querySelector('.toggle-icon');\n                if (icon) icon.textContent = '▼';\n            }\n            taskRow.style.boxShadow = '0 0 0 3px rgba(59, 130, 246, 0.18)';\n            taskRow.style.borderRadius = '12px';\n            taskRow.scrollIntoView({ behavior: 'smooth', block: 'center' });\n            setTimeout(() => {\n                taskRow.style.boxShadow = '';\n                taskRow.style.borderRadius = '';\n            }, 2200);\n            if (empName) {\n                showAppDialog({ tone: 'success', title: '已跳回任务看板', message: `已定位到 ${empName} 的任务 ${normalizedTaskId}。` });\n            }\n        }\n\n        function openBoardTaskLineageFromRun(taskId, empName) {\n            const normalizedTaskId = String(taskId || '').trim();\n            if (!normalizedTaskId) return;\n            jumpToBoardTask(normalizedTaskId, empName);\n            const lineageCard = document.getElementById(`lineage-card-${normalizedTaskId}`);\n            if (lineageCard && !lineageCard.classList.contains('expanded')) {\n                lineageCard.classList.add('expanded');\n            }\n            showAppDialog({ tone: 'success', title: '已打开任务目标链', message: `已展开任务 ${normalizedTaskId} 的目标链。` });\n        }\n\n        function renderAgentRunTaskContextSection(run, empName) {\n            const matched = findBoardTaskByRun(run, empName);\n            const taskId = String(run?.taskId || run?.TaskId || run?.boardTaskId || run?.BoardTaskId || '').trim();\n            if (!matched) {\n                return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>任务上下文</h5>\n                    <div class=\"agent-runtime-stat\"><strong>关联任务</strong>：${escapeHtml(taskId || '未关联')}</div>\n                    <div class=\"agent-runtime-stat\"><strong>所属项目</strong>：未定位</div>\n                    <div class=\"agent-runtime-stat\"><strong>项目目标</strong>：暂无</div>\n                    <div class=\"agent-runtime-stat\"><strong>当前任务上下文</strong>：暂无可用任务上下文</div>\n                </div>`;\n            }\n            const task = matched.task;\n            const project = matched.project;\n            const lineage = buildBoardTaskLineageSummary(task, project);\n            const normalizedTaskId = String(task?.id || task?.Id || taskId || '').trim();\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>任务上下文</h5>\n                    <div class=\"agent-runtime-stat\"><strong>关联任务</strong>：${escapeHtml(String(task?.title || task?.Title || normalizedTaskId || '未命名任务'))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>所属项目</strong>：${escapeHtml(String(project?.project_name || project?.ProjectName || '未命名项目'))}</div>\n                    <div class=\"agent-runtime-stat\"><strong>项目目标</strong>：${escapeHtml(lineage.projectGoal || '未设置')}</div>\n                    <div class=\"agent-runtime-stat\"><strong>当前任务上下文</strong>：${escapeHtml(lineage.taskContext || '未设置')}</div>\n                    <div class=\"agent-run-actions\" style=\"margin-top:8px;\">\n                        ${renderTaskNavigationActionGroup(['跳回任务看板', '查看任务目标链'], normalizedTaskId, empName, { buttonClass: 'agent-run-btn' })}\n                    </div>\n                </div>`;\n        }\n\n        function resolveRunGovernanceTaskContext(run, empName) {\n            const matched = findBoardTaskByRun(run, empName);\n            if (matched?.task) return matched.task;\n            return null;\n        }\n\n        function renderAgentRunGovernanceMeta(task, empName) {\n            if (!task) {\n                return `\n                <div class=\"agent-runtime-stat\"><strong>当前负责人</strong>：未关联任务</div>\n                <div class=\"agent-runtime-stat\"><strong>当前任务状态</strong>：未关联</div>\n                <div class=\"agent-runtime-stat\"><strong>审核责任人</strong>：暂无</div>`;\n            }\n            const employeeName = String(task?.assignee || task?.Assignee || empName || '').trim();\n            const reviewer = getBoardTaskReviewer(task, employeeName);\n            const taskStatusLabel = getBoardTaskStatusLabel(task?.status || task?.Status || 'todo');\n            return `\n                <div class=\"agent-runtime-stat\"><strong>当前负责人</strong>：${escapeHtml(employeeName || '待分配')}</div>\n                <div class=\"agent-runtime-stat\"><strong>当前任务状态</strong>：${escapeHtml(taskStatusLabel)}</div>\n                <div class=\"agent-runtime-stat\"><strong>审核责任人</strong>：${escapeHtml(reviewer || '暂无')}</div>`;\n        }\n\n        function renderAgentRunGovernanceActions(task, empName, run = null) {\n            const taskId = String(task?.id || task?.Id || '').trim();\n            const employeeName = String(task?.assignee || task?.Assignee || empName || '').trim();\n            if (!taskId) {\n                return '<div class=\"agent-inline-note\">当前运行还没有映射到任务，暂时无法执行治理动作。</div>';\n            }\n            const recommendation = buildTaskGovernanceRecommendation(task, employeeName);\n            const policy = buildTaskGovernanceCtaPolicy('run', task, employeeName, { recommendation });\n            const phase = buildTaskControlPlanePhase('run', task, employeeName, { recommendation });\n            const handoff = buildTaskCtaModeHandoff('run', task, employeeName, { recommendation, phase });\n            const actionDescriptors = [\n                { action: policy.primaryAction || '先提交审核', buttonClass: 'agent-run-btn primary', label: policy.primaryAction === '先提交审核' ? '提交审核' : (policy.primaryAction || '直接处理') },\n                ...(policy.reviewActions.includes('批准审核') ? [{ action: '批准审核', buttonClass: 'agent-run-btn primary' }] : []),\n                ...(policy.reviewActions.includes('打回修改') ? [{ action: '打回修改', buttonClass: 'agent-run-btn' }] : []),\n                { action: '先补充评论 / 上下文', buttonClass: 'agent-run-btn', label: '添加评论' },\n                { action: '先升级给上级', buttonClass: 'agent-run-btn', label: '升级给上级' }\n            ];\n            const actions = renderTaskGovernanceActionGroup(actionDescriptors, taskId, employeeName, { surface: 'run', task, latestRun: run, run, snapshotAuditDecision: run?.snapshotAuditDecision || run?.SnapshotAuditDecision || null });\n            const navigationButtons = renderTaskNavigationActionGroup(policy.navigationActions, taskId, employeeName, { buttonClass: 'agent-run-btn' });\n            const phaseBodyHtml = renderTaskControlPlanePhaseBody(phase);\n            const handoffBodyHtml = renderTaskCtaModeHandoffBody(handoff, taskId, employeeName, { buttonClass: 'agent-run-btn' });\n            const primaryPolicy = buildTaskCtaSectionPolicy('primary', task, employeeName, { surface: 'run', recommendation, phase, bodyHtml: actions, sectionClass: 'agent-run-actions' });\n            const navigationPolicy = buildTaskCtaSectionPolicy('navigation', task, employeeName, { surface: 'run', recommendation, phase, bodyHtml: navigationButtons, sectionClass: 'agent-run-actions' });\n            const phasePolicy = buildTaskCtaSectionPolicy('phase', task, employeeName, { surface: 'run', recommendation, phase, bodyHtml: phaseBodyHtml, sectionClass: 'agent-run-actions' });\n            const handoffPolicy = buildTaskCtaSectionPolicy('handoff', task, employeeName, { surface: 'run', recommendation, phase, handoff, bodyHtml: handoffBodyHtml, sectionClass: 'agent-run-actions' });\n            const orderedSections = buildTaskCtaSectionOrder('run', phase, [\n                primaryPolicy.visible ? { kind: 'primary', taskId, title: primaryPolicy.title, bodyHtml: actions, sectionClass: primaryPolicy.sectionClass, tone: primaryPolicy.tone, priority: primaryPolicy.priority, actionDensity: primaryPolicy.actionDensity } : null,\n                navigationPolicy.visible ? { kind: 'navigation', taskId, title: navigationPolicy.title, bodyHtml: navigationButtons, sectionClass: navigationPolicy.sectionClass, tone: navigationPolicy.tone, priority: navigationPolicy.priority, actionDensity: navigationPolicy.actionDensity } : null,\n                phasePolicy.visible ? { kind: 'phase', taskId, title: phasePolicy.title, bodyHtml: phaseBodyHtml, sectionClass: phasePolicy.sectionClass, tone: phasePolicy.tone, priority: phasePolicy.priority, actionDensity: phasePolicy.actionDensity } : null,\n                handoffPolicy.visible ? { kind: 'handoff', taskId, title: handoffPolicy.title, bodyHtml: handoffBodyHtml, sectionClass: handoffPolicy.sectionClass, tone: handoffPolicy.tone, priority: handoffPolicy.priority, actionDensity: handoffPolicy.actionDensity } : null\n            ].filter(Boolean));\n            const runPreferenceDigest = buildTaskCtaPreferenceDigest('run', taskId, phase, orderedSections, { employeeName, runId: getRunIdFromObject(run) });\n            return `${runPreferenceDigest}${renderTaskCtaSections(orderedSections)}`;\n        }\n\n        function renderAgentRunGovernanceSnapshot(run, empName) {\n            const task = resolveRunGovernanceTaskContext(run, empName);\n            const latestRun = task ? findLatestRunForTask(task, String(task?.assignee || task?.Assignee || empName || '').trim()) : null;\n            const reviewer = task ? getBoardTaskReviewer(task, String(task?.assignee || task?.Assignee || empName || '').trim()) : '';\n            const taskStatusLabel = task ? getBoardTaskStatusLabel(task?.status || task?.Status || 'todo') : '未关联';\n            const latestGovernanceAction = task ? getLatestBoardTaskGovernanceAction(task) : '暂无';\n            const consistency = task ? getBoardTaskStatusConsistency(task, latestRun) : '暂无';\n            return `\n                <div class=\"agent-runtime-section-card\">\n                    <h5>治理联动快照</h5>\n                    <div class=\"agent-runtime-stat\"><strong>任务状态</strong>：${escapeHtml(taskStatusLabel)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>最近治理动作</strong>：${escapeHtml(latestGovernanceAction)}</div>\n                    <div class=\"agent-runtime-stat\"><strong>审核责任人</strong>：${escapeHtml(reviewer || '暂无')}</div>\n                    <div class=\"agent-runtime-stat\"><strong>看板状态一致性</strong>：${escapeHtml(consistency)}</div>\n                    ${renderAgentRunGovernanceRecommendation(run, empName)}\n                </div>`;\n        }\n\n        function renderAgentRunGovernanceRecommendation(run, empName) {\n            const task = resolveRunGovernanceTaskContext(run, empName);\n            if (!task) return '<div class=\"board-task-recommendation-summary\">治理建议：当前运行尚未映射到任务，建议先补充评论 / 上下文。</div>';\n            return renderTaskGovernanceRecommendationForSurface('run', task, String(task?.assignee || task?.Assignee || empName || '').trim(), { runId: getRunIdFromObject(run), latestRun: run, snapshotAuditDecision: run?.snapshotAuditDecision || run?.SnapshotAuditDecision || null });\n        }\n\n        function renderAgentRunGovernanceSection(run, empName) {\n            const task = resolveRunGovernanceTaskContext(run, empName);\n            const taskStatusLabel = task ? getBoardTaskStatusLabel(task?.status || task?.Status || 'todo') : '未关联';\n            const metaHtml = task\n                ? `\n                <div class=\"agent-runtime-stat\"><strong>当前负责人</strong>：${escapeHtml(String(task?.assignee || task?.Assignee || empName || '').trim() || '待分配')}</div>\n                <div class=\"agent-runtime-stat\"><strong>当前任务状态</strong>：${escapeHtml(taskStatusLabel)}</div>\n                <div class=\"agent-runtime-stat\"><strong>审核责任人</strong>：${escapeHtml(getBoardTaskReviewer(task, String(task?.assignee || task?.Assignee || empName || '').trim()) || '暂无')}</div>`\n                : renderAgentRunGovernanceMeta(task, empName);\n            return `\n                <div class=\"agent-detail-section\">\n                    <strong>治理动作区</strong>\n                    <div class=\"agent-runtime-section-grid\"><div class=\"agent-runtime-section-card\">${metaHtml}${renderAgentRunGovernanceActions(task, empName, run)}</div>${renderAgentRunGovernanceSnapshot(run, empName)}</div>\n                </div>`;\n        }\n\n        function renderAgentRunRecentTaskHistory(run, empName) {\n            const task = resolveRunGovernanceTaskContext(run, empName);\n            if (!task) {\n                return `\n                <div class=\"agent-detail-section\">\n                    <strong>同任务最近执行历史</strong>\n                    <div class=\"agent-inline-note\">当前运行尚未映射到任务，暂无可聚合的执行历史。</div>\n                </div>`;\n            }\n            const employeeName = String(task?.assignee || task?.Assignee || empName || '').trim();\n            const history = buildTaskExecutionHistory(task, employeeName);\n            const rows = history.recentRuns.map(item => {\n                const status = String(item?.status || item?.Status || 'unknown');\n                const time = String(item?.updatedAt || item?.UpdatedAt || item?.createdAt || item?.CreatedAt || '暂无');\n                const summary = String(item?.summary || item?.Summary || item?.taskText || item?.TaskText || '暂无摘要');\n                return `<div class=\"board-task-history-item\"><strong>${escapeHtml(status)}</strong> / ${escapeHtml(time)}<br>${escapeHtml(summary)}</div>`;\n            }).join('') || '<div class=\"board-task-history-item\">执行历史：暂无</div>';\n            const latestSuccess = history.latestSuccess ? String(history.latestSuccess?.updatedAt || history.latestSuccess?.UpdatedAt || history.latestSuccess?.createdAt || history.latestSuccess?.CreatedAt || '暂无') : '暂无';\n            const latestFailure = history.latestFailure ? String(history.latestFailure?.updatedAt || history.latestFailure?.UpdatedAt || history.latestFailure?.createdAt || history.latestFailure?.CreatedAt || '暂无') : '暂无';\n            const repeatedHints = `${history.repeatedReject ? '反复打回' : '反复打回：否'} / ${history.repeatedFailure ? '反复失败' : '反复失败：否'}`;\n            return `\n                <div class=\"agent-detail-section\">\n                    <strong>同任务最近执行历史</strong>\n                    <div class=\"board-task-inline-meta\"><span class=\"board-task-risk-pill\">最近3次运行：${escapeHtml(String(history.recentRuns.length))}</span><span class=\"board-task-risk-pill\">最近成功：${escapeHtml(latestSuccess)}</span><span class=\"board-task-risk-pill\">最近失败：${escapeHtml(latestFailure)}</span><span class=\"board-task-risk-pill\">${escapeHtml(repeatedHints)}</span></div>\n                    <div class=\"board-task-timeline-card expanded\">${rows}</div>\n                </div>`;\n        }\n\n        async function openAgentRun(empName, runId) {\n            const agentRunModal = document.getElementById('agentRunModal');\n            const title = document.getElementById('agentRunModalTitle');\n            const body = document.getElementById('agentRunModalBody');\n            if (!agentRunModal || !title || !body) return;\n\n            agentRunModal.style.display = 'flex';\n            agentRunModal.dataset.employee = empName;\n            agentRunModal.dataset.runId = runId;\n            title.innerText = '智能体运行详情';\n            body.innerHTML = '<div class=\"agent-inline-note\">正在加载运行详情...</div>';\n\n            try {\n                const run = await fetchAgentJsonSafe('/api/agent/run?user=' + encodeURIComponent(empName) + '&id=' + encodeURIComponent(runId));\n                title.innerText = `${run.User || run.user} / ${run.TaskText || run.taskText}`;\n\n                const artifacts = (run.Artifacts || run.artifacts || []).map(item => `\n                    <a class=\"agent-artifact-link\" href=\"${item.Url || item.url}\" target=\"_blank\">${escapeHtml(item.Label || item.label || item.Url || item.url)}</a>\n                `).join('') || '<div class=\"agent-inline-note\">暂无产物</div>';\n\n                const steps = (run.Steps || run.steps || []).map(step => `\n                    <div class=\"agent-step\">\n                        <strong>${escapeHtml(getStepKindLabel(step))}</strong>\n                        <div style=\"font-size:12px; color:#64748b; margin:4px 0;\">${escapeHtml(step.Status || step.status || '')} / ${escapeHtml(step.Timestamp || step.timestamp || '')}</div>\n                        <div style=\"white-space:pre-wrap; font-size:12px;\">${escapeHtml(getStepText(step))}</div>\n                    </div>`).join('') || '<div class=\"agent-inline-note\">暂无步骤</div>';\n\n                const previewHtml = renderAgentStepPreview(run, 12);\n                const metaSummaryHtml = renderAgentRunMetaSection(run, empName);\n                const governanceHtml = renderAgentRunGovernanceSection(run, empName);\n                const recentTaskHistoryHtml = renderAgentRunRecentTaskHistory(run, empName);\n\n                body.innerHTML = `\n                    <div>\n                        <span class=\"agent-runtime-pill ${getStatusClass(run.Status || run.status)}\">${escapeHtml(run.Status || run.status || '')}</span>\n                        <span class=\"agent-inline-note\">运行编号：${escapeHtml(getRunIdFromObject(run))}</span>\n                    </div>\n                    ${renderApprovalButtons(run, empName)}\n                    <div class=\"agent-detail-section\"><strong>运行控制卡</strong>${metaSummaryHtml}</div>\n                    ${renderAgentRunGovernanceSection(run, empName)}\n                    ${renderAgentRunRecentTaskHistory(run, empName)}\n                    <div class=\"agent-detail-section\">\n                        <strong>最终结果</strong>\n                        <div style=\"white-space:pre-wrap; font-size:12px; margin-top:8px;\">${escapeHtml(run.FinalContent || run.finalContent || run.LastError || run.lastError || '')}</div>\n                    </div>\n                    <div class=\"agent-detail-section\"><strong>实时过程日志</strong>${previewHtml}</div>\n                    <div class=\"agent-detail-section\"><strong>产物</strong>${artifacts}</div>\n                    <div class=\"agent-detail-section\"><strong>工具与步骤</strong>${steps}</div>`;\n            } catch (err) {\n                body.innerHTML = `<div class=\"agent-inline-note\" style=\"color:#b91c1c;\">加载失败：${escapeHtml(err?.message || String(err))}</div>`;\n            }\n        }\n\n        function matchStrategyAssigneeName(rawValue, employeeNames) {\n            const raw = String(rawValue || '').trim();\n            if (!raw) return '';\n            if (employeeNames.includes(raw)) return raw;\n\n            const normalized = raw.replace(/\\s+/g, '');\n            const exact = employeeNames.find(name => normalized === String(name || '').replace(/\\s+/g, ''));\n            if (exact) return exact;\n\n            const fuzzy = employeeNames.find(name => raw.includes(name) || normalized.includes(String(name || '').replace(/\\s+/g, '')));\n            return fuzzy || raw;\n        }\n\n        function coerceStrategyTasks(tasksSource, employeeNames) {\n            const source = Array.isArray(tasksSource) ? tasksSource : [];\n            return source.map((task, index) => {\n                const item = task && typeof task === 'object' ? task : { title: String(task || '') };\n                const title = String(\n                    item.title\n                    || item.task_title\n                    || item.taskTitle\n                    || item.name\n                    || item.task\n                    || item.work\n                    || item.work_item\n                    || item.workItem\n                    || item['任务标题']\n                    || item['任务']\n                    || item['工作项']\n                    || item['工作内容']\n                    || ''\n                ).trim();\n\n                const assignee = matchStrategyAssigneeName(\n                    item.assignee\n                    || item.owner\n                    || item.employee\n                    || item.person\n                    || item.executor\n                    || item.user\n                    || item['负责人']\n                    || item['责任人']\n                    || item['执行人']\n                    || item['员工']\n                    || '',\n                    employeeNames\n                );\n\n                const status = String(item.status || item['状态'] || 'todo').trim().toLowerCase() || 'todo';\n                const dependsOnSource = item.depends_on || item.dependsOn || item.dependencies || item['前置任务'] || item['依赖任务'] || [];\n                const dependsOn = Array.isArray(dependsOnSource)\n                    ? dependsOnSource.map(dep => String(dep || '').trim()).filter(Boolean)\n                    : String(dependsOnSource || '').split(/[,，、\\s]+/).map(dep => dep.trim()).filter(Boolean);\n                return {\n                    id: item.id || Math.random().toString(36).substring(2, 10),\n                    title,\n                    assignee,\n                    status,\n                    order: Number.isFinite(item.order) ? item.order : index,\n                    phase: String(item.phase || item.stage || item['阶段'] || '').trim(),\n                    depends_on: dependsOn,\n                    deliverable: String(item.deliverable || item.output || item['交付物'] || item['产物'] || '').trim(),\n                    gate: String(item.gate || item['准入条件'] || item['完成条件'] || '').trim()\n                };\n            }).filter(task => task.title);\n        }\n\n        function guessStrategyProjectNameFromText(text) {\n            const lines = String(text || '')\n                .replace(/```json/gi, '')\n                .replace(/```/g, '')\n                .split(/\\r?\\n/)\n                .map(line => stripLeadingBom(line).trim())\n                .filter(Boolean);\n\n            const namedLine = lines.find(line => /项目名称|项目标题|方案名称|规划名称|项目[:：]/.test(line));\n            if (namedLine) {\n                const extracted = namedLine\n                    .replace(/^.*?(项目名称|项目标题|方案名称|规划名称|项目)[:：]\\s*/u, '')\n                    .trim();\n                if (extracted) return extracted;\n            }\n\n            const firstMeaningful = lines.find(line => {\n                const compact = line.replace(/^[#*\\-\\d.\\s、（）()]+/g, '').trim();\n                return compact.length >= 4 && !/^(工作规划|执行计划|任务清单|任务分配|负责人安排|说明|要求|输出格式)$/i.test(compact);\n            });\n\n            return firstMeaningful ? firstMeaningful.slice(0, 40) : '未命名项目';\n        }\n\n        function extractStrategyTasksFromFreeText(text, employeeNames) {\n            const lines = String(text || '')\n                .replace(/```json/gi, '')\n                .replace(/```/g, '')\n                .split(/\\r?\\n/)\n                .map(line => stripLeadingBom(line).trim())\n                .filter(Boolean);\n\n            const headingPattern = /^(工作规划|执行计划|任务清单|任务分配|核心目标|目标|说明|要求|输出格式|项目名称|项目标题|项目简介|背景|负责人安排)[:：]?$/i;\n            const collected = [];\n\n            for (const line of lines) {\n                let cleaned = line\n                    .replace(/^[>*\\-\\s]+/g, '')\n                    .replace(/^[（(]?[一二三四五六七八九十百千万0-9]+[)）.\\-、:：\\s]*/u, '')\n                    .replace(/^任务\\s*[0-9一二三四五六七八九十]*[:：\\s-]*/u, '')\n                    .replace(/^工作项\\s*[0-9一二三四五六七八九十]*[:：\\s-]*/u, '')\n                    .trim();\n\n                if (!cleaned || cleaned.length < 5 || headingPattern.test(cleaned)) {\n                    continue;\n                }\n\n                const matchedAssignee = employeeNames.find(name => cleaned.includes(name)) || '';\n                let title = cleaned;\n                if (matchedAssignee) {\n                    const assigneePattern = new RegExp(`(负责人|责任人|执行人|由|安排给|指派给)?[:：\\\\s-]*${matchedAssignee}`, 'g');\n                    title = title.replace(assigneePattern, '').trim();\n                }\n\n                title = title\n                    .replace(/^(负责人|责任人|执行人)[:：\\s-]*/g, '')\n                    .replace(/[，,。；;]*\\s*(负责人|责任人|执行人)[:：]?\\s*$/g, '')\n                    .trim();\n\n                if (title.length < 5) continue;\n                if (!/[A-Za-z\\u4e00-\\u9fa5]/.test(title)) continue;\n\n                collected.push({\n                    id: Math.random().toString(36).substring(2, 10),\n                    title,\n                    assignee: matchedAssignee,\n                    status: 'todo',\n                    order: collected.length\n                });\n            }\n\n            const unique = [];\n            const seen = new Set();\n            for (const task of collected) {\n                const key = `${task.title}@@${task.assignee}`;\n                if (seen.has(key)) continue;\n                seen.add(key);\n                unique.push(task);\n            }\n\n            return unique.slice(0, 8).map((task, index) => ({\n                ...task,\n                assignee: task.assignee || employeeNames[index % Math.max(employeeNames.length, 1)] || ''\n            }));\n        }\n\n        function normalizeStrategyBoardData(rawData, employeeNames, fallbackText) {\n            let data = rawData;\n            if (data && typeof data === 'object' && !Array.isArray(data)) {\n                const nestedContent = data.content || data.Content || data.result || data.Result || data.message || data.Message || '';\n                if ((!data.tasks && !data.project_name && !data.projectName && !data['项目名称']) && nestedContent) {\n                    const nested = parseLooseJsonObjectFromText(nestedContent);\n                    if (nested && typeof nested === 'object') {\n                        data = nested;\n                    }\n                }\n            }\n\n            let rawTasks =\n                data?.tasks\n                || data?.Tasks\n                || data?.task_list\n                || data?.taskList\n                || data?.items\n                || data?.list\n                || data?.works\n                || data?.['任务']\n                || data?.['任务清单']\n                || data?.['工作规划']\n                || data?.['执行计划']\n                || [];\n\n            if (typeof rawTasks === 'string') {\n                const parsed = parseLooseJsonObjectFromText(rawTasks);\n                if (parsed && typeof parsed === 'object') {\n                    rawTasks =\n                        parsed.tasks\n                        || parsed.task_list\n                        || parsed.taskList\n                        || parsed.items\n                        || parsed['任务']\n                        || parsed['任务清单']\n                        || [];\n                } else {\n                    rawTasks = [];\n                }\n            }\n\n            let tasks = coerceStrategyTasks(rawTasks, employeeNames);\n            const projectName = String(\n                data?.project_name\n                || data?.projectName\n                || data?.project\n                || data?.name\n                || data?.title\n                || data?.['项目名称']\n                || data?.['项目']\n                || data?.['项目标题']\n                || ''\n            ).trim() || guessStrategyProjectNameFromText(fallbackText || data?.content || '');\n\n            if (!tasks.length) {\n                tasks = extractStrategyTasksFromFreeText(\n                    fallbackText\n                    || data?.content\n                    || data?.result\n                    || data?.message\n                    || '',\n                    employeeNames\n                );\n            }\n\n            return {\n                project_name: projectName,\n                tasks\n            };\n        }\n\n        function pickStrategyOwner(candidates, usedNames, preferredKeywords) {\n            const keywordList = Array.isArray(preferredKeywords) ? preferredKeywords : [];\n            const lowerKeywords = keywordList.map(item => String(item || '').toLowerCase()).filter(Boolean);\n\n            const scored = candidates.map(([name, info]) => {\n                const role = String(info?.Role || info?.role || '').toLowerCase();\n                const desc = String(info?.Description || info?.description || '').toLowerCase();\n                let score = 0;\n                lowerKeywords.forEach(keyword => {\n                    if (role.includes(keyword)) score += 5;\n                    if (desc.includes(keyword)) score += 2;\n                });\n                if (!usedNames.has(name)) score += 1;\n                return { name, score };\n            }).sort((a, b) => b.score - a.score);\n\n            return scored[0]?.name || candidates[0]?.[0] || '';\n        }\n\n        function isWebsiteStrategyDemand(taskContent) {\n            return /官网|网站|web\\s*site|website|landing\\s*page|网页|页面|前端|响应式|本地预览|测试链接/i.test(String(taskContent || ''));\n        }\n\n        function createPhasedStrategyTask(tasks, candidates, usedNames, phase, title, keywords, dependsOn, deliverable, gate) {\n            const assignee = pickStrategyOwner(candidates, usedNames, keywords);\n            if (assignee) usedNames.add(assignee);\n            const id = `${phase}-${tasks.length + 1}`;\n            tasks.push({\n                id,\n                title,\n                assignee,\n                status: dependsOn?.length ? 'backlog' : 'todo',\n                order: tasks.length,\n                phase,\n                depends_on: dependsOn || [],\n                deliverable,\n                gate\n            });\n            return id;\n        }\n\n        function buildFallbackStrategyBoard(taskContent, availableNodes) {\n            const normalizedDemand = String(taskContent || '').trim();\n            const demandLower = normalizedDemand.toLowerCase();\n            const projectName = guessStrategyProjectNameFromText(normalizedDemand) || (normalizedDemand.slice(0, 24) + '项目');\n            const candidates = Array.isArray(availableNodes) && availableNodes.length ? availableNodes : [];\n            const usedNames = new Set();\n            const tasks = [];\n\n            const pushTask = (title, keywords) => {\n                if (!title) return;\n                const assignee = pickStrategyOwner(candidates, usedNames, keywords);\n                if (assignee) usedNames.add(assignee);\n                tasks.push({\n                    id: Math.random().toString(36).substring(2, 10),\n                    title,\n                    assignee,\n                    status: 'todo',\n                    order: tasks.length\n                });\n            };\n\n            const isWebsiteLike = isWebsiteStrategyDemand(normalizedDemand) || /平台|系统|小程序|后台|saas/i.test(normalizedDemand);\n            const needPpt = /ppt|汇报|路演|演示文稿|幻灯片/i.test(normalizedDemand);\n            const needOperation = /运营|推广|投放|增长|宣传|文案|品牌/i.test(normalizedDemand);\n\n            if (isWebsiteLike) {\n                const prd = createPhasedStrategyTask(tasks, candidates, usedNames, 'prd', `输出《${projectName}》官网 PRD：目标用户、核心卖点、页面范围、验收标准`, ['产品', '项目', 'pm', '策划'], [], 'docs/prd.md', '明确需求边界后才能进入原型');\n                const prototype = createPhasedStrategyTask(tasks, candidates, usedNames, 'prototype', `输出《${projectName}》官网信息架构、页面流程和低保真原型`, ['ui', 'ux', '设计', '交互', '产品'], [prd], 'docs/prototype.md 或 prototype.html', 'PRD 已完成并可追溯');\n                const uiux = createPhasedStrategyTask(tasks, candidates, usedNames, 'uiux', `输出《${projectName}》官网 UI/UX 视觉规范、组件状态和响应式规则`, ['ui', 'ux', '设计', '视觉'], [prototype], 'docs/ui-spec.md', '原型结构已确认');\n                const frontend = createPhasedStrategyTask(tasks, candidates, usedNames, 'frontend', `完成《${projectName}》官网前端页面、视觉还原和移动端适配`, ['前端', 'web', 'html', 'javascript', 'react'], [uiux], 'index.html、样式和前端资源', 'UI/UX 规范已完成');\n                const backend = createPhasedStrategyTask(tasks, candidates, usedNames, 'backend', `完成《${projectName}》官网本地服务、资源组织和预览启动方式`, ['后端', 'java', 'go', 'python', '接口', '服务端', '运维'], [frontend], '本地启动说明和服务配置', '前端页面已可运行');\n                const test = createPhasedStrategyTask(tasks, candidates, usedNames, 'test', `基于本地页面完成《${projectName}》测试报告、问题清单和修复建议`, ['测试', 'qa', '质量'], [frontend, backend], 'docs/test-report.md', '前后端/本地服务已完成');\n                createPhasedStrategyTask(tasks, candidates, usedNames, 'preview', `生成《${projectName}》本地测试链接并整理最终交付说明`, ['运维', 'devops', '部署', '服务器', '测试'], [test], '本地预览 URL 与交付说明', '测试报告已完成');\n            } else {\n                pushTask(`梳理《${projectName}》目标、范围与执行计划`, ['产品', '项目', 'pm', '策划']);\n                pushTask(`完成《${projectName}》核心内容方案与交付结构设计`, ['策划', '产品', '运营', '设计']);\n                pushTask(`完成《${projectName}》主体产出制作与初版交付`, ['设计', '前端', '内容', '运营']);\n                pushTask(`完成《${projectName}》测试校对、优化修订与最终交付`, ['测试', '质量', '法务', '运营']);\n            }\n\n            if (needPpt) {\n                pushTask(`完成《${projectName}》PPT 内容提纲、页结构与讲述逻辑`, ['产品', '运营', '商务', '策划']);\n                pushTask(`完成《${projectName}》PPT 视觉排版、美化与终版导出`, ['ui', '设计', '视觉']);\n            }\n\n            if (needOperation) {\n                pushTask(`完成《${projectName}》宣传文案、运营节奏与发布建议`, ['运营', '品牌', '文案', '商务']);\n            }\n\n            const unique = [];\n            const seen = new Set();\n            for (const task of tasks) {\n                const key = `${task.title}@@${task.assignee}`;\n                if (seen.has(key)) continue;\n                seen.add(key);\n                unique.push(task);\n            }\n\n            return {\n                project_name: projectName,\n                execution_mode: isWebsiteLike ? 'phased' : 'standard',\n                tasks: unique.slice(0, 8)\n            };\n        }\n        \n        async function openCeoModal() {\n            const modal = document.getElementById('ceoModal');\n            const input = document.getElementById('ceoTaskInput');\n            if (!modal || !input) return;\n            modal.style.display = 'flex';\n            input.value = '';\n            setTimeout(() => input.focus(), 30);\n        }\n\n        function populateRoutineEmployeeOptions(selectedEmployee) {\n            const select = document.getElementById('routineEmployeeInput');\n            if (!select) return;\n            const peers = window.teamConfig?.PeerNodes || {};\n            const names = Object.keys(peers).sort((a, b) => a.localeCompare(b, 'zh-CN'));\n            const fallback = selectedEmployee || names[0] || '赫尔墨斯';\n            select.innerHTML = names.map(name => {\n                const role = peers[name]?.Role || peers[name]?.role || '待认领';\n                const isSelected = String(name) === String(selectedEmployee || fallback) ? 'selected' : '';\n                return `<option value=\"${escapeHtml(name)}\" ${isSelected}>${escapeHtml(name)} / ${escapeHtml(role)}</option>`;\n            }).join('');\n            if (!select.value && fallback) {\n                const opt = document.createElement('option');\n                opt.value = fallback;\n                opt.textContent = fallback;\n                opt.selected = true;\n                select.appendChild(opt);\n            }\n        }\n\n        function resetRoutineForm() {\n            document.getElementById('routineIdInput').value = '';\n            document.getElementById('routineNameInput').value = '';\n            document.getElementById('routineIntervalInput').value = '1440';\n            document.getElementById('routineNextRunInput').value = '';\n            document.getElementById('routineMaxRetriesInput').value = '2';\n            document.getElementById('routineBackoffInput').value = '10';\n            document.getElementById('routinePromptInput').value = '';\n            document.getElementById('routineEnabledInput').checked = true;\n            document.getElementById('routineEditorTitle').textContent = '新增周期任务';\n            document.getElementById('routineEditingHint').textContent = '新建模式';\n            populateRoutineEmployeeOptions('赫尔墨斯');\n        }\n\n        function editRoutineJob(routineId) {\n            const routine = (routineManagerCache || []).find(item => String(item.id || item.Id) === String(routineId || ''));\n            if (!routine) {\n                showAppDialog({ tone: 'warning', title: '没有找到周期任务', message: '请先从左侧列表选择一条有效任务。' });\n                return;\n            }\n            document.getElementById('routineIdInput').value = routine.id || routine.Id || '';\n            document.getElementById('routineNameInput').value = routine.name || routine.Name || '';\n            document.getElementById('routineIntervalInput').value = String(routine.trigger?.interval_minutes || routine.trigger?.IntervalMinutes || 1440);\n            document.getElementById('routineNextRunInput').value = routine.next_run_at || routine.NextRunAt || '';\n            document.getElementById('routineMaxRetriesInput').value = String(routine.max_retries ?? routine.MaxRetries ?? 2);\n            document.getElementById('routineBackoffInput').value = String(routine.retry_backoff_minutes ?? routine.RetryBackoffMinutes ?? 10);\n            document.getElementById('routinePromptInput').value = routine.prompt || routine.Prompt || '';\n            document.getElementById('routineEnabledInput').checked = Boolean(routine.enabled ?? routine.Enabled ?? true);\n            document.getElementById('routineEditorTitle').textContent = `编辑周期任务：${routine.name || routine.Name || '未命名任务'}`;\n            document.getElementById('routineEditingHint').textContent = `编辑中 · ${routine.id || routine.Id || ''}`;\n            populateRoutineEmployeeOptions(routine.employee || routine.Employee || '');\n        }\n\n        function renderRoutineList(routines) {\n            const list = document.getElementById('routineList');\n            const summary = document.getElementById('routineSummaryBadge');\n            if (!list || !summary) return;\n            const total = Array.isArray(routines) ? routines.length : 0;\n            const enabledCount = (routines || []).filter(item => Boolean(item.enabled ?? item.Enabled ?? true)).length;\n            summary.textContent = `共 ${total} 条 / 启用 ${enabledCount} 条`;\n            if (!total) {\n                list.innerHTML = '<div style=\"text-align:center; color:#64748b; padding:40px 20px; background:#f8fafc; border:1px dashed #cbd5e1; border-radius:12px;\">还没有周期任务，点右上角“新增周期任务”即可开始配置。</div>';\n                return;\n            }\n            list.innerHTML = (routines || []).map(item => {\n                const id = item.id || item.Id || '';\n                const name = item.name || item.Name || '未命名任务';\n                const employee = item.employee || item.Employee || '未分配';\n                const enabled = Boolean(item.enabled ?? item.Enabled ?? true);\n                const nextRunAt = item.next_run_at || item.NextRunAt || '未设置';\n                const lastRunAt = item.last_run_at || item.LastRunAt || '尚未运行';\n                const interval = item.trigger?.interval_minutes || item.trigger?.IntervalMinutes || 0;\n                const prompt = item.prompt || item.Prompt || '';\n                const maxRetries = item.max_retries ?? item.MaxRetries ?? 2;\n                const retryBackoffMinutes = item.retry_backoff_minutes ?? item.RetryBackoffMinutes ?? 10;\n                const consecutiveFailures = item.consecutive_failures ?? item.ConsecutiveFailures ?? 0;\n                const alertLevel = item.alert_level || item.AlertLevel || 'normal';\n                return `\n                    <div style=\"border:1px solid #e2e8f0; border-radius:12px; padding:14px; display:flex; flex-direction:column; gap:10px; background:${enabled ? '#ffffff' : '#f8fafc'}; box-shadow:0 4px 12px rgba(15,23,42,0.04);\">\n                        <div style=\"display:flex; justify-content:space-between; align-items:flex-start; gap:12px;\">\n                            <div>\n                                <div style=\"font-weight:bold; color:#0f172a;\">${escapeHtml(name)}</div>\n                                <div style=\"font-size:12px; color:#64748b; margin-top:4px;\">ID：${escapeHtml(id)} · 负责人：${escapeHtml(employee)}</div>\n                            </div>\n                            <div style=\"font-size:12px; color:${enabled ? '#166534' : '#92400e'}; background:${enabled ? '#dcfce7' : '#fef3c7'}; border-radius:999px; padding:4px 10px;\">${enabled ? '启用中' : '已停用'}</div>\n                        </div>\n                        <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:8px; font-size:12px; color:#475569;\">\n                            <div>触发方式：schedule / ${interval || '未设'} 分钟</div>\n                            <div>下次运行时间：${escapeHtml(nextRunAt)}</div>\n                            <div>上次运行：${escapeHtml(lastRunAt)}</div>\n                            <div>提示词长度：${prompt.trim().length} 字</div>\n                            <div>最大重试次数：${escapeHtml(String(maxRetries))}</div>\n                            <div>失败退避（分钟）：${escapeHtml(String(retryBackoffMinutes))}</div>\n                            <div>连续失败：${escapeHtml(String(consecutiveFailures))}</div>\n                            <div>告警级别：${escapeHtml(String(alertLevel))}</div>\n                        </div>\n                        <div style=\"font-size:12px; line-height:1.6; color:#334155; background:#f8fafc; border-radius:10px; padding:10px; border:1px solid #e2e8f0;\">${escapeHtml(prompt || '暂无执行提示词')}</div>\n                        <div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n                            <button onclick=\"editRoutineJob('${id}')\" style=\"padding:8px 12px; background:#2563eb; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">编辑</button>\n                            <button onclick=\"runRoutineNow('${id}')\" style=\"padding:8px 12px; background:#f59e0b; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">立即执行</button>\n                            <button onclick=\"deleteRoutineJob('${id}')\" style=\"padding:8px 12px; background:#ef4444; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">删除任务</button>\n                        </div>\n                    </div>`;\n            }).join('');\n        }\n\n        function renderRoutineHistory(history) {\n            const container = document.getElementById('routineHistoryList');\n            if (!container) return;\n            const items = Array.isArray(history) ? history.slice(0, 8) : [];\n            if (!items.length) {\n                container.innerHTML = '<div style=\"font-size:12px; color:#64748b;\">暂无执行历史</div>';\n                return;\n            }\n            container.innerHTML = items.map(item => {\n                const status = item.status || item.Status || 'unknown';\n                const routineName = item.routine_name || item.RoutineName || '未命名任务';\n                const employee = item.employee || item.Employee || '未分配';\n                const startedAt = item.started_at || item.StartedAt || '未知';\n                const summary = item.summary || item.Summary || item.error_message || item.ErrorMessage || '';\n                return `<div style=\"background:#fff; border:1px solid #e2e8f0; border-radius:10px; padding:10px; font-size:12px; color:#334155; line-height:1.6;\"><strong>${escapeHtml(routineName)}</strong><div>状态：${escapeHtml(status)} / 执行人：${escapeHtml(employee)}</div><div>开始时间：${escapeHtml(startedAt)}</div><div>摘要：${escapeHtml(summary || '暂无摘要')}</div></div>`;\n            }).join('');\n        }\n\n        function renderHeartbeatSummary(heartbeats) {\n            const container = document.getElementById('routineHeartbeatSummary');\n            if (!container) return;\n            const entries = Object.entries(heartbeats || {});\n            if (!entries.length) {\n                container.innerHTML = '<div style=\"font-size:12px; color:#64748b;\">暂无心跳状态</div>';\n                return;\n            }\n            container.innerHTML = entries.map(([name, item]) => {\n                const lastSeenAt = item.last_seen_at || item.LastSeenAt || '未知';\n                const lastStatus = item.last_status || item.LastStatus || 'unknown';\n                const lastMessage = item.last_message || item.LastMessage || '暂无说明';\n                const alertLevel = item.alert_level || item.AlertLevel || 'normal';\n                return `<div style=\"background:#fff; border:1px solid #e2e8f0; border-radius:10px; padding:10px; font-size:12px; color:#334155; line-height:1.6;\"><strong>${escapeHtml(name)}</strong><div>心跳状态：${escapeHtml(lastStatus)}</div><div>最近心跳：${escapeHtml(lastSeenAt)}</div><div>告警级别：${escapeHtml(alertLevel)}</div><div>说明：${escapeHtml(lastMessage)}</div></div>`;\n            }).join('');\n        }\n\n        function renderRoutineAlerts(alerts) {\n            const container = document.getElementById('routineAlertsList');\n            if (!container) return;\n            const items = Array.isArray(alerts) ? alerts : [];\n            if (!items.length) {\n                container.innerHTML = '<div style=\"font-size:12px; color:#64748b;\">当前没有异常告警</div>';\n                return;\n            }\n            container.innerHTML = items.map(item => {\n                const level = item.alert_level || item.alertLevel || 'warning';\n                const message = item.message || '异常告警';\n                const routineId = item.routine_id || item.routineId || '';\n                return `<div style=\"background:#fff; border:1px solid #e2e8f0; border-radius:10px; padding:10px; font-size:12px; color:#334155; line-height:1.6;\"><strong>${escapeHtml(String(level))}</strong><div>${escapeHtml(String(message))}</div><div style=\"display:flex; gap:8px; flex-wrap:wrap; margin-top:8px;\"><button onclick=\"recoverRoutineJob('${routineId}')\" style=\"padding:6px 10px; background:#2563eb; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">恢复任务</button><button onclick=\"ackRoutineAlert('${routineId}')\" style=\"padding:6px 10px; background:#64748b; color:#fff; border:none; border-radius:8px; cursor:pointer; font-weight:bold;\">确认告警</button></div></div>`;\n            }).join('');\n        }\n\n        async function recoverRoutineJob(routineId) {\n            const targetId = String(routineId || document.getElementById('routineIdInput')?.value || '').trim();\n            if (!targetId) {\n                showAppDialog({ tone: 'warning', title: '还没有选中任务', message: '请先选择一条告警中的周期任务，再执行恢复。' });\n                return;\n            }\n            const res = await fetch('/api/routines/recover', {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify({ id: targetId })\n            });\n            if (!res.ok) {\n                throw new Error((await res.text()) || '恢复周期任务失败');\n            }\n            await refreshRoutineManager();\n            showAppDialog({ tone: 'success', title: '周期任务已恢复', message: `周期任务 ${targetId} 已重新启用并清空失败计数。` });\n        }\n\n        async function ackRoutineAlert(routineId) {\n            const targetId = String(routineId || document.getElementById('routineIdInput')?.value || '').trim();\n            if (!targetId) {\n                showAppDialog({ tone: 'warning', title: '还没有选中任务', message: '请先选择一条告警中的周期任务，再确认告警。' });\n                return;\n            }\n            const res = await fetch('/api/alerts/ack', {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify({ id: targetId })\n            });\n            if (!res.ok) {\n                throw new Error((await res.text()) || '确认告警失败');\n            }\n            await refreshRoutineManager();\n            showAppDialog({ tone: 'success', title: '告警已确认', message: `周期任务 ${targetId} 的最近告警时间已更新。` });\n        }\n\n        async function refreshRoutineManager() {\n            const [routineRes, historyRes, heartbeatRes, alertRes] = await Promise.all([\n                fetch('/api/routines'),\n                fetch('/api/routines/history'),\n                fetch('/api/heartbeat'),\n                fetch('/api/alerts')\n            ]);\n            if (!routineRes.ok) {\n                throw new Error((await routineRes.text()) || '读取周期任务失败');\n            }\n            const routines = await routineRes.json();\n            const history = historyRes.ok ? await historyRes.json() : [];\n            const heartbeats = heartbeatRes.ok ? await heartbeatRes.json() : {};\n            const alerts = alertRes.ok ? await alertRes.json() : [];\n            routineManagerCache = Array.isArray(routines) ? routines : [];\n            routineHistoryCache = Array.isArray(history) ? history : [];\n            heartbeatCache = heartbeats || {};\n            renderRoutineList(routineManagerCache);\n            renderRoutineHistory(routineHistoryCache);\n            renderHeartbeatSummary(heartbeatCache);\n            renderRoutineAlerts(alerts);\n            return routineManagerCache;\n        }\n\n        async function openRoutineModal() {\n            const modal = document.getElementById('routineModal');\n            if (!modal) return;\n            modal.style.display = 'flex';\n            resetRoutineForm();\n            try {\n                await refreshRoutineManager();\n            } catch (e) {\n                showAppDialog({ tone: 'error', title: '读取周期任务失败', message: e?.message || String(e) });\n            }\n        }\n\n        async function saveRoutineConfig() {\n            const id = document.getElementById('routineIdInput').value.trim();\n            const name = document.getElementById('routineNameInput').value.trim();\n            const employee = document.getElementById('routineEmployeeInput').value.trim();\n            const intervalMinutes = parseInt(document.getElementById('routineIntervalInput').value, 10) || 0;\n            const nextRunAt = document.getElementById('routineNextRunInput').value.trim();\n            const maxRetries = parseInt(document.getElementById('routineMaxRetriesInput').value, 10) || 0;\n            const retryBackoffMinutes = parseInt(document.getElementById('routineBackoffInput').value, 10) || 0;\n            const prompt = document.getElementById('routinePromptInput').value.trim();\n            const enabled = document.getElementById('routineEnabledInput').checked;\n            if (!name) {\n                showAppDialog({ tone: 'warning', title: '请先填写任务名称', message: '周期任务至少要有一个明确名称，方便团队识别。' });\n                return;\n            }\n            if (!employee) {\n                showAppDialog({ tone: 'warning', title: '请先选择负责员工', message: '请选择一个实际执行该周期任务的员工。' });\n                return;\n            }\n            if (!prompt) {\n                showAppDialog({ tone: 'warning', title: '请先填写执行提示词', message: '没有提示词的话，员工不知道例行任务要做什么。' });\n                return;\n            }\n            if (intervalMinutes <= 0) {\n                showAppDialog({ tone: 'warning', title: '触发间隔无效', message: '请填写大于 0 的触发间隔（分钟）。' });\n                return;\n            }\n            if (retryBackoffMinutes <= 0) {\n                showAppDialog({ tone: 'warning', title: '退避时间无效', message: '请填写大于 0 的失败退避分钟数。' });\n                return;\n            }\n            const payload = {\n                id: id || '',\n                name,\n                employee,\n                enabled,\n                prompt,\n                max_retries: maxRetries,\n                retry_backoff_minutes: retryBackoffMinutes,\n                trigger: {\n                    trigger_kind: 'schedule',\n                    cron_expression: '',\n                    interval_minutes: intervalMinutes\n                },\n                next_run_at: nextRunAt,\n                last_run_at: ''\n            };\n            const res = await fetch('/api/routines', {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify(payload)\n            });\n            if (!res.ok) {\n                throw new Error((await res.text()) || '保存周期任务失败');\n            }\n            await refreshRoutineManager();\n            resetRoutineForm();\n            showAppDialog({ tone: 'success', title: '周期任务已保存', message: '新的例行任务已经写入团队配置。' });\n        }\n\n        async function deleteRoutineJob(routineId) {\n            const targetId = String(routineId || '').trim();\n            if (!targetId) {\n                showAppDialog({ tone: 'warning', title: '还没有选中任务', message: '请先在左侧选择一条周期任务，再决定是否删除。' });\n                return;\n            }\n            if (!confirm(`确定要删除周期任务 ${targetId} 吗？`)) return;\n            const res = await fetch('/api/routines/delete', {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify({ id: targetId })\n            });\n            if (!res.ok) {\n                throw new Error((await res.text()) || '删除周期任务失败');\n            }\n            await refreshRoutineManager();\n            resetRoutineForm();\n            showAppDialog({ tone: 'success', title: '周期任务已删除', message: '这条例行任务已经从团队配置中移除。' });\n        }\n\n        async function runRoutineNow(routineId) {\n            const targetId = String(routineId || '').trim();\n            if (!targetId) {\n                showAppDialog({ tone: 'warning', title: '还没有选中任务', message: '请先在左侧选择一条周期任务，再立即执行。' });\n                return;\n            }\n            const res = await fetch('/api/routines/run', {\n                method: 'POST',\n                headers: { 'Content-Type': 'application/json' },\n                body: JSON.stringify({ id: targetId })\n            });\n            if (!res.ok) {\n                throw new Error((await res.text()) || '立即执行周期任务失败');\n            }\n            await refreshRoutineManager();\n            showAppDialog({ tone: 'success', title: '已触发周期任务立即执行', message: `周期任务 ${targetId} 已经开始执行。` });\n        }\n\n        async function dispatchCeoTask() {\n            const input = document.getElementById('ceoTaskInput');\n            const taskContent = (input?.value || '').trim();\n            if (!taskContent) {\n                showAppDialog({\n                    tone: 'warning',\n                    title: '先写一下项目需求',\n                    message: '请输入这次战略项目的目标、交付内容或执行方向，再让 CEO 帮你拆解任务。'\n                });\n                return;\n            }\n\n            const pmName = 'ceo';\n            const companySop = window.teamConfig?.CompanySOP || '';\n            const allNodes = Object.entries(window.teamConfig?.PeerNodes || {}).filter(([name]) => name !== 'ceo');\n            const busyEmployees = new Set();\n\n            try {\n                const boardRes = await fetch('/api/board');\n                if (boardRes.ok) {\n                    const projects = await boardRes.json();\n                    projects.forEach(project => {\n                        (project.tasks || []).forEach(task => {\n                            const status = String(task.status || task.Status || 'todo').toLowerCase();\n                            if (status === 'todo' || status === 'doing' || status === 'in_progress' || status === 'in_review' || status === 'blocked') {\n                                const assignee = task.assignee || task.Assignee;\n                                if (assignee) busyEmployees.add(assignee);\n                            }\n                        });\n                    });\n                }\n            } catch (e) {\n                console.warn('读取项目看板失败，将继续使用当前员工列表。', e);\n            }\n\n            const availableNodes = allNodes.filter(([name]) => !busyEmployees.has(name));\n            if (availableNodes.length === 0) {\n                showAppDialog({\n                    tone: 'warning',\n                    title: '当前没有空闲员工',\n                    message: '团队里现在没有可分配的新员工。\\n可以先等正在执行的任务完成，或者手动取消部分任务后再试。'\n                });\n                return;\n            }\n\n            const teamInfo = availableNodes.map(([name, info]) => {\n                const role = info.Role || info.role || '待认领';\n                const desc = info.Description || info.description || '暂无职责说明';\n                const manager = info.ReportsTo || info.reportsTo || '无';\n                return `- 姓名：${name}，岗位：${role}，上级：${manager}，职责说明：${desc}`;\n            }).join('\\n');\n\n            const websiteFlowHint = isWebsiteStrategyDemand(taskContent)\n                ? `\\n\\n这是官网/网站类需求，必须按阶段依赖拆解，禁止把测试、预览、上线类任务与 PRD/原型/开发并行下发。推荐阶段：\\n1. prd：先输出 PRD 和验收标准。\\n2. prototype：依赖 prd，输出信息架构/低保真原型。\\n3. uiux：依赖 prototype，输出视觉规范和交互状态。\\n4. frontend：依赖 uiux，完成前端页面和响应式适配。\\n5. backend：依赖 frontend，完成本地服务/资源组织/启动方式。\\n6. test：依赖 frontend 和 backend，输出测试报告。\\n7. preview：依赖 test，产出网站本地测试链接和交付说明。`\n                : '';\n            const planPrompt = `你是公司的 PM 助手，需要把老板给出的战略需求拆解为项目看板 JSON。\\n\\n老板需求：\\n${taskContent}\\n\\n当前可用员工：\\n${teamInfo}${websiteFlowHint}\\n\\n请严格只返回 JSON，不要输出 Markdown、解释、额外说明。返回格式必须是：\\n{\\n  \"project_name\": \"项目名称\",\\n  \"execution_mode\": \"phased 或 standard\",\\n  \"tasks\": [\\n    {\\n      \"id\": \"稳定短 id，例如 prd-1\",\\n      \"title\": \"任务标题\",\\n      \"assignee\": \"员工姓名\",\\n      \"phase\": \"prd/prototype/uiux/frontend/backend/test/preview 或普通阶段名\",\\n      \"depends_on\": [\"前置任务 id，没有则为空数组\"],\\n      \"deliverable\": \"明确交付物\",\\n      \"gate\": \"进入下一阶段的完成条件\"\\n    }\\n  ]\\n}\\n\\n要求：\\n1. 任务数量控制在 1 到 8 条之间。\\n2. assignee 必须从当前可用员工里选择。\\n3. title 必须是明确、可执行、可交付的工作事项。\\n4. 只有没有 depends_on 的首阶段任务可以立即开始；后续任务必须等待前置任务完成。`;\n\n            closeModal('ceoModal');\n            document.getElementById('loadingOverlay').style.display = 'flex';\n            document.querySelector('.hr-loading-text').innerText = '正在生成战略项目...';\n            document.querySelector('.hr-loading-subtext').innerText = 'ceo 正在拆解任务并同步项目看板...';\n\n            try {\n                await fetch('/api/clear', {\n                    method: 'POST',\n                    headers: { 'X-Username': encodeURIComponent(pmName) }\n                }).catch(e => console.warn('清理 ceo 上下文失败，但不影响继续生成。', e));\n\n                const res = await fetch('/api/chat', {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/json', 'X-Username': encodeURIComponent(pmName) },\n                    body: JSON.stringify({\n                        message: planPrompt,\n                        modelIndex: window.teamConfig?.PeerNodes?.[pmName]?.ModelIndex || 0,\n                        sop: companySop,\n                        caller: 'ceo'\n                    })\n                });\n\n                const reader = res.body.getReader();\n                const decoder = new TextDecoder();\n                let fullText = '';\n                let buffer = '';\n                let rawResponseText = '';\n                while (true) {\n                    const { value, done } = await reader.read();\n                    if (done) break;\n                    const chunkText = decoder.decode(value, { stream: true });\n                    rawResponseText += chunkText;\n                    buffer += chunkText;\n                    const parts = buffer.split('|||END|||');\n                    buffer = parts.pop();\n                    for (const part of parts) {\n                        if (!part.trim()) continue;\n                        const msg = parseChatEnvelopeChunk(part);\n                        if (msg && (msg.type === 'final' || msg.type === 'tool_result' || msg.type === 'delta')) {\n                            fullText += String(msg.content || '');\n                        } else {\n                            fullText += stripLeadingBom(part);\n                        }\n                    }\n                }\n\n                const trailing = (buffer || '').trim();\n                if (trailing) {\n                    const msg = parseChatEnvelopeChunk(trailing);\n                    if (msg && (msg.type === 'final' || msg.type === 'tool_result' || msg.type === 'delta')) {\n                        fullText += String(msg.content || '');\n                    } else {\n                        fullText += stripLeadingBom(trailing);\n                    }\n                }\n\n                const cleanedFullText = fullText.replace(/```json/gi, '').replace(/```/g, '').trim();\n                const recoveredText = cleanedFullText || collectChatContentFromRawResponse(rawResponseText);\n                const employeeNames = availableNodes.map(([name]) => name);\n                const parsedBoardData = findStrategyBoardPayload(String(recoveredText || '').replace(/```json/gi, '').replace(/```/g, '').trim())\n                    || findStrategyBoardPayload(rawResponseText);\n                let boardData = parsedBoardData\n                    ? normalizeStrategyBoardData(parsedBoardData, employeeNames, recoveredText || rawResponseText)\n                    : null;\n\n                if (!boardData || !boardData.tasks.length) {\n                    boardData = buildFallbackStrategyBoard(taskContent, availableNodes);\n                    if (boardData.tasks.length) {\n                        console.warn('ceo 结果未能直接解析为项目 JSON，已按岗位自动生成初版规划。', {\n                            taskContent,\n                            recoveredText,\n                            rawResponseText\n                        });\n                        showAppDialog({\n                            tone: 'warning',\n                            title: '已生成一版初始规划',\n                            message: 'CEO 这次返回的内容格式不太规范。\\n我已经按当前岗位自动整理出一版项目规划，你可以在接下来的弹窗里继续修改任务和负责人后再发布。',\n                            confirmText: '继续查看'\n                        });\n                    }\n                }\n\n                if (!boardData.tasks.length) {\n                    throw new Error('ceo 已生成结果，但还没有拆出可执行任务。请换一种更明确的项目描述再试一次。');\n                }\n\n                window.tempStrategyBoardData = boardData;\n                openStrategyEditModal();\n            } catch (e) {\n                showAppDialog({\n                    tone: 'error',\n                    title: '这次还没生成项目规划',\n                    message: 'CEO 暂时没能把需求整理成可执行项目。\\n你可以把需求写得更具体一点，例如目标、交付物、时间范围或希望分给哪些岗位。\\n\\n详细原因：' + (e?.message || e)\n                });\n            } finally {\n                document.getElementById('loadingOverlay').style.display = 'none';\n            }\n        }\n\n        function openStrategyEditModal() {\n            const data = window.tempStrategyBoardData || { project_name: '未命名项目', tasks: [] };\n            document.getElementById('editProjectName').value = data.project_name || '未命名项目';\n            renderStrategyTasks();\n            document.getElementById('strategyEditModal').style.display = 'flex';\n        }\n\n        function renderStrategyTasks() {\n            const container = document.getElementById('editTaskListContainer');\n            container.innerHTML = '';\n            const tasks = window.tempStrategyBoardData?.tasks || [];\n            const employees = Object.keys(window.teamConfig?.PeerNodes || {}).filter(name => name !== 'ceo');\n\n            tasks.forEach((task, index) => {\n                const optionsHtml = employees.map(emp => {\n                    const info = window.teamConfig?.PeerNodes?.[emp] || {};\n                    const role = info.Role || info.role || '';\n                    const manager = info.ReportsTo || info.reportsTo || '无';\n                    const label = role ? `${emp} - ${role}` : emp;\n                    return `<option value=\"${emp}\" ${task.assignee === emp ? 'selected' : ''}>${escapeHtml(label)} / 上级：${escapeHtml(manager)}</option>`;\n                }).join('');\n                const delegationTarget = task.assignee || '';\n                const delegationHint = delegationTarget ? `建议分派给：${delegationTarget}` : '建议分派给：待选择';\n                const dependencyHint = Array.isArray(task.depends_on) && task.depends_on.length\n                    ? `前置：${task.depends_on.join('、')}`\n                    : '前置：无，可首轮启动';\n                const phaseHint = [task.phase ? `阶段：${task.phase}` : '', task.deliverable ? `交付：${task.deliverable}` : '', dependencyHint].filter(Boolean).join(' / ');\n\n                container.innerHTML += `\n                    <div style=\"display:flex; gap:10px; margin-bottom:12px; align-items:center; background:#f8fafc; padding:10px; border-radius:8px; border:1px solid #e2e8f0;\">\n                        <div style=\"display:flex; flex-direction:column; flex:1; gap:6px;\">\n                            <input type=\"text\" value=\"${escapeHtml(task.title || '')}\" onchange=\"window.tempStrategyBoardData.tasks[${index}].title = this.value\" style=\"padding:8px; border:1px solid #cbd5e1; border-radius:6px; outline:none; font-size:14px;\" placeholder=\"请输入任务标题\">\n                            <div style=\"font-size:12px; color:#64748b;\">${escapeHtml(getEmployeeOrgBadge(task.assignee || ''))} / ${escapeHtml(delegationHint)} / 升级给上级</div>\n                            ${phaseHint ? `<div style=\"font-size:12px; color:#2563eb; background:#eff6ff; border:1px solid #bfdbfe; border-radius:6px; padding:6px 8px;\">${escapeHtml(phaseHint)}</div>` : ''}\n                            <div style=\"display:flex; align-items:center; gap:8px;\">\n                                <span style=\"font-size:12px; color:#64748b;\">负责人：</span>\n                                <select onchange=\"window.tempStrategyBoardData.tasks[${index}].assignee = this.value\" style=\"padding:6px; border:1px solid #cbd5e1; border-radius:6px; font-size:13px; outline:none; cursor:pointer;\">\n                                    <option value=\"\">请选择负责人</option>\n                                    ${optionsHtml}\n                                </select>\n                            </div>\n                        </div>\n                        <button onclick=\"deleteStrategyTask(${index})\" style=\"padding:10px; background:#fef2f2; color:#ef4444; border:1px solid #fecaca; border-radius:8px; cursor:pointer; font-size:16px;\" title=\"删除任务\">\ud83d\uddd1</button>\n                    </div>`;\n            });\n\n            if (!tasks.length) {\n                container.innerHTML = '<div style=\"text-align:center; padding:20px; color:#94a3b8;\">还没有任务，点击下方按钮新增一项任务。</div>';\n            }\n        }\n\n        function addStrategyTask() {\n            if (!window.tempStrategyBoardData.tasks) window.tempStrategyBoardData.tasks = [];\n            window.tempStrategyBoardData.tasks.push({\n                id: Math.random().toString(36).substring(2, 10),\n                title: '',\n                assignee: '',\n                status: 'todo'\n            });\n            renderStrategyTasks();\n        }\n\n        function deleteStrategyTask(idx) {\n            window.tempStrategyBoardData.tasks.splice(idx, 1);\n            renderStrategyTasks();\n        }\n\n        function getReadyStrategyTasks(tasks) {\n            const list = Array.isArray(tasks) ? tasks : [];\n            const doneIds = new Set(list.filter(task => String(task.status || '').toLowerCase() === 'done').map(task => String(task.id || '')));\n            return list.filter(task => {\n                const status = String(task.status || 'todo').toLowerCase();\n                const deps = Array.isArray(task.depends_on) ? task.depends_on : [];\n                return (status === 'todo' || status === 'backlog') && deps.every(dep => doneIds.has(String(dep || '')));\n            }).map(task => ({ ...task, status: 'todo' }));\n        }\n\n        async function dispatchStrategyTasksToAssignees(tasks, projectName) {\n            const readyTasks = Array.isArray(tasks) ? tasks.filter(task => task && task.id && task.title && task.assignee) : [];\n            if (!readyTasks.length) return [];\n\n            const dispatchResults = [];\n            for (const task of readyTasks) {\n                const payloadTasks = [{\n                    project_name: String(projectName || ''),\n                    id: String(task.id || ''),\n                    title: [\n                        `项目：${projectName || '未命名项目'}`,\n                        `阶段：${task.phase || '未设置'}`,\n                        `任务：${task.title || ''}`,\n                        task.deliverable ? `交付物：${task.deliverable}` : '',\n                        task.gate ? `完成条件：${task.gate}` : '',\n                        '请直接产出文件或可验证结果，完成后提交执行总结。'\n                    ].filter(Boolean).join('\\n'),\n                    assignee: String(task.assignee || '')\n                }];\n\n                const res = await fetch('/api/agent_task', {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/json', 'X-Username': encodeURIComponent(task.assignee) },\n                    body: JSON.stringify({\n                        message: `请执行下面唯一的看板任务 JSON 数组：\\n${JSON.stringify(payloadTasks, null, 2)}`,\n                        modelIndex: window.teamConfig?.PeerNodes?.[task.assignee]?.ModelIndex || 0,\n                        sop: window.teamConfig?.CompanySOP || '',\n                        caller: 'board'\n                    })\n                });\n                const raw = await res.text();\n                if (!res.ok) {\n                    throw new Error(raw || `任务 ${task.id} 下发失败`);\n                }\n                dispatchResults.push(parseLooseJsonObjectFromText(raw) || { raw });\n            }\n\n            return dispatchResults;\n        }\n\n        async function confirmAndDispatchStrategy() {\n            const boardData = window.tempStrategyBoardData || { tasks: [] };\n            boardData.project_name = document.getElementById('editProjectName').value.trim() || '未命名项目';\n            boardData.tasks = (boardData.tasks || []).filter(task => String(task.title || '').trim() !== '').map((task, index, list) => {\n                const deps = Array.isArray(task.depends_on) ? task.depends_on.filter(Boolean) : [];\n                return {\n                    ...task,\n                    status: deps.length ? (task.status === 'done' ? 'done' : 'backlog') : (task.status || 'todo'),\n                    order: Number.isFinite(task.order) ? task.order : index\n                };\n            });\n\n            if (!boardData.tasks.length) {\n                alert('请至少保留一项任务后再发布。');\n                return;\n            }\n\n            closeModal('strategyEditModal');\n            document.getElementById('loadingOverlay').style.display = 'flex';\n            document.querySelector('.hr-loading-text').innerText = '正在发布项目并开始执行...';\n            document.querySelector('.hr-loading-subtext').innerText = '项目看板和执行任务将同时更新。';\n\n            const pmName = 'ceo';\n            const companySop = window.teamConfig?.CompanySOP || '';\n\n            try {\n                await fetch('/api/board', {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/json' },\n                    body: JSON.stringify(boardData)\n                });\n                await refreshBoard();\n\n                const readyTasks = getReadyStrategyTasks(boardData.tasks);\n                dispatchStrategyTasksToAssignees(readyTasks, boardData.project_name)\n                    .catch(e => console.error('自动下发执行任务失败：', e));\n\n                alert(`项目《${boardData.project_name}》已发布到项目看板。本轮只启动 ${readyTasks.length || 0} 个无前置依赖任务，后续阶段需等待前置任务完成。`);\n            } catch (e) {\n                alert('发布项目失败：' + (e?.message || e));\n            } finally {\n                document.getElementById('loadingOverlay').style.display = 'none';\n            }\n        }\n\n\nfunction adjustGridColumns() {\n    const grid = document.getElementById('mainDeskGrid');\n    if (!grid) return;\n\n    if (window.innerWidth >= 1600) {\n        grid.style.gridTemplateColumns = 'repeat(7, minmax(0, 1fr))';\n    } else if (window.innerWidth >= 1320) {\n        grid.style.gridTemplateColumns = 'repeat(6, minmax(0, 1fr))';\n    } else if (window.innerWidth >= 1024) {\n        grid.style.gridTemplateColumns = 'repeat(5, minmax(0, 1fr))';\n    } else if (window.innerWidth >= 768) {\n        grid.style.gridTemplateColumns = 'repeat(4, minmax(0, 1fr))';\n    } else {\n        grid.style.gridTemplateColumns = '';\n    }\n}\nwindow.addEventListener('resize', adjustGridColumns);\n\nfunction createDeskElement() {\n    const desk = document.createElement('div');\n    desk.className = 'company-card office-card-shell china-office-desk-surface empty-desk';\n    desk.innerHTML = `\n        <div class=\"desk-img-container\">\n            <img src=\"office_bull_01.png\" alt=\"牛马办公图\" class=\"shrimp-desk-img\">\n            <img src=\"office_horse_01.png\" alt=\"空工位\" class=\"empty-desk-img\">\n            <img src=\"penzai2.png\" class=\"desk-penzai\">\n            <img src=\"penzai1.png\" class=\"desk-penzai-2\">\n        </div>\n    `;\n    desk.style.cursor = 'pointer';\n\n    desk.addEventListener('click', () => {\n        if (desk.classList.contains('empty-desk') || desk.classList.contains('away')) {\n            currentTargetDesk = desk;\n            document.getElementById('recruitName').value = '';\n            document.getElementById('recruitRole').value = '';\n            document.getElementById('recruitDesc').value = '';\n            document.getElementById('recruitResume').value = '';\n            document.getElementById('recruitUrl').value = '';\n            document.getElementById('recruitModelIndex').value = '0';\n            document.getElementById('recruitModal').style.display = 'flex';\n        } else if (desk.classList.contains('at-work')) {\n            currentTargetDesk = desk;\n            currentTargetName = desk.querySelector('.id-card-name').innerText;\n            document.getElementById('taskModalTitle').innerText = `给 ${currentTargetName} 分配任务`;\n            document.getElementById('taskInput').value = '';\n            document.getElementById('taskAttachmentInput').value = '';\n            handleTaskAttachmentsChanged(document.getElementById('taskAttachmentInput'));\n            clearTaskModalSnapshotAuditPayload();\n            document.getElementById('taskModal').style.display = 'flex';\n        }\n    });\n\n    document.getElementById('mainDeskGrid').appendChild(desk);\n    adjustGridColumns();\n    return desk;\n}\n\nfunction openSopModal() {\n    document.getElementById('sopInput').value = window.teamConfig?.CompanySOP || '';\n    document.getElementById('sopModal').style.display = 'flex';\n}\n\nasync function saveSopConfig() {\n    const newSop = document.getElementById('sopInput').value.trim();\n    if (!window.teamConfig) return;\n\n    window.teamConfig.CompanySOP = newSop;\n\n    try {\n        const res = await fetch('/api/config', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify(window.teamConfig)\n        });\n        if (res.ok) {\n            alert('公司制度 / SOP 已保存。');\n            closeModal('sopModal');\n        } else {\n            alert('保存公司制度 / SOP 失败，请稍后重试。');\n        }\n    } catch (e) {\n        console.error(e);\n        alert('保存公司制度 / SOP 失败，请检查网络后再试。');\n    }\n}\n\nasync function openBoardModal() {\n    document.getElementById('boardModal').style.display = 'flex';\n    await refreshBoard();\n}\n\nfunction getBoardTaskValue(task, key) {\n    const lower = key.charAt(0).toLowerCase() + key.slice(1);\n    return task?.[lower] ?? task?.[key] ?? '';\n}\n\nasync function retryBoardTask(projectName, taskId, trigger) {\n    const retryButton = trigger && trigger.tagName ? trigger : null;\n    const originalText = retryButton ? retryButton.textContent : '';\n    if (!projectName || !taskId) {\n        showAppDialog({\n            tone: 'warning',\n            title: '暂时无法重试',\n            message: '没有拿到完整的项目或任务信息，请先刷新项目看板后再试。'\n        });\n        return;\n    }\n\n    try {\n        if (retryButton) {\n            retryButton.disabled = true;\n            retryButton.style.pointerEvents = 'none';\n            retryButton.textContent = '重试中...';\n        }\n        const res = await fetch('/api/board/retry', {\n            method: 'POST',\n            cache: 'no-store',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ projectName, taskId })\n        });\n        const rawText = await res.text();\n        const data = parseLooseJsonObjectFromText(rawText) || {};\n\n        if (!res.ok) {\n            throw new Error(data?.message || rawText || '重试失败。');\n        }\n\n        showAppDialog({\n            tone: 'success',\n            title: '已重新发起任务',\n            message: data?.message || '这条任务已经重新提交执行，稍后会自动刷新看板状态。'\n        });\n        await refreshBoard();\n    } catch (e) {\n        showAppDialog({\n            tone: 'error',\n            title: '重新尝试失败',\n            message: e?.message || String(e)\n        });\n    } finally {\n        if (retryButton && retryButton.isConnected) {\n            retryButton.disabled = false;\n            retryButton.style.pointerEvents = '';\n            retryButton.textContent = originalText || '重新尝试';\n        }\n    }\n}\n\nasync function deleteBoardTask(projectName, taskId) {\n    if (!projectName || !taskId) {\n        showAppDialog({\n            tone: 'warning',\n            title: '暂时无法删除',\n            message: '没有拿到完整的项目或任务信息，请先刷新项目看板后再试。'\n        });\n        return;\n    }\n\n    if (!confirm('确定要删除这条任务吗？删除后不会自动恢复。')) {\n        return;\n    }\n\n    try {\n        const res = await fetch('/api/board/task/delete', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ projectName, taskId })\n        });\n        const rawText = await res.text();\n        const data = parseLooseJsonObjectFromText(rawText) || {};\n\n        if (!res.ok) {\n            throw new Error(data?.message || rawText || '删除失败。');\n        }\n\n        showAppDialog({\n            tone: 'success',\n            title: '任务已删除',\n            message: data?.message || '这条任务已经从项目看板移除。'\n        });\n        await refreshBoard();\n    } catch (e) {\n        showAppDialog({\n            tone: 'error',\n            title: '删除任务失败',\n            message: e?.message || String(e)\n        });\n    }\n}\n\nasync function restartProjectTasks(projectName) {\n    if (!projectName) {\n        showAppDialog({\n            tone: 'warning',\n            title: '暂时无法重新开始',\n            message: '没有拿到项目名称，请先刷新项目看板后再试。'\n        });\n        return;\n    }\n\n    if (!confirm(`确定要一键重新开始《${projectName}》里的任务吗？`)) {\n        return;\n    }\n\n    try {\n        const res = await fetch('/api/board/project/restart', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ projectName })\n        });\n        const rawText = await res.text();\n        const data = parseLooseJsonObjectFromText(rawText) || {};\n\n        if (!res.ok) {\n            throw new Error(data?.message || rawText || '一键重新开始失败。');\n        }\n\n        showAppDialog({\n            tone: 'success',\n            title: '项目任务已重新开始',\n            message: data?.message || '项目里的任务已经重新提交执行。'\n        });\n        await refreshBoard();\n    } catch (e) {\n        showAppDialog({\n            tone: 'error',\n            title: '一键重新开始失败',\n            message: e?.message || String(e)\n        });\n    }\n}\n\nfunction getCompletedTasksFromProject(project) {\n    const tasks = project?.tasks || project?.Tasks || [];\n    return tasks.filter(task => String(getBoardTaskValue(task, 'Status') || 'todo').toLowerCase() === 'done');\n}\n\nfunction sanitizeExportFileName(name) {\n    return String(name || '未命名项目')\n        .replace(/[\\\\/:*?\"<>|]/g, '_')\n        .replace(/\\s+/g, '_')\n        .slice(0, 80);\n}\n\nfunction formatDocText(value, fallback = '暂无交付内容') {\n    const text = String(value || '').trim();\n    return text ? escapeHtml(text).replace(/\\n/g, '<br>') : fallback;\n}\n\nfunction buildCompletedProjectDocHtml(project) {\n    const projectName = project?.project_name || project?.ProjectName || '未命名项目';\n    const completedTasks = getCompletedTasksFromProject(project);\n    const exportedAt = new Date().toLocaleString('zh-CN', { hour12: false });\n\n    const taskSections = completedTasks.map((task, index) => {\n        const title = getBoardTaskValue(task, 'Title') || `已完成任务 ${index + 1}`;\n        const assignee = getBoardTaskValue(task, 'Assignee') || '待认领';\n        const updateTime = getBoardTaskValue(task, 'UpdateTime') || '未记录完成时间';\n        const result = getBoardTaskValue(task, 'Result');\n\n        return `\n        <div class=\"task-card\">\n            <div class=\"task-index\">已完成工作 ${index + 1}</div>\n            <h2>${escapeHtml(title)}</h2>\n            <div class=\"task-meta\">\n                <span>负责人：${escapeHtml(assignee)}</span>\n                <span>完成时间：${escapeHtml(updateTime)}</span>\n            </div>\n            <div class=\"task-result\">\n                <div class=\"task-result-title\">交付总结</div>\n                <div class=\"task-result-body\">${formatDocText(result, '暂无交付内容')}</div>\n            </div>\n        </div>`;\n    }).join('');\n\n    return `<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>${escapeHtml(projectName)}-已完成工作导出</title>\n  <style>\n    body { font-family: \"Microsoft YaHei\", \"PingFang SC\", sans-serif; color: #1f2937; margin: 32px; line-height: 1.7; }\n    .cover { border: 1px solid #dbeafe; border-radius: 18px; padding: 28px 30px; background: linear-gradient(135deg, #eff6ff, #f8fafc); margin-bottom: 24px; }\n    h1 { margin: 0 0 10px; color: #1d4ed8; font-size: 28px; }\n    .summary { color: #475569; font-size: 14px; }\n    .task-card { border: 1px solid #e2e8f0; border-radius: 16px; padding: 22px; margin-bottom: 18px; background: #fff; }\n    .task-index { display: inline-block; padding: 4px 10px; border-radius: 999px; background: #dcfce7; color: #166534; font-size: 12px; font-weight: 700; margin-bottom: 10px; }\n    h2 { margin: 0 0 10px; font-size: 20px; color: #0f172a; }\n    .task-meta { display: flex; gap: 18px; flex-wrap: wrap; color: #64748b; font-size: 13px; margin-bottom: 16px; }\n    .task-result { background: #f8fafc; border-left: 4px solid #22c55e; border-radius: 10px; padding: 14px 16px; }\n    .task-result-title { font-weight: 700; color: #15803d; margin-bottom: 8px; }\n    .task-result-body { white-space: normal; word-break: break-word; }\n  </style>\n</head>\n<body>\n  <div class=\"cover\">\n    <h1>${escapeHtml(projectName)} 已完成工作导出</h1>\n    <div class=\"summary\">导出时间：${escapeHtml(exportedAt)}</div>\n    <div class=\"summary\">已完成任务数：${completedTasks.length}</div>\n  </div>\n  ${taskSections}\n</body>\n</html>`;\n}\n\nfunction downloadCompletedProjectDoc(event, projectIndex) {\n    if (event) event.stopPropagation();\n\n    const projects = window.latestBoardProjects || [];\n    const project = projects[projectIndex];\n    if (!project) {\n        alert('未找到可导出的项目数据，请先刷新项目看板。');\n        return;\n    }\n\n    const completedTasks = getCompletedTasksFromProject(project);\n    if (!completedTasks.length) {\n        alert('这个项目里还没有已完成任务，暂时无法导出文档。');\n        return;\n    }\n\n    const projectName = project.project_name || project.ProjectName || '未命名项目';\n    const html = buildCompletedProjectDocHtml(project);\n    const blob = new Blob(['\\ufeff' + html], { type: 'application/msword;charset=utf-8' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    const dateTag = new Date().toISOString().slice(0, 10);\n\n    a.href = url;\n    a.download = `${sanitizeExportFileName(projectName)}-已完成工作-${dateTag}.doc`;\n    document.body.appendChild(a);\n    a.click();\n    a.remove();\n    URL.revokeObjectURL(url);\n}\n\nfunction getDeskBudgetTone(monthly, used, softRatio = 0.8, hardRatio = 1.0) {\n    if (monthly > 0 && used >= monthly * hardRatio) return 'hard-stop';\n    if (monthly > 0 && used >= monthly * softRatio) return 'warning';\n    return 'normal';\n}\n\nfunction getDeskHealthSummary(heartbeatStatus, heartbeatMessage) {\n    const tone = getHealthToneMeta(heartbeatStatus);\n    return {\n        label: tone.label,\n        tone: tone.pillClass.replace('health-', ''),\n        title: heartbeatMessage || tone.label\n    };\n}\n\nfunction buildDeskControlPlaneBadges(empName, runs = [], heartbeats = {}) {\n    const configNode = window.teamConfig?.PeerNodes?.[empName] || {};\n    const budgetMonthly = Number(configNode.BudgetMonthly || configNode.budgetMonthly || 0);\n    const budgetUsed = (runs || []).reduce((sum, run) => sum + Number(run.estimatedCost || run.EstimatedCost || 0), Number(configNode.BudgetUsed || configNode.budgetUsed || 0));\n    const budgetTone = getDeskBudgetTone(budgetMonthly, budgetUsed, Number(configNode.BudgetSoftLimitRatio || configNode.budgetSoftLimitRatio || 0.8), Number(configNode.BudgetHardLimitRatio || configNode.budgetHardLimitRatio || 1.0));\n    const heartbeat = heartbeats?.[empName] || {};\n    const healthStatus = heartbeat.last_status || heartbeat.LastStatus || 'healthy';\n    const healthMessage = heartbeat.last_message || heartbeat.LastMessage || '点击查看控制卡';\n    const healthSummary = getDeskHealthSummary(healthStatus, healthMessage);\n    const taskSummary = buildDeskTaskPostureSummary(empName);\n    const recommendationBadge = buildDeskGovernanceRecommendationBadge(empName, taskSummary);\n    return {\n        healthHtml: `<span class=\"desk-health-badge desk-status-chip primary ${escapeHtml(healthSummary.tone)}\" title=\"${escapeHtml(healthSummary.title)}\">健康状态：${escapeHtml(healthSummary.label)}</span>`,\n        budgetHtml: `<span class=\"desk-budget-badge desk-status-chip secondary ${escapeHtml(budgetTone)}\" title=\"点击查看控制卡\">预算风险：${escapeHtml(budgetTone === 'hard-stop' ? '高' : budgetTone === 'warning' ? '中' : '低')}</span>`,\n        taskHtml: `<button type=\"button\" class=\"desk-task-badge desk-status-chip secondary ${escapeHtml(taskSummary.tone)}\" title=\"${escapeHtml(taskSummary.title)}\" onclick=\"event.stopPropagation(); openDeskTaskFocusPanel('${escapeJsSingleQuotedString(empName)}')\">待审核任务：${escapeHtml(String(taskSummary.inReviewCount))} / 阻塞任务：${escapeHtml(String(taskSummary.blockedCount))}</button>`,\n        recommendationHtml: recommendationBadge\n    };\n}\n\nfunction buildDeskTaskPostureSummary(empName) {\n    const summary = buildEmployeeTaskPostureSummary(empName);\n    const recommendedAction = summary.recommendedTask?.recommendation?.action || '暂无';\n    const recommendedTaskTitle = summary.recommendedTask ? String(summary.recommendedTask.task?.title || summary.recommendedTask.task?.Title || '未命名任务') : '暂无';\n    const tone = summary.blockedCount > 0 ? 'error' : summary.inReviewCount > 0 ? 'warning' : 'info';\n    return {\n        inReviewCount: summary.inReviewCount,\n        blockedCount: summary.blockedCount,\n        recommendedAction,\n        recommendedTaskTitle,\n        tone,\n        title: `当前最需要处理：${recommendedTaskTitle} / ${recommendedAction}`\n    };\n}\n\nfunction buildDeskGovernanceRecommendationBadge(empName, taskSummary = null) {\n    const summary = taskSummary || buildDeskTaskPostureSummary(empName);\n    return `<button type=\"button\" class=\"desk-recommendation-badge ${escapeHtml(summary.tone)}\" title=\"${escapeHtml(summary.title)}\" onclick=\"event.stopPropagation(); openDeskTaskFocusPanel('${escapeJsSingleQuotedString(empName)}')\">当前最需要处理：${escapeHtml(summary.recommendedAction)}</button>`;\n}\n\nfunction buildDeskTaskFocusContext(empName) {\n    const summary = buildEmployeeTaskPostureSummary(empName);\n    const recommendedTask = summary.recommendedTask || null;\n    const task = recommendedTask?.task || summary.topPriorityTask?.task || null;\n    const recommendation = recommendedTask?.recommendation || (task ? buildTaskGovernanceRecommendation(task, empName) : null);\n    const latestRun = task ? findLatestRunForTask(task, empName) : null;\n    const history = task ? buildTaskExecutionHistory(task, empName) : null;\n    const reviewer = task ? (recommendation?.reviewer || getBoardTaskReviewer(task, empName) || '暂无') : '暂无';\n    const consistency = task ? (recommendation?.consistency || getBoardTaskStatusConsistency(task, latestRun)) : '暂无';\n    const latestGovernanceAction = task ? (recommendation?.latestComment || getLatestBoardTaskGovernanceAction(task)) : '暂无';\n    return {\n        employee: empName,\n        summary,\n        task,\n        recommendation,\n        latestRun,\n        history,\n        reviewer,\n        consistency,\n        latestGovernanceAction\n    };\n}\n\nfunction renderDeskTaskFocusPanel(context) {\n    const body = document.getElementById('deskTaskFocusBody');\n    const title = document.getElementById('deskTaskFocusTitle');\n    const primaryBtn = document.getElementById('deskTaskFocusPrimaryBtn');\n    const secondaryBtn = document.getElementById('deskTaskFocusSecondaryBtn');\n    if (!body || !title || !primaryBtn || !secondaryBtn) return;\n    const employee = String(context?.employee || '').trim();\n    const task = context?.task || null;\n    const recommendation = context?.recommendation || null;\n    title.textContent = `${employee || '员工'} / 工位任务快捷面板`;\n    if (!task || !recommendation) {\n        body.innerHTML = '<div class=\"agent-inline-note\">当前没有可直接处理的任务。</div>';\n        primaryBtn.textContent = '直接处理';\n        secondaryBtn.textContent = '打开关联运行';\n        primaryBtn.disabled = true;\n        secondaryBtn.disabled = true;\n        return;\n    }\n    const taskId = String(task?.id || task?.Id || '').trim();\n    const taskTitle = String(task?.title || task?.Title || '未命名任务');\n    const taskStatus = getBoardTaskStatusLabel(task?.status || task?.Status || 'todo');\n    const policy = buildTaskGovernanceCtaPolicy('desk', task, employee);\n    const reason = String(recommendation?.reason || '暂无');\n    const reviewer = String(context?.reviewer || '暂无');\n    const consistency = String(context?.consistency || '暂无');\n    const latestGovernanceAction = String(context?.latestGovernanceAction || '暂无');\n    const history = context?.history || { recentRuns: [] };\n    const historyMarkup = Array.isArray(history?.recentRuns) && history.recentRuns.length\n        ? history.recentRuns.slice(0, 3).map(run => {\n            const runStatus = String(run?.status || run?.Status || 'unknown');\n            const runTime = String(run?.updatedAt || run?.UpdatedAt || run?.createdAt || run?.CreatedAt || '暂无');\n            const runSummary = String(run?.summary || run?.Summary || run?.taskText || run?.TaskText || '暂无摘要');\n            return `<div class=\"board-task-history-item\"><strong>${escapeHtml(runStatus)}</strong> / ${escapeHtml(runTime)}<br>${escapeHtml(runSummary)}</div>`;\n        }).join('')\n        : '<div class=\"board-task-history-item\">同任务最近执行历史：暂无</div>';\n    const reviewPresentation = buildTaskCtaSectionPresentation('review', task, employee, { recommendation, consistency });\n    const executionSummaryPresentation = buildTaskCtaSectionPresentation('execution', task, employee, { recommendation, consistency });\n    const executionHistoryPresentation = buildTaskCtaSectionPresentation('execution', task, employee, { recommendation, consistency });\n    const primaryPresentation = buildTaskCtaSectionPresentation('primary', task, employee, { recommendation, consistency });\n    const navigationPresentation = buildTaskCtaSectionPresentation('navigation', task, employee, { recommendation, consistency });\n    const phasePresentation = buildTaskCtaSectionPresentation('phase', task, employee, { surface: 'desk', recommendation, consistency });\n    const handoffPresentation = buildTaskCtaSectionPresentation('handoff', task, employee, { surface: 'desk', recommendation, consistency });\n    const phase = buildTaskControlPlanePhase('desk', task, employee, { recommendation, consistency });\n    const handoff = buildTaskCtaModeHandoff('desk', task, employee, { recommendation, consistency, phase });\n    const reviewBodyHtml = renderTaskGovernanceActionGroup(policy.reviewActions.map(action => ({ action, buttonClass: 'board-task-control-btn' })), taskId, employee, { surface: 'desk', task, latestRun: context?.latestRun || null, closeDeskTaskFocusModal: true });\n    const navigationBodyHtml = renderTaskNavigationActionGroup(policy.navigationActions, taskId, employee, { buttonClass: 'board-task-recommendation-btn', closeDeskTaskFocusModal: true });\n    const primaryBodyHtml = renderTaskGovernanceActionGroup(policy.primaryAction ? [{ action: policy.primaryAction, label: policy.primaryAction, buttonClass: 'board-task-recommendation-btn', closeDeskTaskFocusModal: true }] : [], taskId, employee, { surface: 'desk', task, latestRun: context?.latestRun || null, closeDeskTaskFocusModal: true });\n    const phaseBodyHtml = renderTaskControlPlanePhaseBody(phase);\n    const handoffBodyHtml = renderTaskCtaModeHandoffBody(handoff, taskId, employee, { buttonClass: 'board-task-recommendation-btn', closeDeskTaskFocusModal: true });\n    const executionSummaryBodyHtml = `<span class=\"board-task-risk-pill\">同任务最近执行历史</span>`;\n    const executionHistoryBodyHtml = historyMarkup;\n    const reviewPolicy = policy.reviewActions.length\n        ? buildTaskCtaSectionPolicy('review', task, employee, { surface: 'desk', recommendation, consistency, bodyHtml: reviewBodyHtml, sectionClass: 'desk-task-focus-review-actions' })\n        : null;\n    const navigationPolicy = buildTaskCtaSectionPolicy('navigation', task, employee, { surface: 'desk', recommendation, consistency, phase, bodyHtml: navigationBodyHtml, sectionClass: 'desk-task-focus-navigation-actions' });\n    const primaryPolicy = buildTaskCtaSectionPolicy('primary', task, employee, { surface: 'desk', recommendation, consistency, phase, bodyHtml: primaryBodyHtml, sectionClass: 'desk-task-focus-inline-actions' });\n    const phasePolicy = buildTaskCtaSectionPolicy('phase', task, employee, { surface: 'desk', recommendation, consistency, phase, bodyHtml: phaseBodyHtml, sectionClass: 'desk-task-focus-navigation-actions' });\n    const handoffPolicy = buildTaskCtaSectionPolicy('handoff', task, employee, { surface: 'desk', recommendation, consistency, phase, handoff, bodyHtml: handoffBodyHtml, sectionClass: 'desk-task-focus-navigation-actions' });\n    const executionSummaryPolicy = buildTaskCtaSectionPolicy('summary', task, employee, { surface: 'desk', recommendation, consistency, phase, bodyHtml: executionSummaryBodyHtml });\n    const executionHistoryPolicy = buildTaskCtaSectionPolicy('execution', task, employee, { surface: 'desk', recommendation, consistency, phase, bodyHtml: executionHistoryBodyHtml, sectionClass: 'board-task-comment-timeline', compact: false });\n    const executionSections = renderTaskCtaSections(buildTaskCtaSectionOrder('desk', phase, [\n        executionSummaryPolicy.visible ? { kind: 'summary', taskId, title: executionSummaryPolicy.title, bodyHtml: executionSummaryBodyHtml, sectionClass: executionSummaryPolicy.sectionClass, tone: executionSummaryPresentation.tone, priority: executionSummaryPresentation.priority, actionDensity: executionSummaryPolicy.actionDensity } : null,\n        executionHistoryPolicy.visible ? { kind: 'execution', taskId, title: executionHistoryPolicy.title, bodyHtml: executionHistoryBodyHtml, sectionClass: executionHistoryPolicy.sectionClass, tone: executionHistoryPresentation.tone, priority: executionHistoryPresentation.priority, actionDensity: executionHistoryPolicy.actionDensity } : null\n    ].filter(Boolean)));\n    const orderedSections = buildTaskCtaSectionOrder('desk', phase, [\n        primaryPolicy.visible ? { kind: 'primary', taskId, title: primaryPolicy.title, bodyHtml: primaryBodyHtml, sectionClass: primaryPolicy.sectionClass, tone: primaryPresentation.tone, priority: primaryPresentation.priority, actionDensity: primaryPolicy.actionDensity } : null,\n        reviewPolicy?.visible ? { kind: 'review', taskId, title: reviewPolicy.title, bodyHtml: reviewBodyHtml, sectionClass: reviewPolicy.sectionClass, tone: reviewPresentation.tone, priority: reviewPresentation.priority, actionDensity: reviewPolicy.actionDensity } : null,\n        navigationPolicy.visible ? { kind: 'navigation', taskId, title: navigationPolicy.title, bodyHtml: navigationBodyHtml, sectionClass: navigationPolicy.sectionClass, tone: navigationPresentation.tone, priority: navigationPresentation.priority, actionDensity: navigationPolicy.actionDensity } : null,\n        phasePolicy.visible ? { kind: 'phase', taskId, title: phasePolicy.title, bodyHtml: phaseBodyHtml, sectionClass: phasePolicy.sectionClass, tone: phasePresentation.tone, priority: phasePresentation.priority, actionDensity: phasePolicy.actionDensity } : null,\n        handoffPolicy.visible ? { kind: 'handoff', taskId, title: handoffPolicy.title, bodyHtml: handoffBodyHtml, sectionClass: handoffPolicy.sectionClass, tone: handoffPresentation.tone, priority: handoffPresentation.priority, actionDensity: handoffPolicy.actionDensity } : null\n    ].filter(Boolean));\n    const deskPreferenceDigest = buildTaskCtaPreferenceDigest('desk', taskId, phase, orderedSections, { employeeName: employee });\n    const ctaSections = `${deskPreferenceDigest}${renderTaskCtaSections(orderedSections, { wrapperClass: 'desk-task-focus-cta-sections' })}`;\n    primaryBtn.disabled = false;\n    secondaryBtn.disabled = !policy.secondaryAction;\n    const deskSurfacePhase = buildTaskControlPlanePhase('desk', task, employee, { latestRun: context?.latestRun || null, recommendation });\n    const deskSurfaceGate = buildTaskSurfaceSnapshotAuditGate('desk', task, employee, { latestRun: context?.latestRun || null, phase: deskSurfacePhase });\n    const deskStatusStrip = renderTaskSurfaceSnapshotAuditStatusStrip(deskSurfaceGate, { phase: deskSurfacePhase });\n    const deskPrimaryGuard = applyTaskSurfaceSnapshotAuditActionGuard(policy.primaryAction || recommendation.action || '直接处理', deskSurfaceGate, { label: policy.primaryAction || recommendation.action || '直接处理' });\n    primaryBtn.disabled = primaryBtn.disabled || deskPrimaryGuard.disabled;\n    primaryBtn.textContent = deskPrimaryGuard.label;\n    primaryBtn.title = deskPrimaryGuard.title;\n    primaryBtn.classList.toggle('conflict-auto-handle-review-first', deskPrimaryGuard.className.includes('conflict-auto-handle-review-first'));\n    primaryBtn.classList.toggle('conflict-auto-handle-blocking', deskPrimaryGuard.className.includes('conflict-auto-handle-blocking'));\n    secondaryBtn.textContent = policy.secondaryAction || '打开关联运行';\n    body.innerHTML = `<div class=\"board-task-recommendation-card\"><div class=\"board-task-recommendation-title\"><span>最重要任务</span><span class=\"board-task-posture-pill ${escapeHtml(recommendation.tone || 'info')}\">${escapeHtml(taskStatus)}</span></div><div class=\"board-task-recommendation-summary\">${escapeHtml(taskTitle)} / 推荐动作原因：${escapeHtml(reason)}</div><div class=\"board-task-recommendation-summary\">直接处理：${escapeHtml(policy.primaryAction || recommendation.action || '暂无')} / 当前负责人：${escapeHtml(employee)}</div><div class=\"board-task-recommendation-summary\">任务编号：${escapeHtml(taskId || '暂无')} / 审核责任人：${escapeHtml(reviewer)}</div><div class=\"board-task-recommendation-summary\">看板状态一致性：${escapeHtml(consistency)} / 最近治理动作：${escapeHtml(latestGovernanceAction)}</div>${deskStatusStrip}${executionSections}${ctaSections}</div>`;\n}\n\nfunction openDeskTaskFocusPanel(empName) {\n    const employee = String(empName || '').trim();\n    if (!employee) return;\n    currentDeskTaskFocusContext = buildDeskTaskFocusContext(employee);\n    const modal = document.getElementById('deskTaskFocusModal');\n    renderDeskTaskFocusPanel(currentDeskTaskFocusContext);\n    if (modal) modal.style.display = 'flex';\n}\n\nfunction openDeskTaskFocusBoardTask() {\n    const context = currentDeskTaskFocusContext;\n    const taskId = String(context?.task?.id || context?.task?.Id || '').trim();\n    const employee = String(context?.employee || '').trim();\n    if (!taskId) return;\n    performTaskNavigationAction('查看任务看板', taskId, employee, { closeDeskTaskFocusModal: true }).catch(err => showAppDialog({ title: '打开任务导航失败', message: err.message || '任务导航打开失败', tone: 'error' }));\n}\n\nfunction openDeskTaskFocusLineage() {\n    const context = currentDeskTaskFocusContext;\n    const taskId = String(context?.task?.id || context?.task?.Id || '').trim();\n    const employee = String(context?.employee || '').trim();\n    if (!taskId) return;\n    performTaskNavigationAction('查看任务目标链', taskId, employee, { closeDeskTaskFocusModal: true }).catch(err => showAppDialog({ title: '打开任务导航失败', message: err.message || '任务导航打开失败', tone: 'error' }));\n}\n\nfunction openDeskTaskFocusTimeline() {\n    const context = currentDeskTaskFocusContext;\n    const taskId = String(context?.task?.id || context?.task?.Id || '').trim();\n    const employee = String(context?.employee || '').trim();\n    if (!taskId) return;\n    performTaskNavigationAction('查看执行历史', taskId, employee, { closeDeskTaskFocusModal: true }).catch(err => showAppDialog({ title: '打开任务导航失败', message: err.message || '任务导航打开失败', tone: 'error' }));\n}\n\nfunction buildTaskGovernanceActionSpec(action, taskId, employeeName, options = {}) {\n    const normalizedAction = String(action || '').trim();\n    const normalizedTaskId = String(taskId || '').trim();\n    const normalizedEmployee = String(employeeName || '').trim();\n    if (!normalizedAction || !normalizedTaskId) return null;\n    const buttonClass = String(options?.buttonClass || 'board-task-recommendation-btn').trim() || 'board-task-recommendation-btn';\n    const label = String(options?.label || normalizedAction).trim() || normalizedAction;\n    const closeDeskTaskFocusModal = Boolean(options?.closeDeskTaskFocusModal);\n    const spec = {\n        action: normalizedAction,\n        taskId: normalizedTaskId,\n        employeeName: normalizedEmployee,\n        label,\n        buttonClass,\n        closeDeskTaskFocusModal,\n        errorTitle: '治理动作失败',\n        errorMessage: '治理动作执行失败'\n    };\n    if (normalizedAction === '先恢复执行' || normalizedAction === '打开关联运行') {\n        return { ...spec, errorTitle: '打开运行失败', errorMessage: '任务运行打开失败' };\n    }\n    if (normalizedAction === '先提交审核') {\n        return { ...spec, errorTitle: '提交审核失败', errorMessage: '提交审核失败' };\n    }\n    if (normalizedAction === '先通知审核责任人') {\n        return { ...spec, errorTitle: '评论失败', errorMessage: '添加评论失败' };\n    }\n    if (normalizedAction === '先升级给上级') {\n        return { ...spec, errorTitle: '升级失败', errorMessage: '升级处理失败' };\n    }\n    if (normalizedAction === '先补充评论 / 上下文') {\n        return { ...spec, errorTitle: '评论失败', errorMessage: '添加评论失败' };\n    }\n    if (normalizedAction === '批准审核') {\n        return { ...spec, errorTitle: '批准失败', errorMessage: '批准审核失败' };\n    }\n    if (normalizedAction === '打回修改') {\n        return { ...spec, errorTitle: '打回失败', errorMessage: '打回修改失败' };\n    }\n    return spec;\n}\n\nasync function performTaskGovernanceAction(action, taskId, employeeName, options = {}) {\n    const spec = buildTaskGovernanceActionSpec(action, taskId, employeeName, options);\n    if (!spec) return;\n    const snapshotAuditTrace = options?.snapshotAuditTrace || null;\n    if (snapshotAuditTrace?.summary) {\n        console.info('治理动作携带 snapshot 判定摘要', snapshotAuditTrace);\n        recordTaskGovernanceSnapshotAuditTrace(spec.taskId, spec.employeeName, snapshotAuditTrace, { action: spec.action });\n    }\n    if (spec.action === '先恢复执行' || spec.action === '打开关联运行') {\n        await openBoardTaskLatestRun(spec.taskId, spec.employeeName);\n    } else if (spec.action === '先审批继续') {\n        await approveBoardTaskAgentApproval(spec.taskId, spec.employeeName, null);\n    } else if (spec.action === '先提交审核') {\n        await submitBoardTaskForReview(spec.taskId);\n    } else if (spec.action === '先通知审核责任人') {\n        await addBoardTaskComment(spec.taskId, '请审核责任人尽快处理。', spec.employeeName);\n    } else if (spec.action === '先升级给上级') {\n        await escalateBoardTaskToManager(spec.taskId, spec.employeeName);\n    } else if (spec.action === '批准审核') {\n        await approveBoardTaskReview(spec.taskId, spec.employeeName);\n    } else if (spec.action === '打回修改') {\n        await rejectBoardTaskReview(spec.taskId, spec.employeeName);\n    } else {\n        await addBoardTaskComment(spec.taskId, '', spec.employeeName);\n    }\n    if (spec.closeDeskTaskFocusModal) {\n        closeModal('deskTaskFocusModal');\n    }\n}\n\nfunction renderTaskGovernanceActionButton(action, taskId, employeeName, options = {}) {\n    const spec = buildTaskGovernanceActionSpec(action, taskId, employeeName, options);\n    if (!spec) return '';\n    const gate = buildTaskSurfaceSnapshotAuditGate(String(options?.surface || 'board').trim().toLowerCase(), options?.task || null, employeeName, options);\n    const guard = applyTaskSurfaceSnapshotAuditActionGuard(action, gate, options);\n    const actionTrace = buildTaskSurfaceSnapshotAuditActionTrace(gate, { ...options, action: spec.action });\n    const actionTraceIdMeta = escapeHtml(String(actionTrace.traceId || ''));\n    const actionTraceSummaryMeta = escapeHtml(String(actionTrace.summary || ''));\n    const optionParts = [];\n    if (spec.closeDeskTaskFocusModal) optionParts.push('closeDeskTaskFocusModal: true');\n    if (actionTrace.summary) {\n        optionParts.push(`snapshotAuditTrace: { traceId: '${escapeJsSingleQuotedString(actionTrace.traceId || '')}', summary: '${escapeJsSingleQuotedString(actionTrace.summary || '')}', copyText: '${escapeJsSingleQuotedString(actionTrace.copyText || '')}', actionLabel: '${escapeJsSingleQuotedString(actionTrace.actionLabel || '')}' }`);\n    }\n    const optionsJs = optionParts.length ? `{ ${optionParts.join(', ')} }` : '{}';\n    return `<button type=\"button\" class=\"${escapeHtml(spec.buttonClass)} ${escapeHtml(guard.className)}\"${guard.disabled ? ' disabled' : ''} title=\"${escapeHtml(guard.title || actionTrace.actionLabel || '')}\" data-snapshot-audit-action-trace-id=\"${actionTraceIdMeta}\" data-snapshot-audit-action-trace-summary=\"${actionTraceSummaryMeta}\" onclick=\"event.stopPropagation(); performTaskGovernanceAction('${escapeJsSingleQuotedString(spec.action)}', '${escapeJsSingleQuotedString(spec.taskId)}', '${escapeJsSingleQuotedString(spec.employeeName)}', ${optionsJs}).catch(err => showAppDialog({ title: '${escapeJsSingleQuotedString(spec.errorTitle)}', message: err.message || '${escapeJsSingleQuotedString(spec.errorMessage)}', tone: 'error' }))\">${escapeHtml(guard.label)}</button>`;\n}\n\nfunction renderTaskGovernanceActionGroup(actions, taskId, employeeName, options = {}) {\n    if (!Array.isArray(actions) || !actions.length) return '';\n    return actions.map(item => {\n        const action = typeof item === 'string' ? item : item?.action;\n        if (!action) return '';\n        const mergedOptions = {\n            ...(options || {}),\n            ...(typeof item === 'string' ? {} : item)\n        };\n        delete mergedOptions.action;\n        return renderTaskGovernanceActionButton(action, taskId, employeeName, mergedOptions);\n    }).filter(Boolean).join('');\n}\n\nfunction getTaskGovernanceSnapshotAuditTraceKey(taskId, employeeName) {\n    const normalizedTaskId = String(taskId || '').trim() || 'unknown-task';\n    const normalizedEmployee = String(employeeName || '').trim() || 'unknown-employee';\n    return `task-governance-snapshot-audit-trace:${normalizedTaskId}:${normalizedEmployee}`;\n}\n\nfunction recordTaskGovernanceSnapshotAuditTrace(taskId, employeeName, trace, options = {}) {\n    if (!trace?.summary) return null;\n    const record = {\n        traceId: String(trace.traceId || '').trim(),\n        summary: String(trace.summary || '').trim(),\n        copyText: String(trace.copyText || trace.summary || '').trim(),\n        action: String(options?.action || trace.action || '').trim(),\n        actionLabel: String(trace.actionLabel || '').trim(),\n        taskId: String(taskId || '').trim(),\n        employeeName: String(employeeName || '').trim(),\n        recordedAt: new Date().toISOString(),\n        note: '最近治理动作摘要已记录',\n        snapshotAuditActionTrace: true\n    };\n    try {\n        localStorage.setItem(getTaskGovernanceSnapshotAuditTraceKey(taskId, employeeName), JSON.stringify(record));\n    } catch (err) {\n        console.warn('记录治理动作判定摘要失败', err);\n    }\n    return record;\n}\n\nfunction readTaskGovernanceSnapshotAuditTrace(taskId, employeeName) {\n    try {\n        const raw = localStorage.getItem(getTaskGovernanceSnapshotAuditTraceKey(taskId, employeeName));\n        return raw ? JSON.parse(raw) : null;\n    } catch {\n        return null;\n    }\n}\n\nfunction getWorklogRunSnapshotAuditActionTrace(run) {\n    const directTrace = run?.snapshotAuditActionTrace || run?.SnapshotAuditActionTrace || null;\n    if (directTrace?.summary) return directTrace;\n    const taskId = String(run?.taskId || run?.TaskId || run?.taskID || '').trim();\n    const employeeName = String(run?.employeeName || run?.EmployeeName || run?.user || run?.User || currentTargetName || '').trim();\n    if (!taskId) return null;\n    return readTaskGovernanceSnapshotAuditTrace(taskId, employeeName);\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceFreshnessPolicy(trace, options = {}) {\n    const maxAgeMinutes = Number(options?.maxAgeMinutes || 120);\n    const recordedAtRaw = String(trace?.recordedAt || '').trim();\n    const recordedAtMs = recordedAtRaw ? Date.parse(recordedAtRaw) : NaN;\n    const ageMinutes = Number.isFinite(recordedAtMs) ? Math.max(0, Math.round((Date.now() - recordedAtMs) / 60000)) : null;\n    const freshness = ageMinutes === null ? 'unknown' : ageMinutes <= maxAgeMinutes ? 'fresh' : 'stale';\n    const freshnessLabel = freshness === 'fresh' ? '新鲜' : freshness === 'stale' ? '已过期' : '未知';\n    const shouldReview = freshness !== 'fresh';\n    const reviewLabel = shouldReview ? '建议复核' : '无需复核';\n    const reviewHint = freshness === 'stale'\n        ? '动作摘要已过期，建议重新复核当前 gate。'\n        : freshness === 'unknown'\n            ? '动作摘要缺少记录时间，建议复核后再沿用。'\n            : '动作摘要仍在有效期内，可继续沿用。';\n    return { freshness, freshnessLabel, ageMinutes, maxAgeMinutes, shouldReview, reviewLabel, reviewHint };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceMatchPolicy(trace, run, options = {}) {\n    const traceTaskId = String(trace?.taskId || '').trim();\n    const traceEmployee = String(trace?.employeeName || '').trim();\n    const runTaskId = String(run?.taskId || run?.TaskId || run?.taskID || options?.taskId || '').trim();\n    const runEmployee = String(run?.employeeName || run?.EmployeeName || run?.user || run?.User || options?.employeeName || currentTargetName || '').trim();\n    const taskMatched = !traceTaskId || !runTaskId || traceTaskId === runTaskId;\n    const employeeMatched = !traceEmployee || !runEmployee || traceEmployee === runEmployee;\n    const match = taskMatched && employeeMatched ? 'matched' : 'mismatch';\n    const matchLabel = match === 'matched' ? '匹配当前工作日志' : '与当前工作日志不一致';\n    const shouldReview = match !== 'matched';\n    const reviewLabel = shouldReview ? '建议复核' : '无需复核';\n    const reviewHint = shouldReview ? '动作摘要与当前工作日志不一致，建议重新确认任务/员工。' : '动作摘要与当前工作日志上下文一致。';\n    return { match, matchLabel, taskMatched, employeeMatched, traceTaskId, traceEmployee, runTaskId, runEmployee, shouldReview, reviewLabel, reviewHint };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceTrustPolicy(trace, run, options = {}) {\n    const freshness = buildTaskGovernanceSnapshotAuditTraceFreshnessPolicy(trace, options);\n    const matchPolicy = buildTaskGovernanceSnapshotAuditTraceMatchPolicy(trace, run, options);\n    const trust = !freshness.shouldReview && !matchPolicy.shouldReview\n        ? 'high'\n        : freshness.freshness === 'stale' || matchPolicy.match === 'mismatch'\n            ? 'low'\n            : 'medium';\n    const trustLabel = trust === 'high' ? '高可信' : trust === 'low' ? '低可信' : '中可信';\n    const action = trust === 'high' ? 'reuse-trace' : trust === 'low' ? 'review-gate-first' : 'review-context-first';\n    const actionLabel = trust === 'high' ? '可沿用动作摘要' : trust === 'low' ? '先重新复核 gate' : '先复核上下文';\n    const guidance = trust === 'high'\n        ? '高可信，可沿用动作摘要。'\n        : trust === 'low'\n            ? '低可信，先重新复核 gate。'\n            : '中可信，建议复核动作摘要上下文。';\n    const shouldReview = trust !== 'high';\n    return { trust, trustLabel, action, actionLabel, guidance, shouldReview, freshness, matchPolicy };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceTrustDigest(trace, run, options = {}) {\n    const trustPolicy = buildTaskGovernanceSnapshotAuditTraceTrustPolicy(trace, run, options);\n    const freshness = trustPolicy.freshness || buildTaskGovernanceSnapshotAuditTraceFreshnessPolicy(trace, options);\n    const matchPolicy = trustPolicy.matchPolicy || buildTaskGovernanceSnapshotAuditTraceMatchPolicy(trace, run, options);\n    const machineMap = `trust:${trustPolicy.trust}|freshness:${freshness.freshness}|match:${matchPolicy.match}|action:${trustPolicy.action}`;\n    const summary = `${trustPolicy.trustLabel} / ${freshness.freshnessLabel} / ${matchPolicy.matchLabel} / ${trustPolicy.actionLabel}`;\n    const reviewMode = trustPolicy.shouldReview ? 'review-first' : 'reuse-current-trace';\n    const reviewModeLabel = trustPolicy.shouldReview ? '复核优先' : '沿用当前摘要';\n    const note = trustPolicy.shouldReview ? '动作摘要信任链要求先复核。' : '动作摘要信任链允许沿用。';\n    return { machineMap, summary, reviewMode, reviewModeLabel, note, trustPolicy, freshness, matchPolicy };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceNextStepPolicy(trustDigest, options = {}) {\n    const trustPolicy = trustDigest?.trustPolicy || {};\n    const trust = String(trustPolicy.trust || '').trim() || 'medium';\n    const reviewMode = String(trustDigest?.reviewMode || (trustPolicy.shouldReview ? 'review-first' : 'reuse-current-trace')).trim() || 'review-first';\n    const nextStep = trust === 'high' ? 'reuse-current-action' : trust === 'low' ? 'review-gate-first' : 'review-context-first';\n    const nextStepLabel = trust === 'high' ? '沿用当前动作摘要' : trust === 'low' ? '重新复核 gate' : '先复核上下文';\n    const nextStepHint = trust === 'high'\n        ? '当前动作摘要信任链可直接沿用。'\n        : trust === 'low'\n            ? '当前动作摘要信任链要求先重新复核 gate。'\n            : '当前动作摘要信任链建议先复核上下文。';\n    const nextStepMap = `next:${nextStep}|mode:${reviewMode}|trust:${trust}`;\n    const shouldReview = nextStep !== 'reuse-current-action';\n    return { nextStep, nextStepLabel, nextStepHint, nextStepMap, reviewMode, trust, shouldReview };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceActionRoutePolicy(nextStepPolicy, options = {}) {\n    const nextStep = String(nextStepPolicy?.nextStep || '').trim() || 'review-context-first';\n    const channel = nextStep === 'reuse-current-action' ? 'direct-action' : nextStep === 'review-gate-first' ? 'gate-review' : 'context-review';\n    const actionRoute = nextStep === 'reuse-current-action' ? 'reuse-action-trace' : nextStep === 'review-gate-first' ? 'review-snapshot-gate' : 'review-worklog-context';\n    const actionRouteLabel = nextStep === 'reuse-current-action' ? '沿用动作 trace' : nextStep === 'review-gate-first' ? '复核 snapshot gate' : '复核工作日志上下文';\n    const actionRouteHint = nextStep === 'reuse-current-action'\n        ? '可按当前动作 trace 继续处理。'\n        : nextStep === 'review-gate-first'\n            ? '先进入 snapshot gate 复核通道，再决定是否沿用动作摘要。'\n            : '先进入工作日志上下文复核通道，再决定后续治理动作。';\n    const actionRouteMap = `route:${actionRoute}|channel:${channel}|next:${nextStep}`;\n    const shouldReview = channel !== 'direct-action';\n    return { actionRoute, actionRouteLabel, actionRouteHint, actionRouteMap, channel, nextStep, shouldReview };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceRouteHandlingPolicy(actionRoutePolicy, options = {}) {\n    const actionRoute = String(actionRoutePolicy?.actionRoute || '').trim() || 'review-worklog-context';\n    const handler = actionRoute === 'reuse-action-trace' ? 'applyActionTrace' : actionRoute === 'review-snapshot-gate' ? 'reviewSnapshotGate' : 'reviewWorklogContext';\n    const handlingState = actionRoute === 'reuse-action-trace' ? 'ready-to-apply' : actionRoute === 'review-snapshot-gate' ? 'gate-review-required' : 'context-review-required';\n    const handlingLabel = actionRoute === 'reuse-action-trace' ? '可直接处理' : actionRoute === 'review-snapshot-gate' ? '需 gate 复核' : '需上下文复核';\n    const handlerLabel = actionRoute === 'reuse-action-trace' ? '动作 trace 处理器' : actionRoute === 'review-snapshot-gate' ? 'snapshot gate 复核处理器' : '工作日志上下文复核处理器';\n    const handlingHint = actionRoute === 'reuse-action-trace'\n        ? '处理器可直接沿用动作 trace。'\n        : actionRoute === 'review-snapshot-gate'\n            ? '处理器应先复核 snapshot gate，再继续治理动作。'\n            : '处理器应先复核工作日志上下文，再继续治理动作。';\n    const handlingMap = `handler:${handler}|state:${handlingState}|route:${actionRoute}`;\n    const shouldReview = handlingState !== 'ready-to-apply';\n    return { handler, handlerLabel, handlingState, handlingLabel, handlingHint, handlingMap, actionRoute, shouldReview };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceHandlingHandoff(routeHandlingPolicy, options = {}) {\n    const handler = String(routeHandlingPolicy?.handler || '').trim() || 'reviewWorklogContext';\n    const handlingState = String(routeHandlingPolicy?.handlingState || '').trim() || 'context-review-required';\n    const actionRoute = String(routeHandlingPolicy?.actionRoute || '').trim() || 'review-worklog-context';\n    const handoffContract = 'snapshot-action-handling/v1';\n    const handoffReady = handlingState === 'ready-to-apply' ? 'ready' : 'review-required';\n    const handoffLabel = handlingState === 'ready-to-apply' ? '可交给动作处理器' : handlingState === 'gate-review-required' ? '交给 gate 复核处理器' : '交给上下文复核处理器';\n    const handoffInstruction = handlingState === 'ready-to-apply'\n        ? '下游可按动作 trace 直接处理。'\n        : handlingState === 'gate-review-required'\n            ? '下游需先复核 snapshot gate，再继续动作处理。'\n            : '下游需先复核工作日志上下文，再继续动作处理。';\n    const handoffMap = `contract:${handoffContract}|handler:${handler}|ready:${handoffReady}|route:${actionRoute}`;\n    const shouldReview = handoffReady !== 'ready';\n    return { handoffContract, handoffReady, handoffLabel, handoffInstruction, handoffMap, handler, handlingState, actionRoute, shouldReview };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceHandoffReceiverPolicy(handlingHandoff, options = {}) {\n    const handoffReady = String(handlingHandoff?.handoffReady || '').trim() || 'review-required';\n    const handler = String(handlingHandoff?.handler || '').trim() || 'reviewWorklogContext';\n    const receiver = handoffReady === 'ready' ? 'action-trace-worker' : handler === 'reviewSnapshotGate' ? 'snapshot-gate-reviewer' : 'worklog-context-reviewer';\n    const receiverLabel = handoffReady === 'ready' ? '动作 trace 执行端' : handler === 'reviewSnapshotGate' ? 'snapshot gate 复核端' : '工作日志上下文复核端';\n    const acceptance = handoffReady === 'ready' ? 'accept-directly' : handler === 'reviewSnapshotGate' ? 'accept-after-gate-review' : 'accept-after-context-review';\n    const acceptanceLabel = handoffReady === 'ready' ? '可直接接收' : handler === 'reviewSnapshotGate' ? 'gate 复核后接收' : '上下文复核后接收';\n    const receiverHint = handoffReady === 'ready'\n        ? '接收端可直接读取 handoff map 并执行动作 trace。'\n        : handler === 'reviewSnapshotGate'\n            ? '接收端应先完成 snapshot gate 复核，再确认是否执行动作 trace。'\n            : '接收端应先完成工作日志上下文复核，再确认后续治理动作。';\n    const receiverMap = `receiver:${receiver}|acceptance:${acceptance}|handler:${handler}`;\n    const shouldReview = acceptance !== 'accept-directly';\n    return { receiver, receiverLabel, acceptance, acceptanceLabel, receiverHint, receiverMap, handler, handoffReady, shouldReview };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceReceiverDeliveryPolicy(handoffReceiverPolicy, options = {}) {\n    const receiver = String(handoffReceiverPolicy?.receiver || '').trim() || 'worklog-context-reviewer';\n    const acceptance = String(handoffReceiverPolicy?.acceptance || '').trim() || 'accept-after-context-review';\n    const deliveryTarget = receiver === 'action-trace-worker' ? 'deliver-to-action-worker' : recei