turn { completionArchiveReceiptState, completionArchiveReceiptLabel, completionArchiveReceiptHint, completionArchiveReceiptMap, completionArchiveState, shouldReview };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceCompletionArchiveReceiptRetentionPolicy(completionArchiveReceiptPolicy, options = {}) {\n    const completionArchiveReceiptState = String(completionArchiveReceiptPolicy?.completionArchiveReceiptState || '').trim() || 'receipt-after-context-archive';\n    const shouldReview = Boolean(completionArchiveReceiptPolicy?.shouldReview);\n    const completionArchiveReceiptRetentionState = completionArchiveReceiptState === 'receipt-completion-archive' ? 'retain-completion-archive-receipt' : completionArchiveReceiptState === 'receipt-after-gate-archive' ? 'retain-after-gate-receipt' : 'retain-after-context-receipt';\n    const completionArchiveReceiptRetentionLabel = completionArchiveReceiptState === 'receipt-completion-archive' ? '完成归档回执可留存' : completionArchiveReceiptState === 'receipt-after-gate-archive' ? 'gate 回执后留存' : '上下文回执后留存';\n    const completionArchiveReceiptRetentionHint = completionArchiveReceiptState === 'receipt-completion-archive'\n        ? '完成归档回执已确认，可进入最终回执留存。'\n        : completionArchiveReceiptState === 'receipt-after-gate-archive'\n            ? '需等待 snapshot gate 完成归档回执后再留存。'\n            : '需等待工作日志上下文完成归档回执后再留存。';\n    const completionArchiveReceiptRetentionMap = `completionArchiveReceiptRetention:${completionArchiveReceiptRetentionState}|receipt:${completionArchiveReceiptState}|review:${shouldReview ? 'yes' : 'no'}`;\n    return { completionArchiveReceiptRetentionState, completionArchiveReceiptRetentionLabel, completionArchiveReceiptRetentionHint, completionArchiveReceiptRetentionMap, completionArchiveReceiptState, shouldReview };\n}\n\nfunction buildTaskGovernanceSnapshotAuditTraceCompletionArchiveReceiptRetentionVerificationPolicy(completionArchiveReceiptRetentionPolicy, options = {}) {\n    const completionArchiveReceiptRetentionStat