ficationClosurePolicy(retentionVerificationPolicy, {});\n    const closureAckPolicy = buildTaskGovernanceSnapshotAuditTraceClosureAckPolicy(verificationClosurePolicy, {});\n    const closureAckCompletionPolicy = buildTaskGovernanceSnapshotAuditTraceClosureAckCompletionPolicy(closureAckPolicy, {});\n    const completionArchivePolicy = buildTaskGovernanceSnapshotAuditTraceCompletionArchivePolicy(closureAckCompletionPolicy, {});\n    const completionArchiveReceiptPolicy = buildTaskGovernanceSnapshotAuditTraceCompletionArchiveReceiptPolicy(completionArchivePolicy, {});\n    const completionArchiveReceiptRetentionPolicy = buildTaskGovernanceSnapshotAuditTraceCompletionArchiveReceiptRetentionPolicy(completionArchiveReceiptPolicy, {});\n    const completionArchiveReceiptRetentionVerificationPolicy = buildTaskGovernanceSnapshotAuditTraceCompletionArchiveReceiptRetentionVerificationPolicy(completionArchiveReceiptRetentionPolicy, {});\n    const ageText = freshness.ageMinutes === null ? '未知时长' : `${freshness.ageMinutes}分钟`;\n    return `<span class=\"worklog-run-chip\">动作判定摘要：${escapeHtml(String(trace.summary || '').slice(0, 72))}</span>${traceId ? `<span class=\"worklog-run-chip\">动作 trace：${escapeHtml(traceId)}</span>` : ''}${action ? `<span class=\"worklog-run-chip\">治理动作：${escapeHtml(action)}</span>` : ''}<span class=\"worklog-run-chip\">动作摘要新鲜度：${escapeHtml(freshness.freshnessLabel)} / ${escapeHtml(ageText)}</span><span class=\"worklog-run-chip\">动作摘要复核：${escapeHtml(freshness.reviewLabel)}</span><span class=\"worklog-run-chip\">动作摘要匹配：${escapeHtml(matchPolicy.matchLabel)}</span><span class=\"worklog-run-chip\">动作摘要匹配复核：${escapeHtml(matchPolicy.reviewLabel)}</span><span class=\"worklog-run-chip\">动作摘要可信度：${escapeHtml(trustPolicy.trustLabel)}</span><span class=\"worklog-run-chip\">动作摘要处理建议：${escapeHtml(trustPolicy.actionLabel)}</span><span class=\"worklog-run-chip\" data-snapshot-action-trust-digest=\"${escapeHtml(trustDigest.summary)}\" data-snapshot-action-trust-map=\"${