worklog-run-chip\" data-snapshot-action-completion-archive-receipt-retention=\"${escapeHtml(completionArchiveReceiptRetentionPolicy.completionArchiveReceiptRetentionState)}\" data-snapshot-action-completion-archive-receipt-retention-map=\"${escapeHtml(completionArchiveReceiptRetentionPolicy.completionArchiveReceiptRetentionMap)}\">动作摘要归档回执留存：${escapeHtml(completionArchiveReceiptRetentionPolicy.completionArchiveReceiptRetentionLabel)}</span><span class=\"worklog-run-chip\">动作摘要回执留存依据：${escapeHtml(completionArchiveReceiptRetentionPolicy.completionArchiveReceiptRetentionHint)}</span><span class=\"worklog-run-chip\" data-snapshot-action-completion-archive-receipt-retention-verification=\"${escapeHtml(completionArchiveReceiptRetentionVerificationPolicy.retentionVerificationState)}\" data-snapshot-action-completion-archive-receipt-retention-verification-map=\"${escapeHtml(completionArchiveReceiptRetentionVerificationPolicy.retentionVerificationMap)}\">动作摘要回执留存校验：${escapeHtml(completionArchiveReceiptRetentionVerificationPolicy.retentionVerificationLabel)}</span><span class=\"worklog-run-chip\">动作摘要留存校验依据：${escapeHtml(completionArchiveReceiptRetentionVerificationPolicy.retentionVerificationHint)}</span><span class=\"worklog-run-chip\">${escapeHtml(ackContinuationPolicy.continuationHint)}</span><span class=\"worklog-run-chip\">${escapeHtml(deliveryAckPolicy.ackHint)}</span><span class=\"worklog-run-chip\">${escapeHtml(receiverDeliveryPolicy.deliveryHint)}</span><span class=\"worklog-run-chip\">${escapeHtml(handoffReceiverPolicy.receiverHint)}</span><span class=\"worklog-run-chip\">${escapeHtml(routeHandlingPolicy.handlingHint)}</span>${freshness.shouldReview ? `<span class=\"worklog-run-chip\">${escapeHtml(freshness.reviewHint)}</span>` : ''}${matchPolicy.shouldReview ? `<span class=\"worklog-run-chip\">${escapeHtml(matchPolicy.reviewHint)}</span>` : ''}<span class=\"worklog-run-chip\">${escapeHtml(trustPolicy.guidance)}</span><span class=\"worklog-run-chip\">${escapeHtml(trustDigest.note)}</span>`;\n}\n\nfunction buildTaskNavigationActionSpec(action, taskId, employeeName, options = {}) {\n    const normalizedAction = String(action || '').trim();\n    const normalizedTaskId = String(taskId || '').trim();\n    const normalizedEmployee = String(employeeName || '').trim();\n    if (!normalizedAction || !normalizedTaskId) return null;\n    const buttonClass = String(options?.buttonClass || 'board-task-recommendation-btn').trim() || 'board-task-recommendation-btn';\n    const label = String(options?.label || normalizedAction).trim() || normalizedAction;\n    const closeDeskTaskFocusModal = Boolean(options?.closeDeskTaskFocusModal);\n    const spec = {\n        action: normalizedAction,\n        taskId: normalizedTaskId,\n        employeeName: normalizedEmployee,\n        label,\n        buttonClass,\n        closeDeskTaskFocusModal,\n        successTitle: '已打开任务导航',\n        successMessage: `已打开 ${normalizedTaskId} 的任务导航。`,\n        errorTitle: '打开任务导航失败',\n        errorMessage: '任务导航打开失败'\n    };\n    if (normalizedAction === '查看任务看板' || normalizedAction === '跳回任务看板') {\n        return { ...spec, successTitle: '已跳回任务看板', successMessage: `已定位到任务 ${normalizedTaskId}。` };\n    }\n    if (normalizedAction === '查看任务目标链') {\n        return { ...spec, successTitle: '已打开任务目标链', successMessage: `已展开任务 ${normalizedTaskId} 的目标链。` };\n    }\n    if (normalizedAction === '查看执行历史') {\n        return { ...spec, successTitle: '已打开执行历史', successMessage: `已展开任务 ${normalizedTaskId} 的执行历史。` };\n    }\n    return spec;\n}\n\nasync function performTaskNavigationAction(action, taskId, employeeName, options = {}) {\n    const spec = buildTaskNavigationActionSpec(action, taskId, employeeName, options);\n    if (!spec) return;\n    if (spec.closeDeskTaskFocusModal) {\n        closeModal('deskTaskFocusModal');\n    }\n    if (spec.action === '查看任务看板' || spec.action === '跳回任务看板') {\n        jumpToBoardTask(spec.taskId, spec.employeeName);\n        return;\n    }\n    if (spec.action === '查看任务目标链') {\n        openBoardTaskLineageFromRun(spec.taskId, spec.employeeName);\n        return;\n    }\n    if (spec.action === '查看执行历史') {\n        jumpToBoardTask(spec.taskId, spec.employeeName);\n        const timelineCard = document.getElementById(`board-task-timeline-${spec.taskId}`);\n        if (timelineCard && !timelineCard.classList.contains('expanded')) {\n            timelineCard.classList.add('expanded');\n        }\n        showAppDialog({ tone: 'success', title: spec.successTitle, message: spec.successMessage });\n    }\n}\n\nfunction renderTaskNavigationActionButton(action, taskId, employeeName, options = {}) {\n    const spec = buildTaskNavigationActionSpec(action, taskId, employeeName, options);\n    if (!spec) return '';\n    const optionsJs = spec.closeDeskTaskFocusModal ? '{ closeDeskTaskFocusModal: true }' : '{}';\n    return `<button type=\"button\" class=\"${escapeHtml(spec.buttonClass)}\" onclick=\"event.stopPropagation(); performTaskNavigationAction('${escapeJsSingleQuotedString(spec.action)}', '${escapeJsSingleQuotedString(spec.taskId)}', '${escapeJsSingleQuotedString(spec.employeeName)}', ${optionsJs}).catch(err => showAppDialog({ title: '${escapeJsSingleQuotedString(spec.errorTitle)}', message: err.message || '${escapeJsSingleQuotedString(spec.errorMessage)}', tone: 'error' }))\">${escapeHtml(spec.label)}</button>`;\n}\n\nfunction renderTaskNavigationActionGroup(actions, taskId, employeeName, options = {}) {\n    if (!Array.isArray(actions) || !actions.length) return '';\n    return actions.map(item => {\n        const action = typeof item === 'string' ? item : item?.action;\n        if (!action) return '';\n        const mergedOptions = {\n            ...(options || {}),\n            ...(typeof item === 'string' ? {} : item)\n        };\n        delete mergedOptions.action;\n        return renderTaskNavigationActionButton(action, taskId, employeeName, mergedOptions);\n    }).filter(Boolean).join('');\n}\n\nfunction getTaskCtaSectionTone(options = {}) {\n    const tone = String(options?.tone || 'secondary').trim().toLowerCase();\n    if (['primary', 'warning', 'navigation', 'secondary'].includes(tone)) return tone;\n    return 'secondary';\n}\n\nfunction buildTaskCtaSectionPresentation(kind, task, employeeName, options = {}) {\n    const normalizedKind = String(kind || '').trim().toLowerCase();\n    const normalizedEmployee = String(employeeName || task?.assignee || task?.Assignee || '').trim();\n    const recommendation = options?.recommendation || (task && normalizedEmployee ? buildTaskGovernanceRecommendation(task, normalizedEmployee) : null);\n    const latestRun = options?.latestRun || (task && normalizedEmployee ? findLatestRunForTask(task, normalizedEmployee) : null);\n    const consistency = String(options?.consistency || (task ? getBoardTaskStatusConsistency(task, latestRun) : '') || '').trim();\n    const blockedReason = String(task?.blocked_reason || task?.BlockedReason || '').trim();\n    if (normalizedKind === 'primary') {\n        const tone = recommendation?.tone === 'error' || blockedReason || consistency === '运行状态与任务状态不一致' ? 'warning' : 'primary';\n        return { tone, priority: recommendation?.tone === 'warning' ? 'medium' : 'high' };\n    }\n    if (normalizedKind === 'review') {\n        return { tone: 'warning', priority: blockedReason || consistency === '运行状态与任务状态不一致' ? 'high' : 'medium' };\n    }\n    if (normalizedKind === 'navigation') {\n        return { tone: 'navigation', priority: 'medium' };\n    }\n    if (normalizedKind === 'execution') {\n        return { tone: blockedReason || consistency === '运行状态与任务状态不一致' ? 'warning' : 'secondary', priority: consistency === '运行状态与任务状态不一致' ? 'high' : 'low' };\n    }\n    if (normalizedKind === 'handoff') {\n        const handoff = buildTaskCtaModeHandoff(options?.surface || 'board', task, normalizedEmployee, options);\n        return { tone: handoff?.tone || 'secondary', priority: handoff?.priority || 'medium' };\n    }\n    if (normalizedKind === 'phase') {\n        return { tone: 'secondary', priority: 'medium' };\n    }\n    return { tone: 'secondary', priority: 'low' };\n}\n\nfunction buildTaskCtaOperatorMode(surface, task, employeeName, options = {}) {\n    const explicitMode = String(options?.operatorMode || '').trim().toLowerCase();\n    if (['browse', 'process', 'review'].includes(explicitMode)) {\n        return explicitMode;\n    }\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedEmployee = String(employeeName || task?.assignee || task?.Assignee || '').trim();\n    const taskStatus = getEffectiveBoardTaskStatus(task);\n    const latestRun = options?.latestRun || (task && normalizedEmployee ? findLatestRunForTask(task, normalizedEmployee) : null);\n    const latestRunStatus = String(latestRun?.status || latestRun?.Status || '').trim().toLowerCase();\n    const blockedReason = String(task?.blocked_reason || task?.BlockedReason || '').trim();\n    if (taskStatus === 'in_review') {\n        return 'review';\n    }\n    if (normalizedSurface === 'desk' || normalizedSurface === 'run') {\n        return 'process';\n    }\n    if (blockedReason || ['failed', 'error', 'timeout'].includes(latestRunStatus)) {\n        return 'process';\n    }\n    return 'browse';\n}\n\nfunction buildTaskControlPlanePhase(surface, task, employeeName, options = {}) {\n    const explicitPhase = String(options?.phase || '').trim().toLowerCase();\n    if (['discovering', 'executing', 'awaiting_review', 'post_review_followup'].includes(explicitPhase)) {\n        return buildTaskControlPlanePhase(surface, task, employeeName, { ...options, phase: '', operatorMode: explicitPhase === 'discovering' ? 'browse' : explicitPhase === 'executing' ? 'process' : explicitPhase === 'awaiting_review' ? 'review' : 'review', _forcedPhase: explicitPhase });\n    }\n    const forcedPhase = String(options?._forcedPhase || '').trim().toLowerCase();\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedEmployee = String(employeeName || task?.assignee || task?.Assignee || '').trim();\n    const operatorMode = String(options?.operatorMode || buildTaskCtaOperatorMode(normalizedSurface, task, normalizedEmployee, options)).trim().toLowerCase();\n    const latestRun = options?.latestRun || (task && normalizedEmployee ? findLatestRunForTask(task, normalizedEmployee) : null);\n    const taskStatus = getEffectiveBoardTaskStatus(task);\n    const latestRunStatus = String(latestRun?.status || latestRun?.Status || '').trim().toLowerCase();\n    const phase = forcedPhase || (taskStatus === 'done'\n        ? 'post_review_followup'\n        : taskStatus === 'in_review'\n            ? 'awaiting_review'\n            : operatorMode === 'browse'\n                ? 'discovering'\n                : (operatorMode === 'review' && ['success', 'completed', 'done'].includes(latestRunStatus))\n                    ? 'post_review_followup'\n                    : 'executing');\n    const phaseMap = {\n        discovering: { label: '当前阶段：发现问题', summary: '阶段建议：继续收集上下文并确认负责人。', operatorMode: 'browse' },\n        executing: { label: '当前阶段：执行推进', summary: '阶段建议：聚焦主动作推进，并准备进入审核。', operatorMode: 'process' },\n        awaiting_review: { label: '当前阶段：等待审核', summary: '阶段建议：优先完成审核决策并收口。', operatorMode: 'review' },\n        post_review_followup: { label: '当前阶段：审核后跟进', summary: '阶段建议：回看执行历史、评论和目标链，确认可以关闭任务。', operatorMode: 'review' }\n    };\n    const resolved = phaseMap[phase] || phaseMap.executing;\n    return {\n        phase,\n        label: resolved.label,\n        summary: resolved.summary,\n        operatorMode: resolved.operatorMode,\n        surface: normalizedSurface\n    };\n}\n\nfunction buildTaskCtaModeHandoff(surface, task, employeeName, options = {}) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedEmployee = String(employeeName || task?.assignee || task?.Assignee || '').trim();\n    const phase = options?.phase || buildTaskControlPlanePhase(normalizedSurface, task, normalizedEmployee, options);\n    const currentMode = phase?.operatorMode || buildTaskCtaOperatorMode(normalizedSurface, task, normalizedEmployee, options);\n    const recommendation = options?.recommendation || (task && normalizedEmployee ? buildTaskGovernanceRecommendation(task, normalizedEmployee) : null);\n    const taskStatus = getEffectiveBoardTaskStatus(task);\n    if (phase?.phase === 'discovering' || currentMode === 'browse') {\n        return {\n            currentMode,\n            currentPhase: phase?.phase || 'discovering',\n            nextMode: 'process',\n            nextPhase: 'executing',\n            title: '下一步建议：转入处理',\n            sectionTitle: '模式切换建议',\n            reason: `当前更适合先从浏览切到处理，优先执行“${String(recommendation?.action || '直接处理')}”并进入推进节奏。`,\n            actionType: 'governance',\n            action: String(recommendation?.action || '').trim(),\n            tone: 'primary',\n            priority: 'medium'\n        };\n    }\n    if (phase?.phase === 'executing' || currentMode === 'process') {\n        return {\n            currentMode,\n            currentPhase: phase?.phase || 'executing',\n            nextMode: 'review',\n            nextPhase: 'awaiting_review',\n            title: '下一步建议：提交审核',\n            sectionTitle: '模式切换建议',\n            reason: taskStatus === 'in_review'\n                ? '当前任务已经进入审核队列，继续以审核模式收口即可。'\n                : '当前处于处理模式，完成主动作后建议提交审核，切到 review 模式完成控制闭环。',\n            actionType: taskStatus === 'in_review' ? 'navigation' : 'governance',\n            action: taskStatus === 'in_review' ? '查看任务看板' : '先提交审核',\n            tone: 'warning',\n            priority: 'high'\n        };\n    }\n    return {\n        currentMode,\n        currentPhase: phase?.phase || 'awaiting_review',\n        nextMode: 'followup',\n        nextPhase: 'post_review_followup',\n        title: '下一步建议：审核后跟进',\n        sectionTitle: '模式切换建议',\n        reason: '审核动作完成后建议切回 followup，回看执行历史、评论和目标链，确认没有遗漏后再关闭任务。',\n        actionType: 'navigation',\n        action: '查看执行历史',\n        tone: 'navigation',\n        priority: 'medium'\n    };\n}\n\nfunction renderTaskCtaModeHandoffBody(handoff, taskId, employeeName, options = {}) {\n    if (!handoff) return '';\n    const note = `<div class=\"agent-inline-note\">${escapeHtml(String(handoff.title || '模式切换建议'))} / ${escapeHtml(String(handoff.reason || '暂无'))}</div>`;\n    const buttonClass = String(options?.buttonClass || 'board-task-recommendation-btn').trim() || 'board-task-recommendation-btn';\n    if (!handoff.action || !taskId) {\n        return note;\n    }\n    const actionHtml = handoff.actionType === 'navigation'\n        ? renderTaskNavigationActionGroup([{ action: handoff.action, buttonClass, closeDeskTaskFocusModal: Boolean(options?.closeDeskTaskFocusModal) }], taskId, employeeName, options)\n        : renderTaskGovernanceActionGroup([{ action: handoff.action, buttonClass, closeDeskTaskFocusModal: Boolean(options?.closeDeskTaskFocusModal) }], taskId, employeeName, options);\n    return `${note}${actionHtml}`;\n}\n\nfunction renderTaskControlPlanePhaseBody(phase) {\n    if (!phase) return '';\n    return `<div class=\"agent-inline-note\">${escapeHtml(String(phase.label || '控制平面阶段'))} / ${escapeHtml(String(phase.summary || '暂无'))}</div>`;\n}\n\nfunction buildTaskCtaSectionOrder(surface, phase, sections = []) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const orderedKinds = {\n        discovering: ['phase', 'navigation', 'primary', 'handoff', 'execution', 'review', 'summary'],\n        executing: ['phase', 'primary', 'execution', 'handoff', 'navigation', 'review', 'summary'],\n        awaiting_review: ['phase', 'review', 'handoff', 'navigation', 'execution', 'primary', 'summary'],\n        post_review_followup: ['phase', 'execution', 'navigation', 'handoff', 'primary', 'review', 'summary']\n    };\n    const phaseKey = String(phase?.phase || '').trim().toLowerCase();\n    const rank = orderedKinds[phaseKey] || orderedKinds.executing;\n    const visibleSections = (Array.isArray(sections) ? sections : []).map((section, index) => ({ ...section, __index: index })).filter(Boolean);\n    const ordered = visibleSections.sort((a, b) => {\n        const aRank = rank.indexOf(String(a?.kind || '').trim().toLowerCase());\n        const bRank = rank.indexOf(String(b?.kind || '').trim().toLowerCase());\n        const aScore = aRank === -1 ? 999 : aRank;\n        const bScore = bRank === -1 ? 999 : bRank;\n        if (aScore !== bScore) return aScore - bScore;\n        return a.__index - b.__index;\n    });\n    const orderedVisible = ordered.filter(section => section?.visible !== false);\n    return orderedVisible.map(({ __index, ...section }) => {\n        const kind = String(section?.kind || '').trim().toLowerCase();\n        const taskId = String(section?.taskId || '').trim();\n        const continuityPolicy = buildTaskCtaPreferenceContinuityPolicy(normalizedSurface, taskId, phaseKey, kind);\n        const syncHint = continuityPolicy.hint || getTaskCtaPreferenceHint(normalizedSurface, taskId, phaseKey, kind);\n        const stickyPreference = continuityPolicy.value;\n        const collapseClass = stickyPreference === null\n            ? String(section?.collapseClass || '').trim()\n            : (stickyPreference ? '' : 'collapsed-by-default');\n        const collapsed = stickyPreference === null\n            ? collapseClass.includes('collapsed-by-default')\n            : !stickyPreference;\n        return {\n            ...section,\n            taskId,\n            surface: normalizedSurface,\n            phase: phaseKey,\n            sectionId: buildTaskCtaStickyKey(normalizedSurface, taskId, phaseKey, kind),\n            syncHint,\n            continuityPolicy,\n            collapseClass,\n            collapsed,\n            sectionClass: [String(section?.sectionClass || '').trim(), normalizedSurface === 'desk' ? 'desk-task-focus-cta-sections' : '', String(section?.emphasisClass || '').trim(), collapseClass, continuityPolicy?.freshness ? `preference-${continuityPolicy.freshness}` : '', continuityPolicy?.confidence ? `preference-${continuityPolicy.confidence}-confidence` : '', continuityPolicy?.shouldReview ? 'preference-review-recommended' : ''].filter(Boolean).join(' ')\n        };\n    });\n}\n\nfunction buildTaskCtaStickyKey(surface, taskId, phase, kind) {\n    return ['phase-local', String(surface || 'board').trim().toLowerCase(), String(taskId || '').trim(), String(phase || '').trim().toLowerCase(), String(kind || '').trim().toLowerCase()].join('::');\n}\n\nfunction buildTaskCtaCrossSurfaceKey(taskId, phase, kind) {\n    return ['phase-local', 'cross-surface', String(taskId || '').trim(), String(phase || '').trim().toLowerCase(), String(kind || '').trim().toLowerCase()].join('::');\n}\n\nfunction readTaskCtaSectionPreferences() {\n    try {\n        const raw = localStorage.getItem('task_cta_section_prefs') || '{}';\n        const parsed = JSON.parse(raw);\n        return parsed && typeof parsed === 'object' ? parsed : {};\n    } catch (_) {\n        return {};\n    }\n}\n\nfunction writeTaskCtaSectionPreferences(preferences) {\n    try {\n        localStorage.setItem('task_cta_section_prefs', JSON.stringify(preferences || {}));\n    } catch (_) {\n    }\n}\n\nfunction normalizeTaskCtaPreferenceRecord(record) {\n    if (record && typeof record === 'object' && 'value' in record) {\n        return {\n            value: Boolean(record.value),\n            sourceSurface: String(record.sourceSurface || '').trim().toLowerCase(),\n            updatedAt: String(record.updatedAt || '').trim()\n        };\n    }\n    if (typeof record === 'boolean') {\n        return { value: record, sourceSurface: '', updatedAt: '' };\n    }\n    return null;\n}\n\nfunction formatTaskCtaPreferenceTimestamp(timestamp) {\n    const normalized = String(timestamp || '').trim();\n    if (!normalized) return '';\n    return normalized;\n}\n\nfunction buildTaskCtaPreferenceContinuityPolicy(surface, taskId, phase, kind) {\n    const stickyKey = buildTaskCtaStickyKey(surface, taskId, phase, kind);\n    const crossSurfaceKey = buildTaskCtaCrossSurfaceKey(taskId, phase, kind);\n    const preferences = readTaskCtaSectionPreferences();\n    const localRecord = normalizeTaskCtaPreferenceRecord(preferences[stickyKey]);\n    const sharedRecord = normalizeTaskCtaPreferenceRecord(preferences[crossSurfaceKey]);\n    if (localRecord) {\n        return {\n            value: localRecord.value,\n            sourceSurface: String(localRecord.sourceSurface || String(surface || 'board')).trim().toLowerCase(),\n            updatedAt: formatTaskCtaPreferenceTimestamp(localRecord.updatedAt),\n            ageMinutes: null,\n            freshness: 'local',\n            confidence: 'local',\n            shouldReview: false,\n            hint: ''\n        };\n    }\n    if (!sharedRecord) {\n        return {\n            value: null,\n            sourceSurface: '',\n            updatedAt: '',\n            ageMinutes: null,\n            freshness: 'missing',\n            confidence: 'none',\n            shouldReview: false,\n            hint: ''\n        };\n    }\n    const sourceSurface = String(sharedRecord.sourceSurface || 'cross-surface').trim().toLowerCase() || 'cross-surface';\n    const updatedAt = formatTaskCtaPreferenceTimestamp(sharedRecord.updatedAt);\n    const parsedTimestamp = updatedAt\n        ? Date.parse(updatedAt.replace(/\\./g, '/').replace(/年|月/g, '/').replace(/日/g, ' ').replace(/\\s+/g, ' ').trim())\n        : Number.NaN;\n    const ageMinutes = Number.isFinite(parsedTimestamp)\n        ? Math.max(0, Math.round((Date.now() - parsedTimestamp) / 60000))\n        : null;\n    const freshness = ageMinutes === null ? 'unknown' : (ageMinutes <= 180 ? 'fresh' : 'stale');\n    const confidence = freshness === 'fresh' ? 'high' : (freshness === 'stale' ? 'low' : 'medium');\n    const shouldReview = freshness === 'stale';\n    const recencyLabel = updatedAt ? ` / 最近更新时间：${updatedAt}` : '';\n    const freshnessLabel = ` / 偏好时效：${freshness}`;\n    const confidenceLabel = ` / 继承置信度：${confidence}`;\n    const headline = shouldReview ? '偏好已过期，建议复核' : (confidence === 'high' ? '高置信度沿用' : '沿用历史偏好');\n    return {\n        value: sharedRecord.value,\n        sourceSurface,\n        updatedAt,\n        ageMinutes,\n        freshness,\n        confidence,\n        shouldReview,\n        hint: `沿用上一次控制偏好（${headline} / 来源：${sourceSurface}${recencyLabel}${freshnessLabel}${confidenceLabel} / cross-surface sticky preference）`\n    };\n}\n\nfunction getTaskCtaSectionPreference(surface, taskId, phase, kind) {\n    const continuityPolicy = buildTaskCtaPreferenceContinuityPolicy(surface, taskId, phase, kind);\n    return continuityPolicy.value;\n}\n\nfunction getTaskCtaPreferenceHint(surface, taskId, phase, kind) {\n    const continuityPolicy = buildTaskCtaPreferenceContinuityPolicy(surface, taskId, phase, kind);\n    return String(continuityPolicy?.hint || '').trim();\n}\n\nfunction rememberTaskCtaSectionPreference(surface, taskId, phase, kind, expanded) {\n    const stickyKey = buildTaskCtaStickyKey(surface, taskId, phase, kind);\n    const crossSurfaceKey = buildTaskCtaCrossSurfaceKey(taskId, phase, kind);\n    const preferences = readTaskCtaSectionPreferences();\n    const preferenceRecord = {\n        value: Boolean(expanded),\n        sourceSurface: String(surface || 'board').trim().toLowerCase(),\n        updatedAt: new Date().toLocaleString('zh-CN', { hour12: false })\n    };\n    preferences[stickyKey] = preferenceRecord; // sticky preference\n    preferences[crossSurfaceKey] = preferenceRecord;\n    writeTaskCtaSectionPreferences(preferences);\n}\n\nasync function clearTaskCtaLocalSurfacePreferences(surface, taskId, phase, sections = [], options = {}) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || '').trim();\n    const phaseKey = String(phase?.phase || phase || '').trim().toLowerCase();\n    const parsedSections = typeof sections === 'string'\n        ? (() => {\n            try {\n                return JSON.parse(sections);\n            } catch (_) {\n                return [];\n            }\n        })()\n        : sections;\n    const kinds = Array.from(new Set((Array.isArray(parsedSections) ? parsedSections : [])\n        .map(section => typeof section === 'string' ? section : section?.kind)\n        .map(kind => String(kind || '').trim().toLowerCase())\n        .filter(Boolean)));\n    if (!normalizedTaskId || !phaseKey || !kinds.length) return 0;\n    rememberTaskCtaPreferenceDigestActionOutcome(normalizedSurface, normalizedTaskId, phaseKey, 'rollback-local', 'pending', { message: '正在恢复沿用偏好…' });\n    await refreshTaskCtaPreferenceSurface(normalizedSurface, normalizedTaskId, String(options?.employeeName || options?.employee || '').trim(), { phase: phaseKey, sections: kinds, runId: String(options?.runId || '').trim(), silent: true });\n    try {\n        const preferences = readTaskCtaSectionPreferences();\n        kinds.forEach(kind => {\n            delete preferences[buildTaskCtaStickyKey(normalizedSurface, normalizedTaskId, phaseKey, kind)];\n        });\n        writeTaskCtaSectionPreferences(preferences);\n        rememberTaskCtaPreferenceDigestActionOutcome(normalizedSurface, normalizedTaskId, phaseKey, 'rollback-local', 'success', { message: '已恢复沿用偏好' });\n    } catch (_) {\n        rememberTaskCtaPreferenceDigestActionOutcome(normalizedSurface, normalizedTaskId, phaseKey, 'rollback-local', 'failure', { message: '偏好清除失败，请稍后重试' });\n        throw _;\n    }\n    const employeeName = String(options?.employeeName || options?.employee || '').trim();\n    const runId = String(options?.runId || '').trim();\n    await refreshTaskCtaPreferenceSurface(normalizedSurface, normalizedTaskId, employeeName, { phase: phaseKey, sections: kinds, runId, silent: true });\n    return kinds.length;\n}\n\nasync function clearTaskCtaSurfacePreferences(surface, taskId, phase, sections = [], options = {}) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || '').trim();\n    const phaseKey = String(phase?.phase || phase || '').trim().toLowerCase();\n    const parsedSections = typeof sections === 'string'\n        ? (() => {\n            try {\n                return JSON.parse(sections);\n            } catch (_) {\n                return [];\n            }\n        })()\n        : sections;\n    const kinds = Array.from(new Set((Array.isArray(parsedSections) ? parsedSections : [])\n        .map(section => typeof section === 'string' ? section : section?.kind)\n        .map(kind => String(kind || '').trim().toLowerCase())\n        .filter(Boolean)));\n    if (!normalizedTaskId || !phaseKey || !kinds.length) return 0;\n    rememberTaskCtaPreferenceDigestActionOutcome(normalizedSurface, normalizedTaskId, phaseKey, 'purge-all', 'pending', { message: '正在清除全部偏好…' });\n    await refreshTaskCtaPreferenceSurface(normalizedSurface, normalizedTaskId, String(options?.employeeName || options?.employee || '').trim(), { phase: phaseKey, sections: kinds, runId: String(options?.runId || '').trim(), silent: true });\n    try {\n        const preferences = readTaskCtaSectionPreferences();\n        kinds.forEach(kind => {\n            delete preferences[buildTaskCtaStickyKey(normalizedSurface, normalizedTaskId, phaseKey, kind)];\n            delete preferences[buildTaskCtaCrossSurfaceKey(normalizedTaskId, phaseKey, kind)];\n        });\n        writeTaskCtaSectionPreferences(preferences);\n        rememberTaskCtaPreferenceDigestActionOutcome(normalizedSurface, normalizedTaskId, phaseKey, 'purge-all', 'success', { message: '清除全部偏好成功' });\n    } catch (_) {\n        rememberTaskCtaPreferenceDigestActionOutcome(normalizedSurface, normalizedTaskId, phaseKey, 'purge-all', 'failure', { message: '偏好清除失败，请稍后重试' });\n        throw _;\n    }\n    const employeeName = String(options?.employeeName || options?.employee || '').trim();\n    const runId = String(options?.runId || '').trim();\n    await refreshTaskCtaPreferenceSurface(normalizedSurface, normalizedTaskId, employeeName, { phase: phaseKey, sections: kinds, runId, silent: true });\n    return kinds.length;\n}\n\nfunction refreshTaskCtaPreferenceSurface(surface, taskId, employeeName, options = {}) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || '').trim();\n    const normalizedEmployee = String(employeeName || '').trim();\n    const runId = String(options?.runId || '').trim();\n    if (normalizedSurface === 'board') {\n        return refreshBoard();\n    }\n    if (normalizedSurface === 'desk') {\n        const contextEmployee = normalizedEmployee || String(currentDeskTaskFocusContext?.employee || '').trim();\n        if (!contextEmployee) return Promise.resolve();\n        currentDeskTaskFocusContext = buildDeskTaskFocusContext(contextEmployee);\n        if (!normalizedTaskId || String(currentDeskTaskFocusContext?.task?.id || currentDeskTaskFocusContext?.task?.Id || '').trim() === normalizedTaskId) {\n            renderDeskTaskFocusPanel(currentDeskTaskFocusContext);\n        }\n        return Promise.resolve();\n    }\n    if (normalizedSurface === 'run') {\n        const agentRunModal = document.getElementById('agentRunModal');\n        const modalEmployee = normalizedEmployee || String(agentRunModal?.dataset?.employee || '').trim();\n        const modalRunId = runId || String(agentRunModal?.dataset?.runId || '').trim();\n        if (!modalEmployee || !modalRunId) return Promise.resolve();\n        return openAgentRun(modalEmployee, modalRunId);\n    }\n    return refreshBoard();\n}\n\nfunction buildTaskCtaPreferenceDigestPolicy(surface, taskId, phase, sections = [], options = {}) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || '').trim();\n    const phaseKey = String(phase?.phase || phase || '').trim().toLowerCase();\n    const normalizedSections = (Array.isArray(sections) ? sections : [])\n        .map(section => ({\n            kind: String(section?.kind || '').trim().toLowerCase(),\n            title: String(section?.title || '').trim()\n        }))\n        .filter(section => section.kind);\n    if (!normalizedTaskId || !phaseKey || !normalizedSections.length) return null;\n    const inherited = normalizedSections\n        .map(section => ({ ...section, continuityPolicy: buildTaskCtaPreferenceContinuityPolicy(normalizedSurface, normalizedTaskId, phaseKey, section.kind) }))\n        .filter(item => item.continuityPolicy && item.continuityPolicy.freshness !== 'missing');\n    if (!inherited.length) return null;\n    const inheritedCount = inherited.filter(item => item.continuityPolicy.freshness !== 'local').length;\n    const reviewCount = inherited.filter(item => item.continuityPolicy.shouldReview).length;\n    const localOverrideCount = inherited.filter(item => item.continuityPolicy.freshness === 'local').length;\n    const inheritedTitles = inherited\n        .filter(item => item.continuityPolicy.freshness !== 'local')\n        .map(item => item.title || item.kind)\n        .filter(Boolean)\n        .join('、') || '暂无';\n    const digestClass = reviewCount > 0\n        ? 'review-recommended'\n        : (localOverrideCount > 0 ? 'local-override-active' : 'inherited-active');\n    const headline = reviewCount > 0\n        ? '建议优先复核偏好'\n        : (localOverrideCount > 0 ? '当前界面已覆盖继承偏好' : '已沿用跨界面偏好');\n    const summary = reviewCount > 0\n        ? `当前有 ${reviewCount} 个偏好进入复核状态，建议优先恢复沿用偏好或清除全部偏好。`\n        : (localOverrideCount > 0\n            ? `当前界面有 ${localOverrideCount} 个分区覆盖了继承偏好，可按需恢复沿用。`\n            : `当前界面正在沿用 ${inheritedCount} 个跨界面偏好分区。`);\n    return {\n        normalizedSurface,\n        normalizedTaskId,\n        phaseKey,\n        normalizedSections,\n        inherited,\n        inheritedCount,\n        reviewCount,\n        localOverrideCount,\n        inheritedTitles,\n        digestClass,\n        headline,\n        summary,\n        employeeName: String(options?.employeeName || options?.employee || '').trim(),\n        runId: String(options?.runId || '').trim()\n    };\n}\n\nfunction buildTaskCtaPreferenceDigestActionPolicy(digestPolicy) {\n    if (!digestPolicy) return null;\n    const hasLocalRollback = digestPolicy.localOverrideCount > 0;\n    if (digestPolicy.reviewCount > 0) {\n        return {\n            note: hasLocalRollback ? '建议动作：优先恢复沿用偏好' : '建议动作：建议清除全部偏好',\n            actions: [\n                {\n                    kind: 'rollback-local',\n                    label: '恢复沿用偏好',\n                    className: hasLocalRollback ? 'task-cta-preference-reset task-cta-preference-reset-local recommended' : 'task-cta-preference-reset task-cta-preference-reset-local',\n                    visible: hasLocalRollback,\n                    onClick: 'clearTaskCtaLocalSurfacePreferences'\n                },\n                {\n                    kind: 'purge-all',\n                    label: '清除全部偏好',\n                    className: hasLocalRollback ? 'task-cta-preference-reset caution' : 'task-cta-preference-reset recommended caution',\n                    visible: true,\n                    onClick: 'clearTaskCtaSurfacePreferences'\n                }\n            ]\n        };\n    }\n    if (hasLocalRollback) {\n        return {\n            note: '建议动作：优先恢复沿用偏好',\n            actions: [\n                {\n                    kind: 'rollback-local',\n                    label: '恢复沿用偏好',\n                    className: 'task-cta-preference-reset task-cta-preference-reset-local recommended',\n                    visible: true,\n                    onClick: 'clearTaskCtaLocalSurfacePreferences'\n                },\n                {\n                    kind: 'purge-all',\n                    label: '清除全部偏好',\n                    className: 'task-cta-preference-reset',\n                    visible: true,\n                    onClick: 'clearTaskCtaSurfacePreferences'\n                }\n            ]\n        };\n    }\n    return {\n        note: '建议动作：当前沿用稳定，可按需清理',\n        actions: [\n            {\n                kind: 'rollback-local',\n                label: '恢复沿用偏好',\n                className: 'task-cta-preference-reset task-cta-preference-reset-local',\n                visible: false,\n                onClick: 'clearTaskCtaLocalSurfacePreferences'\n            },\n            {\n                kind: 'purge-all',\n                label: '清除全部偏好',\n                className: 'task-cta-preference-reset',\n                visible: true,\n                onClick: 'clearTaskCtaSurfacePreferences'\n            }\n        ]\n    };\n}\n\nfunction buildTaskCtaPreferenceDigestActionGuardPolicy(digestPolicy, actionPolicy) {\n    const hasLocalRollback = Number(digestPolicy?.localOverrideCount || 0) > 0;\n    const reviewCount = Number(digestPolicy?.reviewCount || 0);\n    const guardPolicy = {};\n    (Array.isArray(actionPolicy?.actions) ? actionPolicy.actions : []).forEach(action => {\n        const kind = String(action?.kind || '').trim().toLowerCase();\n        if (!kind) return;\n        if (kind === 'rollback-local') {\n            guardPolicy[kind] = {\n                disabled: !hasLocalRollback,\n                disabledReason: hasLocalRollback ? '' : '当前没有可恢复的界面覆盖',\n                requiresConfirmation: false,\n                requiresReviewFirst: false\n            };\n            return;\n        }\n        if (kind === 'purge-all') {\n            guardPolicy[kind] = {\n                disabled: reviewCount > 0,\n                disabledReason: reviewCount > 0 ? '建议先复核后再执行清除' : '该动作会清除当前阶段的全部偏好，建议确认后执行',\n                requiresConfirmation: true,\n                requiresReviewFirst: reviewCount > 0\n            };\n            return;\n        }\n        guardPolicy[kind] = {\n            disabled: false,\n            disabledReason: '',\n            requiresConfirmation: false,\n            requiresReviewFirst: false\n        };\n    });\n    return guardPolicy;\n}\n\nfunction rememberTaskCtaPreferenceDigestActionOutcome(surface, taskId, phase, actionKind, status, options = {}) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || '').trim();\n    const phaseKey = String(phase?.phase || phase || '').trim().toLowerCase();\n    const normalizedActionKind = String(actionKind || '').trim().toLowerCase();\n    if (!normalizedTaskId || !phaseKey || !normalizedActionKind) return null;\n    const outcomeKey = ['task_cta_preference_action_outcome', normalizedSurface, normalizedTaskId, phaseKey].join('::');\n    const outcomeRecord = {\n        actionKind: normalizedActionKind,\n        status: String(status || '').trim().toLowerCase() || 'idle',\n        message: String(options?.message || '').trim(),\n        updatedAt: new Date().toLocaleString('zh-CN', { hour12: false })\n    };\n    try {\n        localStorage.setItem(outcomeKey, JSON.stringify(outcomeRecord));\n    } catch (_) {\n    }\n    return outcomeRecord;\n}\n\nfunction buildTaskCtaPreferenceDigestActionOutcomePolicy(surface, taskId, phase, options = {}) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || '').trim();\n    const phaseKey = String(phase?.phase || phase || '').trim().toLowerCase();\n    if (!normalizedTaskId || !phaseKey) return { status: 'idle', message: '', toneClass: '', shouldAutoClear: false, retryRecommended: false };\n    const outcomeKey = ['task_cta_preference_action_outcome', normalizedSurface, normalizedTaskId, phaseKey].join('::');\n    let record = null;\n    try {\n        record = JSON.parse(localStorage.getItem(outcomeKey) || 'null');\n    } catch (_) {\n        record = null;\n    }\n    const status = String(record?.status || '').trim().toLowerCase() || 'idle';\n    const actionKind = String(record?.actionKind || '').trim().toLowerCase();\n    const fallbackMessage = status === 'pending'\n        ? (actionKind === 'rollback-local' ? '正在恢复沿用偏好…' : '正在清除全部偏好…')\n        : status === 'success'\n            ? (actionKind === 'rollback-local' ? '已恢复沿用偏好' : '清除全部偏好成功')\n            : status === 'failure'\n                ? '偏好清除失败，请稍后重试'\n                : '';\n    const message = String(record?.message || fallbackMessage).trim();\n    return {\n        status,\n        actionKind,\n        message,\n        toneClass: status && status !== 'idle' ? status : '',\n        shouldAutoClear: status === 'success',\n        retryRecommended: status === 'failure'\n    };\n}\n\nfunction renderTaskCtaPreferenceDigestOutcome(policy) {\n    if (!policy || String(policy?.status || '').trim().toLowerCase() === 'idle' || !String(policy?.message || '').trim()) return '';\n    return `<div class=\"task-cta-preference-outcome ${escapeHtml(String(policy.toneClass || '').trim())}\">${escapeHtml(String(policy.message || '').trim())}</div>`;\n}\n\nfunction buildTaskCtaPreferenceDigestNextStepPolicy(digestPolicy, actionPolicy, outcomePolicy, auditTrailPolicy) {\n    if (!digestPolicy) return null;\n    const latestActionKind = String(auditTrailPolicy?.latestActionKind || '').trim().toLowerCase();\n    if (Number(digestPolicy.reviewCount || 0) > 0 || latestActionKind === 'purge-all-blocked' || auditTrailPolicy?.latest?.requiresReviewFirst) {\n        return {\n            toneClass: 'warning',\n            label: '下一步建议',\n            message: '建议先复核当前偏好，再决定是否清除全部偏好。'\n        };\n    }\n    if (String(outcomePolicy?.status || '').trim().toLowerCase() === 'success' && String(outcomePolicy?.actionKind || '').trim().toLowerCase() === 'rollback-local') {\n        return {\n            toneClass: 'success',\n            label: '下一步建议',\n            message: '已恢复沿用偏好，建议继续观察当前分区状态。'\n        };\n    }\n    if (String(outcomePolicy?.status || '').trim().toLowerCase() === 'success' && String(outcomePolicy?.actionKind || '').trim().toLowerCase() === 'purge-all') {\n        return {\n            toneClass: 'success',\n            label: '下一步建议',\n            message: '已清除全部偏好，建议重新确认当前界面的分区展开方式。'\n        };\n    }\n    if (Number(digestPolicy.localOverrideCount || 0) > 0 || latestActionKind === 'rollback-local') {\n        return {\n            toneClass: 'info',\n            label: '下一步建议',\n            message: '当前存在界面覆盖，建议优先恢复沿用偏好。'\n        };\n    }\n    return {\n        toneClass: 'neutral',\n        label: '下一步建议',\n        message: '当前沿用稳定，可继续处理任务。'\n    };\n}\n\nfunction renderTaskCtaPreferenceDigestNextStep(policy) {\n    if (!policy || !String(policy?.message || '').trim()) return '';\n    return `<div class=\"task-cta-preference-next-step ${escapeHtml(String(policy.toneClass || 'neutral').trim())}\"><strong>${escapeHtml(String(policy.label || '下一步建议'))}</strong>：${escapeHtml(String(policy.message || '').trim())}</div>`;\n}\n\nfunction buildTaskCtaPreferenceDigestActionAlignmentPolicy(nextStepPolicy, actionPolicy, guardPolicy) {\n    const actions = Array.isArray(actionPolicy?.actions) ? actionPolicy.actions : [];\n    const nextMessage = String(nextStepPolicy?.message || '').trim();\n    const recommendedKind = nextMessage.includes('恢复沿用偏好')\n        ? 'rollback-local'\n        : nextMessage.includes('清除全部偏好')\n            ? 'purge-all'\n            : '';\n    const orderedKinds = actions\n        .slice()\n        .sort((left, right) => {\n            const leftKind = String(left?.kind || '').trim().toLowerCase();\n            const rightKind = String(right?.kind || '').trim().toLowerCase();\n            const leftRecommended = recommendedKind && leftKind === recommendedKind ? 0 : 1;\n            const rightRecommended = recommendedKind && rightKind === recommendedKind ? 0 : 1;\n            if (leftRecommended !== rightRecommended) return leftRecommended - rightRecommended;\n            const leftGuard = guardPolicy?.[leftKind] || { disabled: false };\n            const rightGuard = guardPolicy?.[rightKind] || { disabled: false };\n            const leftDisabled = leftGuard.disabled ? 1 : 0;\n            const rightDisabled = rightGuard.disabled ? 1 : 0;\n            if (leftDisabled !== rightDisabled) return leftDisabled - rightDisabled;\n            return 0;\n        })\n        .map(action => String(action?.kind || '').trim().toLowerCase())\n        .filter(Boolean);\n    return {\n        recommendedKind,\n        orderedKinds,\n        containerClass: recommendedKind ? `focus-${recommendedKind}` : ''\n    };\n}\n\nfunction buildTaskCtaPreferenceDigestVisibilityPolicy(surface, phase, nextStepPolicy, actionAlignmentPolicy, outcomePolicy, auditTrailPolicy) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const phaseKey = String(phase?.phase || phase || '').trim().toLowerCase();\n    const hasRecommendedKind = Boolean(String(actionAlignmentPolicy?.recommendedKind || '').trim());\n    const surfaceDefaults = normalizedSurface === 'run'\n        ? { recommendedAuditCount: 2, neutralAuditCount: 4, surfaceNote: 'run 视图保留更完整的操作上下文。', density: 'comfortable', surfaceClass: 'surface-run' }\n        : normalizedSurface === 'desk'\n            ? { recommendedAuditCount: 1, neutralAuditCount: 3, surfaceNote: 'desk 视图兼顾摘要与动作。', density: 'balanced', surfaceClass: 'surface-desk' }\n            : { recommendedAuditCount: 1, neutralAuditCount: 2, surfaceNote: 'board 视图保持紧凑呈现。', density: 'dense', surfaceClass: 'surface-board' };\n    const phaseDefaults = phaseKey === 'executing'\n        ? { recommendedDelta: 1, neutralDelta: 1, phaseNote: 'executing 阶段优先保留执行所需上下文。', phaseClass: 'phase-executing' }\n        : phaseKey === 'awaiting_review'\n            ? { recommendedDelta: 1, neutralDelta: 0, phaseNote: 'awaiting_review 阶段优先展示复核相关信息。', phaseClass: 'phase-awaiting_review' }\n            : phaseKey === 'post_review_followup'\n                ? { recommendedDelta: 0, neutralDelta: 1, phaseNote: 'post_review_followup 阶段保留后续跟进上下文。', phaseClass: 'phase-post_review_followup' }\n                : { recommendedDelta: 0, neutralDelta: 0, phaseNote: 'discovering 阶段优先保留导航前的摘要。', phaseClass: 'phase-discovering' };\n    return {\n        visibleAuditCount: hasRecommendedKind\n            ? surfaceDefaults.recommendedAuditCount + phaseDefaults.recommendedDelta\n            : surfaceDefaults.neutralAuditCount + phaseDefaults.neutralDelta,\n        auditTrailClass: hasRecommendedKind ? 'collapsed-by-default' : 'expanded-by-default',\n        containerClass: hasRecommendedKind ? 'primary-focus' : 'balanced-visibility',\n        note: hasRecommendedKind\n            ? `首屏已聚焦推荐动作，历史记录默认折叠。 / ${surfaceDefaults.surfaceNote} / ${phaseDefaults.phaseNote}`\n            : `当前无强推荐动作，保留完整摘要。 / ${surfaceDefaults.surfaceNote} / ${phaseDefaults.phaseNote}`,\n        density: surfaceDefaults.density,\n        surfaceClass: surfaceDefaults.surfaceClass,\n        phaseClass: phaseDefaults.phaseClass\n    };\n}\n\nfunction readTaskCtaPreferenceDigestSnapshot(surface, taskId, phase) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || '').trim();\n    const phaseKey = String(phase?.phase || phase || '').trim().toLowerCase();\n    if (!normalizedTaskId || !phaseKey) return null;\n    const snapshotKey = ['task_cta_preference_digest_snapshot', normalizedSurface, normalizedTaskId, phaseKey].join('::');\n    try {\n        return JSON.parse(localStorage.getItem(snapshotKey) || 'null');\n    } catch (_) {\n        return null;\n    }\n}\n\nfunction rememberTaskCtaPreferenceDigestSnapshot(snapshot) {\n    const normalizedSurface = String(snapshot?.surface || '').trim().toLowerCase();\n    const normalizedTaskId = String(snapshot?.taskId || '').trim();\n    const phaseKey = String(snapshot?.phase || '').trim().toLowerCase();\n    if (!normalizedSurface || !normalizedTaskId || !phaseKey) return null;\n    const snapshotKey = ['task_cta_preference_digest_snapshot', normalizedSurface, normalizedTaskId, phaseKey].join('::');\n    try {\n        localStorage.setItem(snapshotKey, JSON.stringify(snapshot));\n    } catch (_) {\n    }\n    return snapshot;\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshot(surface, taskId, phase, digestPolicy, actionAlignmentPolicy, visibilityPolicy) {\n    return {\n        surface: String(surface || digestPolicy?.normalizedSurface || 'board').trim().toLowerCase(),\n        taskId: String(taskId || digestPolicy?.normalizedTaskId || '').trim(),\n        phase: String(phase?.phase || phase || digestPolicy?.phaseKey || '').trim().toLowerCase(),\n        posture: String(digestPolicy?.digestClass || '').trim(),\n        recommendedKind: String(actionAlignmentPolicy?.recommendedKind || '').trim().toLowerCase(),\n        density: String(visibilityPolicy?.density || '').trim().toLowerCase(),\n        surfaceClass: String(visibilityPolicy?.surfaceClass || '').trim(),\n        phaseClass: String(visibilityPolicy?.phaseClass || '').trim(),\n        visibleAuditCount: Number(visibilityPolicy?.visibleAuditCount || 0),\n        reviewCount: Number(digestPolicy?.reviewCount || 0),\n        localOverrideCount: Number(digestPolicy?.localOverrideCount || 0),\n        recordedAt: new Date().toLocaleString('zh-CN', { hour12: false })\n    };\n}\n\nfunction buildTaskCtaPreferenceDigestConsistencyPolicy(previousSnapshot, nextSnapshot, options = {}) {\n    if (!nextSnapshot) return { status: 'unknown', note: '摘要快照不可用。', statusClass: 'unknown' };\n    const outcomePolicy = options?.outcomePolicy || {};\n    const outcomeStatus = String(outcomePolicy?.status || '').trim().toLowerCase();\n    const outcomeActionKind = String(outcomePolicy?.actionKind || '').trim().toLowerCase();\n    if (outcomeStatus === 'success' && outcomeActionKind === 'rollback-local') {\n        return nextSnapshot.localOverrideCount === 0\n            ? { status: 'consistent', note: '已验证恢复沿用后的摘要一致性。', statusClass: 'consistent' }\n            : { status: 'warning', note: '恢复沿用后摘要仍显示界面覆盖，请复核。', statusClass: 'warning' };\n    }\n    if (outcomeStatus === 'success' && outcomeActionKind === 'purge-all') {\n        return nextSnapshot.localOverrideCount === 0 && !String(nextSnapshot.recommendedKind || '').trim()\n            ? { status: 'consistent', note: '已验证清除后的摘要一致性。', statusClass: 'consistent' }\n            : { status: 'warning', note: '清除全部偏好后摘要仍残留推荐动作，请复核。', statusClass: 'warning' };\n    }\n    if (!previousSnapshot) {\n        return { status: 'initial', note: '摘要快照与当前状态一致。', statusClass: 'initial' };\n    }\n    const changed = ['posture', 'recommendedKind', 'visibleAuditCount', 'reviewCount', 'localOverrideCount']\n        .some(key => String(previousSnapshot?.[key] ?? '') !== String(nextSnapshot?.[key] ?? ''));\n    return changed\n        ? { status: 'updated', note: '摘要快照已随最新状态更新。', statusClass: 'updated' }\n        : { status: 'stable', note: '摘要快照与当前状态一致。', statusClass: 'stable' };\n}\n\nfunction buildTaskCtaPreferenceDigestConsistencyPresentation(consistencyPolicy) {\n    const status = String(consistencyPolicy?.status || '').trim().toLowerCase();\n    if (status === 'warning') {\n        return { className: 'consistency-warning', toneClass: 'warning' };\n    }\n    if (status === 'consistent') {\n        return { className: 'consistency-consistent', toneClass: 'consistent' };\n    }\n    if (status === 'updated') {\n        return { className: 'consistency-updated', toneClass: 'updated' };\n    }\n    if (status === 'stable') {\n        return { className: 'consistency-stable', toneClass: 'stable' };\n    }\n    return { className: '', toneClass: status || 'initial' };\n}\n\nfunction rememberTaskCtaPreferenceDigestSnapshotAudit(surface, taskId, phase, snapshot, consistencyPolicy) {\n    const normalizedSurface = String(surface || snapshot?.surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || snapshot?.taskId || '').trim();\n    const phaseKey = String(phase?.phase || phase || snapshot?.phase || '').trim().toLowerCase();\n    if (!normalizedTaskId || !phaseKey || !snapshot) return null;\n    const auditKey = ['task_cta_preference_digest_snapshot_audit', normalizedSurface, normalizedTaskId, phaseKey].join('::');\n    const entry = {\n        surface: normalizedSurface,\n        taskId: normalizedTaskId,\n        phase: phaseKey,\n        posture: String(snapshot?.posture || '').trim(),\n        recommendedKind: String(snapshot?.recommendedKind || '').trim(),\n        reviewCount: Number(snapshot?.reviewCount || 0),\n        localOverrideCount: Number(snapshot?.localOverrideCount || 0),\n        visibleAuditCount: Number(snapshot?.visibleAuditCount || 0),\n        consistencyStatus: String(consistencyPolicy?.status || '').trim(),\n        consistencyNote: String(consistencyPolicy?.note || '').trim(),\n        recordedAt: String(snapshot?.recordedAt || new Date().toLocaleString('zh-CN', { hour12: false })).trim()\n    };\n    let history = [];\n    try {\n        const parsed = JSON.parse(localStorage.getItem(auditKey) || '[]');\n        history = Array.isArray(parsed) ? parsed : [];\n    } catch (_) {\n        history = [];\n    }\n    const nextHistory = [entry, ...history].slice(0, 10);\n    try {\n        localStorage.setItem(auditKey, JSON.stringify(nextHistory));\n        localStorage.setItem(`${auditKey}::latest`, JSON.stringify(entry));\n    } catch (_) {\n    }\n    return entry;\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditHistoryPolicy(surface, taskId, phase, options = {}) {\n    const normalizedSurface = String(surface || 'board').trim().toLowerCase();\n    const normalizedTaskId = String(taskId || '').trim();\n    const phaseKey = String(phase?.phase || phase || '').trim().toLowerCase();\n    const auditKey = normalizedTaskId && phaseKey ? ['task_cta_preference_digest_snapshot_audit', normalizedSurface, normalizedTaskId, phaseKey].join('::') : '';\n    if (!auditKey) return { entries: [], latest: null, summary: '摘要状态轨迹暂为空' };\n    let latest = null;\n    let entries = [];\n    try {\n        latest = JSON.parse(localStorage.getItem(`${auditKey}::latest`) || 'null');\n    } catch (_) {\n        latest = null;\n    }\n    try {\n        const parsed = JSON.parse(localStorage.getItem(auditKey) || '[]');\n        entries = Array.isArray(parsed) ? parsed : [];\n    } catch (_) {\n        entries = [];\n    }\n    return {\n        auditKey,\n        latest,\n        entries: entries.slice(0, 3),\n        summary: latest ? `最近摘要变更：${String(latest.recordedAt || '暂无')}` : '摘要状态轨迹暂为空'\n    };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditDelta(entry, previousEntry) {\n    const changedFields = [];\n    if (!entry) return { status: 'stable', badgeLabel: '稳定', fields: ['摘要快照稳定'] };\n    if (!previousEntry) return { status: 'changed', badgeLabel: '新增', fields: ['摘要快照新增'] };\n    if (String(entry?.recommendedKind || '') !== String(previousEntry?.recommendedKind || '')) {\n        changedFields.push('推荐动作变更');\n    }\n    if (Number(entry?.reviewCount || 0) !== Number(previousEntry?.reviewCount || 0)) {\n        changedFields.push('审核计数变更');\n    }\n    if (Number(entry?.localOverrideCount || 0) !== Number(previousEntry?.localOverrideCount || 0)) {\n        changedFields.push('界面覆盖变更');\n    }\n    if (Number(entry?.visibleAuditCount || 0) !== Number(previousEntry?.visibleAuditCount || 0)) {\n        changedFields.push('可见轨迹条数变更');\n    }\n    if (!changedFields.length) {\n        return { status: 'stable', badgeLabel: '稳定', fields: ['摘要快照稳定'] };\n    }\n    return { status: 'changed', badgeLabel: '变化', fields: changedFields };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditRollupPolicy(entries) {\n    const normalizedEntries = Array.isArray(entries) ? entries : [];\n    const deltas = normalizedEntries.map((entry, index) => buildTaskCtaPreferenceDigestSnapshotAuditDelta(entry, normalizedEntries[index + 1] || null));\n    const changedCount = deltas.filter(delta => delta.status === 'changed').length;\n    const stableCount = deltas.filter(delta => delta.status === 'stable').length;\n    const visibleEntries = changedCount > 0\n        ? normalizedEntries.filter((entry, index) => deltas[index]?.status === 'changed')\n        : normalizedEntries.slice(0, 1);\n    return {\n        changedCount,\n        stableCount,\n        focusMode: changedCount > 0 ? 'changed-first' : 'latest-first',\n        badgeLabel: changedCount > 0 ? '变化项' : '稳定项',\n        badgeClass: changedCount > 0 ? 'changed-first' : 'latest-first',\n        summary: `轨迹聚合：变化项 ${changedCount} / 稳定项 ${stableCount}`,\n        note: changedCount > 0 ? '最近轨迹以变化为主，首屏优先展示变化项。' : '最近轨迹整体稳定，首屏保留最新摘要。',\n        visibleEntries\n    };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditRootPosturePolicy(entries, rollupPolicy) {\n    const normalizedEntries = Array.isArray(entries) ? entries : [];\n    if (!normalizedEntries.length) {\n        return { posture: 'empty', severity: 'idle', note: '摘要状态轨迹暂为空', className: 'snapshot-posture-empty' };\n    }\n    if (Number(rollupPolicy?.changedCount || 0) > 0) {\n        return { posture: 'attention', severity: 'warning', note: '最近摘要轨迹存在变化，建议优先关注变化项。', className: 'snapshot-posture-attention' };\n    }\n    return { posture: 'stable', severity: 'normal', note: '最近摘要轨迹整体稳定，可继续处理当前任务。', className: 'snapshot-posture-stable' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditRootRecommendedActionPolicy(rootPosturePolicy, rollupPolicy) {\n    const posture = String(rootPosturePolicy?.posture || '').trim().toLowerCase();\n    if (posture === 'empty') {\n        return { action: 'no-history', note: '当前暂无摘要轨迹，可继续等待新状态。', className: 'snapshot-action-no-history' };\n    }\n    if (posture === 'attention' || Number(rollupPolicy?.changedCount || 0) > 0) {\n        return { action: 'inspect-changes', note: '建议先检查变化项，再决定是否继续处理。', className: 'snapshot-action-inspect-changes' };\n    }\n    return { action: 'observe', note: '建议继续观察当前摘要轨迹。', className: 'snapshot-action-observe' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditRootRecommendedActionScopePolicy(rootRecommendedActionPolicy, rollupPolicy, visibleEntries, entries) {\n    const action = String(rootRecommendedActionPolicy?.action || '').trim().toLowerCase();\n    if (action === 'no-history' || Number(entries?.length || 0) === 0) {\n        return { scope: 'empty', note: '当前没有可处理的摘要项。', className: 'snapshot-scope-empty' };\n    }\n    if (action === 'inspect-changes' || String(rollupPolicy?.focusMode || '') === 'changed-first') {\n        return { scope: 'visible-changed-only', note: '建议优先处理当前可见的变化项。', className: 'snapshot-scope-visible-changed-only' };\n    }\n    return { scope: 'latest-only', note: '建议先观察最新一条摘要。', className: 'snapshot-scope-latest-only' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditExecutionHintPolicy(rootPosturePolicy, rootRecommendedActionPolicy, rootRecommendedActionScopePolicy) {\n    const action = String(rootRecommendedActionPolicy?.action || '').trim().toLowerCase();\n    const scope = String(rootRecommendedActionScopePolicy?.scope || '').trim().toLowerCase();\n    if (action === 'no-history' || scope === 'empty') {\n        return { executionHint: 'await-history', title: '等待摘要轨迹', priority: 'idle', className: 'snapshot-execution-await-history' };\n    }\n    if (action === 'inspect-changes' || scope === 'visible-changed-only') {\n        return { executionHint: 'inspect-visible-changes', title: '检查变化项', priority: 'high', className: 'snapshot-execution-inspect-visible-changes' };\n    }\n    return { executionHint: 'observe-latest', title: '观察最新摘要', priority: 'normal', className: 'snapshot-execution-observe-latest' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditExecutionReadinessPolicy(rootPosturePolicy, rootRecommendedActionPolicy, rootRecommendedActionScopePolicy, executionHintPolicy) {\n    const action = String(rootRecommendedActionPolicy?.action || '').trim().toLowerCase();\n    const scope = String(rootRecommendedActionScopePolicy?.scope || '').trim().toLowerCase();\n    const priority = String(executionHintPolicy?.priority || '').trim().toLowerCase();\n    if (action === 'inspect-changes' || scope === 'visible-changed-only' || priority === 'high') {\n        return { safeToAct: 'false', reviewGate: 'blocked', note: '当前应先复核变化项，再执行后续动作。', className: 'snapshot-review-blocked' };\n    }\n    if (action === 'observe' || scope === 'latest-only') {\n        return { safeToAct: 'true', reviewGate: 'ready', note: '当前可直接按建议动作继续处理。', className: 'snapshot-review-ready' };\n    }\n    return { safeToAct: 'true', reviewGate: 'idle', note: '当前暂无可执行摘要动作。', className: 'snapshot-review-idle' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditAutomationVerdictPolicy(executionHintPolicy, executionReadinessPolicy) {\n    const reviewGate = String(executionReadinessPolicy?.reviewGate || '').trim().toLowerCase();\n    const safeToAct = String(executionReadinessPolicy?.safeToAct || '').trim().toLowerCase();\n    const executionHint = String(executionHintPolicy?.executionHint || '').trim().toLowerCase();\n    if (executionHint === 'await-history' || reviewGate === 'idle') {\n        return { verdict: 'wait', note: '当前应等待新的摘要轨迹。', className: 'snapshot-verdict-wait' };\n    }\n    if (safeToAct !== 'true' || reviewGate === 'blocked') {\n        return { verdict: 'review-first', note: '当前应先复核，再决定是否执行动作。', className: 'snapshot-verdict-review-first' };\n    }\n    return { verdict: 'act-now', note: '当前可直接执行建议动作。', className: 'snapshot-verdict-act-now' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditAutomationRoutePolicy(automationVerdictPolicy, rootRecommendedActionScopePolicy, executionHintPolicy) {\n    const verdict = String(automationVerdictPolicy?.verdict || '').trim().toLowerCase();\n    const scope = String(rootRecommendedActionScopePolicy?.scope || '').trim().toLowerCase();\n    const executionHint = String(executionHintPolicy?.executionHint || '').trim().toLowerCase();\n    if (verdict === 'wait' || executionHint === 'await-history') {\n        return { route: 'await-history', note: '当前自动化应继续等待新的摘要轨迹。', className: 'snapshot-route-await-history' };\n    }\n    if (verdict === 'review-first' || scope === 'visible-changed-only' || executionHint === 'inspect-visible-changes') {\n        return { route: 'review-visible-changes', note: '当前自动化应转入变化项复核分支。', className: 'snapshot-route-review-visible-changes' };\n    }\n    return { route: 'observe-latest-summary', note: '当前自动化可直接转入最新摘要处理分支。', className: 'snapshot-route-observe-latest-summary' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditAutomationHandlerPolicy(automationRoutePolicy, automationVerdictPolicy) {\n    const route = String(automationRoutePolicy?.route || '').trim();\n    const normalizedRoute = route.toLowerCase();\n    const verdict = String(automationVerdictPolicy?.verdict || '').trim().toLowerCase();\n    if (normalizedRoute === 'await-history' || verdict === 'wait') {\n        return { handler: 'awaitSnapshotHistory', note: '当前自动化可调用等待摘要处理器。', className: 'snapshot-handler-await-history' };\n    }\n    if (normalizedRoute === 'review-visible-changes' || verdict === 'review-first') {\n        return { handler: 'reviewVisibleChanges', note: '当前自动化可调用变化项复核处理器。', className: 'snapshot-handler-review-visible-changes' };\n    }\n    return { handler: 'processLatestSummary', note: '当前自动化可调用最新摘要处理器。', className: 'snapshot-handler-process-latest-summary' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditAutomationPayloadPolicy(automationHandlerPolicy, automationRoutePolicy, automationVerdictPolicy) {\n    const handler = String(automationHandlerPolicy?.handler || '').trim();\n    const route = String(automationRoutePolicy?.route || '').trim();\n    const verdict = String(automationVerdictPolicy?.verdict || '').trim();\n    if (handler === 'awaitSnapshotHistory' || route === 'await-history' || verdict === 'wait') {\n        return { payload: 'awaitSnapshotHistory|await-history|wait', note: '当前自动化可直接读取等待摘要载荷。', className: 'snapshot-payload-await-history' };\n    }\n    if (handler === 'reviewVisibleChanges' || route === 'review-visible-changes' || verdict === 'review-first') {\n        return { payload: 'reviewVisibleChanges|review-visible-changes|review-first', note: '当前自动化可直接读取变化项复核载荷。', className: 'snapshot-payload-review-visible-changes' };\n    }\n    return { payload: 'processLatestSummary|observe-latest-summary|act-now', note: '当前自动化可直接读取最新摘要处理载荷。', className: 'snapshot-payload-process-latest-summary' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditAutomationPayloadPartPolicy(automationPayloadPolicy) {\n    const payload = String(automationPayloadPolicy?.payload || '').trim();\n    const [handlerPart = '', routePart = '', verdictPart = ''] = payload.split('|');\n    const payloadPartExamples = [\n        { handlerPart: 'awaitSnapshotHistory', routePart: 'await-history', verdictPart: 'wait' },\n        { handlerPart: 'reviewVisibleChanges', routePart: 'review-visible-changes', verdictPart: 'review-first' },\n        { handlerPart: 'processLatestSummary', routePart: 'observe-latest-summary', verdictPart: 'act-now' }\n    ];\n    return { handlerPart: handlerPart || '', routePart: routePart || '', verdictPart: verdictPart || '', note: '当前自动化可直接读取摘要载荷拆分字段。', className: 'snapshot-payload-part-ready' };\n}\n\nfunction buildTaskCtaPreferenceDigestSnapshotAuditAutomationPayloadJsonPolicy(automationPayloadPartPolicy) {\n    const handlerPart = String(automationPayloadPartPolicy?.handlerPart || '');\n    const routePart = String(aut