	{
		switch ((value ?? "codex_runner").Trim().ToLowerInvariant())
		{
		case "codex_runner":
		case "codex":
			return "codex_runner";
		case "hermes":
		case "hermes_runner":
			return "hermes_runner";
		case "claude":
		case "claude_runner":
		case "claude_code":
			return "claude_runner";
		case "local_runner":
		case "runner":
			return "local_runner";
		default:
			return "codex_runner";
		}
	}

