	private static JsonElement JsonStringElement(string value)
	{
		using JsonDocument jsonDocument = JsonDocument.Parse(JsonSerializer.Serialize(value, AppJsonContext.Default.String));
		return jsonDocument.RootElement.Clone();
	}

	private static JsonElement JsonNumberElement(long value)
	{
		using JsonDocument jsonDocument = JsonDocument.Parse(value.ToString(CultureInfo.InvariantCulture));
		return jsonDocument.RootElement.Clone();
	}

	private static JsonElement EmptyJsonArrayElement()
	{
		using JsonDocument jsonDocument = JsonDocument.Parse("[]");
