	private static long? ReadLongFromAdapterConfig(Dictionary<string, JsonElement>? config, string key)
	{
		if (config == null || !config.TryGetValue(key, out var value))
		{
			return null;
		}
		switch (value.ValueKind)
		{
		case JsonValueKind.Number:
		{
			if (value.TryGetInt64(out var value2))
			{
				return value2;
			}
			break;
		}
		case JsonValueKind.String:
		{
			if (long.TryParse(value.GetString(), out var result))
			{
				return result;
			}
			break;
		}
		}
		return null;
	}

	private static long? GetBoundAgentNodeId(NodeInfo? node)
	{
		if (node == null)
		{
			return null;
		}
		long? result = ReadLongFromAdapterConfig(node.AdapterConfig, "nodeId");
		if (result.HasValue && result.GetValueOrDefault() > 0)
		{
			return result;
		}
		string text = (node.Url ?? string.Empty).Trim();
		if (text.StartsWith("agent-node://", StringComparison.OrdinalIgnoreCase))
		{
			string text2 = text;
			int length = "agent-node://".Length;
			if (long.TryParse(text2.Substring(length, text2.Length - length).Split('/', StringSplitOptions.RemoveEmptyEntries).FirstOrDefault(), out var result2) && result2 > 0)
			{
				return result2;
			}
		}
		return null;
	}

	private static bool IsAgentNodeUrl(string? url)
	{
		return (url ?? string.Empty).Trim().StartsWith("agent-node://", StringComparison.OrdinalIgnoreCase);
	}

	private static string BuildClientPackageDeviceId(string platformPrefix, string adapterType, string? requestedDeviceId)
	{
		string baseId = string.IsNullOrWhiteSpace(requestedDeviceId)
			? platformPrefix + "-" + adapterType
			: requestedDeviceId.Trim();
		return SanitizeAgentDeviceId(baseId) + "-" + NewToken().Substring(0, 10);
	}

	private static string SanitizeAgentDeviceId(string value)
	{
		StringBuilder builder = new StringBuilder(value.Length);
		foreach (char ch in value)
		{
			builder.Append(char.IsLetterOrDigit(ch) || ch == '-' || ch == '_' || ch == '.' ? ch : '-');
		}
		string text = builder.ToString().Trim('-', '_', '.');
		return string.IsNullOrWhiteSpace(text) ? "desktop-client" : text;
	}

	private static string? ReadBearerToken(HttpListenerRequest req)
	{
		string text = req.Headers["Authorization"] ?? string.Empty;
		if (!text.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase))
		{
			return null;
		}
		string text2 = text;
		int length = "Bearer ".Length;
		string text3 = text2.Substring(length, text2.Length - length).Trim();
		if (!string.IsNullOrWhiteSpace(text3))
		{
			return text3;
		}
		return null;
	}

	private static async Task<AgentNodeContext?> GetAgentNodeFromBearerAsync(HttpListenerRequest req)
	{
		if (!IsDatabaseMode)
		{
			return null;
		}
		string token = ReadBearerToken(req);
		if (string.IsNullOrWhiteSpace(token))
		{
			return null;
		}
		AgentNodeContext result;
		await using (NpgsqlConnection conn = await OpenDatabaseAsync())
		{
			AgentNodeContext agentNodeContext2;
			await using (NpgsqlCommand cmd = new NpgsqlCommand("SELECT id, account_id, device_id, device_name\nFROM agent_nodes\nWHERE node_token_hash = @token_hash\nLIMIT 1", conn))
			{
				cmd.Parameters.AddWithValue("token_hash", HashText(token));
				AgentNodeContext agentNodeContext;
				await using (NpgsqlDataReader reader = await cmd.ExecuteReaderAsync())
				{
					agentNodeContext = ((await reader.ReadAsync()) ? new AgentNodeContext
					{
						NodeId = reader.GetInt64(0),
						AccountId = reader.GetGuid(1),
						DeviceId = reader.GetString(2),
						DeviceName = reader.GetString(3)
					} : null);
				}
				agentNodeContext2 = agentNodeContext;
			}
			result = agentNodeContext2;
		}
		return result;
	}

	private static string NewCode()
	{
		return RandomNumberGenerator.GetInt32(0, 1000000).ToString("D6");
	}

	private static async Task CleanupExpiredAuthArtifactsAsync(NpgsqlConnection? existingConnection = null)
	{
		if (!IsDatabaseMode)
		{
			return;
		}
		DateTime utcNow = DateTime.UtcNow;
		if (utcNow - _lastAuthCleanupUtc < TimeSpan.FromHours(1))
		{
			return;
		}
		_lastAuthCleanupUtc = utcNow;
		if (existingConnection == null)
		{
			await using (NpgsqlConnection conn = await OpenDatabaseAsync())
			{
				await CleanupExpiredAuthArtifactsCoreAsync(conn);
				return;
			}
		}
		await CleanupExpiredAuthArtifactsCoreAsync(existingConnection);
	}

	private static async Task CleanupExpiredAuthArtifactsCoreAsync(NpgsqlConnection conn)
	{
		await using NpgsqlCommand cmd = new NpgsqlCommand("DELETE FROM sessions WHERE expires_at < now();\nDELETE FROM verification_codes\nWHERE expires_at < now() - interval '1 day'\n   OR (consumed_at IS NOT NULL AND consumed_at < now() - interval '1 day');", conn);
		await cmd.ExecuteNonQueryAsync();
	}

	private static bool IsClientDisconnectException(Exception ex)
	{
		for (Exception ex2 = ex; ex2 != null; ex2 = ex2.InnerException)
		{
			if ((ex2 is HttpListenerException || ex2 is IOException || ex2 is SocketException) ? true : false)
			{
				string text = ex2.Message ?? string.Empty;
				if (text.Contains("Broken pipe", StringComparison.OrdinalIgnoreCase) || text.Contains("net_io_writefailure", StringComparison.OrdinalIgnoreCase) || text.Contains("forcibly closed", StringComparison.OrdinalIgnoreCase) || text.Contains("connection reset", StringComparison.OrdinalIgnoreCase) || text.Contains("The response has been closed", StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static async Task<(bool allowed, string error, int retryAfterSeconds)> CheckVerificationRateLimitAsync(NpgsqlConnection conn, string channel, string target, string purpose)
	{
		await using (NpgsqlCommand recentCmd = new NpgsqlCommand("SELECT EXTRACT(EPOCH FROM (now() - created_at))\nFROM verification_codes\nWHERE channel = @channel AND target = @target AND purpose = @purpose\nORDER BY created_at DESC\nLIMIT 1", conn))
		{
			recentCmd.Parameters.AddWithValue("channel", channel);
			recentCmd.Parameters.AddWithValue("target", target);
			recentCmd.Parameters.AddWithValue("purpose", purpose);
			object obj = await recentCmd.ExecuteScalarAsync();
			if (obj != null && !(obj is DBNull))
			{
				double num = Convert.ToDouble(obj);
				if (num < 60.0)
				{
					return (allowed: false, error: "verification_too_frequent", retryAfterSeconds: Math.Max(1, (int)Math.Ceiling(60.0 - num)));
				}
			}
		}
		(bool allowed, string error, int retryAfterSeconds) tuple = default((bool, string, int));
		await using (NpgsqlCommand recentCmd = new NpgsqlCommand("SELECT count(*)\nFROM verification_codes\nWHERE channel = @channel AND target = @target AND purpose = @purpose AND created_at > now() - interval '1 hour'", conn))
		{
			recentCmd.Parameters.AddWithValue("channel", channel);
			recentCmd.Parameters.AddWithValue("target", target);
			recentCmd.Parameters.AddWithValue("purpose", purpose);
			if (Convert.ToInt64(await recentCmd.ExecuteScalarAsync()) >= 5)
			{
				return (allowed: false, error: "verification_hourly_limited", retryAfterSeconds: 3600);
			}
		}
		tuple = default((bool, string, int));
		await using (NpgsqlCommand recentCmd = new NpgsqlCommand("SELECT count(*)\nFROM verification_codes\nWHERE channel = @channel AND target = @target AND created_at > now() - interval '24 hours'", conn))
		{
			recentCmd.Parameters.AddWithValue("channel", channel);
			recentCmd.Parameters.AddWithValue("target", target);
			if (Convert.ToInt64(await recentCmd.ExecuteScalarAsync()) >= 20)
			{
				return (allowed: false, error: "verification_daily_limited", retryAfterSeconds: 86400);
			}
		}
		return (allowed: true, error: string.Empty, retryAfterSeconds: 0);
	}

	private static bool IsVerificationDebugEnabled()
	{
		return !string.Equals(Environment.GetEnvironmentVariable("NIUMACLAW_VERIFICATION_DEBUG"), "false", StringComparison.OrdinalIgnoreCase);
	}

	private static string VerificationPurposeText(string purpose)
	{
		switch (purpose)
		{
		case "register":
			return "注册";
		case "profile":
		case "profile_email_old":
		case "profile_phone_old":
			return "账号资料变更";
		case "reset":
			return "找回密码";
		default:
			return "登录";
		}
	}

	private static async Task<(bool ok, string error)> SendVerificationCodeAsync(string channel, string target, string purpose, string code)
	{
		_ = 1;
		try
		{
			if (channel == "email")
			{
				return await SendEmailVerificationCodeAsync(target, purpose, code);
			}
			if (channel == "phone")
			{
				return await SendSmsVerificationCodeAsync(target, purpose, code);
			}
			return (ok: false, error: "invalid_channel");
		}
		catch (Exception ex)
		{
			return (ok: false, error: ex.GetType().Name);
		}
	}

	private static async Task<(bool ok, string error)> SendEmailVerificationCodeAsync(string target, string purpose, string code)
	{
		string environmentVariable = Environment.GetEnvironmentVariable("NIUMACLAW_SMTP_HOST");
		string environmentVariable2 = Environment.GetEnvironmentVariable("NIUMACLAW_SMTP_FROM");
		if (string.IsNullOrWhiteSpace(environmentVariable) || string.IsNullOrWhiteSpace(environmentVariable2))
		{
			return IsVerificationDebugEnabled() ? (ok: true, error: "debug_only") : (ok: false, error: "email_sender_not_configured");
		}
		int result;
		int port = (int.TryParse(Environment.GetEnvironmentVariable("NIUMACLAW_SMTP_PORT"), out result) ? result : 587);
		bool enableSsl = !string.Equals(Environment.GetEnvironmentVariable("NIUMACLAW_SMTP_ENABLE_SSL"), "false", StringComparison.OrdinalIgnoreCase);
		string text = Environment.GetEnvironmentVariable("NIUMACLAW_SMTP_FROM_NAME");
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "NiumaClaw";
		}
		using MailMessage message = new MailMessage
		{
			From = new MailAddress(environmentVariable2.Trim(), text.Trim()),
			Subject = "NiumaClaw " + VerificationPurposeText(purpose) + "验证码",
			Body = $"你的 NiumaClaw {VerificationPurposeText(purpose)}验证码是：{code}\n\n验证码 10 分钟内有效。若非本人操作，请忽略本邮件。",
			BodyEncoding = Encoding.UTF8,
			SubjectEncoding = Encoding.UTF8
		};
		message.To.Add(target);
		using SmtpClient client = new SmtpClient(environmentVariable.Trim(), port)
		{
			EnableSsl = enableSsl
		};
		string environmentVariable3 = Environment.GetEnvironmentVariable("NIUMACLAW_SMTP_USER");
		string environmentVariable4 = Environment.GetEnvironmentVariable("NIUMACLAW_SMTP_PASSWORD");
		if (!string.IsNullOrWhiteSpace(environmentVariable3))
		{
			client.Credentials = new NetworkCredential(environmentVariable3.Trim(), environmentVariable4 ?? string.Empty);
		}
		await client.SendMailAsync(message);
		return (ok: true, error: string.Empty);
	}

	private static async Task<(bool ok, string error)> SendSmsVerificationCodeAsync(string target, string purpose, string code)
	{
		string environmentVariable = Environment.GetEnvironmentVariable("NIUMACLAW_SMS_WEBHOOK_URL");
		if (string.IsNullOrWhiteSpace(environmentVariable))
		{
			return IsVerificationDebugEnabled() ? (ok: true, error: "debug_only") : (ok: false, error: "sms_sender_not_configured");
		}
		using HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Post, environmentVariable.Trim());
		string environmentVariable2 = Environment.GetEnvironmentVariable("NIUMACLAW_SMS_WEBHOOK_AUTH");
		if (!string.IsNullOrWhiteSpace(environmentVariable2))
		{
			string value = (environmentVariable2.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase) ? environmentVariable2 : ("Bearer " + environmentVariable2));
			request.Headers.TryAddWithoutValidation("Authorization", value);
		}
		string value2 = $"你的 NiumaClaw {VerificationPurposeText(purpose)}验证码是：{code}，10分钟内有效。";
		string content = "{\"target\":" + JsonSerializer.Serialize(target, AppJsonContext.Default.String) + ",\"code\":" + JsonSerializer.Serialize(code, AppJsonContext.Default.String) + ",\"purpose\":" + JsonSerializer.Serialize(purpose, AppJsonContext.Default.String) + ",\"message\":" + JsonSerializer.Serialize(value2, AppJsonContext.Default.String) + "}";
		request.Content = new StringContent(content, Encoding.UTF8, "application/json");
		using HttpResponseMessage httpResponseMessage = await _httpClient.SendAsync(request);
		return httpResponseMessage.IsSuccessStatusCode ? (ok: true, error: string.Empty) : (ok: false, error: $"sms_webhook_{(int)httpResponseMessage.StatusCode}");
	}

	private static string HashPassword(string password)
	{
		byte[] bytes = RandomNumberGenerator.GetBytes(16);
		byte[] inArray = Rfc2898DeriveBytes.Pbkdf2(password, bytes, 120000, HashAlgorithmName.SHA256, 32);
		return "pbkdf2$120000$" + Convert.ToBase64String(bytes) + "$" + Convert.ToBase64String(inArray);
	}

	private static bool VerifyPassword(string password, string? stored)
	{
		if (string.IsNullOrWhiteSpace(stored))
		{
			return false;
		}
		string[] array = stored.Split('$');
		if (array.Length != 4 || array[0] != "pbkdf2" || !int.TryParse(array[1], out var result))
		{
			return false;
		}
		byte[] salt = Convert.FromBase64String(array[2]);
		byte[] array2 = Convert.FromBase64String(array[3]);
		return CryptographicOperations.FixedTimeEquals(Rfc2898DeriveBytes.Pbkdf2(password, salt, result, HashAlgorithmName.SHA256, array2.Length), array2);
	}

	private static byte[] SecretKey()
	{
		string text = Environment.GetEnvironmentVariable("NIUMACLAW_SECRET_KEY");
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "niumaclaw-development-secret";
		}
		return SHA256.HashData(Encoding.UTF8.GetBytes(text));
	}

	private static string EncryptSecret(string plain)
	{
		if (string.IsNullOrWhiteSpace(plain))
		{
			return string.Empty;
		}
		byte[] key = SecretKey();
		byte[] bytes = RandomNumberGenerator.GetBytes(12);
		byte[] bytes2 = Encoding.UTF8.GetBytes(plain);
		byte[] array = new byte[bytes2.Length];
		byte[] array2 = new byte[16];
		using AesGcm aesGcm = new AesGcm(key, 16);
		aesGcm.Encrypt(bytes, bytes2, array, array2);
		return $"v1:{Convert.ToBase64String(bytes)}:{Convert.ToBase64String(array2)}:{Convert.ToBase64String(array)}";
	}

	private static string DecryptSecret(string encrypted)
	{
		if (string.IsNullOrWhiteSpace(encrypted))
		{
			return string.Empty;
		}
		string[] array = encrypted.Split(':');
		if (array.Length != 4 || array[0] != "v1")
		{
			return string.Empty;
		}
		byte[] nonce = Convert.FromBase64String(array[1]);
		byte[] tag = Convert.FromBase64String(array[2]);
		byte[] array2 = Convert.FromBase64String(array[3]);
		byte[] array3 = new byte[array2.Length];
		using AesGcm aesGcm = new AesGcm(SecretKey(), 16);
		aesGcm.Decrypt(nonce, array2, tag, array3);
		return Encoding.UTF8.GetString(array3);
	}

	private static string BuildAccountCallbackToken(Guid accountId)
	{
		using HMACSHA256 hMACSHA = new HMACSHA256(SecretKey());
		return Convert.ToBase64String(hMACSHA.ComputeHash(Encoding.UTF8.GetBytes($"board-callback:{accountId:N}")));
	}

	private static bool IsValidAccountCallbackToken(Guid accountId, string? token)
	{
		if (string.IsNullOrWhiteSpace(token))
		{
			return false;
		}
		byte[] bytes = Encoding.UTF8.GetBytes(BuildAccountCallbackToken(accountId));
		byte[] bytes2 = Encoding.UTF8.GetBytes(token.Trim());
		if (bytes2.Length == bytes.Length)
		{
			return CryptographicOperations.FixedTimeEquals(bytes2, bytes);
		}
		return false;
	}

	private static string MaskSecret(string value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return string.Empty;
		}
		if (value.Length > 8)
		{
			string text = value.Substring(0, 4);
			int length = value.Length;
			int num = length - 4;
			return text + "****" + value.Substring(num, length - num);
		}
		return "********";
	}

	private static async Task<(long NodeId, string Token, AgentNodeClientPayload Node)> RegisterAgentNodeAsync(Guid accountId, AgentNodeRegisterRequest payload, bool markOnline = false)
	{
		string deviceId = (string.IsNullOrWhiteSpace(payload.DeviceId) ? ("desktop-" + NewToken().Substring(0, 10)) : payload.DeviceId.Trim());
		string deviceName = (string.IsNullOrWhiteSpace(payload.DeviceName) ? Environment.MachineName : payload.DeviceName.Trim());
		string token = "nnode_" + NewToken();
		string tokenHash = HashText(token);
		string capsJson = CapabilitiesToJson(payload.Capabilities);
		string status = (markOnline ? "online" : "pending");
		long nodeId;
		await using (NpgsqlConnection conn = await OpenDatabaseAsync())
		{
			await using NpgsqlCommand cmd = new NpgsqlCommand("INSERT INTO agent_nodes(account_id, device_id, device_name, node_token_hash, platform, version, status, capabilities_json, last_seen_at, updated_at)\nVALUES (@account_id, @device_id, @device_name, @token_hash, @platform, @version, @status, @capabilities::jsonb, CASE WHEN @mark_online THEN now() ELSE NULL END, now())\nON CONFLICT (account_id, device_id) DO UPDATE SET\n    device_name = EXCLUDED.device_name,\n    node_token_hash = EXCLUDED.node_token_hash,\n    platform = EXCLUDED.platform,\n    version = EXCLUDED.version,\n    status = @status,\n    capabilities_json = EXCLUDED.capabilities_json,\n    last_seen_at = CASE WHEN @mark_online THEN now() ELSE NULL END,\n    updated_at = now()\nRETURNING id", conn);
			cmd.Parameters.AddWithValue("account_id", accountId);
			cmd.Parameters.AddWithValue("device_id", deviceId);
			cmd.Parameters.AddWithValue("device_name", deviceName);
			cmd.Parameters.AddWithValue("token_hash", tokenHash);
			cmd.Parameters.AddWithValue("platform", ((object)payload.Platform?.Trim()) ?? ((object)DBNull.Value));
			cmd.Parameters.AddWithValue("version", ((object)payload.Version?.Trim()) ?? ((object)DBNull.Value));
			cmd.Parameters.AddWithValue("status", status);
			cmd.Parameters.AddWithValue("mark_online", markOnline);
			cmd.Parameters.AddWithValue("capabilities", capsJson);
			nodeId = Convert.ToInt64(await cmd.ExecuteScalarAsync());
		}
		AgentNodeClientPayload item = (await LoadAgentNodesAsync(accountId)).FirstOrDefault((AgentNodeClientPayload n) => n.Id == nodeId) ?? new AgentNodeClientPayload
		{
			Id = nodeId,
			DeviceId = deviceId,
			DeviceName = deviceName,
			Status = status,
			Online = markOnline,
			Capabilities = payload.Capabilities
		};
		return (NodeId: nodeId, Token: token, Node: item);
	}

