		private static async Task<byte[]> BuildAgentMacDesktopClientDmgAsync(string server, string token, long nodeId, string adapterType, string workspacePath, string deviceName)
		{
			string configJson = BuildNativeDesktopClientConfigJson(server, token, nodeId, adapterType, workspacePath, deviceName);
			byte[] template = await LoadMacDesktopClientDmgTemplateAsync();
			return PatchMacDesktopClientDmgConfig(template, Base64Utf8(configJson));
		}

		private static async Task<string> SaveGeneratedDesktopDownloadAsync(byte[] content, string fileName)
		{
			string root = GetGeneratedDesktopDownloadRoot();
			Directory.CreateDirectory(root);
			CleanupGeneratedDesktopDownloads(root);
			string token = NewToken().Substring(0, 24);
			string safeFileName = SafeDownloadFileName(fileName);
			string directory = Path.Combine(root, token);
			Directory.CreateDirectory(directory);
			await File.WriteAllBytesAsync(Path.Combine(directory, safeFileName), content);
			return "/generated-downloads/" + token + "/" + Uri.EscapeDataString(safeFileName);
		}

		private static string GetGeneratedDesktopDownloadRoot()
		{
			string? configured = Environment.GetEnvironmentVariable("NIUMACLAW_GENERATED_DOWNLOAD_DIR");
			if (!string.IsNullOrWhiteSpace(configured))
			{
				return configured.Trim();
			}
			string sharedRoot = "/opt/niumaclaw/shared";
			return Directory.Exists(sharedRoot)
				? Path.Combine(sharedRoot, "generated-downloads")
				: Path.Combine(AppContext.BaseDirectory, "generated-downloads");
		}

		private static string SafeDownloadFileName(string fileName)
		{
			char[] invalid = Path.GetInvalidFileNameChars();
			StringBuilder builder = new StringBuilder(fileName.Length);
			foreach (char ch in fileName)
			{
				builder.Append(invalid.Contains(ch) ? '-' : ch);
			}
			string safe = builder.ToString().Trim();
			return string.IsNullOrWhiteSpace(safe) ? "NiumaClaw-Agent.bin" : safe;
		}

		private static void CleanupGeneratedDesktopDownloads(string root)
		{
			try
			{
				if (!Directory.Exists(root)) return;
				DateTime cutoff = DateTime.UtcNow.AddHours(-6);
				foreach (FileSystemInfo item in new DirectoryInfo(root).EnumerateFileSystemInfos())
				{
					if (item.LastWriteTimeUtc >= cutoff) continue;
					if ((item.Attributes & FileAttributes.Directory) == FileAttributes.Directory)
					{
						Directory.Delete(item.FullName, recursive: true);
					}
					else
					{
						File.Delete(item.FullName);
					}
				}
			}
			catch
			{
				// Best-effort cleanup only; a failed cleanup should not block downloads.
			}
		}

		private static async Task<byte[]> BuildAgentWindowsDesktopClientExeAsync(string server, string token, long nodeId, string adapterType, string workspacePath, string deviceName)
		{
			byte[]? template = await LoadWindowsDesktopClientTemplateExeAsync();
			if (template == null)
			{
				throw new FileNotFoundException("Windows desktop client template is missing from the deployment.", WindowsDesktopClientTemplateFileName);
			}
			string configJson = BuildNativeDesktopClientConfigJson(server, token, nodeId, adapterType, workspacePath, deviceName);
			return AppendNativeDesktopClientConfigToExe(template, configJson);
		}

		private static string BuildNativeDesktopClientConfigJson(string server, string token, long nodeId, string adapterType, string workspacePath, string deviceName)
		{
			string commandAdapter = RunnerCommandAdapter(adapterType);
			string normalizedWorkspace = workspacePath?.Trim() ?? string.Empty;
			return "{\n  \"server\": " + JsonSerializer.Serialize(server, AppJsonContext.Default.String) + ",\n" + $"  \"nodeId\": {nodeId},\n" + "  \"token\": " + JsonSerializer.Serialize(token, AppJsonContext.Default.String) + ",\n  \"adapter\": " + JsonSerializer.Serialize(commandAdapter, AppJsonContext.Default.String) + ",\n  \"adapterType\": " + JsonSerializer.Serialize(adapterType, AppJsonContext.Default.String) + ",\n  \"deviceName\": " + JsonSerializer.Serialize(deviceName, AppJsonContext.Default.String) + ",\n  \"workspace\": " + JsonSerializer.Serialize(normalizedWorkspace, AppJsonContext.Default.String) + "\n}\n";
		}

	private static byte[] PatchMacDesktopClientDmgConfig(byte[] template, string configBase64)
	{
		byte[] startMarker = Encoding.ASCII.GetBytes(MacDesktopClientDmgConfigStart);
		byte[] endMarker = Encoding.ASCII.GetBytes(MacDesktopClientDmgConfigEnd);
		int start = IndexOfBytes(template, startMarker, 0);
		if (start < 0)
		{
			throw new InvalidOperationException("macOS client DMG template is missing the config start marker.");
		}
		int payloadStart = start + startMarker.Length;
		int payloadEnd = IndexOfBytes(template, endMarker, payloadStart);
		if (payloadEnd < 0)
		{
			throw new InvalidOperationException("macOS client DMG template is missing the config end marker.");
		}
		int capacity = payloadEnd - payloadStart;
		byte[] payload = Encoding.ASCII.GetBytes(configBase64);
		if (payload.Length > capacity)
		{
			throw new InvalidOperationException($"macOS client config is too large for the DMG template ({payload.Length}/{capacity} bytes).");
		}
		byte[] output = (byte[])template.Clone();
		Array.Fill<byte>(output, (byte)'#', payloadStart, capacity);
		Buffer.BlockCopy(payload, 0, output, payloadStart, payload.Length);
		return output;
	}

	private static int IndexOfBytes(byte[] source, byte[] value, int startIndex)
	{
		if (value.Length == 0)
		{
			return startIndex;
		}
		for (int i = Math.Max(0, startIndex); i <= source.Length - value.Length; i++)
		{
			int j = 0;
			while (j < value.Length && source[i + j] == value[j])
			{
				j++;
			}
			if (j == value.Length)
			{
				return i;
			}
		}
		return -1;
	}

	private static async Task<byte[]> BuildAgentDesktopClientZipAsync(string server, string token, long nodeId, string adapterType, string workspacePath, string deviceName)
	{
		string commandAdapter = RunnerCommandAdapter(adapterType);
		string windowsWorkspace = DefaultDesktopWorkspace(workspacePath);
		string powershellWorkspace = (string.IsNullOrWhiteSpace(workspacePath) ? "$env:USERPROFILE\\NiumaClawWorkspace" : workspacePath.Trim());
		string shellWorkspace = (string.IsNullOrWhiteSpace(workspacePath) ? "$HOME/NiumaClawWorkspace" : workspacePath.Trim());
