	private static AgentJobRecord ReadAgentJobRecord(NpgsqlDataReader reader)
	{
		string text = reader.GetString(7);
		using JsonDocument jsonDocument = JsonDocument.Parse(string.IsNullOrWhiteSpace(text) ? "{}" : text);
		return new AgentJobRecord
		{
			Id = reader.GetInt64(0),
			AccountId = reader.GetGuid(1),
			NodeId = reader.GetInt64(2),
			EmployeeName = reader.GetString(3),
			AdapterType = reader.GetString(4),
			Status = reader.GetString(5),
			Prompt = reader.GetString(6),
			Payload = jsonDocument.RootElement.Clone(),
			Result = (reader.IsDBNull(8) ? null : reader.GetString(8)),
			Error = (reader.IsDBNull(9) ? null : reader.GetString(9)),
			BoardTaskId = (reader.IsDBNull(10) ? null : reader.GetString(10)),
			CreatedAt = reader.GetString(11),
			StartedAt = reader.GetString(12),
			FinishedAt = reader.GetString(13),
			UpdatedAt = reader.GetString(14)
		};
	}

