				await using (NpgsqlCommand cmd = new NpgsqlCommand("WITH next_job AS (\n    SELECT id\n    FROM agent_jobs\n    WHERE node_id = @node_id AND status = 'queued'\n    ORDER BY created_at ASC, id ASC\n    LIMIT 1\n)\nSELECT j.id, j.account_id, j.node_id, j.employee_name, j.adapter_type, j.status, j.prompt, j.payload_json::text,\n       j.result, j.error, j.board_task_id,\n       COALESCE(to_char(j.created_at AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD HH24:MI:SS'), ''),\n       COALESCE(to_char(j.started_at AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD HH24:MI:SS'), ''),\n       COALESCE(to_char(j.finished_at AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD HH24:MI:SS'), ''),\n       COALESCE(to_char(j.updated_at AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD HH24:MI:SS'), '')\nFROM agent_jobs j\nJOIN next_job n ON n.id = j.id", conn))
				{
					cmd.Parameters.AddWithValue("node_id", node.NodeId);
					AgentJobRecord agentJobRecord;
					await using (NpgsqlDataReader reader = await cmd.ExecuteReaderAsync())
					{
						if (await reader.ReadAsync())
						{
							agentJobRecord = ReadAgentJobRecord(reader);
							goto IL_02f2;
						}
					}
					agentJobRecord = null;
					goto end_IL_0114;
