					result = agentJobRecord;
					goto IL_03cb;
					end_IL_0114:;
				}
				result = null;
				goto end_IL_00db;
				IL_03cb:
				return result;
				end_IL_00db:;
			}
			AgentJobRecord agentJobRecord2 = null;
			if (timeoutMs <= 0)
			{
				break;
			}
