	private static AgentNodeJobPayload ToAgentNodeJobPayload(AgentJobRecord job)
	{
		return new AgentNodeJobPayload
		{
			Id = job.Id,
			AccountId = job.AccountId.ToString("N"),
			EmployeeName = job.EmployeeName,
			AdapterType = job.AdapterType,
			Prompt = job.Prompt,
			Payload = job.Payload,
			BoardTaskId = job.BoardTaskId,
			CreatedAt = (job.CreatedAt ?? string.Empty)
		};
	}

	private static async Task UpdateBoardTaskFromAgentJobAsync(AgentJobRecord job, AgentNodeJobFinishRequest finish)
	{
		if (string.IsNullOrWhiteSpace(job.BoardTaskId))
		{
			return;
		}
		AppConfig appConfig = await LoadAccountConfigAsync(job.AccountId);
		ProjectTask projectTask = appConfig.Projects.SelectMany((ProjectBoard p) => p.Tasks).FirstOrDefault((ProjectTask t) => string.Equals(t.Id, job.BoardTaskId, StringComparison.OrdinalIgnoreCase));
		if (projectTask != null)
		{
			projectTask.UpdateTime = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
			projectTask.CheckedOutBy = null;
			projectTask.CheckedOutAt = null;
			if (finish.Ok)
			{
				projectTask.Status = "in_review";
				projectTask.ReviewRequired = true;
				projectTask.Result = (string.IsNullOrWhiteSpace(finish.Output) ? "本机 Agent 已完成执行，等待人工复核。" : finish.Output.Trim());
				projectTask.BlockedReason = null;
			}
			else
			{
				projectTask.Status = "blocked";
				projectTask.BlockedReason = (string.IsNullOrWhiteSpace(finish.Error) ? "本机 Agent 执行失败。" : finish.Error.Trim());
				projectTask.Result = (string.IsNullOrWhiteSpace(finish.Output) ? projectTask.Result : finish.Output.Trim());
			}
			await SaveAccountConfigAsync(job.AccountId, appConfig);
		}
	}

	private static string ReadSessionToken(HttpListenerRequest req)
	{
		string[] array = (req.Headers["Cookie"] ?? string.Empty).Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
		foreach (string text in array)
		{
			int num = text.IndexOf('=');
			if (num > 0 && string.Equals(text.Substring(0, num), "niuma_session", StringComparison.OrdinalIgnoreCase))
			{
				string text2 = text;
				int num2 = num + 1;
				return Uri.UnescapeDataString(text2.Substring(num2, text2.Length - num2));
			}
		}
		return string.Empty;
	}

	private static void SetSessionCookie(HttpListenerResponse res, string token)
	{
		res.Headers.Add("Set-Cookie", "niuma_session=" + Uri.EscapeDataString(token) + "; Path=/; Max-Age=2592000; HttpOnly; SameSite=Lax");
	}

	private static void ClearSessionCookie(HttpListenerResponse res)
	{
		res.Headers.Add("Set-Cookie", "niuma_session=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax");
	}

	private static string BuildPublicServerUrl(HttpListenerRequest req)
	{
		string scheme = (req.Headers["X-Forwarded-Proto"] ?? req.Url?.Scheme ?? "http").Split(',')[0].Trim();
		if (string.IsNullOrWhiteSpace(scheme))
		{
			scheme = "http";
		}
		string host = (req.Headers["X-Forwarded-Host"] ?? req.Headers["Host"] ?? req.UserHostName ?? string.Empty).Split(',')[0].Trim();
		if (string.IsNullOrWhiteSpace(host))
		{
			host = "127.0.0.1";
		}
		return scheme + "://" + host;
	}

