	private static async Task<AccountContext?> GetAccountFromRequestAsync(HttpListenerRequest req)
	{
		if (!IsDatabaseMode)
		{
			return null;
		}
		string token = ReadSessionToken(req);
		if (string.IsNullOrWhiteSpace(token))
		{
			return null;
		}
		AccountContext result;
		await using (NpgsqlConnection conn = await OpenDatabaseAsync())
		{
			AccountContext accountContext2;
			await using (NpgsqlCommand cmd = new NpgsqlCommand("SELECT a.id, a.email, a.phone, a.display_name\nFROM sessions s\nJOIN accounts a ON a.id = s.account_id\nWHERE s.token_hash = @token_hash AND s.expires_at > now()", conn))
			{
				cmd.Parameters.AddWithValue("token_hash", HashText(token));
				AccountContext accountContext;
				await using (NpgsqlDataReader reader = await cmd.ExecuteReaderAsync())
				{
					accountContext = ((await reader.ReadAsync()) ? new AccountContext
					{
						AccountId = reader.GetGuid(0),
						Email = (reader.IsDBNull(1) ? null : reader.GetString(1)),
						Phone = (reader.IsDBNull(2) ? null : reader.GetString(2)),
						DisplayName = reader.GetString(3)
					} : null);
				}
				accountContext2 = accountContext;
			}
			result = accountContext2;
		}
		return result;
	}

