	private static async Task<AccountContext?> GetAccountFromSignedCallbackAsync(HttpListenerRequest req)
	{
		string? input = req.Headers["X-Account-Id"];
		string token = req.Headers["X-Team-Callback-Token"];
		if (!Guid.TryParse(input, out var result) || !IsValidAccountCallbackToken(result, token))
		{
			return null;
		}
		return await GetAccountByIdAsync(result);
	}

	private static async Task<bool> WriteUnauthorizedAsync(HttpListenerResponse res)
	{
		res.StatusCode = 401;
		res.ContentType = "application/json; charset=utf-8";
		await res.OutputStream.WriteAsync(Encoding.UTF8.GetBytes("{\"authenticated\":false,\"error\":\"login_required\"}"));
		res.OutputStream.Close();
		return true;
	}

	private static async Task WriteJsonAsync(HttpListenerResponse res, string json, int statusCode = 200)
	{
		res.StatusCode = statusCode;
		res.ContentType = "application/json; charset=utf-8";
		await res.OutputStream.WriteAsync(Encoding.UTF8.GetBytes(json));
	}

	private static string EscapeJsonForInlineScript(string json)
	{
		return json.Replace("<", "\\u003C", StringComparison.Ordinal).Replace(">", "\\u003E", StringComparison.Ordinal).Replace("&", "\\u0026", StringComparison.Ordinal)
			.Replace("\u2028", "\\u2028", StringComparison.Ordinal)
			.Replace("\u2029", "\\u2029", StringComparison.Ordinal);
	}

	private static string InjectBeforeBodyEnd(string html, string snippet)
	{
		if (string.IsNullOrWhiteSpace(snippet))
		{
			return html;
		}
		int num = html.LastIndexOf("</body>", StringComparison.OrdinalIgnoreCase);
		if (num >= 0)
		{
			return html.Insert(num, snippet);
		}
		return html + snippet;
	}

	private static string BuildInitialTeamHydrationScript(AppConfig config, AuthMePayload account, int modelCount)
	{
		string value = EscapeJsonForInlineScript(JsonSerializer.Serialize(config, AppJsonContext.Default.AppConfig));
		string value2 = EscapeJsonForInlineScript(JsonSerializer.Serialize(account, AppJsonContext.Default.AuthMePayload));
		return $"<script>\nwindow.__INITIAL_TEAM_CONFIG__ = {value};\nwindow.__INITIAL_ACCOUNT__ = {value2};\nwindow.__INITIAL_MODEL_COUNT__ = {modelCount};\n(function () {{\n  function esc(value) {{\n    return String(value == null ? '' : value)\n      .replaceAll('&', '&amp;')\n      .replaceAll('<', '&lt;')\n      .replaceAll('>', '&gt;')\n      .replaceAll('\"', '&quot;')\n      .replaceAll(\"'\", '&#39;');\n  }}\n  function peers(cfg) {{\n    return Object.entries((cfg && (cfg.PeerNodes || cfg.peerNodes)) || {{}}).filter(function (entry) {{ return entry[0] !== 'ceo'; }});\n  }}\n  function renderInitialTeamConfig() {{\n    var cfg = window.__INITIAL_TEAM_CONFIG__;\n    if (!cfg) return;\n    cfg.PeerNodes = cfg.PeerNodes || cfg.peerNodes || {{}};\n    window.teamConfig = cfg;\n    window.currentAccount = window.__INITIAL_ACCOUNT__ || window.currentAccount;\n    if (typeof applyAccountUi === 'function' && window.currentAccount) applyAccountUi(window.currentAccount);\n\n    var companyName = document.getElementById('companyNameDisplay');\n    if (companyName) companyName.textContent = cfg.CompanyName || cfg.companyName || '牛马Claw';\n    var licenseTag = document.getElementById('licenseTag');\n    if (licenseTag) {{\n      if (cfg.HasLicense || cfg.hasLicense) {{\n        licenseTag.textContent = '已获取营业执照';\n        licenseTag.style.background = '#2ecc71';\n      }} else {{\n        licenseTag.textContent = '未获取营业执照';\n        licenseTag.style.background = '#e74c3c';\n      }}\n    }}\n\n    var profile = String(cfg.CompanyProfile || cfg.companyProfile || '').replace(/\\\\n/g, '\\n');\n    var guide = document.getElementById('onboardingGuide');\n    if (guide && profile.trim()) {{\n      if (typeof marked !== 'undefined') {{\n        guide.innerHTML = marked.parse ? marked.parse(profile) : marked(profile);\n      }} else {{\n        guide.innerHTML = '<pre style=\"white-space:pre-wrap; font-family:inherit;\">' + esc(profile) + '</pre>';\n      }}\n    }}\n\n    var employeeEntries = peers(cfg);\n    var grid = document.getElementById('mainDeskGrid');\n    if (grid && employeeEntries.length && typeof createDeskElement === 'function' && typeof renderEmployeeUI === 'function') {{\n      grid.innerHTML = '';\n      employeeEntries.forEach(function (entry) {{\n        var name = entry[0], info = entry[1] || {{}};\n        var desk = createDeskElement();\n        renderEmployeeUI(desk, name, info.Role || info.role || '待认领');\n      }});\n      if (typeof ensureOneEmptyDesk === 'function') ensureOneEmptyDesk();\n    }}\n\n    var metrics = [\n      ['员工数', employeeEntries.length, 'default'],\n      ['活跃任务', 0, 'default'],\n      ['阻塞任务', 0, 'warning'],\n      ['异常告警', 0, 'danger'],\n      ['预算紧张员工', 0, 'warning'],\n      ['周期任务数', Array.isArray(cfg.Routines || cfg.routines) ? (cfg.Routines || cfg.routines).length : 0, 'default']\n    ];\n    if (typeof buildControlPlaneOverviewMetrics === 'function') {{\n      metrics = buildControlPlaneOverviewMetrics(cfg, [], cfg.Routines || cfg.routines || [], cfg.AgentHeartbeats || cfg.agentHeartbeats || {{}});\n    }}\n    var strip = document.getElementById('controlPlaneOverviewStrip');\n    if (strip) {{\n      strip.innerHTML = metrics.map(function (metric) {{\n        var tone = metric.tone || metric[2];\n        var label = metric.label || metric[0];\n        var value = metric.value == null ? metric[1] : metric.value;\n        var style = tone === 'danger'\n          ? 'background:linear-gradient(135deg,#fff1f2,#ffe4e6); border-color:#fecdd3; color:#be123c;'\n          : tone === 'warning'\n            ? 'background:linear-gradient(135deg,#fffbeb,#fef3c7); border-color:#fde68a; color:#b45309;'\n            : tone === 'active'\n              ? 'background:linear-gradient(135deg,#ecfeff,#cffafe); border-color:#a5f3fc; color:#0f766e;'\n              : 'background:rgba(255,255,255,0.82); border-color:rgba(148,163,184,0.28); color:#0f172a;';\n        return '<div style=\"padding:10px 12px; border-radius:12px; border:1px solid; ' + style + '\"><div style=\"font-size:11px; color:#64748b;\">' + esc(label) + '</div><div style=\"font-size:18px; font-weight:800; margin-top:2px;\">' + esc(value) + '</div></div>';\n      }}).join('');\n    }}\n\n    var stats = document.getElementById('headerSideStats');\n    if (stats) {{\n      var modelCount = Number(window.__INITIAL_MODEL_COUNT__ || 0);\n      var masterNodeUrl = String(cfg.MasterNodeUrl || cfg.masterNodeUrl || '').trim();\n      var items = [\n        ['数据库', '已连接', 'PostgreSQL', 'good'],\n        ['员工', employeeEntries.length, employeeEntries.length > 0 ? '已接入' : '待添加', employeeEntries.length > 0 ? 'good' : 'warning'],\n        ['模型', modelCount, modelCount > 0 ? 'API 可用' : '待配置', modelCount > 0 ? 'good' : 'warning'],\n        ['节点', masterNodeUrl ? '已接入' : '未配置', masterNodeUrl ? '待命中' : '无地址', masterNodeUrl ? 'good' : 'warning']\n      ];\n      stats.innerHTML = items.map(function (item) {{\n        return '<div class=\"header-side-stat ' + item[3] + '\"><div class=\"header-side-stat-label\">' + esc(item[0]) + '</div><div class=\"header-side-stat-value\">' + esc(item[1]) + '</div><div class=\"header-side-stat-detail\">' + esc(item[2]) + '</div></div>';\n      }}).join('');\n    }}\n    var status = document.getElementById('headerSideStatus');\n    if (status) status.textContent = '已连接';\n    if (typeof updateHeaderAccountMeta === 'function') updateHeaderAccountMeta(window.currentAccount, cfg);\n    if (typeof syncGuideRightHeight === 'function') requestAnimationFrame(syncGuideRightHeight);\n  }}\n  if (document.readyState === 'loading') {{\n    document.addEventListener('DOMContentLoaded', renderInitialTeamConfig, {{ once: true }});\n  }} else {{\n    renderInitialTeamConfig();\n  }}\n  window.setTimeout(renderInitialTeamConfig, 900);\n}})();\n</script>";
	}

	private static async Task<AppConfig> LoadAccountConfigAsync(Guid accountId)
	{
		AppConfig result;
		await using (NpgsqlConnection conn = await OpenDatabaseAsync())
		{
			await EnsureDefaultCompanyAsync(conn, accountId);
			AppConfig config = new AppConfig();
			await using (NpgsqlCommand cmd = new NpgsqlCommand("SELECT name, profile, has_license, master_node_url, sop FROM companies WHERE account_id = @account_id", conn))
			{
				cmd.Parameters.AddWithValue("account_id", accountId);
				await using NpgsqlDataReader reader = await cmd.ExecuteReaderAsync();
				if (await reader.ReadAsync())
				{
					config.CompanyName = reader.GetString(0);
					config.CompanyProfile = (reader.IsDBNull(1) ? null : reader.GetString(1));
					config.HasLicense = reader.GetBoolean(2);
					config.MasterNodeUrl = NormalizeConfiguredLocalNodeUrl(reader.GetString(3));
					config.CompanySOP = (reader.IsDBNull(4) ? null : reader.GetString(4));
				}
			}
			config.PeerNodes["ceo"] = new NodeInfo
			{
				Name = "ceo",
				Role = "CEO",
				Url = config.MasterNodeUrl,
				ModelIndex = 0
			};
			await using (NpgsqlCommand cmd = new NpgsqlCommand("SELECT name, data::text FROM employees WHERE account_id = @account_id ORDER BY name", conn))
			{
				cmd.Parameters.AddWithValue("account_id", accountId);
				await using NpgsqlDataReader reader = await cmd.ExecuteReaderAsync();
				while (await reader.ReadAsync())
				{
					string key = reader.GetString(0);
					NodeInfo nodeInfo = JsonSerializer.Deserialize(reader.GetString(1), AppJsonContext.Default.NodeInfo);
					if (nodeInfo != null)
					{
						config.PeerNodes[key] = nodeInfo;
					}
				}
			}
			await using (NpgsqlCommand cmd = new NpgsqlCommand("SELECT company_goals_json::text, projects_json::text, routines_json::text, routine_history_json::text, heartbeats_json::text FROM account_state WHERE account_id = @account_id", conn))
			{
				cmd.Parameters.AddWithValue("account_id", accountId);
				await using NpgsqlDataReader reader = await cmd.ExecuteReaderAsync();
				if (await reader.ReadAsync())
				{
					config.CompanyGoals = JsonSerializer.Deserialize(reader.GetString(0), AppJsonContext.Default.ListCompanyGoal) ?? new List<CompanyGoal>();
					config.Projects = JsonSerializer.Deserialize(reader.GetString(1), AppJsonContext.Default.ListProjectBoard) ?? new List<ProjectBoard>();
					config.Routines = JsonSerializer.Deserialize(reader.GetString(2), AppJsonContext.Default.ListRoutineJob) ?? new List<RoutineJob>();
					config.RoutineHistory = JsonSerializer.Deserialize(reader.GetString(3), AppJsonContext.Default.ListRoutineRunRecord) ?? new List<RoutineRunRecord>();
					config.AgentHeartbeats = JsonSerializer.Deserialize(reader.GetString(4), AppJsonContext.Default.DictionaryStringAgentHeartbeatStatus) ?? new Dictionary<string, AgentHeartbeatStatus>();
				}
			}
			result = config;
		}
		return result;
	}

	private static async Task EnsureDefaultCompanyAsync(NpgsqlConnection conn, Guid accountId)
	{
		string value = DefaultLocalNodeBaseUrl();
		await using (NpgsqlCommand companyCmd = new NpgsqlCommand("INSERT INTO companies(account_id, name, profile, has_license, master_node_url, sop)\nVALUES (@account_id, '牛马Claw', NULL, false, @master_node_url, NULL)\nON CONFLICT (account_id) DO NOTHING", conn))
		{
			companyCmd.Parameters.AddWithValue("account_id", accountId);
			companyCmd.Parameters.AddWithValue("master_node_url", value);
			await companyCmd.ExecuteNonQueryAsync();
		}
		await using NpgsqlCommand accountStateCmd = new NpgsqlCommand("INSERT INTO account_state(account_id, company_goals_json, projects_json, routines_json, routine_history_json, heartbeats_json)\nVALUES (@account_id, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{}'::jsonb)\nON CONFLICT (account_id) DO NOTHING", conn);
		accountStateCmd.Parameters.AddWithValue("account_id", accountId);
		await accountStateCmd.ExecuteNonQueryAsync();
	}

