	private static async Task SaveAccountConfigAsync(NpgsqlConnection conn, Guid accountId, AppConfig config)
	{
		config.MasterNodeUrl = NormalizeConfiguredLocalNodeUrl(config.MasterNodeUrl);
		await using (NpgsqlCommand companyCmd = new NpgsqlCommand("INSERT INTO companies(account_id, name, profile, has_license, master_node_url, sop)\nVALUES (@account_id, @name, @profile, @has_license, @master_node_url, @sop)\nON CONFLICT (account_id) DO UPDATE SET\n    name = EXCLUDED.name,\n    profile = EXCLUDED.profile,\n    has_license = EXCLUDED.has_license,\n    master_node_url = EXCLUDED.master_node_url,\n    sop = EXCLUDED.sop", conn))
		{
			companyCmd.Parameters.AddWithValue("account_id", accountId);
			companyCmd.Parameters.AddWithValue("name", string.IsNullOrWhiteSpace(config.CompanyName) ? "牛马Claw" : config.CompanyName);
			companyCmd.Parameters.AddWithValue("profile", ((object)config.CompanyProfile) ?? ((object)DBNull.Value));
			companyCmd.Parameters.AddWithValue("has_license", config.HasLicense);
			companyCmd.Parameters.AddWithValue("master_node_url", config.MasterNodeUrl);
			companyCmd.Parameters.AddWithValue("sop", ((object)config.CompanySOP) ?? ((object)DBNull.Value));
			await companyCmd.ExecuteNonQueryAsync();
		}
		await using (NpgsqlCommand deleteEmployeesCmd = new NpgsqlCommand("DELETE FROM employees WHERE account_id = @account_id", conn))
		{
			deleteEmployeesCmd.Parameters.AddWithValue("account_id", accountId);
			await deleteEmployeesCmd.ExecuteNonQueryAsync();
		}
		foreach (KeyValuePair<string, NodeInfo> item in config.PeerNodes.Where<KeyValuePair<string, NodeInfo>>((KeyValuePair<string, NodeInfo> kvp) => !string.Equals(kvp.Key, "ceo", StringComparison.OrdinalIgnoreCase)))
		{
			NodeInfo value = item.Value;
			if (string.IsNullOrWhiteSpace(value.Name))
			{
				value.Name = item.Key;
			}
			string adapterType = GetAdapterType(value);
			string text = (string.IsNullOrWhiteSpace(value.Url) ? config.MasterNodeUrl : value.Url);
			value.Url = ((IsRunnerAdapter(adapterType) || (text ?? string.Empty).Trim().StartsWith("agent-node://", StringComparison.OrdinalIgnoreCase)) ? (text ?? string.Empty).Trim() : NormalizeConfiguredLocalNodeUrl(text));
			string value2 = JsonSerializer.Serialize(value, AppJsonContext.Default.NodeInfo);
			await using NpgsqlCommand insertEmployeeCmd = new NpgsqlCommand("INSERT INTO employees(account_id, name, data) VALUES (@account_id, @name, @data::jsonb)", conn);
			insertEmployeeCmd.Parameters.AddWithValue("account_id", accountId);
			insertEmployeeCmd.Parameters.AddWithValue("name", item.Key);
			insertEmployeeCmd.Parameters.AddWithValue("data", NpgsqlDbType.Jsonb, value2);
			await insertEmployeeCmd.ExecuteNonQueryAsync();
		}
		string value3 = JsonSerializer.Serialize(config.CompanyGoals, AppJsonContext.Default.ListCompanyGoal);
		string value4 = JsonSerializer.Serialize(config.Projects, AppJsonContext.Default.ListProjectBoard);
		string value5 = JsonSerializer.Serialize(config.Routines, AppJsonContext.Default.ListRoutineJob);
		string value6 = JsonSerializer.Serialize(config.RoutineHistory, AppJsonContext.Default.ListRoutineRunRecord);
		string value7 = JsonSerializer.Serialize(config.AgentHeartbeats, AppJsonContext.Default.DictionaryStringAgentHeartbeatStatus);
		await using NpgsqlCommand accountStateCmd = new NpgsqlCommand("INSERT INTO account_state(account_id, company_goals_json, projects_json, routines_json, routine_history_json, heartbeats_json)\nVALUES (@account_id, @company_goals::jsonb, @projects::jsonb, @routines::jsonb, @routine_history::jsonb, @heartbeats::jsonb)\nON CONFLICT (account_id) DO UPDATE SET\n    company_goals_json = EXCLUDED.company_goals_json,\n    projects_json = EXCLUDED.projects_json,\n    routines_json = EXCLUDED.routines_json,\n    routine_history_json = EXCLUDED.routine_history_json,\n    heartbeats_json = EXCLUDED.heartbeats_json", conn);
		accountStateCmd.Parameters.AddWithValue("account_id", accountId);
		accountStateCmd.Parameters.AddWithValue("company_goals", NpgsqlDbType.Jsonb, value3);
		accountStateCmd.Parameters.AddWithValue("projects", NpgsqlDbType.Jsonb, value4);
		accountStateCmd.Parameters.AddWithValue("routines", NpgsqlDbType.Jsonb, value5);
		accountStateCmd.Parameters.AddWithValue("routine_history", NpgsqlDbType.Jsonb, value6);
		accountStateCmd.Parameters.AddWithValue("heartbeats", NpgsqlDbType.Jsonb, value7);
		await accountStateCmd.ExecuteNonQueryAsync();
	}

	private static async Task<List<ModelEndpointConfig>> LoadAccountModelsAsync(Guid accountId, bool includeSecrets)
	{
		List<ModelEndpointConfig> models = new List<ModelEndpointConfig>();
		List<ModelEndpointConfig> result;
		await using (NpgsqlConnection conn = await OpenDatabaseAsync())
		{
			List<ModelEndpointConfig> list2;
			await using (NpgsqlCommand cmd = new NpgsqlCommand("SELECT id, provider, name, version, base_url, api_key_encrypted, enabled, endpoint_id, sort_order\nFROM model_endpoints\nWHERE account_id = @account_id\nORDER BY sort_order, name", conn))
			{
				cmd.Parameters.AddWithValue("account_id", accountId);
				List<ModelEndpointConfig> list;
				await using (NpgsqlDataReader reader = await cmd.ExecuteReaderAsync())
				{
					while (await reader.ReadAsync())
					{
						string encrypted = reader.GetString(5);
						string apiKey = (includeSecrets ? DecryptSecret(encrypted) : MaskSecret(DecryptSecret(encrypted)));
						models.Add(new ModelEndpointConfig
						{
							Id = reader.GetGuid(0).ToString("N"),
							Provider = reader.GetString(1),
							Name = reader.GetString(2),
							Version = reader.GetString(3),
							BaseUrl = reader.GetString(4),
							ApiKey = apiKey,
							Enabled = reader.GetBoolean(6),
							EndpointId = reader.GetString(7),
							SortOrder = reader.GetInt32(8)
						});
					}
					list = models;
				}
				list2 = list;
			}
			result = list2;
		}
		return result;
	}

	private static async Task SaveAccountModelsAsync(Guid accountId, List<ModelEndpointConfig> incoming)
	{
		Dictionary<string, string> existingSecrets = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		Dictionary<string, string> existingSecretsBySignature = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		await using NpgsqlConnection conn = await OpenDatabaseAsync();
		await using (NpgsqlCommand selectCmd = new NpgsqlCommand("SELECT id, api_key_encrypted, provider, name, version, base_url, endpoint_id\nFROM model_endpoints\nWHERE account_id = @account_id", conn))
		{
			selectCmd.Parameters.AddWithValue("account_id", accountId);
			await using NpgsqlDataReader reader = await selectCmd.ExecuteReaderAsync();
			while (await reader.ReadAsync())
			{
				string value = reader.GetString(1);
				existingSecrets[reader.GetGuid(0).ToString("N")] = value;
				string text = BuildModelSecretSignature(reader.GetString(2), reader.GetString(3), reader.GetString(4), reader.GetString(5), reader.GetString(6));
				if (!string.IsNullOrWhiteSpace(text))
				{
					existingSecretsBySignature[text] = value;
				}
			}
		}
		await using (NpgsqlCommand selectCmd = new NpgsqlCommand("DELETE FROM model_endpoints WHERE account_id = @account_id", conn))
		{
			selectCmd.Parameters.AddWithValue("account_id", accountId);
			await selectCmd.ExecuteNonQueryAsync();
		}
		for (int i = 0; i < incoming.Count; i++)
		{
			ModelEndpointConfig modelEndpointConfig = incoming[i];
			Guid result;
			Guid guid = (Guid.TryParse(modelEndpointConfig.Id, out result) ? result : Guid.NewGuid());
			string key = guid.ToString("N");
			string key2 = BuildModelSecretSignature(modelEndpointConfig.Provider, modelEndpointConfig.Name, modelEndpointConfig.Version, modelEndpointConfig.BaseUrl, modelEndpointConfig.EndpointId);
			string value2 = ((string.IsNullOrWhiteSpace(modelEndpointConfig.ApiKey) || modelEndpointConfig.ApiKey.Contains("****", StringComparison.Ordinal)) ? existingSecrets.GetValueOrDefault(key, existingSecretsBySignature.GetValueOrDefault(key2, string.Empty)) : EncryptSecret(modelEndpointConfig.ApiKey.Trim()));
			await using NpgsqlCommand selectCmd = new NpgsqlCommand("INSERT INTO model_endpoints(id, account_id, provider, name, version, base_url, api_key_encrypted, enabled, endpoint_id, sort_order)\nVALUES (@id, @account_id, @provider, @name, @version, @base_url, @api_key, @enabled, @endpoint_id, @sort_order)", conn);
			selectCmd.Parameters.AddWithValue("id", guid);
			selectCmd.Parameters.AddWithValue("account_id", accountId);
			selectCmd.Parameters.AddWithValue("provider", modelEndpointConfig.Provider?.Trim() ?? string.Empty);
			selectCmd.Parameters.AddWithValue("name", modelEndpointConfig.Name?.Trim() ?? string.Empty);
			selectCmd.Parameters.AddWithValue("version", modelEndpointConfig.Version?.Trim() ?? string.Empty);
			selectCmd.Parameters.AddWithValue("base_url", modelEndpointConfig.BaseUrl?.Trim() ?? string.Empty);
			selectCmd.Parameters.AddWithValue("api_key", value2);
			selectCmd.Parameters.AddWithValue("enabled", modelEndpointConfig.Enabled);
			selectCmd.Parameters.AddWithValue("endpoint_id", modelEndpointConfig.EndpointId?.Trim() ?? string.Empty);
			selectCmd.Parameters.AddWithValue("sort_order", (modelEndpointConfig.SortOrder == 0) ? i : modelEndpointConfig.SortOrder);
			await selectCmd.ExecuteNonQueryAsync();
		}
	}

	private static string BuildModelSecretSignature(string? provider, string? name, string? version, string? baseUrl, string? endpointId)
	{
		return string.Join("\u001f", new string[5]
		{
			provider?.Trim().ToLowerInvariant() ?? string.Empty,
			name?.Trim().ToLowerInvariant() ?? string.Empty,
			version?.Trim().ToLowerInvariant() ?? string.Empty,
			baseUrl?.Trim().TrimEnd('/').ToLowerInvariant() ?? string.Empty,
			endpointId?.Trim().ToLowerInvariant() ?? string.Empty
		});
	}

	private static async Task<string> BuildLocalNodeModelsHeaderAsync(Guid accountId)
	{
		return JsonSerializer.Serialize((from m in await LoadAccountModelsAsync(accountId, includeSecrets: true)
			where m.Enabled
			select new LocalNodeModelPayload
			{
				Provider = m.Provider,
				Name = m.Name,
				Version = m.Version,
				BaseUrl = m.BaseUrl,
				ApiKey = m.ApiKey,
				Enabled = m.Enabled,
				EndpointId = m.EndpointId
			}).ToList(), AppJsonContext.Default.ListLocalNodeModelPayload);
	}

	private static void ApplyAccountHeaders(HttpRequestMessage request)
	{
		AccountContext value = _currentAccount.Value;
		if (value != null)
		{
			ApplyAccountHeaders(request, value);
		}
	}

	private static void ApplyAccountHeaders(HttpRequestMessage request, AccountContext account)
	{
		request.Headers.Remove("X-Account-Id");
		request.Headers.Add("X-Account-Id", account.AccountId.ToString("N"));
		if (!string.IsNullOrWhiteSpace(account.LocalNodeModelsHeader))
		{
			request.Headers.Remove("X-Account-Models");
			request.Headers.Add("X-Account-Models", Convert.ToBase64String(Encoding.UTF8.GetBytes(account.LocalNodeModelsHeader)));
		}
	}

	private static void ApplyBoardCallbackHeaders(HttpRequestMessage request)
	{
		AccountContext value = _currentAccount.Value;
		if (value != null)
		{
			request.Headers.Remove("X-Team-Callback-Token");
			request.Headers.Add("X-Team-Callback-Token", BuildAccountCallbackToken(value.AccountId));
		}
	}

	private static async Task<bool> HandleAgentNodeEndpointAsync(HttpListenerContext context)
	{
		HttpListenerRequest req = context.Request;
		HttpListenerResponse res = context.Response;
		string text = req.Url?.AbsolutePath.ToLowerInvariant() ?? string.Empty;
		if (!IsDatabaseMode)
		{
			await WriteJsonAsync(res, "{\"error\":\"database_required\"}", 503);
			return true;
		}
		if (text == "/api/agent-nodes" && req.HttpMethod == "GET")
		{
			AccountContext accountContext = await GetAccountFromRequestAsync(req);
			if (accountContext == null)
			{
				await WriteJsonAsync(res, "{\"error\":\"unauthorized\"}", 401);
				return true;
			}
			await WriteJsonAsync(res, JsonSerializer.Serialize(await LoadAgentNodesAsync(accountContext.AccountId), AppJsonContext.Default.ListAgentNodeClientPayload));
			return true;
		}
		if (text == "/api/agent-jobs" && req.HttpMethod == "GET")
		{
			AccountContext accountContext2 = await GetAccountFromRequestAsync(req);
			if (accountContext2 == null)
			{
				await WriteJsonAsync(res, "{\"error\":\"unauthorized\"}", 401);
				return true;
			}
			int result;
			int limit = (int.TryParse(req.QueryString["limit"], out result) ? result : 50);
			await WriteJsonAsync(res, JsonSerializer.Serialize(await LoadRecentAgentJobsAsync(accountContext2.AccountId, limit), AppJsonContext.Default.ListAgentJobRecord));
			return true;
		}
