	private static async Task<bool> ConsumeVerificationCodeAsync(string channel, string target, string purpose, string code)
	{
		if (string.IsNullOrWhiteSpace(code))
		{
			return false;
		}
		bool result;
		await using (NpgsqlConnection conn = await OpenDatabaseAsync())
		{
			bool flag;
			await using (NpgsqlCommand cmd = new NpgsqlCommand("UPDATE verification_codes\nSET consumed_at = now()\nWHERE id = (\n    SELECT id FROM verification_codes\n    WHERE channel = @channel AND target = @target AND purpose = @purpose\n      AND code_hash = @code_hash AND consumed_at IS NULL AND expires_at > now()\n    ORDER BY created_at DESC\n    LIMIT 1\n)\nRETURNING id", conn))
			{
				cmd.Parameters.AddWithValue("channel", channel);
				cmd.Parameters.AddWithValue("target", target);
				cmd.Parameters.AddWithValue("purpose", purpose);
				cmd.Parameters.AddWithValue("code_hash", HashText($"{channel}:{target}:{purpose}:{code.Trim()}"));
				flag = await cmd.ExecuteScalarAsync() != null;
			}
			result = flag;
		}
		return result;
	}

	private static async Task<(AccountContext? account, string? passwordHash)> FindAccountByIdentifierAsync(string identifier)
	{
		(AccountContext?, string?) result;
		await using (NpgsqlConnection conn = await OpenDatabaseAsync())
		{
			(AccountContext?, string?) tuple2;
			await using (NpgsqlCommand cmd = new NpgsqlCommand("SELECT id, email, phone, display_name, password_hash\nFROM accounts\nWHERE email = @identifier OR phone = @identifier", conn))
			{
				cmd.Parameters.AddWithValue("identifier", identifier);
				(AccountContext?, string?) tuple;
				await using (NpgsqlDataReader reader = await cmd.ExecuteReaderAsync())
				{
					tuple = ((await reader.ReadAsync()) ? (new AccountContext
					{
						AccountId = reader.GetGuid(0),
						Email = (reader.IsDBNull(1) ? null : reader.GetString(1)),
						Phone = (reader.IsDBNull(2) ? null : reader.GetString(2)),
						DisplayName = reader.GetString(3)
					}, reader.IsDBNull(4) ? null : reader.GetString(4)) : (null, null));
				}
				tuple2 = tuple;
			}
			result = tuple2;
		}
		return result;
	}

	private static async Task<string?> GetAccountPasswordHashAsync(Guid accountId)
	{
