	private static async Task CreateSessionAsync(HttpListenerResponse res, AccountContext account)
	{
		string token = NewToken();
		await using NpgsqlConnection conn = await OpenDatabaseAsync();
		await CleanupExpiredAuthArtifactsAsync(conn);
		await using NpgsqlCommand cmd = new NpgsqlCommand("INSERT INTO sessions(token_hash, account_id, expires_at)\nVALUES (@token_hash, @account_id, now() + interval '30 days')", conn);
