	private static async Task WriteAdminHtmlAsync(HttpListenerResponse res)
	{
		res.ContentType = "text/html; charset=utf-8";
		string s = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title>NiumaClaw 账号后台</title>\n  <style>\n    body{margin:0;font-family:Arial,'Microsoft YaHei',sans-serif;background:#f6f3ec;color:#172033}\n    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;background:#fff;border-bottom:1px solid #e7dfd2}\n    main{padding:20px;display:grid;grid-template-columns:1fr 1fr;gap:16px}\n    section{background:#fff;border:1px solid #e7dfd2;border-radius:10px;padding:16px}\n    label{display:block;font-size:12px;color:#64748b;margin:10px 0 4px}\n    input,textarea{box-sizing:border-box;width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:10px;font:inherit}\n    textarea{min-height:120px}\n    button{border:0;border-radius:8px;padding:10px 14px;font-weight:700;cursor:pointer;background:#2563eb;color:#fff}\n    .ghost{background:#e2e8f0;color:#172033}\n    .danger{background:#dc2626}\n    .row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n    .card{border:1px solid #e2e8f0;border-radius:8px;padding:10px;margin:8px 0;background:#f8fafc}\n    .wide{grid-column:1/-1}\n    @media(max-width:900px){main{grid-template-columns:1fr}}\n  </style>\n</head>\n<body>\n  <header>\n    <strong>NiumaClaw 账号后台</strong>\n    <div class=\"row\"><button class=\"ghost\" onclick=\"location.href='/'\">返回前台</button><button class=\"danger\" onclick=\"logout()\">退出登录</button></div>\n  </header>\n  <main id=\"app\" style=\"display:none\">\n    <section>\n      <h3>公司资料</h3>\n      <label>公司名</label><input id=\"companyName\">\n      <label>MasterNodeUrl</label><input id=\"masterNodeUrl\">\n      <label>公司简介</label><textarea id=\"companyProfile\"></textarea>\n      <label>SOP</label><textarea id=\"companySop\"></textarea>\n    </section>\n    <section>\n      <div class=\"row\" style=\"justify-content:space-between\"><h3>员工管理</h3><button onclick=\"addEmployee()\">新增员工</button></div>\n      <div id=\"employees\"></div>\n    </section>\n    <section class=\"wide\">\n      <div class=\"row\" style=\"justify-content:space-between\"><h3>模型 API</h3><button onclick=\"addModel()\">新增模型</button></div>\n      <div id=\"models\"></div>\n    </section>\n    <section class=\"wide\"><button onclick=\"saveAll()\">保存后台配置</button><span id=\"status\" style=\"margin-left:12px;color:#64748b\"></span></section>\n  </main>\n  <script>\n    let state={config:{PeerNodes:{}},models:[]};\n    const esc=s=>String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));\n    async function auth(){const r=await fetch('/api/auth/me');const me=await r.json();if(!me.authenticated){location.href='/';return;}document.getElementById('app').style.display='grid';await load();}\n    async function load(){const r=await fetch('/api/account/admin/config');if(!r.ok){location.href='/';return;}state=await r.json();render();}\n    function render(){const c=state.config||{};companyName.value=c.CompanyName||c.companyName||'';masterNodeUrl.value=c.MasterNodeUrl||c.masterNodeUrl||'http://127.0.0.1:5050';companyProfile.value=c.CompanyProfile||c.companyProfile||'';companySop.value=c.CompanySOP||c.companySOP||'';renderEmployees();renderModels();}\n    function renderEmployees(){const box=document.getElementById('employees');const nodes=state.config.PeerNodes||{};box.innerHTML=Object.entries(nodes).filter(([n])=>n.toLowerCase()!=='ceo').map(([name,node],i)=>`<div class=\"card\" data-emp=\"${esc(name)}\"><div class=\"row\"><input data-k=\"name\" value=\"${esc(name)}\" placeholder=\"姓名\"><input data-k=\"Role\" value=\"${esc(node.Role||'')}\" placeholder=\"岗位\"><button class=\"danger\" onclick=\"this.closest('.card').remove()\">删除</button></div><label>节点 URL</label><input data-k=\"Url\" value=\"${esc(node.Url||state.config.MasterNodeUrl||'http://127.0.0.1:5050')}\"><label>简介</label><textarea data-k=\"Description\">${esc(node.Description||'')}</textarea><label>简历</label><textarea data-k=\"Resume\">${esc(node.Resume||'')}</textarea><div class=\"row\"><input data-k=\"ReportsTo\" value=\"${esc(node.ReportsTo||'')}\" placeholder=\"汇报对象\"><input data-k=\"ModelIndex\" value=\"${esc(node.ModelIndex||0)}\" placeholder=\"模型索引\"></div></div>`).join('')||'<p>还没有员工。</p>'}\n    function renderModels(){const box=document.getElementById('models');box.innerHTML=(state.models||[]).map((m,i)=>`<div class=\"card\"><div class=\"row\"><input data-k=\"provider\" value=\"${esc(m.provider||'')}\" placeholder=\"供应商\"><input data-k=\"name\" value=\"${esc(m.name||'')}\" placeholder=\"模型名\"><input data-k=\"endpointId\" value=\"${esc(m.endpointId||'')}\" placeholder=\"Endpoint ID\"><button class=\"danger\" onclick=\"this.closest('.card').remove()\">删除</button></div><div class=\"row\"><input data-k=\"version\" value=\"${esc(m.version||'')}\" placeholder=\"版本\"><input data-k=\"baseUrl\" value=\"${esc(m.baseUrl||'')}\" placeholder=\"Base URL\"><input data-k=\"apiKey\" value=\"${esc(m.apiKey||'')}\" placeholder=\"API Key，留空/掩码则保留\"></div><label><input type=\"checkbox\" data-k=\"enabled\" ${m.enabled!==false?'checked':''}> 启用</label></div>`).join('')||'<p>还没有模型。</p>'}\n    function addEmployee(){state.config.PeerNodes=state.config.PeerNodes||{};state.config.PeerNodes['新员工'+Date.now()]={Name:'新员工',Role:'',Url:state.config.MasterNodeUrl||'http://127.0.0.1:5050',Description:'',Resume:'',ModelIndex:0};renderEmployees();}\n    function addModel(){state.models=state.models||[];state.models.push({id:crypto.randomUUID(),provider:'',name:'',version:'',baseUrl:'',apiKey:'',enabled:true,endpointId:'',sortOrder:state.models.length});renderModels();}\n    function collect(){const config=state.config||{};config.CompanyName=companyName.value.trim();config.MasterNodeUrl=masterNodeUrl.value.trim()||'http://127.0.0.1:5050';config.CompanyProfile=companyProfile.value;config.CompanySOP=companySop.value;config.PeerNodes={ceo:{Name:'ceo',Role:'CEO',Url:config.MasterNodeUrl,ModelIndex:0}};document.querySelectorAll('#employees .card').forEach(card=>{const node={};card.querySelectorAll('[data-k]').forEach(el=>{let v=el.value;if(el.dataset.k==='ModelIndex')v=Number(v||0);node[el.dataset.k]=v});const name=(node.name||node.Name||'').trim();if(name){node.Name=name;delete node.name;config.PeerNodes[name]=node;}});const models=[...document.querySelectorAll('#models .card')].map((card,i)=>{const m={id:(state.models[i]&&state.models[i].id)||crypto.randomUUID(),sortOrder:i};card.querySelectorAll('[data-k]').forEach(el=>{m[el.dataset.k]=el.type==='checkbox'?el.checked:el.value});return m});return{config,models};}\n    async function saveAll(){status.textContent='保存中...';const r=await fetch('/api/account/admin/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(collect())});status.textContent=r.ok?'已保存':'保存失败';if(r.ok)await load();}\n    async function logout(){await fetch('/api/auth/logout',{method:'POST'});location.href='/'}\n    auth();\n  </script>\n</body>\n</html>";
		await res.OutputStream.WriteAsync(Encoding.UTF8.GetBytes(s));
	}

	private static async Task HandleLocalNodeAdminPageAsync(HttpListenerContext context, AccountContext account)
	{
		account.LocalNodeModelsHeader = await BuildLocalNodeModelsHeaderAsync(account.AccountId);
		HttpListenerResponse res = context.Response;
		string baseUrl = await GetAccountLocalNodeBaseUrlAsync(account);
		using HttpRequestMessage proxyReq = new HttpRequestMessage(HttpMethod.Get, BuildLocalNodeProxyUri(baseUrl, "/", string.Empty));
		ApplyAccountHeaders(proxyReq, account);
		try
		{
			using HttpResponseMessage proxyRes = await _httpClient.SendAsync(proxyReq);
			string text = await proxyRes.Content.ReadAsStringAsync();
			res.StatusCode = (int)proxyRes.StatusCode;
			res.ContentType = proxyRes.Content.Headers.ContentType?.ToString() ?? "text/html; charset=utf-8";
			if (proxyRes.IsSuccessStatusCode)
			{
				text = RewriteLocalNodeAdminHtml(text);
			}
			await res.OutputStream.WriteAsync(Encoding.UTF8.GetBytes(text));
		}
		catch (Exception ex)
		{
			res.StatusCode = 502;
			res.ContentType = "text/html; charset=utf-8";
			string s = "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><title>后台未启动</title></head>\n<body style=\"font-family:Arial,'Microsoft YaHei',sans-serif;background:#f6f3ec;color:#172033;padding:32px\">\n<h1>5050 后台暂时不可用</h1>\n<p>当前账号已登录，但本地后台节点没有响应：" + WebUtility.HtmlEncode(ex.Message) + "</p>\n<p><a href=\"/\">返回前台</a></p>\n</body></html>";
			await res.OutputStream.WriteAsync(Encoding.UTF8.GetBytes(s));
		}
	}

	private static async Task HandleLocalNodeAdminProxyAsync(HttpListenerContext context, AccountContext account)
	{
		HttpListenerRequest req = context.Request;
		HttpListenerResponse res = context.Response;
		string text = req.Url?.AbsolutePath ?? "/admin-node/";
		string upstreamPath = ((text.Equals("/admin-node", StringComparison.OrdinalIgnoreCase) || text.Equals("/admin-node/", StringComparison.OrdinalIgnoreCase)) ? "/" : ("/" + text.Substring("/admin-node/".Length)));
		if (upstreamPath.Contains("..", StringComparison.Ordinal))
		{
			await WriteJsonAsync(res, "{\"error\":\"invalid_path\"}", 400);
			return;
		}
		account.LocalNodeModelsHeader = await BuildLocalNodeModelsHeaderAsync(account.AccountId);
		if (upstreamPath.Equals("/", StringComparison.OrdinalIgnoreCase) || upstreamPath.Equals("/admin", StringComparison.OrdinalIgnoreCase))
		{
			await HandleLocalNodeAdminPageAsync(context, account);
			return;
		}
		if (upstreamPath.Equals("/api/admin/config", StringComparison.OrdinalIgnoreCase))
		{
			if (req.HttpMethod == "GET")
			{
				await HandleLocalNodeAdminConfigGetAsync(res, account);
				return;
			}
			if (req.HttpMethod == "POST")
			{
				await HandleLocalNodeAdminConfigPostAsync(req, res, account);
				return;
			}
		}
		if (upstreamPath.Equals("/api/admin/disable-invalid-models", StringComparison.OrdinalIgnoreCase) && req.HttpMethod == "POST")
		{
			await HandleLocalNodeAdminDisableInvalidAsync(req, res, account);
			return;
		}
		if (IsAllowedLocalNodeAdminProxyPath(upstreamPath))
		{
			string baseUrl = await GetAccountLocalNodeBaseUrlAsync(account);
			using HttpRequestMessage proxyReq = new HttpRequestMessage(new HttpMethod(req.HttpMethod), BuildLocalNodeProxyUri(baseUrl, upstreamPath, req.Url?.Query ?? string.Empty));
			ApplyAccountHeaders(proxyReq, account);
			if (req.HasEntityBody)
			{
				if (req.HttpMethod == "POST" && upstreamPath.Equals("/api/admin/test", StringComparison.OrdinalIgnoreCase))
				{
					string body = await ReadRequestBodyTextAsync(req);
					proxyReq.Content = new StringContent(await HydrateLocalNodeAdminConfigPayloadSecretsAsync(account.AccountId, body), Encoding.UTF8, "application/json");
				}
				else if (req.HttpMethod == "POST" && upstreamPath.Equals("/api/admin/discover-models", StringComparison.OrdinalIgnoreCase))
				{
					string body2 = await ReadRequestBodyTextAsync(req);
					proxyReq.Content = new StringContent(await HydrateDiscoverModelsPayloadSecretsAsync(account.AccountId, body2), Encoding.UTF8, "application/json");
				}
				else
				{
					proxyReq.Content = new ByteArrayContent(await ReadRequestBodyBytesAsync(req));
					if (!string.IsNullOrWhiteSpace(req.ContentType))
					{
						proxyReq.Content.Headers.TryAddWithoutValidation("Content-Type", req.ContentType);
					}
				}
			}
			using HttpResponseMessage proxyRes = await _httpClient.SendAsync(proxyReq, HttpCompletionOption.ResponseHeadersRead);
			await RelayProxyResponseAsync(res, proxyRes);
			return;
		}
		await WriteJsonAsync(res, "{\"error\":\"not_found\"}", 404);
	}

	private static bool IsAllowedLocalNodeAdminProxyPath(string path)
	{
		if (!path.Equals("/api/admin/test", StringComparison.OrdinalIgnoreCase) && !path.Equals("/api/admin/discover-models", StringComparison.OrdinalIgnoreCase) && !path.StartsWith("/generated/", StringComparison.OrdinalIgnoreCase))
		{
			return path.StartsWith("/preview/", StringComparison.OrdinalIgnoreCase);
		}
		return true;
	}

	private static string RewriteLocalNodeAdminHtml(string html)
	{
		html = html.Replace("fetch('/api/", "fetch('/admin-node/api/", StringComparison.Ordinal).Replace("fetch(\"/api/", "fetch(\"/admin-node/api/", StringComparison.Ordinal).Replace("fetch(`/api/", "fetch(`/admin-node/api/", StringComparison.Ordinal)
			.Replace("href=\"/api/", "href=\"/admin-node/api/", StringComparison.Ordinal)
			.Replace("src=\"/generated/", "src=\"/admin-node/generated/", StringComparison.Ordinal)
			.Replace("src=\"/preview/", "src=\"/admin-node/preview/", StringComparison.Ordinal);
		if (!html.Contains("data-niumaclaw-back-home", StringComparison.Ordinal))
		{
			int num = html.IndexOf("<body", StringComparison.OrdinalIgnoreCase);
			if (num >= 0)
			{
				int num2 = html.IndexOf('>', num);
				if (num2 >= 0)
				{
					html = html.Insert(num2 + 1, "\n<a data-niumaclaw-back-home href=\"/\" style=\"position:fixed;right:26px;top:22px;z-index:10000;display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(207,122,46,.28);border-radius:999px;background:#ffffff;color:#1f2937;text-decoration:none;font-weight:800;padding:10px 16px;box-shadow:0 12px 28px rgba(31,41,55,.12);\">← 回到前台</a>");
				}
			}
			else
			{
				html = "<a data-niumaclaw-back-home href=\"/\" style=\"position:fixed;right:26px;top:22px;z-index:10000;display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(207,122,46,.28);border-radius:999px;background:#ffffff;color:#1f2937;text-decoration:none;font-weight:800;padding:10px 16px;box-shadow:0 12px 28px rgba(31,41,55,.12);\">← 回到前台</a>\n" + html;
			}
		}
		return html;
	}

	private static async Task HandleLocalNodeAdminConfigGetAsync(HttpListenerResponse res, AccountContext account)
	{
		AppConfig config = await LoadAccountConfigAsync(account.AccountId);
		List<ModelEndpointConfig> list = await LoadAccountModelsAsync(account.AccountId, includeSecrets: false);
		string baseUrl = list.FirstOrDefault((ModelEndpointConfig m) => !string.IsNullOrWhiteSpace(m.BaseUrl))?.BaseUrl ?? string.Empty;
		string apiKey = list.FirstOrDefault((ModelEndpointConfig m) => !string.IsNullOrWhiteSpace(m.ApiKey))?.ApiKey ?? string.Empty;
		LocalNodeAdminConfigPayload value = new LocalNodeAdminConfigPayload
		{
			BaseUrl = baseUrl,
			ApiKey = apiKey,
			Port = TryReadPort(config.MasterNodeUrl, 5050),
			Models = list,
			PeerNodes = config.PeerNodes,
			ConfigPath = $"PostgreSQL account {account.AccountId:N}"
		};
		await WriteJsonAsync(res, JsonSerializer.Serialize(value, AppJsonContext.Default.LocalNodeAdminConfigPayload));
	}

	private static async Task HandleLocalNodeAdminConfigPostAsync(HttpListenerRequest req, HttpListenerResponse res, AccountContext account)
	{
		string body = await ReadRequestBodyTextAsync(req);
		LocalNodeAdminConfigPayload payload;
		try
		{
			payload = JsonSerializer.Deserialize(body, AppJsonContext.Default.LocalNodeAdminConfigPayload);
		}
		catch (JsonException)
		{
			payload = null;
		}
		if (payload == null)
		{
			await WriteJsonAsync(res, "{\"error\":\"invalid_json\"}", 400);
			return;
		}
		List<ModelEndpointConfig> incoming = NormalizeLocalNodeAdminModels(payload);
		await SaveAccountModelsAsync(account.AccountId, incoming);
		if (BodyHasJsonProperty(body, "peerNodes", "PeerNodes"))
		{
			AppConfig appConfig = await LoadAccountConfigAsync(account.AccountId);
			appConfig.PeerNodes = payload.PeerNodes ?? new Dictionary<string, NodeInfo>();
			await SaveAccountConfigAsync(account.AccountId, appConfig);
		}
		await WriteJsonAsync(res, "{\"status\":\"ok\",\"message\":\"已保存到当前账号后台。\"}");
	}

	private static async Task HandleLocalNodeAdminDisableInvalidAsync(HttpListenerRequest req, HttpListenerResponse res, AccountContext account)
	{
		string body = await ReadRequestBodyTextAsync(req);
		LocalNodeAdminConfigPayload payload;
		try
		{
			payload = JsonSerializer.Deserialize(body, AppJsonContext.Default.LocalNodeAdminConfigPayload);
		}
		catch (JsonException)
		{
			payload = null;
		}
		if (payload == null)
		{
			await WriteJsonAsync(res, "{\"error\":\"invalid_json\"}", 400);
			return;
		}
		string baseUrl = await GetAccountLocalNodeBaseUrlAsync(account);
		using HttpRequestMessage proxyReq = new HttpRequestMessage(HttpMethod.Post, BuildLocalNodeProxyUri(baseUrl, "/api/admin/test", string.Empty));
		proxyReq.Content = new StringContent(body, Encoding.UTF8, "application/json");
		ApplyAccountHeaders(proxyReq, account);
		using HttpResponseMessage proxyRes = await _httpClient.SendAsync(proxyReq);
		string text = await proxyRes.Content.ReadAsStringAsync();
		if (!proxyRes.IsSuccessStatusCode)
		{
			res.StatusCode = (int)proxyRes.StatusCode;
			res.ContentType = proxyRes.Content.Headers.ContentType?.ToString() ?? "application/json; charset=utf-8";
			await res.OutputStream.WriteAsync(Encoding.UTF8.GetBytes(text));
			return;
		}
		List<LocalNodeAdminDisabledModel> disabled = ExtractDisableCandidates(text);
		List<ModelEndpointConfig> models = NormalizeLocalNodeAdminModels(payload);
		foreach (ModelEndpointConfig model in models)
		{
			if (disabled.Any((LocalNodeAdminDisabledModel item) => (!string.IsNullOrWhiteSpace(item.EndpointId) && string.Equals(item.EndpointId, model.EndpointId, StringComparison.OrdinalIgnoreCase)) || (!string.IsNullOrWhiteSpace(item.Model) && string.Equals(item.Model, model.Name, StringComparison.OrdinalIgnoreCase))))
			{
				model.Enabled = false;
			}
		}
		if (disabled.Count > 0)
		{
			await SaveAccountModelsAsync(account.AccountId, models);
		}
		LocalNodeAdminDisableResult value = new LocalNodeAdminDisableResult
		{
			CheckedCount = models.Count((ModelEndpointConfig m) => m.Enabled || disabled.Any((LocalNodeAdminDisabledModel item) => string.Equals(item.EndpointId, m.EndpointId, StringComparison.OrdinalIgnoreCase))),
			DisabledCount = disabled.Count,
			DisabledModels = disabled,
			Summary = ((disabled.Count > 0) ? $"已为当前账号自动停用 {disabled.Count} 个不可用模型。" : "当前启用模型都还能用，没有需要自动停用的项。")
		};
		await WriteJsonAsync(res, JsonSerializer.Serialize(value, AppJsonContext.Default.LocalNodeAdminDisableResult));
	}

	private static List<LocalNodeAdminDisabledModel> ExtractDisableCandidates(string json)
	{
		List<LocalNodeAdminDisabledModel> list = new List<LocalNodeAdminDisabledModel>();
		try
		{
			using JsonDocument jsonDocument = JsonDocument.Parse(json);
			if (!jsonDocument.RootElement.TryGetProperty("results", out var value) || value.ValueKind != JsonValueKind.Array)
			{
				return list;
			}
			foreach (JsonElement item in value.EnumerateArray())
			{
				JsonElement value2;
				bool flag = item.TryGetProperty("ok", out value2) && value2.ValueKind == JsonValueKind.True;
				string text = ReadJsonString(item, "error", "Error");
				if (!flag && ShouldDisableModelForAccountAdmin(text))
				{
					list.Add(new LocalNodeAdminDisabledModel
					{
						Provider = ReadJsonString(item, "provider", "Provider"),
						Model = ReadJsonString(item, "model", "Model"),
						Version = ReadJsonString(item, "version", "Version"),
						EndpointId = ReadJsonString(item, "endpointId", "EndpointId"),
						Reason = text
					});
				}
			}
		}
		catch (JsonException)
		{
		}
		return list;
	}

	private static bool ShouldDisableModelForAccountAdmin(string? error)
	{
		string text = (error ?? string.Empty).Trim().ToLowerInvariant();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		if (!text.Contains("invalidendpointormodel") && !text.Contains("modelnotopen") && !text.Contains("does not exist") && !text.Contains("do not have access") && !text.Contains("unauthorized") && !text.Contains("api key") && !text.Contains("setlimitexceeded") && !text.Contains("safe experience mode"))
		{
			return text.Contains("does not support this api");
		}
		return true;
	}

	private static List<ModelEndpointConfig> NormalizeLocalNodeAdminModels(LocalNodeAdminConfigPayload payload)
	{
		string defaultBaseUrl = payload.BaseUrl?.Trim() ?? string.Empty;
		string defaultApiKey = payload.ApiKey?.Trim() ?? string.Empty;
		return (payload.Models ?? new List<ModelEndpointConfig>()).Where((ModelEndpointConfig model) => !string.IsNullOrWhiteSpace(model.Name) || !string.IsNullOrWhiteSpace(model.EndpointId)).Select((ModelEndpointConfig model, int index) => new ModelEndpointConfig
		{
			Id = (model.Id?.Trim() ?? string.Empty),
			Provider = (string.IsNullOrWhiteSpace(model.Provider) ? "OpenAI Compatible" : model.Provider.Trim()),
			Name = (model.Name?.Trim() ?? string.Empty),
			Version = (model.Version?.Trim() ?? string.Empty),
			BaseUrl = (string.IsNullOrWhiteSpace(model.BaseUrl) ? defaultBaseUrl : model.BaseUrl.Trim()),
			ApiKey = (string.IsNullOrWhiteSpace(model.ApiKey) ? defaultApiKey : model.ApiKey.Trim()),
			Enabled = model.Enabled,
			EndpointId = (model.EndpointId?.Trim() ?? string.Empty),
			SortOrder = index
		}).ToList();
	}

	private static bool IsMaskedSecretValue(string? value)
	{
		string text = (value ?? string.Empty).Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return true;
		}
		if (text.Contains("****", StringComparison.Ordinal))
		{
			return true;
		}
		return text.All((char ch) => ch == '*' || ch == '•' || ch == '●' || ch == '·');
	}

	private static string ModelSecretSignature(ModelEndpointConfig model)
	{
		return BuildModelSecretSignature(model.Provider, model.Name, model.Version, model.BaseUrl, model.EndpointId);
	}

	private static string FindBestSavedModelSecret(IReadOnlyList<ModelEndpointConfig> savedModels, string? provider, string? name, string? version, string? baseUrl, string? endpointId)
	{
		ModelEndpointConfig model = new ModelEndpointConfig
		{
			Provider = (provider?.Trim() ?? string.Empty),
			Name = (name?.Trim() ?? string.Empty),
			Version = (version?.Trim() ?? string.Empty),
			BaseUrl = (baseUrl?.Trim() ?? string.Empty),
			EndpointId = (endpointId?.Trim() ?? string.Empty)
		};
		string signature = ModelSecretSignature(model);
		ModelEndpointConfig modelEndpointConfig = savedModels.FirstOrDefault((ModelEndpointConfig modelEndpointConfig4) => !string.IsNullOrWhiteSpace(modelEndpointConfig4.ApiKey) && string.Equals(ModelSecretSignature(modelEndpointConfig4), signature, StringComparison.OrdinalIgnoreCase));
		if (modelEndpointConfig != null)
		{
			return modelEndpointConfig.ApiKey;
		}
		string normalizedBaseUrl = (baseUrl ?? string.Empty).Trim().TrimEnd('/');
		ModelEndpointConfig modelEndpointConfig2 = savedModels.FirstOrDefault((ModelEndpointConfig modelEndpointConfig4) => !string.IsNullOrWhiteSpace(modelEndpointConfig4.ApiKey) && !string.IsNullOrWhiteSpace(normalizedBaseUrl) && string.Equals((modelEndpointConfig4.BaseUrl ?? string.Empty).Trim().TrimEnd('/'), normalizedBaseUrl, StringComparison.OrdinalIgnoreCase));
		if (modelEndpointConfig2 != null)
		{
			return modelEndpointConfig2.ApiKey;
		}
		ModelEndpointConfig modelEndpointConfig3 = savedModels.FirstOrDefault((ModelEndpointConfig modelEndpointConfig4) => !string.IsNullOrWhiteSpace(modelEndpointConfig4.ApiKey) && !string.IsNullOrWhiteSpace(endpointId) && string.Equals(modelEndpointConfig4.EndpointId, endpointId, StringComparison.OrdinalIgnoreCase));
		if (modelEndpointConfig3 != null)
		{
			return modelEndpointConfig3.ApiKey;
		}
		return savedModels.FirstOrDefault((ModelEndpointConfig modelEndpointConfig4) => !string.IsNullOrWhiteSpace(modelEndpointConfig4.ApiKey))?.ApiKey ?? string.Empty;
	}

	private static async Task<string> HydrateLocalNodeAdminConfigPayloadSecretsAsync(Guid accountId, string body)
	{
		LocalNodeAdminConfigPayload payload;
		try
		{
			payload = JsonSerializer.Deserialize(body, AppJsonContext.Default.LocalNodeAdminConfigPayload);
		}
		catch (JsonException)
		{
			return body;
		}
		if (payload == null)
		{
			return body;
		}
		List<ModelEndpointConfig> list = await LoadAccountModelsAsync(accountId, includeSecrets: true);
		if (list.Count == 0)
		{
			return body;
		}
		if (IsMaskedSecretValue(payload.ApiKey))
		{
			payload.ApiKey = FindBestSavedModelSecret(list, null, null, null, payload.BaseUrl, null);
		}
		foreach (ModelEndpointConfig model in payload.Models)
		{
			if (IsMaskedSecretValue(model.ApiKey))
			{
				model.ApiKey = FindBestSavedModelSecret(list, model.Provider, model.Name, model.Version, string.IsNullOrWhiteSpace(model.BaseUrl) ? payload.BaseUrl : model.BaseUrl, model.EndpointId);
			}
		}
		return JsonSerializer.Serialize(payload, AppJsonContext.Default.LocalNodeAdminConfigPayload);
	}

	private static async Task<string> HydrateDiscoverModelsPayloadSecretsAsync(Guid accountId, string body)
	{
		try
		{
			using JsonDocument doc = JsonDocument.Parse(body);
			JsonElement rootElement = doc.RootElement;
			string provider = ReadJsonString(rootElement, "provider", "Provider") ?? string.Empty;
			string baseUrl = ReadJsonString(rootElement, "baseUrl", "BaseUrl") ?? string.Empty;
			string value = ReadJsonString(rootElement, "apiKey", "ApiKey") ?? string.Empty;
			if (IsMaskedSecretValue(value))
			{
				value = FindBestSavedModelSecret(await LoadAccountModelsAsync(accountId, includeSecrets: true), provider, null, null, baseUrl, null);
			}
			return "{\"provider\":" + JsonSerializer.Serialize(provider, AppJsonContext.Default.String) + ",\"baseUrl\":" + JsonSerializer.Serialize(baseUrl, AppJsonContext.Default.String) + ",\"apiKey\":" + JsonSerializer.Serialize(value, AppJsonContext.Default.String) + "}";
		}
		catch (JsonException)
		{
			return body;
		}
	}

	private static string DefaultLocalNodeBaseUrl()
	{
		if (Uri.TryCreate(Environment.GetEnvironmentVariable("NIUMACLAW_LOCALNODE_URL") ?? Environment.GetEnvironmentVariable("NiumaClaw_LOCALNODE_URL"), UriKind.Absolute, out Uri result))
		{
			return result.GetLeftPart(UriPartial.Authority);
		}
		string environmentVariable = Environment.GetEnvironmentVariable("NiumaClaw_LOCALNODE_CONFIG");
		if (!string.IsNullOrWhiteSpace(environmentVariable) && File.Exists(environmentVariable))
		{
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(environmentVariable));
				if (jsonDocument.RootElement.TryGetProperty("Port", out var value) && value.TryGetInt32(out var value2) && value2 > 0)
				{
					return $"http://127.0.0.1:{value2}";
				}
				if (jsonDocument.RootElement.TryGetProperty("port", out var value3) && value3.TryGetInt32(out var value4) && value4 > 0)
				{
					return $"http://127.0.0.1:{value4}";
				}
			}
			catch
			{
			}
		}
		return "http://127.0.0.1:5050";
	}

	private static string NormalizeConfiguredLocalNodeUrl(string? rawUrl)
	{
		string text = DefaultLocalNodeBaseUrl();
		string text2 = (string.IsNullOrWhiteSpace(rawUrl) ? text : rawUrl.Trim());
		if (Uri.TryCreate(text2, UriKind.Absolute, out Uri result) && result.IsLoopback && Uri.TryCreate(text, UriKind.Absolute, out Uri result2) && result2.IsLoopback && result2.Port != 5050 && result.Port != result2.Port)
		{
			return result2.GetLeftPart(UriPartial.Authority);
		}
		return text2;
	}

	private static string SafeLoopbackLocalNodeBaseUrl(string? rawUrl)
	{
		if (Uri.TryCreate(NormalizeConfiguredLocalNodeUrl(rawUrl), UriKind.Absolute, out Uri result) && result.IsLoopback)
		{
			return result.GetLeftPart(UriPartial.Authority);
		}
		return DefaultLocalNodeBaseUrl();
	}

