	private static Uri BuildLocalNodeProxyUri(string baseUrl, string upstreamPath, string query)
	{
		string text = (string.IsNullOrWhiteSpace(upstreamPath) ? "/" : upstreamPath);
		if (!text.StartsWith('/'))
		{
			text = "/" + text;
		}
		string relativeUri = text.TrimStart('/') + (query ?? string.Empty);
		return new Uri(new Uri(baseUrl.TrimEnd('/') + "/"), relativeUri);
	}

	private static int TryReadPort(string? url, int fallback)
	{
		if (!Uri.TryCreate(url, UriKind.Absolute, out Uri result) || result.Port <= 0)
		{
			return fallback;
		}
		return result.Port;
	}

	private static bool BodyHasJsonProperty(string body, params string[] names)
	{
		try
		{
			JsonDocument doc = JsonDocument.Parse(body);
			try
			{
				if (doc.RootElement.ValueKind != JsonValueKind.Object)
				{
					return false;
				}
				return names.Any((string name) => doc.RootElement.TryGetProperty(name, out var _));
			}
			finally
			{
				if (doc != null)
				{
					((IDisposable)doc).Dispose();
				}
			}
		}
		catch (JsonException)
		{
			return false;
		}
	}

	private static async Task<byte[]> ReadRequestBodyBytesAsync(HttpListenerRequest req)
	{
		using MemoryStream ms = new MemoryStream();
		await req.InputStream.CopyToAsync(ms);
		return ms.ToArray();
	}

	private static async Task<string> ReadRequestBodyTextAsync(HttpListenerRequest req)
	{
		byte[] bytes = await ReadRequestBodyBytesAsync(req);
		return Encoding.UTF8.GetString(bytes);
	}

	private static string GetAdapterType(NodeInfo? node)
	{
		string text = node?.AdapterType?.Trim();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text.ToLowerInvariant();
		}
		string text2 = node?.Url?.Trim().ToLowerInvariant() ?? string.Empty;
		if (text2.StartsWith("agent-node://", StringComparison.OrdinalIgnoreCase))
		{
			return "codex_runner";
		}
		if (text2.Contains(":5060"))
		{
			return "hermes";
		}
		if (!string.IsNullOrWhiteSpace(text2))
		{
			return "localnode";
		}
		return "unknown";
	}

	private static List<string> GetNodeCapabilities(NodeInfo? node)
	{
		List<string> list = node?.Capabilities;
		if (list != null && list.Count > 0)
		{
			return (from item in node.Capabilities
				where !string.IsNullOrWhiteSpace(item)
				select item.Trim()).Distinct<string>(StringComparer.OrdinalIgnoreCase).ToList();
		}
		return GetAdapterType(node) switch
		{
			"hermes" => new List<string> { "code", "search", "terminal", "files", "vision" },
			"catmeme" => new List<string> { "video", "ffmpeg", "subtitles", "meme", "bilibili", "runs", "artifacts" },
			"localnode" => new List<string> { "chat", "tasks", "approvals", "attachments" },
			"codex_runner" => new List<string> { "chat", "tasks", "terminal", "files", "code", "runner" },
			"hermes_runner" => new List<string> { "chat", "tasks", "terminal", "files", "code", "runner" },
			"claude_runner" => new List<string> { "chat", "tasks", "terminal", "files", "code", "runner" },
			"local_runner" => new List<string> { "chat", "tasks", "runner" },
			_ => new List<string>(),
		};
	}

	private static string GetAdapterTypeDisplayName(string? adapterType)
	{
		return (adapterType ?? string.Empty).Trim().ToLowerInvariant() switch
		{
			"codex_runner" => "Codex",
			"hermes_runner" => "Hermes",
			"claude_runner" => "Claude Code",
			"local_runner" => "Local",
			"hermes" => "Hermes",
			"catmeme" => "CatMeme",
			_ => "LocalNode",
		};
	}

