	private static void TouchTask(ProjectTask task)
	{
		task.UpdateTime = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
	}

	private static void NormalizeProjectTaskForSave(ProjectTask task, ProjectBoard board)
	{
		if (task == null)
		{
			return;
		}
		if (string.IsNullOrWhiteSpace(task.Id))
		{
			task.Id = Guid.NewGuid().ToString("N").Substring(0, 8);
		}
		ProjectTask projectTask = task;
		if (projectTask.DependsOn == null)
		{
			List<string> list = (projectTask.DependsOn = new List<string>());
		}
		task.DependsOn = (from dep in task.DependsOn
			select (dep ?? string.Empty).Trim() into dep
			where dep.Length > 0
			select dep).Distinct<string>(StringComparer.OrdinalIgnoreCase).ToList();
		if (string.IsNullOrWhiteSpace(task.Assignee))
		{
			task.Assignee = "待认领";
		}
		string text = NormalizeTaskStatus(task.Status);
		task.Status = ((text.Length > 0) ? text : "todo");
		if (task.DependsOn.Count > 0 && task.Status == "todo")
		{
			task.Status = "backlog";
			projectTask = task;
			if (projectTask.BlockedReason == null)
			{
				string text2 = (projectTask.BlockedReason = "等待前置阶段完成");
			}
		}
		if (string.IsNullOrWhiteSpace(task.GoalId))
		{
			task.GoalId = board.GoalId;
		}
		if (string.IsNullOrWhiteSpace(task.ContextSummary))
		{
			task.ContextSummary = board.ContextSummary ?? board.ProjectGoal;
		}
		TouchTask(task);
	}

	private static int UnlockReadyDependentTasks(ProjectTask completedTask, List<ProjectTask>? unlockedTasks = null)
	{
		ProjectBoard projectBoard = FindProjectContainingTask(completedTask);
		if (projectBoard == null)
		{
			return 0;
		}
		HashSet<string> doneIds = (from task in projectBoard.Tasks
			where string.Equals(NormalizeTaskStatus(task.Status), "done", StringComparison.OrdinalIgnoreCase)
			select task.Id).ToHashSet<string>(StringComparer.OrdinalIgnoreCase);
		int num = 0;
		foreach (ProjectTask task in projectBoard.Tasks)
		{
			if (task == null || string.Equals(task.Id, completedTask.Id, StringComparison.OrdinalIgnoreCase))
			{
				continue;
			}
			ProjectTask projectTask = task;
			if (projectTask.DependsOn == null)
			{
				List<string> list = (projectTask.DependsOn = new List<string>());
			}
			if (task.DependsOn.Count == 0 || !task.DependsOn.Any((string dep) => string.Equals(dep, completedTask.Id, StringComparison.OrdinalIgnoreCase)))
			{
				continue;
			}
			bool flag;
			switch (NormalizeTaskStatus(task.Status))
			{
			case "done":
			case "in_progress":
			case "waiting_approval":
			case "in_review":
			case "cancelled":
				flag = true;
				break;
			default:
				flag = false;
				break;
			}
			if (flag || !task.DependsOn.All((string dep) => doneIds.Contains(dep)))
			{
				continue;
			}
			if (!CanStartBoardTask(task, out string reason))
			{
				task.Status = "backlog";
				task.BlockedReason = reason;
				TouchTask(task);
				continue;
			}
			task.Status = "todo";
			task.BlockedReason = null;
			projectTask = task;
			if (projectTask.Comments == null)
			{
				List<TaskComment> list3 = (projectTask.Comments = new List<TaskComment>());
			}
			task.Comments.Add(new TaskComment
			{
				Author = "system",
				Content = "前置任务《" + completedTask.Title + "》已完成，当前阶段已解锁，可开始执行。",
				Timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
			});
			TouchTask(task);
			unlockedTasks?.Add(task);
			num++;
		}
		return num;
	}

	private static bool AreTaskDependenciesSatisfied(ProjectTask task, out string missingTitles)
	{
		missingTitles = string.Empty;
		if (task.DependsOn == null)
		{
			List<string> list = (task.DependsOn = new List<string>());
		}
		if (task.DependsOn.Count == 0)
		{
			return true;
		}
		ProjectBoard project = FindProjectContainingTask(task);
		if (project == null)
		{
			return false;
		}
		List<string> list3 = (from dep in task.DependsOn
			select project.Tasks.FirstOrDefault((ProjectTask candidate) => string.Equals(candidate.Id, dep, StringComparison.OrdinalIgnoreCase)) into depTask
			where depTask != null && NormalizeTaskStatus(depTask.Status) != "done"
			select depTask.Title into title
			where !string.IsNullOrWhiteSpace(title)
			select title).ToList();
		missingTitles = string.Join("、", list3);
		return list3.Count == 0;
	}

	private static async Task DispatchReadyBoardTasksAsync(ProjectBoard project, IReadOnlyList<ProjectTask> tasks, string currentTeamUrl)
	{
		List<ProjectTask> readyTasks = new List<ProjectTask>();
		lock (_configSyncRoot)
		{
			bool flag = false;
			foreach (ProjectTask task2 in tasks)
			{
				if (task2 == null || string.IsNullOrWhiteSpace(task2.Id) || string.IsNullOrWhiteSpace(task2.Assignee) || NormalizeTaskStatus(task2.Status) != "todo")
				{
					continue;
				}
				if (CanStartBoardTask(task2, out string reason))
				{
					readyTasks.Add(task2);
					continue;
				}
				task2.Status = "backlog";
				task2.BlockedReason = reason;
				ProjectTask projectTask = task2;
				if (projectTask.Comments == null)
				{
					projectTask.Comments = new List<TaskComment>();
				}
				task2.Comments.Add(new TaskComment
				{
					Author = "system",
					Content = reason,
					Timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
				});
				TouchTask(task2);
				flag = true;
			}
			if (flag)
			{
				SaveConfigLocked();
			}
		}
		if (readyTasks.Count == 0)
		{
			return;
		}
		AccountContext currentAccount = _currentAccount.Value;
		bool flag2 = false;
		if (IsDatabaseMode && currentAccount != null)
		{
			foreach (ProjectTask task in readyTasks.ToList())
			{
				if (_config.PeerNodes.TryGetValue(task.Assignee, out NodeInfo value) && IsRunnerAdapter(GetAdapterType(value)))
				{
					string prompt = string.Join("\n", new string[7]
					{
						"项目：" + project.ProjectName,
						"阶段：" + task.Phase,
						"任务：" + task.Title,
						string.IsNullOrWhiteSpace(task.Deliverable) ? string.Empty : ("交付物：" + task.Deliverable),
						string.IsNullOrWhiteSpace(task.Gate) ? string.Empty : ("完成条件：" + task.Gate),
						string.IsNullOrWhiteSpace(project.ContextSummary) ? string.Empty : ("项目上下文：" + project.ContextSummary),
						"请在本机工作区完成任务，并输出执行总结、关键文件路径或可验证结果。"
					}.Where((string line) => !string.IsNullOrWhiteSpace(line)));
					string payloadJson = "{\"source\":\"project_board\",\"projectName\":" + JsonSerializer.Serialize(project.ProjectName ?? string.Empty, AppJsonContext.Default.String) + ",\"taskId\":" + JsonSerializer.Serialize(task.Id, AppJsonContext.Default.String) + ",\"assignee\":" + JsonSerializer.Serialize(task.Assignee, AppJsonContext.Default.String) + "}";
					await CreateAgentJobAsync(currentAccount.AccountId, value, task.Assignee, prompt, task.Id, payloadJson);
					lock (_configSyncRoot)
					{
						task.Status = "in_progress";
						task.CheckedOutBy = task.Assignee;
						task.CheckedOutAt = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
						task.Result = "任务已派发给本机 Agent Runner，等待桌面端执行完成。";
						task.BlockedReason = null;
						TouchTask(task);
					}
					readyTasks.Remove(task);
					flag2 = true;
				}
			}
			if (flag2)
			{
				await SaveAccountConfigAsync(currentAccount.AccountId, _config);
			}
		}
		if (readyTasks.Count == 0)
		{
			return;
		}
		string text = string.Join(",\n", readyTasks.Select((ProjectTask projectTask2) => "  {\n    \"project_name\": " + JsonSerializer.Serialize(project.ProjectName, AppJsonContext.Default.String) + ",\n    \"id\": " + JsonSerializer.Serialize(projectTask2.Id, AppJsonContext.Default.String) + ",\n    \"title\": " + JsonSerializer.Serialize(string.Join("\n", new string[6]
		{
			"项目：" + project.ProjectName,
			"阶段：" + projectTask2.Phase,
			"任务：" + projectTask2.Title,
			string.IsNullOrWhiteSpace(projectTask2.Deliverable) ? string.Empty : ("交付物：" + projectTask2.Deliverable),
			string.IsNullOrWhiteSpace(projectTask2.Gate) ? string.Empty : ("完成条件：" + projectTask2.Gate),
			"请直接产出文件或可验证结果，完成后提交执行总结。"
		}.Where((string line) => !string.IsNullOrWhiteSpace(line))), AppJsonContext.Default.String) + ",\n    \"assignee\": " + JsonSerializer.Serialize(projectTask2.Assignee, AppJsonContext.Default.String) + ",\n    \"phase\": " + JsonSerializer.Serialize(projectTask2.Phase, AppJsonContext.Default.String) + ",\n    \"deliverable\": " + JsonSerializer.Serialize(projectTask2.Deliverable, AppJsonContext.Default.String) + ",\n    \"gate\": " + JsonSerializer.Serialize(projectTask2.Gate, AppJsonContext.Default.String) + "\n  }"));
		NodeInfo value3;
		ChatRequest value2 = new ChatRequest
		{
			message = "请执行下面的看板任务 JSON 数组，只派发这些已解锁阶段：\n[\n" + text + "\n]",
			modelIndex = (_config.PeerNodes.TryGetValue("ceo", out value3) ? value3.ModelIndex : 0),
			sop = _config.CompanySOP,
			caller = "board"
		};
		string text2 = (string.IsNullOrEmpty(_config.MasterNodeUrl) ? "http://127.0.0.1:5050" : _config.MasterNodeUrl);
		HttpRequestMessage httpRequestMessage = new HttpRequestMessage(HttpMethod.Post, text2.TrimEnd('/') + "/api/agent_task");
		httpRequestMessage.Headers.Add("X-Username", Uri.EscapeDataString("ceo"));
		ApplyAccountHeaders(httpRequestMessage);
		httpRequestMessage.Headers.Add("X-Team-Url", Uri.EscapeDataString(currentTeamUrl));
		ApplyBoardCallbackHeaders(httpRequestMessage);
		httpRequestMessage.Content = new StringContent(JsonSerializer.Serialize(value2, typeof(ChatRequest), AppJsonContext.Default), Encoding.UTF8, "application/json");
		using HttpResponseMessage httpResponseMessage = await _httpClient.SendAsync(httpRequestMessage);
		httpResponseMessage.EnsureSuccessStatusCode();
