	private static string NormalizeTaskStatus(string? raw)
	{
		return (raw ?? string.Empty).Trim().ToLowerInvariant() switch
		{
			"doing" => "in_progress",
			"done" => "done",
			"failed" => "blocked",
			"pending" => "todo",
			"backlog" => "backlog",
			"todo" => "todo",
			"in_progress" => "in_progress",
			"waiting_approval" => "waiting_approval",
			"waitingapproval" => "waiting_approval",
			"approval" => "waiting_approval",
			"in_review" => "in_review",
			"blocked" => "blocked",
			"cancelled" => "cancelled",
			_ => string.Empty,
		};
	}

	private static string GetTaskStatusLabel(string? raw)
	{
		return NormalizeTaskStatus(raw) switch
		{
			"backlog" => "待规划",
			"todo" => "待办",
			"in_progress" => "处理中",
			"waiting_approval" => "待人工审批",
			"in_review" => "待审核",
			"blocked" => "已阻塞",
			"done" => "已完成",
			"cancelled" => "已取消",
			_ => raw ?? "未知状态",
		};
	}

	private static string NormalizePhaseKey(ProjectTask? task)
	{
