	private static IEnumerable<string> ExtractDeliverableCandidates(ProjectTask task)
	{
		List<string> list = new List<string>();
		string key = NormalizePhaseKey(task);
		if (WebsiteStageDeliverables.TryGetValue(key, out string[] value))
		{
			list.AddRange(value);
		}
		foreach (Match item in Regex.Matches(string.Join("\n", new string[2]
		{
			task.Deliverable ?? string.Empty,
			task.Result ?? string.Empty
		}), "(?:[A-Za-z]:\\\\[^\\s\"'<>`，。,；;)）]+?\\.(?:html|md|pdf|docx?|png|jpe?g|gif|webp|mp4)|(?:docs|artifacts|preview|dist|src|public|assets|reports|test-results)[\\\\/][^\\s\"'<>`，。,；;)）]+|[\\w.-]+\\.(?:html|md|pdf|docx?|png|jpe?g|gif|webp|mp4))", RegexOptions.IgnoreCase))
		{
			list.Add(item.Value);
		}
		return (from item in list
			select item.Trim().Trim(new char[9] { '"', '\'', '`', '，', '。', '；', ';', ')', '）' }) into item
			where item.Length > 0
			select item).Distinct<string>(StringComparer.OrdinalIgnoreCase);
	}

	private static IEnumerable<string> GetDeliverableSearchRoots(ProjectTask task)
	{
		List<string> roots = new List<string>();
		string currentDirectory = Directory.GetCurrentDirectory();
		string baseDirectory = AppContext.BaseDirectory;
		AddRoot(currentDirectory);
		AddRoot(baseDirectory);
		AddRoot(Path.GetFullPath(Path.Combine(baseDirectory, "..", "..", "..")));
		string text = roots.FirstOrDefault((string root) => root.EndsWith("NiumaClaw.Team", StringComparison.OrdinalIgnoreCase)) ?? roots.FirstOrDefault((string root) => File.Exists(Path.Combine(root, "NiumaClaw.Team.csproj")));
		string text2 = ((text != null) ? Directory.GetParent(text)?.FullName : Directory.GetParent(currentDirectory)?.FullName);
		string text3 = (string.IsNullOrWhiteSpace(text2) ? null : Path.Combine(text2, "NiumaClaw.LocalNode"));
		string text4 = (string.IsNullOrWhiteSpace(text3) ? null : Path.Combine(text3, "agent_workspace"));
		if (!string.IsNullOrWhiteSpace(text4))
		{
			if (!string.IsNullOrWhiteSpace(task.Assignee))
			{
				AddRoot(Path.Combine(text4, task.Assignee));
			}
			AddRoot(text4);
			try
			{
				if (Directory.Exists(text4))
				{
					string[] directories = Directory.GetDirectories(text4);
					for (int num = 0; num < directories.Length; num++)
					{
						AddRoot(directories[num]);
					}
				}
			}
			catch
			{
			}
		}
		AddRoot(text3);
		return roots;
		void AddRoot(string? value)
		{
			if (string.IsNullOrWhiteSpace(value))
			{
				return;
			}
			try
			{
				string fullPath = Path.GetFullPath(value);
				if (Directory.Exists(fullPath) && !roots.Contains<string>(fullPath, StringComparer.OrdinalIgnoreCase))
				{
					roots.Add(fullPath);
				}
			}
			catch
			{
			}
		}
	}

	private static bool IsIgnoredDeliverablePath(string path)
	{
		string text = path.Replace('/', '\\');
		if (!text.Contains("\\.git\\", StringComparison.OrdinalIgnoreCase) && !text.Contains("\\bin\\", StringComparison.OrdinalIgnoreCase) && !text.Contains("\\obj\\", StringComparison.OrdinalIgnoreCase) && !text.Contains("\\runs\\", StringComparison.OrdinalIgnoreCase))
		{
			return text.Contains("\\memory\\", StringComparison.OrdinalIgnoreCase);
		}
		return true;
	}

	private static bool TryFindTaskDeliverable(ProjectTask task, out string evidence)
	{
		evidence = string.Empty;
		if (NormalizePhaseKey(task) == "preview" && Regex.IsMatch(task.Result ?? string.Empty, "https?://\\S+", RegexOptions.IgnoreCase))
		{
			evidence = "结果中已包含本地预览链接";
			return true;
		}
		foreach (string item in ExtractDeliverableCandidates(task))
		{
			string text = item.Replace('/', Path.DirectorySeparatorChar).Replace('\\', Path.DirectorySeparatorChar);
			try
			{
				if (Path.IsPathRooted(text) && File.Exists(text) && !IsIgnoredDeliverablePath(text))
				{
					evidence = text;
					return true;
				}
			}
			catch
			{
			}
			foreach (string deliverableSearchRoot in GetDeliverableSearchRoots(task))
			{
				try
				{
					string fullPath = Path.GetFullPath(Path.Combine(deliverableSearchRoot, text));
					if (File.Exists(fullPath) && !IsIgnoredDeliverablePath(fullPath))
					{
						if (string.Equals(Path.GetFileName(fullPath), "index.html", StringComparison.OrdinalIgnoreCase) && fullPath.Contains("NiumaClaw.Team", StringComparison.OrdinalIgnoreCase))
						{
							continue;
						}
						evidence = fullPath;
						return true;
					}
				}
				catch
				{
				}
				string fileName = Path.GetFileName(text);
				if (string.IsNullOrWhiteSpace(fileName) || text.Contains(Path.DirectorySeparatorChar))
				{
					continue;
				}
				try
				{
					string text2 = Directory.EnumerateFiles(deliverableSearchRoot, fileName, SearchOption.AllDirectories).FirstOrDefault((string path) => !IsIgnoredDeliverablePath(path) && (!string.Equals(fileName, "index.html", StringComparison.OrdinalIgnoreCase) || !path.Contains("NiumaClaw.Team", StringComparison.OrdinalIgnoreCase)));
					if (!string.IsNullOrWhiteSpace(text2))
					{
						evidence = text2;
						return true;
					}
				}
				catch
				{
				}
			}
		}
		return false;
	}

	private static bool ValidateTaskCompletionDeliverables(ProjectTask task, out string message)
	{
		message = string.Empty;
		if (!IsWebsiteStageTask(task))
		{
			return true;
		}
		if (TryFindTaskDeliverable(task, out string evidence))
		{
			message = evidence;
			return true;
		}
		string text = NormalizePhaseKey(task);
		string[] value;
		string text2 = (WebsiteStageDeliverables.TryGetValue(text, out value) ? string.Join(" 或 ", value) : (task.Deliverable ?? "阶段交付物"));
		message = "阶段《" + GetStageDisplayName(text) + "》缺少必须交付物：" + text2;
		return false;
	}

	private static bool IsEmptyModelResponseFailure(string? text)
	{
		string text2 = (text ?? string.Empty).Trim();
		if (!text2.Contains("empty response", StringComparison.OrdinalIgnoreCase) && !text2.Contains("空返回", StringComparison.OrdinalIgnoreCase) && !text2.Contains("模型未返回", StringComparison.OrdinalIgnoreCase))
		{
			return text2.Contains("returned an empty", StringComparison.OrdinalIgnoreCase);
		}
		return true;
	}

	private static bool TryAutoCompleteFromExistingDeliverable(ProjectTask task, string reason, List<ProjectTask>? unlockedTasks, out string summary)
	{
		summary = string.Empty;
		if (!TryFindTaskDeliverable(task, out string evidence))
		{
			return false;
		}
		task.Status = "done";
		task.BlockedReason = null;
		task.ReviewRequired = false;
		task.CheckedOutBy = null;
		task.CheckedOutAt = null;
		task.Result = "模型返回为空，但系统已检测到目标交付物存在，自动标记本阶段完成。\n原因：" + reason + "\n交付物：" + evidence;
		if (task.Comments == null)
		{
			List<TaskComment> list = (task.Comments = new List<TaskComment>());
		}
		task.Comments.Add(new TaskComment
		{
			Author = "system",
			Content = "模型空返回兜底：检测到交付物已存在，自动完成阶段。交付物：" + evidence,
			Timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
		});
		TouchTask(task);
		UnlockReadyDependentTasks(task, unlockedTasks);
		summary = task.Result;
		return true;
	}

	private static bool CanStartBoardTask(ProjectTask task, out string reason)
	{
		reason = string.Empty;
		if (!AreTaskDependenciesSatisfied(task, out string missingTitles))
		{
			reason = "前置阶段未完成：" + missingTitles;
			return false;
		}
		ProjectBoard projectBoard = FindProjectContainingTask(task);
		if (projectBoard == null)
		{
			return true;
		}
		string text = NormalizePhaseKey(task);
		string[] value;
		string[] array = (WebsiteStagePrerequisites.TryGetValue(text, out value) ? value : Array.Empty<string>());
		foreach (string priorPhase in array)
		{
			List<ProjectTask> list = projectBoard.Tasks.Where((ProjectTask candidate) => string.Equals(NormalizePhaseKey(candidate), priorPhase, StringComparison.OrdinalIgnoreCase)).ToList();
			if (list.Count != 0)
			{
				ProjectTask projectTask = list.FirstOrDefault((ProjectTask candidate) => NormalizeTaskStatus(candidate.Status) == "done");
				if (projectTask == null)
				{
					reason = $"阶段门禁：必须先完成《{GetStageDisplayName(priorPhase)}》后才能开始《{GetStageDisplayName(text)}》。";
					return false;
				}
				if (!ValidateTaskCompletionDeliverables(projectTask, out string message))
				{
					reason = "阶段门禁：前置阶段《" + GetStageDisplayName(priorPhase) + "》尚未产出有效交付物。" + message;
					return false;
				}
			}
		}
		foreach (string depId in task.DependsOn ?? new List<string>())
		{
			ProjectTask projectTask2 = projectBoard.Tasks.FirstOrDefault((ProjectTask candidate) => string.Equals(candidate.Id, depId, StringComparison.OrdinalIgnoreCase));
			if (projectTask2 != null && IsWebsiteStageTask(projectTask2) && !ValidateTaskCompletionDeliverables(projectTask2, out string message2))
			{
				reason = "阶段门禁：前置任务《" + projectTask2.Title + "》尚未产出有效交付物。" + message2;
				return false;
			}
		}
		return true;
	}

	private static string GetTeamProjectRoot()
	{
		string[] array = new string[3]
		{
			Directory.GetCurrentDirectory(),
			AppContext.BaseDirectory,
			Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "..", "..", ".."))
		};
		foreach (string path in array)
		{
			try
			{
				string fullPath = Path.GetFullPath(path);
				if (File.Exists(Path.Combine(fullPath, "NiumaClaw.Team.csproj")))
				{
					return fullPath;
				}
			}
			catch
			{
			}
		}
		return Directory.GetCurrentDirectory();
	}

	private static string GetWorkspaceRoot()
	{
		return Directory.GetParent(GetTeamProjectRoot())?.FullName ?? Directory.GetCurrentDirectory();
	}

	private static async Task<NodeDiagnosis> DiagnoseNodeAsync(string name, NodeInfo info)
	{
		string text = (info.Url ?? string.Empty).Trim().TrimEnd('/');
		NodeDiagnosis diagnosis = new NodeDiagnosis
		{
			Name = name,
			Url = text,
			AdapterType = GetAdapterType(info),
			LastCheckedAt = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),
			LogHint = GetNodeLogPath(name, info),
			RestartHint = "可点击“重启节点”尝试恢复。"
		};
		if (string.IsNullOrWhiteSpace(text) || !Uri.TryCreate(text, UriKind.Absolute, out Uri baseUri))
		{
			diagnosis.Reason = "节点地址为空或格式不正确。";
			diagnosis.Suggestion = "编辑员工节点地址，格式示例：http://127.0.0.1:5050";
			return diagnosis;
		}
		(bool ok, string error) configProbe = await ProbeAsync("/api/config");
		(bool, string) tuple = await ProbeAsync("/api/status");
		diagnosis.ConfigOk = configProbe.ok;
		diagnosis.StatusOk = tuple.Item1;
		diagnosis.Online = configProbe.ok || tuple.Item1;
		if (diagnosis.Online)
		{
			diagnosis.Reason = ((tuple.Item1 && configProbe.ok) ? "节点在线，配置与状态接口均可访问。" : $"节点部分可用：config={configProbe.ok}，status={tuple.Item1}。");
			diagnosis.Suggestion = (tuple.Item1 ? "无需处理。" : "节点可访问但状态接口异常，建议打开日志确认。");
		}
		else
		{
			diagnosis.Reason = $"节点无响应：/api/config {configProbe.error}；/api/status {tuple.Item2}。";
			diagnosis.Suggestion = "先重启节点；如果仍失败，检查端口是否被占用、脚本是否报错、模型配置是否完整。";
		}
		return diagnosis;
		async Task<(bool ok, string error)> ProbeAsync(string suffix)
		{
			try
			{
				using CancellationTokenSource cts = new CancellationTokenSource(TimeSpan.FromSeconds(3L));
				using HttpResponseMessage httpResponseMessage = await _httpClient.GetAsync(new Uri(baseUri, suffix), cts.Token);
				return httpResponseMessage.IsSuccessStatusCode ? (ok: true, error: string.Empty) : (ok: false, error: $"HTTP {(int)httpResponseMessage.StatusCode}");
			}
			catch (TaskCanceledException)
			{
				return (ok: false, error: "请求超时");
			}
			catch (Exception ex2)
			{
				return (ok: false, error: ex2.Message);
			}
		}
	}

	private static string GetNodeLogPath(string name, NodeInfo info)
	{
		string teamProjectRoot = GetTeamProjectRoot();
		string workspaceRoot = GetWorkspaceRoot();
		if (GetAdapterType(info).ToLowerInvariant().Contains("hermes") || (info.Url ?? string.Empty).Contains(":5061") || (info.Url ?? string.Empty).Contains(":5077"))
		{
			return Path.Combine(teamProjectRoot, "logs");
		}
		string text = Path.Combine(workspaceRoot, "NiumaClaw.LocalNode");
		string text2 = Path.Combine(text, "agent_workspace", name);
		if (Directory.Exists(text2))
		{
			return text2;
		}
		return text;
	}

	private static bool TryRestartNode(string name, NodeInfo info, out string message)
	{
		message = string.Empty;
		try
		{
			string teamProjectRoot = GetTeamProjectRoot();
			string workspaceRoot = GetWorkspaceRoot();
			string text = GetAdapterType(info).ToLowerInvariant();
			string text2 = info.Url ?? string.Empty;
			ProcessStartInfo startInfo;
			if (text.Contains("hermes") || text2.Contains(":5061") || text2.Contains(":5077"))
			{
				string text3 = Path.Combine(teamProjectRoot, "start_hermes_node.cmd");
				if (!File.Exists(text3))
				{
					message = "未找到 Hermes 启动脚本：" + text3;
					return false;
				}
				startInfo = new ProcessStartInfo("cmd.exe", "/c start \"NiumaClaw Hermes\" /min \"" + text3 + "\"")
				{
					WorkingDirectory = teamProjectRoot,
					CreateNoWindow = true,
					UseShellExecute = false
				};
			}
			else
			{
				string text4 = Path.Combine(workspaceRoot, "NiumaClaw.LocalNode", "NiumaClaw.LocalNode.csproj");
				if (!File.Exists(text4))
				{
					message = "未找到 LocalNode 项目：" + text4;
					return false;
				}
				startInfo = new ProcessStartInfo("cmd.exe", "/c start \"NiumaClaw LocalNode\" /min dotnet run --project \"" + text4 + "\"")
				{
					WorkingDirectory = (Path.GetDirectoryName(text4) ?? workspaceRoot),
					CreateNoWindow = true,
					UseShellExecute = false
				};
			}
			Process.Start(startInfo);
			message = "已发起重启，请等待几秒后重新检测。";
			return true;
		}
		catch (Exception ex)
		{
			message = ex.Message;
			return false;
		}
	}

	private static bool TryOpenNodeLog(string name, NodeInfo info, out string message)
	{
		message = string.Empty;
		try
		{
			string text = GetNodeLogPath(name, info);
			if (!Directory.Exists(text) && File.Exists(text))
			{
				text = Path.GetDirectoryName(text) ?? text;
			}
			if (!Directory.Exists(text))
			{
				message = "日志目录不存在：" + text;
				return false;
			}
			Process.Start(new ProcessStartInfo("explorer.exe", "\"" + text + "\"")
			{
				UseShellExecute = true
			});
			message = "已打开日志目录：" + text;
			return true;
		}
		catch (Exception ex)
		{
			message = ex.Message;
			return false;
		}
	}

	private static string ReadNodeNameFromJson(string body)
	{
		try
		{
			using JsonDocument jsonDocument = JsonDocument.Parse(body);
			JsonElement value;
			return jsonDocument.RootElement.TryGetProperty("name", out value) ? (value.GetString() ?? string.Empty).Trim() : string.Empty;
		}
		catch
		{
			return string.Empty;
		}
	}

