	private static string GetStaticContentType(string filePath)
	{
		switch (Path.GetExtension(filePath).ToLowerInvariant())
		{
		case ".html":
		case ".htm":
			return "text/html; charset=utf-8";
		case ".md":
			return "text/markdown; charset=utf-8";
		case ".css":
			return "text/css; charset=utf-8";
		case ".js":
			return "application/javascript; charset=utf-8";
		case ".json":
			return "application/json; charset=utf-8";
		case ".svg":
			return "image/svg+xml";
		case ".png":
			return "image/png";
		case ".jpeg":
		case ".jpg":
			return "image/jpeg";
		case ".webp":
			return "image/webp";
		default:
			return "application/octet-stream";
		}
	}

	private static bool TryGetDemoStaticFile(string requestPath, out string filePath)
	{
		filePath = string.Empty;
		if (!requestPath.StartsWith("/demo/website-task/", StringComparison.OrdinalIgnoreCase))
		{
			return false;
		}
		string text = Uri.UnescapeDataString(requestPath.Substring("/demo/website-task/".Length));
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "index.html";
		}
		text = text.Replace('/', Path.DirectorySeparatorChar).TrimStart(Path.DirectorySeparatorChar);
		if (text.Contains("..", StringComparison.Ordinal))
		{
			return false;
		}
		string fullPath = Path.GetFullPath(GetDemoWebsiteTaskRoot());
		string fullPath2 = Path.GetFullPath(Path.Combine(fullPath, text));
		if (!fullPath2.StartsWith(fullPath + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) && !string.Equals(fullPath2, fullPath, StringComparison.OrdinalIgnoreCase))
		{
			return false;
		}
		filePath = fullPath2;
		return true;
	}

	private static string BuildProjectLineageContext(ProjectBoard project)
	{
		if (project == null)
		{
			return string.Empty;
		}
		List<string> list = new List<string>();
		if (_config.CompanyGoals.Count > 0)
		{
			List<string> values = _config.CompanyGoals.Select((CompanyGoal goal) => "- " + goal.Title + (string.IsNullOrWhiteSpace(goal.Description) ? string.Empty : ("：" + goal.Description))).ToList();
			list.Add("公司目标：");
			list.Add(string.Join("\n", values));
		}
		else if (!string.IsNullOrWhiteSpace(_config.CompanyProfile))
		{
			list.Add("公司目标：");
			list.Add(_config.CompanyProfile.Trim());
		}
		string text = project.ProjectGoal;
		if (string.IsNullOrWhiteSpace(text) && !string.IsNullOrWhiteSpace(project.GoalId))
		{
			CompanyGoal companyGoal = FindCompanyGoalById(project.GoalId);
			text = ((companyGoal == null) ? string.Empty : (companyGoal.Title + "：" + companyGoal.Description).TrimEnd('：'));
		}
		if (!string.IsNullOrWhiteSpace(project.ProjectName))
		{
			list.Add("项目：" + project.ProjectName);
		}
		if (!string.IsNullOrWhiteSpace(text))
		{
			list.Add("项目目标：" + text);
		}
		if (!string.IsNullOrWhiteSpace(project.ContextSummary))
		{
			list.Add("项目背景：" + project.ContextSummary);
		}
		return string.Join("\n", list.Where((string line) => !string.IsNullOrWhiteSpace(line)));
	}

	private static string BuildTaskLineageContext(ProjectTask task)
	{
		if (task == null)
		{
			return string.Empty;
		}
		List<string> list = new List<string>();
		ProjectBoard projectBoard = FindProjectContainingTask(task);
		string text = ((projectBoard == null) ? string.Empty : BuildProjectLineageContext(projectBoard));
		if (!string.IsNullOrWhiteSpace(text))
		{
			list.Add(text);
		}
		CompanyGoal companyGoal = FindCompanyGoalById((task.GoalId ?? projectBoard?.GoalId) ?? string.Empty);
		if (companyGoal != null)
		{
			list.Add("任务目标：" + companyGoal.Title + (string.IsNullOrWhiteSpace(companyGoal.Description) ? string.Empty : ("：" + companyGoal.Description)));
		}
		if (!string.IsNullOrWhiteSpace(task.ParentId))
		{
			ProjectTask projectTask = FindTaskById(task.ParentId);
			if (projectTask != null)
			{
				list.Add("父任务：" + projectTask.Title);
				if (!string.IsNullOrWhiteSpace(projectTask.ContextSummary))
				{
					list.Add("父任务上下文：" + projectTask.ContextSummary);
				}
			}
		}
		if (!string.IsNullOrWhiteSpace(task.ContextSummary))
		{
			list.Add("当前任务上下文：" + task.ContextSummary);
		}
		list.Add("当前任务：" + task.Title);
		return string.Join("\n", list.Where((string line) => !string.IsNullOrWhiteSpace(line)));
	}

	private static string BuildDefaultLineageContext()
	{
		if (_config.CompanyGoals.Count > 0)
		{
			return string.Join("\n", new string[2]
			{
				"公司目标：",
				string.Join("\n", _config.CompanyGoals.Select((CompanyGoal goal) => "- " + goal.Title + (string.IsNullOrWhiteSpace(goal.Description) ? string.Empty : ("：" + goal.Description))))
			});
		}
		if (!string.IsNullOrWhiteSpace(_config.CompanyProfile))
		{
			return "公司目标：\n" + _config.CompanyProfile.Trim();
		}
		return string.Empty;
	}

	private static decimal ComputeAgentBudgetUsage(JsonElement? profileElement, IEnumerable<JsonElement> runs)
	{
		decimal val = default(decimal);
		if (profileElement.HasValue && profileElement.Value.ValueKind == JsonValueKind.Object && profileElement.Value.TryGetProperty("budgetUsed", out var value) && value.ValueKind == JsonValueKind.Number)
		{
			val = value.GetDecimal();
		}
		decimal val2 = default(decimal);
		foreach (JsonElement item in runs ?? Enumerable.Empty<JsonElement>())
		{
			if (item.ValueKind == JsonValueKind.Object)
			{
				JsonElement value3;
				if (item.TryGetProperty("estimatedCost", out var value2) && value2.ValueKind == JsonValueKind.Number)
				{
					val2 += value2.GetDecimal();
				}
				else if (item.TryGetProperty("EstimatedCost", out value3) && value3.ValueKind == JsonValueKind.Number)
				{
					val2 += value3.GetDecimal();
				}
			}
		}
		return Math.Max(val, val2);
	}

	private static List<string> GetDirectReports(string managerName)
	{
		if (string.IsNullOrWhiteSpace(managerName))
		{
			return new List<string>();
		}
		return (from kvp in _config.PeerNodes
			where string.Equals(kvp.Value.ReportsTo, managerName, StringComparison.OrdinalIgnoreCase)
			select kvp.Key).OrderBy<string, string>((string name) => name, StringComparer.OrdinalIgnoreCase).ToList();
	}

	private static List<string> BuildChainOfCommand(string employeeName)
	{
		List<string> list = new List<string>();
		if (string.IsNullOrWhiteSpace(employeeName))
		{
			return list;
		}
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		string key = employeeName;
		NodeInfo value;
		while (_config.PeerNodes.TryGetValue(key, out value) && !string.IsNullOrWhiteSpace(value.ReportsTo))
		{
			string text = value.ReportsTo.Trim();
			if (!hashSet.Add(text))
			{
				break;
			}
			list.Add(text);
			key = text;
		}
		return list;
	}

	private static string BuildEmployeeOrgSummary(string employeeName)
	{
		if (!_config.PeerNodes.TryGetValue(employeeName, out NodeInfo value))
		{
			return string.Empty;
		}
		List<string> directReports = GetDirectReports(employeeName);
		List<string> list = BuildChainOfCommand(employeeName);
		List<string> list2 = new List<string>
		{
			"员工：" + employeeName,
			"汇报对象：" + (string.IsNullOrWhiteSpace(value.ReportsTo) ? "无" : value.ReportsTo),
			"直属下级：" + ((directReports.Count == 0) ? "无" : string.Join("、", directReports))
		};
		if (list.Count > 0)
		{
			list2.Add("组织关系：" + string.Join(" -> ", list));
		}
		return string.Join("\n", list2);
	}

	private static string SuggestDelegationTarget(string managerName, ProjectTask task)
	{
		List<string> directReports = GetDirectReports(managerName);
		if (directReports.Count == 0)
		{
			return string.Empty;
		}
		if (task != null)
		{
			if (!string.IsNullOrWhiteSpace(task.Assignee) && directReports.Contains<string>(task.Assignee, StringComparer.OrdinalIgnoreCase))
			{
				return task.Assignee;
			}
			foreach (string item in directReports)
			{
				if (_config.PeerNodes.TryGetValue(item, out NodeInfo value) && !string.IsNullOrWhiteSpace(value.Role) && task.Title.Contains(value.Role, StringComparison.OrdinalIgnoreCase))
				{
					return item;
				}
			}
		}
		return directReports[0];
	}

	private static string GetBudgetLevel(decimal used, decimal monthly, decimal softRatio, decimal hardRatio)
	{
		if (monthly <= 0m)
		{
			return "normal";
		}
		if (used >= monthly * hardRatio)
		{
			return "hard-stop";
		}
		if (used >= monthly * softRatio)
		{
			return "warning";
		}
		return "normal";
	}

	private static string RenderBudgetSummaryHtml(decimal used, decimal monthly, string budgetLevel)
	{
		decimal num = ((monthly <= 0m) ? 0m : monthly);
		decimal value = ((num <= 0m) ? 0m : (used / num * 100m));
		string text = ((budgetLevel == "hard-stop") ? "预算已耗尽" : ((!(budgetLevel == "warning")) ? "预算正常" : "预算紧张"));
		string value2 = text;
		return $"本月预算：{num:0.##} / 当前已用：{used:0.##} / 使用率：{value:0.#}% / {value2}";
	}

	private static string ReadJsonString(JsonElement source, params string[] names)
	{
		foreach (string propertyName in names)
		{
			if (source.TryGetProperty(propertyName, out var value) && value.ValueKind == JsonValueKind.String)
			{
				return value.GetString() ?? string.Empty;
			}
		}
		return string.Empty;
	}

	private static int ReadJsonInt(JsonElement source, params string[] names)
	{
		foreach (string propertyName in names)
		{
			if (source.TryGetProperty(propertyName, out var value))
			{
				if (value.ValueKind == JsonValueKind.Number && value.TryGetInt32(out var value2))
				{
					return value2;
				}
				if (value.ValueKind == JsonValueKind.String && int.TryParse(value.GetString(), out var result))
				{
					return result;
				}
			}
		}
		return 0;
	}

	private static decimal ReadJsonDecimal(JsonElement source, params string[] names)
	{
		foreach (string propertyName in names)
		{
			if (source.TryGetProperty(propertyName, out var value))
			{
				if (value.ValueKind == JsonValueKind.Number && value.TryGetDecimal(out var value2))
				{
					return value2;
				}
				if (value.ValueKind == JsonValueKind.String && decimal.TryParse(value.GetString(), out var result))
				{
					return result;
				}
			}
		}
		return 0m;
	}

	private static bool ReadJsonBool(JsonElement source, params string[] names)
	{
		foreach (string propertyName in names)
		{
			if (source.TryGetProperty(propertyName, out var value))
			{
				if (value.ValueKind == JsonValueKind.True)
				{
					return true;
				}
				if (value.ValueKind == JsonValueKind.False)
				{
					return false;
				}
				if (value.ValueKind == JsonValueKind.String && bool.TryParse(value.GetString(), out var result))
				{
					return result;
				}
			}
		}
		return false;
	}

	private static JsonElement? ReadJsonElementClone(JsonElement source, params string[] names)
	{
		foreach (string propertyName in names)
		{
			if (source.TryGetProperty(propertyName, out var value))
			{
				return value.Clone();
			}
		}
		return null;
	}

	private static List<string> ReadJsonStringArray(JsonElement source, params string[] names)
	{
		JsonElement? jsonElement = ReadJsonElementClone(source, names);
		if (!jsonElement.HasValue || jsonElement.Value.ValueKind != JsonValueKind.Array)
		{
			return new List<string>();
		}
		return (from item in jsonElement.Value.EnumerateArray()
			where item.ValueKind == JsonValueKind.String
			select item.GetString() ?? string.Empty into item
			where !string.IsNullOrWhiteSpace(item)
			select item).Distinct<string>(StringComparer.OrdinalIgnoreCase).ToList();
	}

	private static AgentHealthPayload BuildAgentHealthPayload(NodeInfo nodeInfo, string username)
	{
		AgentHeartbeatStatus value = null;
		lock (_configSyncRoot)
		{
			_config.AgentHeartbeats.TryGetValue(username, out value);
		}
		string text = value?.LastStatus;
		if (string.IsNullOrWhiteSpace(text))
		{
			text = (string.IsNullOrWhiteSpace(nodeInfo?.Url) ? "offline" : "unknown");
		}
		return new AgentHealthPayload
		{
			Status = text,
			Source = (value?.Source ?? string.Empty),
			Message = (value?.LastMessage ?? string.Empty),
			LastSeenAt = (value?.LastSeenAt ?? string.Empty)
		};
	}

	private static AgentProfilePayload NormalizeAgentProfilePayload(NodeInfo nodeInfo, string username, string upstreamJson)
	{
		using JsonDocument jsonDocument = JsonDocument.Parse(string.IsNullOrWhiteSpace(upstreamJson) ? "{}" : upstreamJson);
		JsonElement rootElement = jsonDocument.RootElement;
		List<string> list = ReadJsonStringArray(rootElement, "capabilities", "Capabilities");
		if (list.Count == 0)
		{
			list = GetNodeCapabilities(nodeInfo);
		}
		JsonElement? jsonElement = ReadJsonElementClone(rootElement, "tools", "Tools");
		JsonElement? jsonElement2 = ReadJsonElementClone(rootElement, "recentMemory", "RecentMemory");
		JsonElement? jsonElement3 = ReadJsonElementClone(rootElement, "supports", "Supports");
		JsonElement source = ((jsonElement3.HasValue && jsonElement3.Value.ValueKind == JsonValueKind.Object) ? jsonElement3.Value : default(JsonElement));
		AgentProfilePayload agentProfilePayload = new AgentProfilePayload();
		agentProfilePayload.User = (string.IsNullOrWhiteSpace(ReadJsonString(rootElement, "user", "User")) ? username : ReadJsonString(rootElement, "user", "User"));
		agentProfilePayload.AdapterType = GetAdapterType(nodeInfo);
		agentProfilePayload.Role = ReadJsonString(rootElement, "role", "Role");
		agentProfilePayload.Workspace = ReadJsonString(rootElement, "workspace", "Workspace");
		agentProfilePayload.Identity = ReadJsonString(rootElement, "identity", "Identity");
		agentProfilePayload.Capabilities = list;
		agentProfilePayload.Supports = new AgentSupportsPayload
		{
			Approvals = (jsonElement3.HasValue ? ReadJsonBool(source, "approvals", "Approvals") : SupportsApprovals(nodeInfo)),
			Runs = (jsonElement3.HasValue ? ReadJsonBool(source, "runs", "Runs") : SupportsRunDetail(nodeInfo)),
			History = (!jsonElement3.HasValue || ReadJsonBool(source, "history", "History")),
			Attachments = (jsonElement3.HasValue ? ReadJsonBool(source, "attachments", "Attachments") : SupportsAttachments(nodeInfo)),
			Vision = (jsonElement3.HasValue ? ReadJsonBool(source, "vision", "Vision") : list.Any((string item) => string.Equals(item, "vision", StringComparison.OrdinalIgnoreCase)))
		};
		agentProfilePayload.Tools = jsonElement ?? JsonSerializer.SerializeToElement(new List<JsonElement>(), AppJsonContext.Default.ListJsonElement);
		agentProfilePayload.RecentMemory = jsonElement2 ?? JsonSerializer.SerializeToElement(new List<JsonElement>(), AppJsonContext.Default.ListJsonElement);
		agentProfilePayload.BudgetMonthly = nodeInfo.BudgetMonthly.GetValueOrDefault();
		agentProfilePayload.BudgetUsed = nodeInfo.BudgetUsed.GetValueOrDefault();
		agentProfilePayload.ReportsTo = nodeInfo.ReportsTo ?? string.Empty;
		agentProfilePayload.Health = BuildAgentHealthPayload(nodeInfo, username);
		return agentProfilePayload;
	}

	private static AgentRunPayload NormalizeAgentRunPayload(NodeInfo nodeInfo, string username, string upstreamJson)
	{
		using JsonDocument jsonDocument = JsonDocument.Parse(string.IsNullOrWhiteSpace(upstreamJson) ? "{}" : upstreamJson);
		JsonElement rootElement = jsonDocument.RootElement;
		AgentRunPayload agentRunPayload = new AgentRunPayload();
		agentRunPayload.RunId = ReadJsonString(rootElement, "runId", "RunId");
		agentRunPayload.User = (string.IsNullOrWhiteSpace(ReadJsonString(rootElement, "user", "User")) ? username : ReadJsonString(rootElement, "user", "User"));
		agentRunPayload.Role = ReadJsonString(rootElement, "role", "Role");
		agentRunPayload.TaskText = ReadJsonString(rootElement, "taskText", "TaskText");
		agentRunPayload.Status = ReadJsonString(rootElement, "status", "Status");
		agentRunPayload.Origin = ReadJsonString(rootElement, "origin", "Origin");
		agentRunPayload.Workspace = ReadJsonString(rootElement, "workspace", "Workspace");
		agentRunPayload.CreatedAt = ReadJsonString(rootElement, "createdAt", "CreatedAt");
		agentRunPayload.UpdatedAt = ReadJsonString(rootElement, "updatedAt", "UpdatedAt");
		agentRunPayload.FinalContent = ReadJsonString(rootElement, "finalContent", "FinalContent");
		agentRunPayload.LastError = ReadJsonString(rootElement, "lastError", "LastError");
		agentRunPayload.Provider = ReadJsonString(rootElement, "provider", "Provider");
		agentRunPayload.Model = ReadJsonString(rootElement, "model", "Model");
		agentRunPayload.InputTokens = ReadJsonInt(rootElement, "inputTokens", "InputTokens");
		agentRunPayload.OutputTokens = ReadJsonInt(rootElement, "outputTokens", "OutputTokens");
		agentRunPayload.EstimatedCost = ReadJsonDecimal(rootElement, "estimatedCost", "EstimatedCost");
		agentRunPayload.CostCurrency = ReadJsonString(rootElement, "costCurrency", "CostCurrency");
		agentRunPayload.TaskId = ReadJsonString(rootElement, "taskId", "TaskId", "boardTaskId", "BoardTaskId");
		agentRunPayload.Steps = ReadJsonElementClone(rootElement, "steps", "Steps") ?? JsonSerializer.SerializeToElement(new List<JsonElement>(), AppJsonContext.Default.ListJsonElement);
		agentRunPayload.Artifacts = ReadJsonElementClone(rootElement, "artifacts", "Artifacts") ?? JsonSerializer.SerializeToElement(new List<JsonElement>(), AppJsonContext.Default.ListJsonElement);
		agentRunPayload.PendingApproval = ReadJsonElementClone(rootElement, "pendingApproval", "PendingApproval") ?? JsonSerializer.SerializeToElement(null, AppJsonContext.Default.String);
		agentRunPayload.AdapterType = GetAdapterType(nodeInfo);
		return agentRunPayload;
	}

	private static List<AgentRunPayload> NormalizeAgentRunsPayload(NodeInfo nodeInfo, string username, string upstreamJson)
	{
		using JsonDocument jsonDocument = JsonDocument.Parse(string.IsNullOrWhiteSpace(upstreamJson) ? "[]" : upstreamJson);
		if (jsonDocument.RootElement.ValueKind != JsonValueKind.Array)
		{
			return new List<AgentRunPayload>();
		}
		return (from run in jsonDocument.RootElement.EnumerateArray()
			select NormalizeAgentRunPayload(nodeInfo, username, run.GetRawText())).ToList();
	}

	private static void UpdateAgentHeartbeat(string employee, string status, string? message, string? source = "routine")
	{
		if (string.IsNullOrWhiteSpace(employee))
		{
			return;
		}
		string alertLevel = ((string.Equals(status, "error", StringComparison.OrdinalIgnoreCase) || string.Equals(status, "missing-worker", StringComparison.OrdinalIgnoreCase)) ? "warning" : "normal");
		lock (_configSyncRoot)
		{
			_config.AgentHeartbeats[employee] = new AgentHeartbeatStatus
			{
				Employee = employee,
				LastSeenAt = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),
				LastStatus = (string.IsNullOrWhiteSpace(status) ? "unknown" : status),
				LastMessage = message,
				Source = source,
				AlertLevel = alertLevel
			};
			SaveConfigLocked();
		}
	}

	private static string GetRoutineAlertLevel(RoutineJob routine)
	{
		if (routine == null)
		{
			return "normal";
		}
		if (routine.ConsecutiveFailures >= 3)
		{
			return "critical";
		}
		if (routine.ConsecutiveFailures >= 1)
		{
			return "warning";
		}
		return "normal";
	}

	private static List<object> BuildRoutineAlerts()
	{
		List<object> list = new List<object>();
		foreach (RoutineJob routine in _config.Routines)
		{
			string routineAlertLevel = GetRoutineAlertLevel(routine);
			if (!(routineAlertLevel == "normal"))
			{
				list.Add(new RoutineAlertPayload
				{
					Type = "routine",
					RoutineId = routine.Id,
					RoutineName = routine.Name,
					Employee = routine.Employee,
					ConsecutiveFailures = routine.ConsecutiveFailures,
					AlertLevel = routineAlertLevel,
					LastAlertAt = routine.LastAlertAt,
					Message = $"周期任务 {routine.Name} 已连续失败 {routine.ConsecutiveFailures} 次"
				});
			}
		}
		foreach (AgentHeartbeatStatus value in _config.AgentHeartbeats.Values)
		{
			if (string.Equals(value.AlertLevel, "warning", StringComparison.OrdinalIgnoreCase) || string.Equals(value.AlertLevel, "critical", StringComparison.OrdinalIgnoreCase))
			{
				list.Add(new RoutineAlertPayload
				{
					Type = "heartbeat",
					Employee = value.Employee,
					AlertLevel = (value.AlertLevel ?? "warning"),
					LastSeenAt = value.LastSeenAt,
					Message = (value.LastMessage ?? "员工心跳异常")
				});
			}
		}
		return list;
	}

	private static void RecoverRoutineState(string routineId)
	{
		if (string.IsNullOrWhiteSpace(routineId))
		{
			return;
		}
		lock (_configSyncRoot)
		{
			RoutineJob routineJob = _config.Routines.FirstOrDefault((RoutineJob item) => string.Equals(item.Id, routineId, StringComparison.OrdinalIgnoreCase));
			if (routineJob != null)
			{
				routineJob.Enabled = true;
				routineJob.ConsecutiveFailures = 0;
				routineJob.AlertLevel = "normal";
				routineJob.LastAlertAt = null;
				routineJob.NextRunAt = ComputeNextRunAt(routineJob, DateTime.Now);
				SaveConfigLocked();
			}
		}
	}

	private static void AckRoutineAlert(string routineId)
	{
		if (string.IsNullOrWhiteSpace(routineId))
		{
			return;
		}
		lock (_configSyncRoot)
		{
			RoutineJob routineJob = _config.Routines.FirstOrDefault((RoutineJob item) => string.Equals(item.Id, routineId, StringComparison.OrdinalIgnoreCase));
			if (routineJob != null)
			{
				routineJob.LastAlertAt = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
				SaveConfigLocked();
			}
		}
	}

	private static void RecordRoutineExecution(RoutineJob routine, string status, DateTime startedAt, string? summary = null, string? errorMessage = null)
	{
		if (routine == null)
		{
			return;
		}
		lock (_configSyncRoot)
		{
			RoutineJob routineJob = _config.Routines.FirstOrDefault((RoutineJob item) => string.Equals(item.Id, routine.Id, StringComparison.OrdinalIgnoreCase));
			if (routineJob != null)
			{
				if (string.Equals(status, "success", StringComparison.OrdinalIgnoreCase))
				{
					routineJob.ConsecutiveFailures = 0;
					routineJob.AlertLevel = "normal";
				}
				else
				{
					routineJob.ConsecutiveFailures++;
					routineJob.AlertLevel = GetRoutineAlertLevel(routineJob);
					routineJob.LastAlertAt = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
					int num = Math.Max(1, (routineJob.RetryBackoffMinutes <= 0) ? 10 : routineJob.RetryBackoffMinutes);
					if (routineJob.ConsecutiveFailures <= Math.Max(0, routineJob.MaxRetries))
					{
						routineJob.NextRunAt = DateTime.Now.AddMinutes(num).ToString("yyyy-MM-dd HH:mm:ss");
					}
					else
					{
						routineJob.Enabled = false;
					}
				}
				routineJob.LastRunAt = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
			}
			_config.RoutineHistory.Insert(0, new RoutineRunRecord
			{
				RoutineId = routine.Id,
				RoutineName = routine.Name,
				Employee = routine.Employee,
				StartedAt = startedAt.ToString("yyyy-MM-dd HH:mm:ss"),
				FinishedAt = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),
				Status = (string.IsNullOrWhiteSpace(status) ? "unknown" : status),
				Summary = summary,
				ErrorMessage = errorMessage
			});
			if (_config.RoutineHistory.Count > 80)
			{
				_config.RoutineHistory = _config.RoutineHistory.Take(80).ToList();
			}
			SaveConfigLocked();
		}
	}

	private static bool ShouldRunRoutine(RoutineJob routine, DateTime now)
	{
		if (routine == null || !routine.Enabled)
		{
			return false;
		}
		RoutineTrigger trigger = routine.Trigger;
		if (trigger == null || trigger.TriggerKind?.Equals("schedule", StringComparison.OrdinalIgnoreCase) != true)
		{
			return false;
		}
		if (string.IsNullOrWhiteSpace(routine.NextRunAt))
		{
			return false;
		}
		if (DateTime.TryParse(routine.NextRunAt, out var result))
		{
			return result <= now;
		}
		return false;
	}

	private static string ComputeNextRunAt(RoutineJob routine, DateTime now)
	{
		int valueOrDefault = (routine?.Trigger?.IntervalMinutes).GetValueOrDefault();
		if (valueOrDefault <= 0)
		{
			return now.AddMinutes(5.0).ToString("yyyy-MM-dd HH:mm:ss");
		}
		return now.AddMinutes(valueOrDefault).ToString("yyyy-MM-dd HH:mm:ss");
	}

	private static Task ExecuteRoutineAsync(RoutineJob routine)
	{
		return Task.Run(async delegate
		{
			if (routine == null || string.IsNullOrWhiteSpace(routine.Employee) || string.IsNullOrWhiteSpace(routine.Prompt))
			{
				return;
			}
			DateTime startedAt = DateTime.Now;
			UpdateAgentHeartbeat(routine.Employee, "running", "正在执行周期任务：" + routine.Name);
			await _routineRunLock.WaitAsync();
			try
			{
				NodeInfo nodeInfo;
				lock (_configSyncRoot)
				{
					nodeInfo = (_config.PeerNodes.TryGetValue(routine.Employee, out NodeInfo value) ? value : null);
				}
				if (nodeInfo == null || string.IsNullOrWhiteSpace(nodeInfo.Url))
				{
					UpdateAgentHeartbeat(routine.Employee, "missing-worker", "没有找到可执行该任务的员工节点。");
					RecordRoutineExecution(routine, "failed", startedAt, null, "没有找到可执行该任务的员工节点。");
				}
				else
				{
					ChatRequest value2 = new ChatRequest
					{
						message = routine.Prompt,
						modelIndex = nodeInfo.ModelIndex,
						sop = _config.CompanySOP,
						caller = "routine"
					};
					using HttpRequestMessage proxyReq = new HttpRequestMessage(HttpMethod.Post, nodeInfo.Url.TrimEnd('/') + "/api/chat");
					proxyReq.Headers.Add("X-Username", Uri.EscapeDataString(routine.Employee));
					ApplyAccountHeaders(proxyReq);
					proxyReq.Headers.Add("X-Adapter-Type", Uri.EscapeDataString(GetAdapterType(nodeInfo)));
					proxyReq.Content = new StringContent(JsonSerializer.Serialize(value2, typeof(ChatRequest), AppJsonContext.Default), Encoding.UTF8, "application/json");
					using HttpResponseMessage proxyRes = await _httpClient.SendAsync(proxyReq);
					string text = await proxyRes.Content.ReadAsStringAsync();
					proxyRes.EnsureSuccessStatusCode();
					string text2 = (string.IsNullOrWhiteSpace(text) ? (routine.Employee + " 已执行 " + routine.Name) : text.Trim());
					if (text2.Length > 280)
					{
						text2 = text2.Substring(0, 280);
					}
					UpdateAgentHeartbeat(routine.Employee, "healthy", "最近完成周期任务：" + routine.Name);
					RecordRoutineExecution(routine, "success", startedAt, text2);
				}
			}
			catch (Exception ex)
			{
				UpdateAgentHeartbeat(routine.Employee, "error", ex.Message);
				RecordRoutineExecution(routine, "failed", startedAt, null, ex.Message);
				throw;
			}
			finally
			{
				_routineRunLock.Release();
			}
		});
	}

	private static Task StartRoutineSchedulerAsync(CancellationToken cancellationToken)
	{
		return Task.Run(async delegate
		{
			while (!cancellationToken.IsCancellationRequested)
			{
				DateTime now = DateTime.Now;
				List<RoutineJob> list;
				lock (_configSyncRoot)
				{
					list = _config.Routines.Where((RoutineJob routine2) => ShouldRunRoutine(routine2, now)).ToList();
				}
				foreach (RoutineJob routine in list)
				{
					try
					{
						await ExecuteRoutineAsync(routine);
					}
					catch (Exception ex)
					{
						Console.WriteLine("[Routine] " + routine.Name + " 执行失败：" + ex.Message);
					}
					lock (_configSyncRoot)
					{
						RoutineJob routineJob = _config.Routines.FirstOrDefault((RoutineJob item) => string.Equals(item.Id, routine.Id, StringComparison.OrdinalIgnoreCase));
						if (routineJob != null && routineJob.ConsecutiveFailures == 0)
						{
							routineJob.LastRunAt = now.ToString("yyyy-MM-dd HH:mm:ss");
							routineJob.NextRunAt = ComputeNextRunAt(routineJob, now);
							SaveConfigLocked();
						}
					}
				}
				await Task.Delay(TimeSpan.FromSeconds(5L), cancellationToken);
			}
		}, cancellationToken);
	}

