	private static List<string> ResolveTeamListenerUrls()
	{
		string text = Environment.GetEnvironmentVariable("NiumaClaw_TEAM_URLS")?.Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			text = Environment.GetEnvironmentVariable("NiumaClaw_TEAM_URL")?.Trim();
		}
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "http://localhost:4050/";
		}
		return (from url in text.Split(new char[2] { ';', ',' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
			select (!url.EndsWith('/')) ? (url + "/") : url).Distinct<string>(StringComparer.OrdinalIgnoreCase).ToList();
	}

	private static IEnumerable<string> BuildTeamAccessUrls(IEnumerable<string> listenerUrls)
	{
		List<int> list = listenerUrls.Select((string url) => (!Uri.TryCreate(url.Replace("*", "localhost").Replace("+", "localhost"), UriKind.Absolute, out Uri result)) ? 4050 : result.Port).DefaultIfEmpty(4050).Distinct()
			.ToList();
		List<string> ips = (from address in Dns.GetHostEntry(Dns.GetHostName()).AddressList
			where address.AddressFamily == AddressFamily.InterNetwork
			where !IPAddress.IsLoopback(address)
			select address.ToString()).Distinct<string>(StringComparer.OrdinalIgnoreCase).ToList();
		foreach (int port in list)
		{
			yield return $"本机访问：http://localhost:{port}/";
			foreach (string item in ips)
			{
				yield return $"同网络同事访问：http://{item}:{port}/";
			}
		}
	}

	private static string ExtractFirstBalancedJsonObject(string raw)
	{
		if (string.IsNullOrWhiteSpace(raw))
		{
			return string.Empty;
		}
		string text = raw.Replace("```json", string.Empty).Replace("```", string.Empty);
		int num = text.IndexOf('{');
		if (num < 0)
		{
			return string.Empty;
		}
		int num2 = 0;
		bool flag = false;
		bool flag2 = false;
		for (int i = num; i < text.Length; i++)
		{
			char c = text[i];
			if (flag2)
			{
				flag2 = false;
				continue;
			}
			switch (c)
			{
			case '\\':
				flag2 = true;
				continue;
			case '"':
				flag = !flag;
				continue;
			}
			if (flag)
			{
				continue;
			}
			switch (c)
			{
			case '{':
				num2++;
				break;
			case '}':
				num2--;
				if (num2 == 0)
				{
					return text.Substring(num, i - num + 1).Trim();
				}
				break;
			}
		}
		return string.Empty;
	}

	private static CreateCompanyReq? ParseCreateCompanyRequestBody(string body)
	{
		if (string.IsNullOrWhiteSpace(body))
		{
			return null;
		}
		string text = body.Trim();
		if (text.StartsWith("{"))
		{
			try
			{
				return JsonSerializer.Deserialize(text, typeof(CreateCompanyReq), AppJsonContext.Default) as CreateCompanyReq;
			}
			catch
			{
				Match match = Regex.Match(text, "[\"\\']?description[\"\\']?\\s*[:=]\\s*(?:([\"\\'])(?<value>.*?)\\1|(?<value>[^,}]+))", RegexOptions.IgnoreCase | RegexOptions.Singleline);
				Match match2 = Regex.Match(text, "[\"\\']?masterNodeUrl[\"\\']?\\s*[:=]\\s*(?:([\"\\'])(?<value>.*?)\\1|(?<value>[^,}]+))", RegexOptions.IgnoreCase | RegexOptions.Singleline);
				if (!match.Success && !match2.Success)
				{
					throw;
				}
				return new CreateCompanyReq
				{
					Description = (match.Success ? match.Groups["value"].Value.Trim() : null),
					MasterNodeUrl = (match2.Success ? match2.Groups["value"].Value.Trim() : null)
				};
			}
		}
		NameValueCollection nameValueCollection = HttpUtility.ParseQueryString(text);
		string text2 = nameValueCollection["description"];
		string text3 = nameValueCollection["masterNodeUrl"] ?? nameValueCollection["master_node_url"];
		if (string.IsNullOrWhiteSpace(text2) && string.IsNullOrWhiteSpace(text3))
		{
			return null;
		}
		return new CreateCompanyReq
		{
			Description = text2,
			MasterNodeUrl = text3
		};
	}

	private static string GetWorkspaceRootPath()
	{
		InlineArray5<string> buffer = default(InlineArray5<string>);
		buffer[0] = AppContext.BaseDirectory;
		buffer[1] = "..";
		buffer[2] = "..";
		buffer[3] = "..";
		buffer[4] = "..";
		string fullPath = Path.GetFullPath(Path.Combine(buffer));
		if (!Directory.Exists(fullPath))
		{
			return Directory.GetCurrentDirectory();
		}
		return fullPath;
	}

	private static string NormalizeLocalPath(string rawPath)
	{
		string text = (rawPath ?? string.Empty).Trim().Trim('"');
		if (string.IsNullOrWhiteSpace(text))
		{
			return string.Empty;
		}
		if (text.StartsWith("a/") || text.StartsWith("b/"))
		{
			text = text.Substring(2);
		}
		if (text.StartsWith("./"))
		{
			text = text.Substring(2);
		}
		if (Regex.IsMatch(text, "^/mnt/[a-zA-Z]/"))
		{
			char value = char.ToUpperInvariant(text[5]);
			string text2 = text.Substring(6).Replace('/', '\\');
			return $"{value}:\\{text2.TrimStart('\\')}";
		}
		if (Path.IsPathRooted(text) || text.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || text.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
		{
			return text;
		}
		return Path.GetFullPath(Path.Combine(GetWorkspaceRootPath(), text));
	}

	private static void OpenPathOnHost(string action, string rawPath)
	{
		string text = NormalizeLocalPath(rawPath);
		if (string.IsNullOrWhiteSpace(text))
		{
			throw new InvalidOperationException("路径为空");
		}
		if (text.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || text.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
		{
			Process.Start(new ProcessStartInfo(text)
			{
				UseShellExecute = true
			});
		}
		else if (action == "reveal")
		{
			if (File.Exists(text))
			{
				Process.Start(new ProcessStartInfo("explorer.exe", "/select,\"" + text + "\"")
				{
					UseShellExecute = true
				});
				return;
			}
			string text2 = (Directory.Exists(text) ? text : Path.GetDirectoryName(text));
			if (string.IsNullOrWhiteSpace(text2))
			{
				throw new FileNotFoundException("无法定位路径：" + text);
			}
			Process.Start(new ProcessStartInfo("explorer.exe", "\"" + text2 + "\"")
			{
				UseShellExecute = true
			});
		}
		else
		{
			if (!File.Exists(text) && !Directory.Exists(text))
			{
				throw new FileNotFoundException("路径不存在：" + text);
			}
			Process.Start(new ProcessStartInfo(text)
			{
				UseShellExecute = true
			});
		}
	}

	private static async Task SyncPeerNodesToMasterAsync()
	{
		if (IsDatabaseMode)
		{
			return;
		}
		string targetUrl = (string.IsNullOrEmpty(_config.MasterNodeUrl) ? "http://127.0.0.1:5050" : _config.MasterNodeUrl);
		try
		{
			HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Get, targetUrl.TrimEnd('/') + "/api/config");
			using HttpResponseMessage getRes = await _httpClient.SendAsync(request);
			if (!getRes.IsSuccessStatusCode)
			{
				return;
			}
			Dictionary<string, JsonElement> dictionary = JsonSerializer.Deserialize(await getRes.Content.ReadAsStringAsync(), AppJsonContext.Default.DictionaryStringJsonElement) ?? new Dictionary<string, JsonElement>();
			dictionary["PeerNodes"] = JsonSerializer.SerializeToElement(_config.PeerNodes, AppJsonContext.Default.DictionaryStringNodeInfo);
			HttpRequestMessage httpRequestMessage = new HttpRequestMessage(HttpMethod.Post, targetUrl.TrimEnd('/') + "/api/config");
			httpRequestMessage.Content = new StringContent(JsonSerializer.Serialize(dictionary, AppJsonContext.Default.DictionaryStringJsonElement), Encoding.UTF8, "application/json");
			using (await _httpClient.SendAsync(httpRequestMessage))
			{
				Console.WriteLine($"[节点同步] 已向 {_config.PeerNodes.Count} 个子节点同步主节点配置：{targetUrl}");
			}
		}
		catch (Exception ex)
		{
			Console.WriteLine("[节点同步失败] 无法将主节点配置同步到 " + targetUrl + "：" + ex.Message);
		}
	}

	private static async Task RelayProxyResponseAsync(HttpListenerResponse res, HttpResponseMessage proxyRes, string fallbackContentType = "application/json; charset=utf-8")
	{
		res.StatusCode = (int)proxyRes.StatusCode;
		res.ContentType = proxyRes.Content.Headers.ContentType?.ToString() ?? fallbackContentType;
		using Stream proxyStream = await proxyRes.Content.ReadAsStreamAsync();
		await proxyStream.CopyToAsync(res.OutputStream);
	}

	private static async Task HandleRequestAsync(HttpListenerContext context)
	{
		if (!IsDatabaseMode)
		{
			HttpListenerRequest request = context.Request;
			HttpListenerResponse legacyRes = context.Response;
			string text = request.Url?.AbsolutePath.ToLowerInvariant() ?? "/";
			if (text == "/api/auth/me" && (request.HttpMethod == "GET" || request.HttpMethod == "HEAD"))
			{
				if (request.HttpMethod == "HEAD")
				{
					legacyRes.StatusCode = 200;
					legacyRes.Close();
				}
				else
				{
					await WriteJsonAsync(legacyRes, "{\"authenticated\":false,\"databaseConfigured\":false,\"error\":\"database_not_configured\"}");
					legacyRes.Close();
				}
			}
			else if (text.StartsWith("/api/auth/", StringComparison.OrdinalIgnoreCase) || text.StartsWith("/api/account/", StringComparison.OrdinalIgnoreCase))
			{
				await WriteJsonAsync(legacyRes, "{\"error\":\"database_not_configured\",\"message\":\"Set NIUMACLAW_DATABASE_URL to enable account login.\"}", 503);
				legacyRes.Close();
			}
			else if (text == "/admin" || text == "/admin/")
			{
				await WriteAdminHtmlAsync(legacyRes);
				legacyRes.Close();
			}
			else
			{
				await HandleRequestCoreAsync(context);
			}
			return;
		}
		HttpListenerRequest req = context.Request;
		HttpListenerResponse res = context.Response;
		string path = req.Url?.AbsolutePath.ToLowerInvariant() ?? "/";
		try
		{
			if (path.StartsWith("/api/auth/", StringComparison.OrdinalIgnoreCase))
			{
				await HandleAuthEndpointAsync(context);
				res.Close();
				return;
			}
			if (path.StartsWith("/api/agent-nodes", StringComparison.OrdinalIgnoreCase) || path.StartsWith("/api/agent-jobs", StringComparison.OrdinalIgnoreCase))
			{
				await HandleAgentNodeEndpointAsync(context);
				res.Close();
				return;
			}
			if (path == "/admin" || path == "/admin/" || path.StartsWith("/admin-node/", StringComparison.OrdinalIgnoreCase) || path == "/admin-node")
			{
				AccountContext accountContext = await GetAccountFromRequestAsync(req);
				if (accountContext == null)
				{
					res.StatusCode = 302;
					res.RedirectLocation = "/";
					res.Close();
					return;
				}
				if (!(path == "/admin") && !(path == "/admin/"))
				{
					await HandleLocalNodeAdminProxyAsync(context, accountContext);
				}
				else
				{
					await HandleLocalNodeAdminPageAsync(context, accountContext);
				}
				res.Close();
				return;
			}
			if (path.StartsWith("/api/account/", StringComparison.OrdinalIgnoreCase))
			{
				AccountContext account = await GetAccountFromRequestAsync(req);
				if (account == null)
				{
					await WriteUnauthorizedAsync(res);
					return;
				}
				if (!path.Equals("/api/account/admin/config", StringComparison.OrdinalIgnoreCase) || !string.Equals(req.HttpMethod, "POST", StringComparison.OrdinalIgnoreCase))
				{
					await HandleAccountEndpointAsync(context, account);
				}
				else
				{
					await _accountRequestGate.WaitAsync();
					try
					{
						_currentAccount.Value = account;
						AccountContext accountContext2 = account;
						accountContext2.LocalNodeModelsHeader = await BuildLocalNodeModelsHeaderAsync(account.AccountId);
						await HandleAccountEndpointAsync(context, account);
					}
					finally
					{
						_currentAccount.Value = null;
						_accountRequestGate.Release();
					}
				}
				res.Close();
				return;
			}
			if (path.StartsWith("/api/", StringComparison.OrdinalIgnoreCase))
			{
				AccountContext account = await GetAccountFromRequestAsync(req);
				if (account == null && path.Equals("/api/board", StringComparison.OrdinalIgnoreCase) && string.Equals(req.HttpMethod, "POST", StringComparison.OrdinalIgnoreCase))
				{
					account = await GetAccountFromSignedCallbackAsync(req);
				}
				if (account == null)
				{
					await WriteUnauthorizedAsync(res);
					return;
				}
				await _accountRequestGate.WaitAsync();
				try
				{
					_currentAccount.Value = account;
					AccountContext accountContext2 = account;
					accountContext2.LocalNodeModelsHeader = await BuildLocalNodeModelsHeaderAsync(account.AccountId);
					lock (_configSyncRoot)
					{
						_config = LoadAccountConfigAsync(account.AccountId).GetAwaiter().GetResult();
					}
					await HandleRequestCoreAsync(context);
					if (IsMutatingRequest(req.HttpMethod))
					{
						lock (_configSyncRoot)
						{
							SaveAccountConfigAsync(account.AccountId, _config).GetAwaiter().GetResult();
							return;
						}
					}
					return;
				}
				finally
				{
					_currentAccount.Value = null;
					_accountRequestGate.Release();
				}
			}
			await HandleRequestCoreAsync(context);
		}
		catch (Exception ex)
		{
			if (IsClientDisconnectException(ex))
			{
				Console.WriteLine($"[client disconnected] {req.HttpMethod} {req.Url?.AbsolutePath}: {ex.Message}");
				return;
			}
			if (res.OutputStream.CanWrite)
			{
				res.StatusCode = 500;
				res.ContentType = "application/json; charset=utf-8";
				await res.OutputStream.WriteAsync(Encoding.UTF8.GetBytes("{\"error\":" + JsonSerializer.Serialize(ex.Message, AppJsonContext.Default.String) + "}"));
				res.OutputStream.Close();
			}
		}
	}

	private static bool IsMutatingRequest(string? method)
	{
		switch (method)
		{
		case "POST":
		case "PUT":
		case "PATCH":
		case "DELETE":
			return true;
		default:
			return false;
		}
	}

	private static bool RequestAcceptsGzip(HttpListenerRequest req)
	{
		string? acceptEncoding = req.Headers["Accept-Encoding"];
		return !string.IsNullOrWhiteSpace(acceptEncoding)
			&& acceptEncoding.Split(',').Any((string item) => item.Trim().StartsWith("gzip", StringComparison.OrdinalIgnoreCase));
	}

	private static byte[] GzipBytes(byte[] bytes)
	{
		using MemoryStream memoryStream = new MemoryStream();
		using (GZipStream gzipStream = new GZipStream(memoryStream, CompressionLevel.Optimal, leaveOpen: true))
		{
			gzipStream.Write(bytes, 0, bytes.Length);
		}
		return memoryStream.ToArray();
	}

	private static async Task WriteResponseBytesAsync(HttpListenerRequest req, HttpListenerResponse res, byte[] bytes, bool allowGzip = true)
	{
		byte[] payload = bytes;
		if (allowGzip && bytes.Length >= 1024 && RequestAcceptsGzip(req))
		{
			payload = GzipBytes(bytes);
			res.Headers["Content-Encoding"] = "gzip";
			res.Headers["Vary"] = "Accept-Encoding";
		}
		res.ContentLength64 = payload.Length;
		await res.OutputStream.WriteAsync(payload);
	}

	private static async Task<bool> TryServeGeneratedDesktopDownloadAsync(HttpListenerRequest req, HttpListenerResponse res, string requestPath)
	{
		const string Prefix = "/generated-downloads/";
		if (!requestPath.StartsWith(Prefix, StringComparison.OrdinalIgnoreCase))
		{
			return false;
		}
		string relativePath = Uri.UnescapeDataString(requestPath[Prefix.Length..]).Replace('\\', '/');
		string[] pathParts = relativePath.Split('/');
		if (pathParts.Length < 2 || pathParts.Any(part => string.IsNullOrWhiteSpace(part) || part == "." || part == ".."))
		{
			res.StatusCode = 404;
			return true;
		}
		string root = Path.GetFullPath(GetGeneratedDesktopDownloadRoot());
		string filePath = Path.GetFullPath(Path.Combine(root, Path.Combine(pathParts)));
		string rootPrefix = root.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar;
		if (!filePath.StartsWith(rootPrefix, StringComparison.Ordinal) || !File.Exists(filePath))
		{
			res.StatusCode = 404;
			return true;
		}
		FileInfo fileInfo = new FileInfo(filePath);
		res.ContentType = Path.GetExtension(filePath).ToLowerInvariant() switch
		{
			".dmg" => "application/x-apple-diskimage",
			".exe" => "application/vnd.microsoft.portable-executable",
			_ => "application/octet-stream"
		};
		res.Headers["Cache-Control"] = "no-store, no-cache, max-age=0";
		res.Headers["Content-Disposition"] = $"attachment; filename=\"{SafeDownloadFileName(fileInfo.Name)}\"";
		res.ContentLength64 = fileInfo.Length;
		if (string.Equals(req.HttpMethod, "HEAD", StringComparison.OrdinalIgnoreCase))
		{
			return true;
		}
		using FileStream fileStream = File.OpenRead(filePath);
		await fileStream.CopyToAsync(res.OutputStream);
		return true;
	}

