   padding: 8px 14px;\n            font-size: 8px;\n            font-weight: 800;\n            color: #475569;\n            max-width: 90%;\n            z-index: 100;\n            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08);\n            animation: bubbleFloat 3s ease-in-out infinite;\n            transition: all 0.3s ease;\n\n\n            white-space: nowrap; \n            display: -webkit-box;\n            -webkit-line-clamp: 4;\n            -webkit-box-orient: vertical;\n            text-align: left;\n            line-height: 1.4;\n            overflow: hidden;\n        }\n\n        .chat-bubble.compact-status-bubble {\n            max-width: 78%;\n            min-height: 32px;\n            padding: 7px 12px;\n            font-size: 11px;\n            line-height: 1.35;\n        }\n\n        .chat-bubble::after {\n            content: '';\n            position: absolute;\n            bottom: -6px;\n            left: 50%;\n            transform: translateX(-50%);\n            border-width: 6px 6px 0;\n            border-style: solid;\n            border-color: rgba(255, 255, 255, 0.95) transparent transparent;\n            transition: border-color 0.3s ease;\n        }\n\n\n        .chat-bubble.thinking {\n            background: linear-gradient(135deg, #f0f4ff, #e6edfa);\n            color: #3b82f6; \n            border: 1px solid #dbeafe;\n            box-shadow: 0 6px 16px rgba(59, 130, 246, 0.15);\n            animation: bubblePulse 1s infinite alternate;\n        }\n        .chat-bubble.thinking::after {\n            border-color: #e6edfa transparent transparent;\n        }\n\n\n        .chat-bubble.done {\n            background: linear-gradient(135deg, #fdfbf7, #fff8f1);\n            color: #f59e0b;\n            border: 1px solid #fef3c7;\n            box-shadow: 0 6px 16px rgba(245, 158, 11, 0.15);\n            cursor: pointer;\n        }\n        .chat-bubble.done::after {\n            border-color: #fff8f1 transparent transparent;\n        }\n\n        @