   }\n        .role-scroll-wrapper {\n            width: 100%;\n            overflow: hidden;\n            white-space: nowrap;\n            box-sizing: border-box;\n            container-type: inline-size;\n        }\n        @keyframes marqueeScroll {\n            0% {\n                transform: translateX(0);\n            }\n            100% {\n                transform: translateX(-100%);\n            }\n        }\n        .company-card.at-work .shrimp-desk-img {\n            display: block;\n        }\n\n        .company-card.at-work .empty-desk-img {\n            display: none;\n        }\n\n        .company-card.away .shrimp-desk-img {\n            display: none;\n        }\n\n        .company-card.away .empty-desk-img {\n            display: block;\n        }\n\n        .company-card.empty-desk .shrimp-desk-img {\n            display: none;\n        }\n\n        .company-card.empty-desk .empty-desk-img {\n            display: block;\n        }\n\n        .away .id-card-area,\n        .empty-desk .id-card-area,\n        .away .chat-bubble,\n        .empty-desk .chat-bubble {\n            display: none;\n        }\n        @keyframes bubbleFloat {\n            0%, 100% { transform: translate(-50%, 0); }\n            50% { transform: translate(-50%, -5px); }\n        }\n\n        .chat-bubble.thinking {\n            background: #e0f7fa;\n            color: #006064;\n            box-shadow: 0 4px 15px rgba(0, 172, 193, 0.2);\n            animation: bubblePulse 1s infinite alternate;\n        }\n        .chat-bubble.thinking::after {\n            border-color: #e0f7fa transparent transparent;\n        }\n        @keyframes bubblePulse {\n            0% { transform: translate(-50%, 0) scale(1); box-shadow: 0 0 5px rgba(0,172,193,0.2); }\n            100% { transform: translate(-50%, -4px) scale(1.05); box-shadow: 0 0 15px rgba(0,172,193,0.5); }\n        }\n\n        .chat-bubble.done {\n            background: #fff3e0;\n            color: #e65100;\n            cursor: pointer;\n            box-shadow: 0 4px 15px rgba(255, 152, 0, 0.2);\n            display: flex;\n            align-items: center;\n            gap: 6px; \n        }\n        .chat-bubble.done::after {\n            border-color: #fff3e0 transparent transparent;\n        }\n        .desk-alert-warning {\n            box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.35), 0 18px 38px rgba(245, 158, 11, 0.18);\n            border-radius: 24px;\n        }\n        .desk-alert-critical {\n            box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.45), 0 22px 45px rgba(220, 38, 38, 0.22);\n            border-radius: 24px;\n        }\n        .desk-alert-bubble {\n            background: linear-gradient(135deg, #fef2f2, #fee2e2) !important;\n            color: #b91c1c !important;\n            border: 1px solid #fecaca !important;\n            box-shadow: 0 10px 24px rgba(220, 38, 38, 0.22) !important;\n            animation: blink 1s infinite;\n        }\n        .desk-alert-bubble::after {\n            border-color: #fee2e2 transparent transparent !important;\n        }\n        .chat-bubble.done:hover {\n            background: #ffe0b2;\n            transform: translate(-50%, -2px) scale(1.05);\n        }\n        .chat-bubble.done::before {\n            content: '';\n            display: block;\n            width: 8px;\n            height: 8px;\n            background: #f44336;\n            border-radius: 50%;\n            box-shadow: 0 0 4px rgba(244,67,54,0.6);\n            animation: blink 1s infinite;\n            flex-shrink: 0;\n        }\n        @keyframes blink { 50% { opacity: 0.4; } }\n\n        .report-badge {\n            display: block !important;\n            position: absolute;\n            bottom: 7%;\n            right: 8px;\n            z-index: 20;\n            background: #e3f2fd;\n            color: #1976d2;\n            border: 1px solid #bbdefb;\n            padding: 3px 8px;\n            border-radius: 12px;\n            font-size: 10px;\n            font-weight: bold;\n            cursor: pointer;\n            transition: all 0.2s ease;\n            pointer-events: auto;\n            box-shadow: 0 2px 5px rgba(0,0,0,0.15);\n        }\n        .report-badge:hover {\n            background: #bbdefb;\n            transform: scale(1.05);\n        }\n\n\n        #reportModal {\n            display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.6);\n            z-index: 10050;\n            align-items: center; justify-content: center; backdrop-filter: blur(5px);\n        }\n\n\n        .report-content {\n            background: #fff; \n            width: 96%;\n            height: 96vh;\n            max-width: 1200px;\n            border-radius: 12px; \n            display: flex; \n            flex-direction: column; \n            overflow: hidden;\n            box-shadow: 0 10px 30px rgba(0,0,0,0.3);\n        }\n\n\n        @media (min-width: 768px) {\n            .id-card-area {\n                bottom: 28%;\n            }\n            .id-card-name {\n                font-size: clamp(8px, 1.2vw, 8px);\n            }\n            .id-card-role {\n                font-size: clamp(6px, 1vw, 8px);\n            }\n        }\n        .report-header {\n            padding: 15px 20px; background: #f8f9fa; border-bottom: 1px solid #eee;\n            display: flex; justify-content: space-between; align-items: center;\n        }\n        .report-body {\n            padding: 20px; overflow-y: auto; flex: 1; font-family: sans-serif; line-height: 1.6; color: #333;\n        }\n        .report-body pre { background: #282c34; color: #abb2bf; padding: 12px; border-radius: 6px; overflow-x: auto; }\n        .report-body code { font-family: Consolas, monospace; }\n        .report-body table { border-collapse: collapse; width: 100%; margin-bottom: 1em; }\n        .report-body th, .report-body td { border: 1px solid #ddd; padding: 8px; }\n        .report-body th { background-color: #f2f2f2; }\n        .worklog-thread { display:flex; flex-direction:column; gap:16px; }\n        .worklog-message { display:flex; flex-direction:column; gap:8px; max-width: 88%; }\n        .worklog-message.user { align-self:flex-end; }\n        .worklog-message.assistant, .worklog-message.system { align-self:flex-start; }\n        .worklog-meta { font-size:12px; color:#64748b; display:flex; align-items:center; gap:8px; }\n        .worklog-role { font-weight:700; color:#334155; }\n        .worklog-bubble { border-radius:18px; padding:14px 16px; box-shadow:0 8px 24px rgba(15,23,42,0.08); border:1px solid #e2e8f0; background:#fff; }\n        .worklog-message.user .worklog-bubble { background:linear-gradient(135deg, #dbeafe, #eff6ff); border-color:#bfdbfe; }\n        .worklog-message.assistant .worklog-bubble { background:linear-gradient(135deg, #ffffff, #f8fafc); }\n        .worklog-message.system .worklog-bubble { background:linear-gradient(135deg, #f8fafc, #f1f5f9); }\n        .worklog-bubble blockquote { margin:0; padding-left:12px; border-left:3px solid #cbd5e1; color:#475569; }\n        .worklog-bubble > *:first-child { margin-top:0; }\n        .worklog-bubble > *:last-child { margin-bottom:0; }\n        .worklog-tabs { margin-top:10px; }\n        .worklog-run-summary { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:10px; }\n        .worklog-run-chip { border-radius:999px; padding:4px 10px; background:#e2e8f0; color:#334155; font-size:12px; }\n        .worklog-tab-buttons { display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px; }\n        .worklog-tab-btn { border:none; border-radius:999px; padding:6px 12px; background:#e2e8f0; color:#334155; cursor:pointer; font-size:12px; }\n        .worklog-tab-btn.active { background:#2563eb; color:#fff; }\n        .worklog-tab-panel { display:none; }\n        .worklog-tab-panel.active { display:block; }\n        .worklog-result-panel, .worklog-process-panel { display:flex; flex-direction:column; gap:12px; }\n        .worklog-live-status { border-radius:14px; border:1px solid #bfdbfe; background:linear-gradient(135deg, #eff6ff, #dbeafe); padding:12px; box-shadow:0 10px 30px rgba(37,99,235,0.08); }\n        .worklog-live-status-head { display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:8px; }\n        .worklog-live-status-title { font-size:13px; font-weight:800; color:#1d4ed8; }\n        .worklog-live-status-subtitle { font-size:12px; color:#334155; white-space:pre-wrap; }\n        .worklog-live-chip-row { display:flex; flex-wrap:wrap; gap:8px; margin-top:8px; }\n        .worklog-process-layout { display:grid; grid-template-columns:minmax(0, 1.4fr) minmax(260px, 0.8fr); gap:12px; align-items:start; }\n        .worklog-main-column, .worklog-side-column { display:flex; flex-direction:column; gap:12px; min-width:0; }\n        .worklog-plan-card, .worklog-file-change-panel, .worklog-tool-trace, .worklog-result-actions { border-radius:14px; border:1px solid #dbeafe; background:linear-gradient(135deg, #ffffff, #f8fafc); padding:12px; }\n        .worklog-plan-list { display:flex; flex-direction:column; gap:8px; }\n        .worklog-plan-item { display:flex; align-items:flex-start; gap:10px; padding:8px 10px; border-radius:12px; background:#f8fafc; border:1px solid #e2e8f0; }\n        .worklog-plan-item.current { border-color:#60a5fa; background:#eff6ff; box-shadow:0 0 0 2px rgba(96,165,250,0.16); }\n        .worklog-plan-item.done { border-color:#86efac; background:#f0fdf4; }\n        .worklog-plan-badge { width:20px; height:20px; border-radius:999px; display:inline-flex; align-items:center; justify-content:center; font-size:11px; font-weight:800; background:#cbd5e1; color:#334155; flex:0 0 auto; }\n        .worklog-plan-item.current .worklog-plan-badge { background:#2563eb; color:#fff; }\n        .worklog-plan-item.done .worklog-plan-badge { background:#16a34a; color:#fff; }\n        .worklog-file-change-list { display:flex; flex-direction:column; gap:10px; }\n        .worklog-file-change-item { border-radius:12px; border:1px solid #dbeafe; background:#eff6ff; padding:10px; }\n        .worklog-result-actions { display:flex; flex-wrap:wrap; gap:8px; }\n        .worklog-result-action-btn { border:none; border-radius:999px; padding:6px 12px; cursor:pointer; font-size:12px; font-weight:800; color:#fff; background:#2563eb; }\n        .worklog-result-action-btn.secondary { background:#7c3aed; }\n        .worklog-result-action-btn.ghost { background:#0f766e; }\n        .worklog-tool-trace-list { display:flex; flex-direction:column; gap:8px; }\n        .worklog-tool-trace-item { border-radius:12px; border:1px solid #e2e8f0; background:#f8fafc; padding:8px 10px; }\n        .worklog-stream-groups { display:flex; flex-direction:column; gap:10px; }\n        .worklog-stream-tab-bar { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:10px; }\n        .worklog-stream-tab-btn { border:none; border-radius:999px; padding:5px 10px; cursor:pointer; background:#e2e8f0; color:#334155; font-size:11px; font-weight:800; }\n        .worklog-stream-tab-btn.active { background:#2563eb; color:#fff; }\n        .worklog-stream-group { border-radius:14px; border:1px solid #dbeafe; background:linear-gradient(135deg, #ffffff, #f8fafc); overflow:hidden; position:relative; }\n        .worklog-stream-group.hidden-stream-tab { display:none; }\n        .worklog-stream-step.entering { animation: streamStepEnter 0.45s ease-out; } /* worklog-stream-step.entering */\n        .worklog-step-trace-line { position:absolute; left:18px; top:44px; bottom:14px; width:3px; border-radius:999px; background:linear-gradient(180deg, rgba(148,163,184,0.18), rgba(59,130,246,0.36), rgba(148,163,184,0.18)); }\n        .worklog-stream-group.current-group .worklog-step-trace-line { background:linear-gradient(180deg, rgba(96,165,250,0.32), rgba(37,99,235,0.9), rgba(96,165,250,0.32)); animation: currentStepTracePulse 1.5s ease-in-out infinite; }\n        .worklog-stream-group-header { display:flex; justify-content:space-between; align-items:center; gap:8px; padding:10px 12px; border-bottom:1px solid #dbeafe; background:linear-gradient(135deg, #eff6ff, #f8fafc); }\n        .worklog-stream-step-list { display:flex; flex-direction:column; gap:8px; padding:12px 12px 12px 34px; }\n        .worklog-stream-step { border-radius:12px; border:1px solid #e2e8f0; background:#f8fafc; padding:8px 10px; position:relative; }\n        .worklog-stream-step::before { content:''; position:absolute; left:-24px; top:14px; width:10px; height:10px; border-radius:999px; background:#cbd5e1; box-shadow:0 0 0 4px rgba(226,232,240,0.9); }\n        .worklog-stream-step.current-step { border-color:#60a5fa; background:linear-gradient(135deg, #eff6ff, #dbeafe); box-shadow:0 0 0 2px rgba(96,165,250,0.18), 0 14px 32px rgba(37,99,235,0.12); animation: currentStepTracePulse 1.5s ease-in-out infinite; } /* worklog-stream-step current-step */\n        .worklog-stream-step.current-step::before { background:#2563eb; box-shadow:0 0 0 6px rgba(191,219,254,0.95); }\n        @keyframes currentStepTracePulse {\n            0% { box-shadow:0 0 0 2px rgba(96,165,250,0.14), 0 8px 22px rgba(37,99,235,0.10); }\n            50% { box-shadow:0 0 0 3px rgba(59,130,246,0.26), 0 18px 38px rgba(37,99,235,0.18); }\n            100% { box-shadow:0 0 0 2px rgba(96,165,250,0.14), 0 8px 22px rgba(37,99,235,0.10); }\n        }\n        @keyframes streamStepEnter {\n            0% { opacity:0; transform:translateY(8px) scale(0.985); }\n            100% { opacity:1; transform:translateY(0) scale(1); }\n        }\n        .result-artifact-panel, .result-diff-preview { border-radius:14px; border:1px solid #dbeafe; background:linear-gradient(135deg, #ffffff, #f8fafc); padding:12px; }\n        .result-artifact-panel { border-color:#bfdbfe; background:linear-gradient(135deg, #eff6ff, #eef6ff); }\n        .result-panel-title { font-size:12px; font-weight:800; color:#1e3a8a; margin-bottom:8px; }\n        .result-artifact-list { display:flex; flex-direction:column; gap:10px; }\n        .result-diff-preview pre { margin:0; padding:12px; border-radius:12px; background:#0f172a; color:#e2e8f0; overflow:auto; font-size:12px; }\n        .result-diff-preview code { font-family:Consolas, monospace; white-space:pre; }\n        @media (max-width: 980px) {\n            .worklog-process-layout { grid-template-columns:1fr; }\n        }\n        .worklog-process-panel { display:flex; flex-direction:column; gap:12px; }\n        .worklog-timeline { display:flex; flex-direction:column; gap:8px; }\n\n        .worklog-timeline-item { border-radius:12px; padding:10px 12px; border:1px solid #dbeafe; background:linear-gradient(135deg, #ffffff, #f8fafc); }\n        .worklog-timeline-item.stdout { border-color:#93c5fd; background:linear-gradient(135deg, #eff6ff, #dbeafe); }\n        .worklog-timeline-item.chat { border-color:#cbd5e1; background:linear-gradient(135deg, #f8fafc, #f1f5f9); }\n        .worklog-timeline-item.heartbeat { border-color:#fde68a; background:linear-gradient(135deg, #fffbeb, #fef3c7); }\n        .worklog-timeline-item.watchdog, .worklog-timeline-item.failed, .worklog-timeline-item.error { border-color:#fca5a5; background:linear-gradient(135deg, #fff1f2, #fee2e2); }\n        .worklog-timeline-item.latest { box-shadow:0 0 0 2px rgba(37,99,235,0.18), 0 10px 28px rgba(37,99,235,0.12); }\n        .worklog-timeline-meta { font-size:11px; color:#64748b; margin-bottom:4px; display:flex; gap:8px; flex-wrap:wrap; }\n        .worklog-stage-list { display:flex; flex-direction:column; gap:10px; position:relative; padding-left:18px; }\n        .worklog-stage-list::before { content:''; position:absolute; left:8px; top:6px; bottom:6px; width:2px; background:linear-gradient(180deg, rgba(148,163,184,0.15), rgba(59,130,246,0.28), rgba(148,163,184,0.15)); }\n        .worklog-stage-node { position:relative; }\n        .worklog-stage-node::before { content:''; position:absolute; left:-14px; top:18px; width:10px; height:10px; border-radius:999px; border:2px solid #93c5fd; background:#fff; box-shadow:0 0 0 4px rgba(219,234,254,0.85); z-index:1; }\n        .worklog-stage-details { border:1px solid #dbeafe; border-radius:14px; background:#fff; overflow:hidden; position:relative; }\n        .worklog-stage-details.running { border-color:#93c5fd; }\n        .worklog-stage-details.failed, .worklog-stage-details.timeout, .worklog-stage-details.watchdog { border-color:#fca5a5; }\n        .worklog-stage-details.completed { border-color:#86efac; }\n        .worklog-stage-details.active-focus { border-color:#60a5fa; box-shadow:0 0 0 2px rgba(96,165,250,0.22), 0 16px 40px rgba(37,99,235,0.16); animation: activeStageFramePulse 1.8s ease-in-out infinite; }\n        .worklog-stage-details summary { list-style:none; cursor:pointer; padding:12px 14px; display:flex; justify-content:space-between; align-items:center; gap:8px; font-size:12px; font-weight:700; color:#1e293b; background:linear-gradient(135deg, #f8fafc, #eef2ff); }\n        .worklog-stage-summary-main { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }\n        .worklog-stage-summary-side { display:flex; align-items:center; gap:8px; flex-wrap:wrap; justify-content:flex-end; }\n        .worklog-stage-pin { border:none; border-radius:999px; padding:4px 10px; cursor:pointer; background:#e2e8f0; color:#334155; font-size:11px; font-weight:700; }\n        .worklog-stage-pin:hover { background:#cbd5e1; }\n        .worklog-stage-pin.pinned { background:#2563eb; color:#fff; }\n        .worklog-stage-status-bar { height:4px; background:#cbd5e1; }\n        .worklog-stage-status-bar.running { background:linear-gradient(90deg, #60a5fa, #2563eb); animation: stagePulseGlow 1.6s ease-in-out infinite; }\n        .worklog-stage-details.running .worklog-stage-status-bar { animation: stagePulseGlow 1.6s ease-in-out infinite; }\n        .worklog-stage-status-bar.completed { background:linear-gradient(90deg, #4ade80, #16a34a); }\n        .worklog-