ze: 1.05em; \n    color: #1e293b; \n    display: flex; \n    align-items: center; \n    gap: 8px; \n    flex: 1;\n    min-width: 0;\n    overflow: hidden; \n    white-space: nowrap; \n    text-overflow: ellipsis; \n}\n.project-progress-container { \n    flex: 0 0 180px;\n    margin: 0 20px; \n    display: flex; \n    flex-direction: column; \n    gap: 4px; \n}\n.progress-bar-bg { height: 6px; background: #e2e8f0; border-radius: 3px; overflow: hidden; width: 100%; }\n.progress-bar-fill { height: 100%; background: linear-gradient(90deg, #3b82f6, #10b981); transition: width 0.4s ease; }\n.project-meta { \n    font-size: 0.85em; \n    color: #64748b; \n    font-weight: bold; \n    flex: 0 0 60px; \n    text-align: right; \n}\n.task-list { padding: 5px 20px 15px 20px; background: #fff; }\n.task-row { display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px dashed #f1f5f9; transition: background 0.2s; }\n.task-row:last-child { border-bottom: none; }\n.task-row:hover { background: #fafafa; }\n.task-title { font-size: 0.9em; color: #334155; flex: 1; padding-right: 15px; font-weight: 500; }\n.task-badges { display: flex; gap: 8px; align-items: center; font-size: 0.75em; flex-shrink: 0; }\n.board-task-card { gap: 10px; }\n.board-task-card.approval { border-color:#f59e0b !important; background:linear-gradient(180deg,#fffbeb 0%,#ffffff 58%); box-shadow:0 8px 20px rgba(180,83,9,0.10); }\n.board-task-secondary-btn { padding:7px 12px; border:none; border-radius:999px; cursor:pointer; font-size:12px; font-weight:800; white-space:nowrap; color:#1d4ed8; background:#eff6ff; }\n.board-task-secondary-btn.approve { color:#047857; background:#dcfce7; }\n.board-task-secondary-btn.danger { color:#dc2626; background:#fee2e2; }\n.board-task-head { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; width:100%; }\n.board-task-title-text { padding-right:0; line-height:1.5; min-width:0; }\n.board-task-delivery-grid { displ